find-the-minimum-cost-array-permutation.solutionCode:
class Solution {
public:
	vector<int> findPermutation(vector<int>& nums) {
		int n = nums.size();
		vector<int> ans;
		int f[1 << n][n];
		memset(f, -1, sizeof(f));
		function<int(int, int)> dfs = [&](int mask, int pre) {
			if (mask == (1 << n) - 1) {
				return abs(pre - nums[0]);
			}
			int* res = &f[mask][pre];
			if (*res != -1) {
				return *res;
			}
			*res = INT_MAX;
			for (int cur = 1; cur < n; ++cur) {
				if (mask >> cur & 1 ^ 1) {
					*res = min(*res, abs(pre - nums[cur]) + dfs(mask | 1 << cur, cur));
				}
			}
			return *res;
		};
		function<void(int, int)> g = [&](int mask, int pre) {
			ans.push_back(pre);
			if (mask == (1 << n) - 1) {
				return;
			}
			int res = dfs(mask, pre);
			for (int cur = 1; cur < n; ++cur) {
				if (mask >> cur & 1 ^ 1) {
					if (abs(pre - nums[cur]) + dfs(mask | 1 << cur, cur) == res) {
						g(mask | 1 << cur, cur);
						break;
					}
				}
			}
		};
		g(1, 0);
		return ans;
	}
};

equalize-strings-by-adding-or-removing-c.solutionCode:
class Solution {
public:
	int minOperations(string initial, string target) {
		int m = initial.size(), n = target.size();
		int f[m + 1][n + 1];
		memset(f, 0, sizeof(f));
		int mx = 0;
		for (int i = 1; i <= m; ++i) {
			for (int j = 1; j <= n; ++j) {
				if (initial[i - 1] == target[j - 1]) {
					f[i][j] = f[i - 1][j - 1] + 1;
					mx = max(mx, f[i][j]);
				}
			}
		}
		return m + n - 2 * mx;
	}
};

sum-of-digit-differences-of-all-pairs.solutionCode:
class Solution {
public:
	long long sumDigitDifferences(vector<int>& nums) {
		int n = nums.size();
		int m = floor(log10(nums[0])) + 1;
		int cnt[10];
		long long ans = 0;
		for (int k = 0; k < m; ++k) {
			memset(cnt, 0, sizeof(cnt));
			for (int i = 0; i < n; ++i) {
				++cnt[nums[i] % 10];
				nums[i] /= 10;
			}
			for (int i = 0; i < 10; ++i) {
				ans += 1LL * cnt[i] * (n - cnt[i]);
			}
		}
		return ans / 2;
	}
};

