						ans += cnt1[i] * cnt2[j] * cnt3[k];
					}
				}
			}
		}
		return ans;
	}
};

maximum-number-of-potholes-that-can-be-f.solutionCode:
class Solution {
public:
	int maxPotholes(string road, int budget) {
		road.push_back('.');
		int n = road.size();
		vector<int> cnt(n);
		int k = 0;
		for (char& c : road) {
			if (c == 'x') {
				++k;
			} else if (k) {
				++cnt[k];
				k = 0;
			}
		}
		int ans = 0;
		for (k = n - 1; k && budget; --k) {
			int t = min(budget / (k + 1), cnt[k]);
			ans += t * k;
			budget -= t * (k + 1);
			cnt[k - 1] += cnt[k] - t;
		}
		return ans;
	}
};

find-subarray-with-bitwise-or-closest-to.solutionCode:
class Solution {
public:
	int minimumDifference(vector<int>& nums, int k) {
		int mx = *max_element(nums.begin(), nums.end());
		int m = 32 - __builtin_clz(mx);
		int n = nums.size();
		int ans = INT_MAX;
		vector<int> cnt(m);
		for (int i = 0, j = 0, s = 0; j < n; ++j) {
			s |= nums[j];
			ans = min(ans, abs(s - k));
			for (int h = 0; h < m; ++h) {
				if (nums[j] >> h & 1) {
					++cnt[h];
				}
			}
			while (i < j && s > k) {
				for (int h = 0; h < m; ++h) {
					if (nums[i] >> h & 1 && --cnt[h] == 0) {
						s ^= 1 << h;
					}
				}
				ans = min(ans, abs(s - k));
				++i;
			}
		}
		return ans;
	}
};

find-the-minimum-area-to-cover-all-ones-.solutionCode:
class Solution {
public:
	int minimumArea(vector<vector<int>>& grid) {
		int m = grid.size(), n = grid[0].size();
		int x1 = m, y1 = n;
		int x2 = 0, y2 = 0;
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j] == 1) {
					x1 = min(x1, i);
					y1 = min(y1, j);
					x2 = max(x2, i);
					y2 = max(y2, j);
				}
			}
		}
		return (x2 - x1 + 1) * (y2 - y1 + 1);
	}
};

minimum-length-of-anagram-concatenation.solutionCode:
class Solution {
public:
	int minAnagramLength(string s) {
		int n = s.size();
		int cnt[26]{};
		for (char c : s) {
			cnt[c - 'a']++;
		}
		auto check = [&](int k) {
			for (int i = 0; i < n; i += k) {
				int cnt1[26]{};
				for (int j = i; j < i + k; ++j) {
					cnt1[s[j] - 'a']++;
				}
				for (int j = 0; j < 26; ++j) {
					if (cnt1[j] * (n / k) != cnt[j]) {
						return false;
					}
				}
			}
			return true;
		};
		for (int i = 1;; ++i) {
			if (n % i == 0 && check(i)) {
				return i;
			}
		}
	}
};

minimize-manhattan-distances.solutionCode:
class Solution {
public:
	int minimumDistance(vector<vector<int>>& points) {
		multiset<int> st1;
		multiset<int> st2;
		for (auto& p : points) {
			int x = p[0], y = p[1];
			st1.insert(x + y);
			st2.insert(x - y);
		}
		int ans = INT_MAX;
		for (auto& p : points) {
			int x = p[0], y = p[1];
			st1.erase(st1.find(x + y));
			st2.erase(st2.find(x - y));
			ans = min(ans, max(*st1.rbegin() - *st1.begin(), *st2.rbegin() - *st2.begin()));
			st1.insert(x + y);
			st2.insert(x - y);
		}
		return ans;
	}
};

maximum-total-reward-using-operations-i.solutionCode:
class Solution {
public:
	int maxTotalReward(vector<int>& rewardValues) {
		sort(rewardValues.begin(), rewardValues.end());
		int n = rewardValues.size();
		int f[rewardValues.back() << 1];
		memset(f, -1, sizeof(f));
		function<int(int)> dfs = [&](int x) {
			if (f[x] != -1) {
				return f[x];
			}
			auto it = upper_bound(rewardValues.begin(), rewardValues.end(), x);
			int ans = 0;
			for (; it != rewardValues.end(); ++it) {
				ans = max(ans, rewardValues[it - rewardValues.begin()] + dfs(x + *it));
			}
			return f[x] = ans;
		};
		return dfs(0);
	}
};

