class BinaryIndexedTree {
private:
	int n;
	vector<int> c;

public:
	BinaryIndexedTree(int n)
		: n(n)
		, c(n + 1) {}

	void update(int x, int delta) {
		for (; x <= n; x += x & -x) {
			c[x] += delta;
		}
	}

	int query(int x) {
		int s = 0;
		for (; x > 0; x -= x & -x) {
			s += c[x];
		}
		return s;
	}
};

class Solution {
public:
	vector<int> countOfPeaks(vector<int>& nums, vector<vector<int>>& queries) {
		int n = nums.size();
		BinaryIndexedTree tree(n - 1);
		auto update = [&](int i, int val) {
			if (i <= 0 || i >= n - 1) {
				return;
			}
			if (nums[i - 1] < nums[i] && nums[i] > nums[i + 1]) {
				tree.update(i, val);
			}
		};
		for (int i = 1; i < n - 1; ++i) {
			update(i, 1);
		}
		vector<int> ans;
		for (auto& q : queries) {
			if (q[0] == 1) {
				int l = q[1] + 1, r = q[2] - 1;
				ans.push_back(l > r ? 0 : tree.query(r) - tree.query(l - 1));
			} else {
				int idx = q[1], val = q[2];
				for (int i = idx - 1; i <= idx + 1; ++i) {
					update(i, -1);
				}
				nums[idx] = val;
				for (int i = idx - 1; i <= idx + 1; ++i) {
					update(i, 1);
				}
			}
		}
		return ans;
	}
};

find-occurrences-of-an-element-in-an-arr.solutionCode:
class Solution {
public:
	vector<int> occurrencesOfElement(vector<int>& nums, vector<int>& queries, int x) {
		vector<int> ids;
		for (int i = 0; i < nums.size(); ++i) {
			if (nums[i] == x) {
				ids.push_back(i);
			}
		}
		vector<int> ans;
		for (int& i : queries) {
			ans.push_back(i - 1 < ids.size() ? ids[i - 1] : -1);
		}
		return ans;
	}
};

count-days-without-meetings.solutionCode:
class Solution {
public:
	int countDays(int days, vector<vector<int>>& meetings) {
		sort(meetings.begin(), meetings.end());
		int ans = 0, last = 0;
		for (auto& e : meetings) {
			int st = e[0], ed = e[1];
			if (last < st) {
				ans += st - last - 1;
			}
			last = max(last, ed);
		}
		ans += days - last;
		return ans;
	}
};

find-all-possible-stable-binary-arrays-i.solutionCode:
class Solution {
public:
	int numberOfStableArrays(int zero, int one, int limit) {
		const int mod = 1e9 + 7;
		using ll = long long;
		vector<vector<array<ll, 2>>> f = vector<vector<array<ll, 2>>>(zero + 1, vector<array<ll, 2>>(one + 1, {-1, -1}));
		auto dfs = [&](this auto&& dfs, int i, int j, int k) -> ll {
			if (i < 0 || j < 0) {
				return 0;
			}
			if (i == 0) {
				return k == 1 && j <= limit;
			}
			if (j == 0) {
				return k == 0 && i <= limit;
			}
			ll& res = f[i][j][k];
			if (res != -1) {
				return res;
			}
			if (k == 0) {
				res = (dfs(i - 1, j, 0) + dfs(i - 1, j, 1) - dfs(i - limit - 1, j, 1) + mod) % mod;
			} else {
				res = (dfs(i, j - 1, 0) + dfs(i, j - 1, 1) - dfs(i, j - limit - 1, 0) + mod) % mod;
			}
			return res;
		};
		return (dfs(zero, one, 0) + dfs(zero, one, 1)) % mod;
	}
};

