class Solution {
public:
	string clearStars(string s) {
		stack<int> g[26];
		int n = s.length();
		vector<bool> rem(n);
		for (int i = 0; i < n; ++i) {
			if (s[i] == '*') {
				rem[i] = true;
				for (int j = 0; j < 26; ++j) {
					if (!g[j].empty()) {
						rem[g[j].top()] = true;
						g[j].pop();
						break;
					}
				}
			} else {
				g[s[i] - 'a'].push(i);
			}
		}
		string ans;
		for (int i = 0; i < n; ++i) {
			if (!rem[i]) {
				ans.push_back(s[i]);
			}
		}
		return ans;
	}
};

maximum-sum-of-subsequence-with-non-adja.solutionCode:
class Node {
public:
	int l, r;
	long long s00, s01, s10, s11;

	Node(int l, int r)
		: l(l)
		, r(r)
		, s00(0)
		, s01(0)
		, s10(0)
		, s11(0) {}
};

class SegmentTree {
public:
	vector<Node*> tr;

	SegmentTree(int n)
		: tr(n << 2) {
		build(1, 1, n);
	}

	void build(int u, int l, int r) {
		tr[u] = new Node(l, r);
		if (l == r) {
			return;
		}
		int mid = (l + r) >> 1;
		build(u << 1, l, mid);
		build(u << 1 | 1, mid + 1, r);
	}

	long long query(int u, int l, int r) {
		if (tr[u]->l >= l && tr[u]->r <= r) {
			return tr[u]->s11;
		}
		int mid = (tr[u]->l + tr[u]->r) >> 1;
		long long ans = 0;
		if (r <= mid) {
			ans = query(u << 1, l, r);
		}
		if (l > mid) {
			ans = max(ans, query(u << 1 | 1, l, r));
		}
		return ans;
	}

	void pushup(int u) {
		Node* left = tr[u << 1];
		Node* right = tr[u << 1 | 1];
		tr[u]->s00 = max(left->s00 + right->s10, left->s01 + right->s00);
		tr[u]->s01 = max(left->s00 + right->s11, left->s01 + right->s01);
		tr[u]->s10 = max(left->s10 + right->s10, left->s11 + right->s00);
		tr[u]->s11 = max(left->s10 + right->s11, left->s11 + right->s01);
	}

	void modify(int u, int x, int v) {
		if (tr[u]->l == tr[u]->r) {
			tr[u]->s11 = max(0LL, (long long) v);
			return;
		}
		int mid = (tr[u]->l + tr[u]->r) >> 1;
		if (x <= mid) {
			modify(u << 1, x, v);
		} else {
			modify(u << 1 | 1, x, v);
		}
		pushup(u);
	}

	~SegmentTree() {
		for (auto node : tr) {
			delete node;
		}
	}
};

class Solution {
public:
	int maximumSumSubsequence(vector<int>& nums, vector<vector<int>>& queries) {
		int n = nums.size();
		SegmentTree tree(n);
		for (int i = 0; i < n; ++i) {
			tree.modify(1, i + 1, nums[i]);
		}
		long long ans = 0;
		const int mod = 1e9 + 7;
		for (const auto& q : queries) {
			tree.modify(1, q[0] + 1, q[1]);
			ans = (ans + tree.query(1, 1, n)) % mod;
		}
		return (int) ans;
	}
};

find-number-of-ways-to-reach-the-k-th-st.solutionCode:
class Solution {
public:
	int waysToReachStair(int k) {
		unordered_map<long long, int> f;
		auto dfs = [&](this auto&& dfs, int i, int j, int jump) -> int {
			if (i > k + 1) {
				return 0;
			}
			long long key = ((long long) i << 32) | jump << 1 | j;
			if (f.contains(key)) {
				return f[key];
			}
			int ans = i == k ? 1 : 0;
			if (i > 0 && j == 0) {
				ans += dfs(i - 1, 1, jump);
			}
			ans += dfs(i + (1 << jump), 0, jump + 1);
			f[key] = ans;
			return ans;
		};
		return dfs(1, 0, 0);
	}
};

