class Solution {
public:
	int numberOfWays(int n) {
		const int mod = 1e9 + 7;
		int coins[3] = {1, 2, 6};
		int f[n + 1];
		memset(f, 0, sizeof(f));
		f[0] = 1;
		for (int x : coins) {
			for (int j = x; j <= n; ++j) {
				f[j] = (f[j] + f[j - x]) % mod;
			}
		}
		int ans = f[n];
		if (n >= 4) {
			ans = (ans + f[n - 4]) % mod;
		}
		if (n >= 8) {
			ans = (ans + f[n - 8]) % mod;
		}
		return ans;
	}
};

find-the-minimum-area-to-cover-all-ones-.solutionCode:
class Solution {
public:
	int minimumSum(vector<vector<int>>& grid) {
		int m = grid.size();
		int n = grid[0].size();
		int ans = m * n;
		int inf = INT_MAX / 4;
		auto f = [&](int i1, int j1, int i2, int j2) {
			int x1 = inf, y1 = inf;
			int x2 = -inf, y2 = -inf;
			for (int i = i1; i <= i2; i++) {
				for (int j = j1; j <= j2; j++) {
					if (grid[i][j] == 1) {
						x1 = min(x1, i);
						y1 = min(y1, j);
						x2 = max(x2, i);
						y2 = max(y2, j);
					}
				}
			}
			return x1 > x2 || y1 > y2 ? inf : (x2 - x1 + 1) * (y2 - y1 + 1);
		};

		for (int i1 = 0; i1 < m - 1; i1++) {
			for (int i2 = i1 + 1; i2 < m - 1; i2++) {
				ans = min(ans, f(0, 0, i1, n - 1) + f(i1 + 1, 0, i2, n - 1) + f(i2 + 1, 0, m - 1, n - 1));
			}
		}

		for (int j1 = 0; j1 < n - 1; j1++) {
			for (int j2 = j1 + 1; j2 < n - 1; j2++) {
				ans = min(ans, f(0, 0, m - 1, j1) + f(0, j1 + 1, m - 1, j2) + f(0, j2 + 1, m - 1, n - 1));
			}
		}

		for (int i = 0; i < m - 1; i++) {
			for (int j = 0; j < n - 1; j++) {
				ans = min(ans, f(0, 0, i, j) + f(0, j + 1, i, n - 1) + f(i + 1, 0, m - 1, n - 1));
				ans = min(ans, f(0, 0, i, n - 1) + f(i + 1, 0, m - 1, j) + f(i + 1, j + 1, m - 1, n - 1));
				ans = min(ans, f(0, 0, i, j) + f(i + 1, 0, m - 1, j) + f(0, j + 1, m - 1, n - 1));
				ans = min(ans, f(0, 0, m - 1, j) + f(0, j + 1, i, n - 1) + f(i + 1, j + 1, m - 1, n - 1));
			}
		}

		return ans;
	}
};

