minimum-cost-walk-in-weighted-graph.solutionCode:
class UnionFind {
public:
	UnionFind(int n) {
		p = vector<int>(n);
		size = vector<int>(n, 1);
		iota(p.begin(), p.end(), 0);
	}

	bool unite(int a, int b) {
		int pa = find(a), pb = find(b);
		if (pa == pb) {
			return false;
		}
		if (size[pa] > size[pb]) {
			p[pb] = pa;
			size[pa] += size[pb];
		} else {
			p[pa] = pb;
			size[pb] += size[pa];
		}
		return true;
	}

	int find(int x) {
		if (p[x] != x) {
			p[x] = find(p[x]);
		}
		return p[x];
	}

	int getSize(int x) {
		return size[find(x)];
	}

private:
	vector<int> p, size;
};

class Solution {
public:
	vector<int> minimumCost(int n, vector<vector<int>>& edges, vector<vector<int>>& query) {
		g = vector<int>(n, -1);
		uf = new UnionFind(n);
		for (auto& e : edges) {
			uf->unite(e[0], e[1]);
		}
		for (auto& e : edges) {
			int root = uf->find(e[0]);
			g[root] &= e[2];
		}
		vector<int> ans;
		for (auto& q : query) {
			ans.push_back(f(q[0], q[1]));
		}
		return ans;
	}

private:
	UnionFind* uf;
	vector<int> g;

	int f(int u, int v) {
		if (u == v) {
			return 0;
		}
		int a = uf->find(u), b = uf->find(v);
		return a == b ? g[a] : -1;
	}
};

