minimum-time-to-visit-disappearing-nodes.solutionCode:
class Solution {
public:
	vector<int> minimumTime(int n, vector<vector<int>>& edges, vector<int>& disappear) {
		vector<vector<pair<int, int>>> g(n);
		for (const auto& e : edges) {
			int u = e[0], v = e[1], w = e[2];
			g[u].push_back({v, w});
			g[v].push_back({u, w});
		}

		vector<int> dist(n, 1 << 30);
		dist[0] = 0;

		using pii = pair<int, int>;
		priority_queue<pii, vector<pii>, greater<pii>> pq;
		pq.push({0, 0});

		while (!pq.empty()) {
			auto [du, u] = pq.top();
			pq.pop();

			if (du > dist[u]) {
				continue;
			}

			for (auto [v, w] : g[u]) {
				if (dist[v] > dist[u] + w && dist[u] + w < disappear[v]) {
					dist[v] = dist[u] + w;
					pq.push({dist[v], v});
				}
			}
		}

		vector<int> ans(n);
		for (int i = 0; i < n; ++i) {
			ans[i] = dist[i] < disappear[i] ? dist[i] : -1;
		}

		return ans;
	}
};

minimum-sum-of-values-by-dividing-array.solutionCode:
class Solution {
public:
	int minimumValueSum(vector<int>& nums, vector<int>& andValues) {
		this->nums = nums;
		this->andValues = andValues;
		n = nums.size();
		m = andValues.size();
		int ans = dfs(0, 0, -1);
		return ans >= inf ? -1 : ans;
	}

private:
	vector<int> nums;
	vector<int> andValues;
	int n;
	int m;
	const int inf = 1 << 29;
	unordered_map<long long, int> f;

	int dfs(int i, int j, int a) {
		if (n - i < m - j) {
			return inf;
		}
		if (j == m) {
			return i == n ? 0 : inf;
		}
		a &= nums[i];
		if (a < andValues[j]) {
			return inf;
		}
		long long key = (long long) i << 36 | (long long) j << 32 | a;
		if (f.contains(key)) {
			return f[key];
		}
		int ans = dfs(i + 1, j, a);
		if (a == andValues[j]) {
			ans = min(ans, dfs(i + 1, j + 1, -1) + nums[i]);
		}
		return f[key] = ans;
	}
};

