minimum-substring-partition-of-equal-cha.solutionCode:
class Solution {
public:
	int minimumSubstringsInPartition(string s) {
		int n = s.size();
		int f[n];
		memset(f, -1, sizeof(f));
		auto dfs = [&](this auto&& dfs, int i) -> int {
			if (i >= n) {
				return 0;
			}
			if (f[i] != -1) {
				return f[i];
			}
			f[i] = n - i;
			int cnt[26]{};
			unordered_map<int, int> freq;
			for (int j = i; j < n; ++j) {
				int k = s[j] - 'a';
				if (cnt[k]) {
					freq[cnt[k]]--;
					if (freq[cnt[k]] == 0) {
						freq.erase(cnt[k]);
					}
				}
				++cnt[k];
				++freq[cnt[k]];
				if (freq.size() == 1) {
					f[i] = min(f[i], 1 + dfs(j + 1));
				}
			}
			return f[i];
		};
		return dfs(0);
	}
};

