		}
		return ans;
	}
};

maximum-hamming-distances.solutionCode:
class Solution {
public:
	vector<int> maxHammingDistances(vector<int>& nums, int m) {
		int dist[1 << m];
		memset(dist, -1, sizeof(dist));
		queue<int> q;
		for (int x : nums) {
			dist[x] = 0;
			q.push(x);
		}
		for (int k = 1; q.size(); ++k) {
			for (int t = q.size(); t; --t) {
				int x = q.front();
				q.pop();
				for (int i = 0; i < m; ++i) {
					int y = x ^ (1 << i);
					if (dist[y] == -1) {
						dist[y] = k;
						q.push(y);
					}
				}
			}
		}
		for (int& x : nums) {
			x = m - dist[x ^ ((1 << m) - 1)];
		}
		return nums;
	}
};

find-the-level-of-tree-with-minimum-sum.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int minimumLevel(TreeNode* root) {
		queue<TreeNode*> q{{root}};
		int ans = 0;
		long long s = 1LL << 60;
		for (int level = 1; q.size(); ++level) {
			long long t = 0;
			for (int m = q.size(); m; --m) {
				TreeNode* node = q.front();
				q.pop();
				t += node->val;
				if (node->left) {
					q.push(node->left);
				}
				if (node->right) {
					q.push(node->right);
				}
			}
			if (s > t) {
				s = t;
				ans = level;
			}
		}
		return ans;
	}
};

count-the-number-of-inversions.solutionCode:
class Solution {
public:
	int numberOfPermutations(int n, vector<vector<int>>& requirements) {
		vector<int> req(n, -1);
		int m = 0;
		for (const auto& r : requirements) {
			req[r[0]] = r[1];
			m = max(m, r[1]);
		}
		if (req[0] > 0) {
			return 0;
		}
		req[0] = 0;
		const int mod = 1e9 + 7;
		vector<vector<int>> f(n, vector<int>(m + 1, 0));
		f[0][0] = 1;
		for (int i = 1; i < n; ++i) {
			int l = 0, r = m;
			if (req[i] >= 0) {
				l = r = req[i];
			}
			for (int j = l; j <= r; ++j) {
				for (int k = 0; k <= min(i, j); ++k) {
					f[i][j] = (f[i][j] + f[i - 1][j - k]) % mod;
				}
			}
		}
		return f[n - 1][req[n - 1]];
	}
};

