boundary-of-binary-tree.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	vector<int> boundaryOfBinaryTree(TreeNode* root) {
		auto dfs = [&](this auto&& dfs, vector<int>& nums, TreeNode* root, int i) -> void {
			if (!root) {
				return;
			}
			if (i == 0) {
				if (root->left != root->right) {
					nums.push_back(root->val);
					if (root->left) {
						dfs(nums, root->left, i);
					} else {
						dfs(nums, root->right, i);
					}
				}
			} else if (i == 1) {
				if (root->left == root->right) {
					nums.push_back(root->val);
				} else {
					dfs(nums, root->left, i);
					dfs(nums, root->right, i);
				}
			} else {
				if (root->left != root->right) {
					nums.push_back(root->val);
					if (root->right) {
						dfs(nums, root->right, i);
					} else {
						dfs(nums, root->left, i);
					}
				}
			}
		};
		vector<int> ans = {root->val};
		if (root->left == root->right) {
			return ans;
		}
		vector<int> left, right, leaves;
		dfs(left, root->left, 0);
		dfs(leaves, root, 1);
		dfs(right, root->right, 2);
		ans.insert(ans.end(), left.begin(), left.end());
		ans.insert(ans.end(), leaves.begin(), leaves.end());
		ans.insert(ans.end(), right.rbegin(), right.rend());
		return ans;
	}
};

word-abbreviation.solutionCode:
class Trie {
public:
	Trie()
		: cnt(0) {
		fill(children.begin(), children.end(), nullptr);
	}

	void insert(const string& w) {
		Trie* node = this;
		for (char c : w) {
			int idx = c - 'a';
			if (node->children[idx] == nullptr) {
				node->children[idx] = new Trie();
			}
			node = node->children[idx];
			++node->cnt;
		}
	}

	int search(const string& w) {
		Trie* node = this;
		int ans = 0;
		for (char c : w) {
			++ans;
			int idx = c - 'a';
			node = node->children[idx];
			if (node->cnt == 1) {
				return ans;
			}
		}
		return w.size();
	}

private:
	array<Trie*, 26> children;
	int cnt;
};

class Solution {
public:
	vector<string> wordsAbbreviation(vector<string>& words) {
		map<pair<int, int>, Trie*> tries;
		for (const auto& w : words) {
			pair<int, int> key = {static_cast<int>(w.size()), w.back() - 'a'};
			if (tries.find(key) == tries.end()) {
				tries[key] = new Trie();
			}
			tries[key]->insert(w);
		}

		vector<string> ans;
		for (const auto& w : words) {
			int m = w.size();
			pair<int, int> key = {m, w.back() - 'a'};
			int cnt = tries[key]->search(w);
			ans.push_back((cnt + 2 >= m) ? w : w.substr(0, cnt) + to_string(m - cnt - 1) + w.back());
		}

		return ans;
	}
};

