class Solution {
public:
	int change(int amount, vector<int>& coins) {
		int m = coins.size(), n = amount;
		unsigned f[m + 1][n + 1];
		memset(f, 0, sizeof(f));
		f[0][0] = 1;
		for (int i = 1; i <= m; ++i) {
			for (int j = 0; j <= n; ++j) {
				f[i][j] = f[i - 1][j];
				if (j >= coins[i - 1]) {
					f[i][j] += f[i][j - coins[i - 1]];
				}
			}
		}
		return f[m][n];
	}
};

