	int n;
	int ans;
	vector<bool> vis;
	unordered_map<int, vector<int>> match;

	int countArrangement(int n) {
		this->n = n;
		this->ans = 0;
		vis.resize(n + 1);
		for (int i = 1; i <= n; ++i)
			for (int j = 1; j <= n; ++j)
				if (i % j == 0 || j % i == 0)
					match[i].push_back(j);
		dfs(1);
		return ans;
