class Solution {
public:
	int longestPalindromeSubseq(string s) {
		int n = s.size();
		int f[n][n];
		memset(f, 0, sizeof(f));
		for (int i = 0; i < n; ++i) {
			f[i][i] = 1;
		}
		for (int i = n - 1; ~i; --i) {
			for (int j = i + 1; j < n; ++j) {
				if (s[i] == s[j]) {
					f[i][j] = f[i + 1][j - 1] + 2;
				} else {
					f[i][j] = max(f[i + 1][j], f[i][j - 1]);
				}
			}
		}
		return f[0][n - 1];
	}
};

