 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int findTilt(TreeNode* root) {
		int ans = 0;
		auto dfs = [&](this auto&& dfs, TreeNode* root) -> int {
			if (!root) {
				return 0;
			}
			int l = dfs(root->left), r = dfs(root->right);
			ans += abs(l - r);
			return l + r + root->val;
		};
		dfs(root);
		return ans;
	}
};

erect-the-fence.solutionCode:
class Solution {
public:
	vector<vector<int>> outerTrees(vector<vector<int>>& trees) {
		int n = trees.size();
		if (n < 4) return trees;
		sort(trees.begin(), trees.end());
		vector<int> vis(n);
		vector<int> stk(n + 10);
		int cnt = 1;
		for (int i = 1; i < n; ++i) {
			while (cnt > 1 && cross(trees[stk[cnt - 1]], trees[stk[cnt - 2]], trees[i]) < 0) vis[stk[--cnt]] = false;
			vis[i] = true;
			stk[cnt++] = i;
		}
		int m = cnt;
		for (int i = n - 1; i >= 0; --i) {
			if (vis[i]) continue;
			while (cnt > m && cross(trees[stk[cnt - 1]], trees[stk[cnt - 2]], trees[i]) < 0) --cnt;
			stk[cnt++] = i;
		}
		vector<vector<int>> ans;
		for (int i = 0; i < cnt - 1; ++i) ans.push_back(trees[stk[i]]);
		return ans;
	}

	int cross(vector<int>& a, vector<int>& b, vector<int>& c) {
		return (b[0] - a[0]) * (c[1] - b[1]) - (b[1] - a[1]) * (c[0] - b[0]);
	}
};

