	}
	return res;
}

int init = []() {
	f[0] = g[0] = 1;
	for (int i = 1; i < N; ++i) {
		f[i] = f[i - 1] * i % MOD;
		g[i] = qmi(f[i], MOD - 2);
	}
	return 0;
}();

class Solution {
public:
	int makeStringSorted(string s) {
		int cnt[26]{};
		for (char& c : s) {
			++cnt[c - 'a'];
		}
		int n = s.size();
		long ans = 0;
		for (int i = 0; i < n; ++i) {
			int m = 0;
			for (int j = s[i] - 'a' - 1; ~j; --j) {
				m += cnt[j];
			}
			long t = m * f[n - i - 1] % MOD;
			for (int& v : cnt) {
				t = t * g[v] % MOD;
			}
			ans = (ans + t + MOD) % MOD;
			--cnt[s[i] - 'a'];
		}
		return ans;
	}
};

maximum-subarray-min-product.solutionCode:
class Solution {
public:
	int maxSumMinProduct(vector<int>& nums) {
		int n = nums.size();
		vector<int> left(n, -1);
		vector<int> right(n, n);
		stack<int> stk;
		for (int i = 0; i < n; ++i) {
			while (!stk.empty() && nums[stk.top()] >= nums[i]) {
				stk.pop();
			}
			if (!stk.empty()) {
				left[i] = stk.top();
			}
			stk.push(i);
		}
		stk = stack<int>();
		for (int i = n - 1; ~i; --i) {
			while (!stk.empty() && nums[stk.top()] > nums[i]) {
				stk.pop();
			}
			if (!stk.empty()) {
				right[i] = stk.top();
			}
			stk.push(i);
		}
		long long s[n + 1];
		s[0] = 0;
		for (int i = 0; i < n; ++i) {
			s[i + 1] = s[i] + nums[i];
		}
		long long ans = 0;
		for (int i = 0; i < n; ++i) {
			ans = max(ans, nums[i] * (s[right[i]] - s[left[i] + 1]));
		}
		const int mod = 1e9 + 7;
		return ans % mod;
	}
};

