class Solution {
public:
	int countNicePairs(vector<int>& nums) {
		auto rev = [](int x) {
			int y = 0;
			for (; x > 0; x /= 10) {
				y = y * 10 + x % 10;
			}
			return y;
		};
		unordered_map<int, int> cnt;
		for (int& x : nums) {
			int y = x - rev(x);
			cnt[y]++;
		}
		long long ans = 0;
		const int mod = 1e9 + 7;
		for (auto& [_, v] : cnt) {
			ans = (ans + 1ll * v * (v - 1) / 2) % mod;
		}
		return ans;
	}
};

