class Solution {
public:
	int minAbsoluteSumDiff(vector<int>& nums1, vector<int>& nums2) {
		const int mod = 1e9 + 7;
		vector<int> nums(nums1);
		sort(nums.begin(), nums.end());
		int s = 0, n = nums.size();
		for (int i = 0; i < n; ++i) {
			s = (s + abs(nums1[i] - nums2[i])) % mod;
		}
		int mx = 0;
		for (int i = 0; i < n; ++i) {
			int d1 = abs(nums1[i] - nums2[i]);
			int d2 = 1 << 30;
			int j = lower_bound(nums.begin(), nums.end(), nums2[i]) - nums.begin();
			if (j < n) {
				d2 = min(d2, abs(nums[j] - nums2[i]));
			}
			if (j) {
				d2 = min(d2, abs(nums[j - 1] - nums2[i]));
			}
			mx = max(mx, d1 - d2);
		}
		return (s - mx + mod) % mod;
	}
};

minimum-xor-sum-of-two-arrays.solutionCode:
class Solution {
public:
	int minimumXORSum(vector<int>& nums1, vector<int>& nums2) {
		int n = nums1.size();
		int f[n + 1][1 << n];
		memset(f, 0x3f, sizeof(f));
		f[0][0] = 0;
		for (int i = 1; i <= n; ++i) {
			for (int j = 0; j < 1 << n; ++j) {
				for (int k = 0; k < n; ++k) {
					if (j >> k & 1) {
						f[i][j] = min(f[i][j], f[i - 1][j ^ (1 << k)] + (nums1[i - 1] ^ nums2[k]));
					}
				}
			}
		}
		return f[n][(1 << n) - 1];
	}
};

remove-duplicates-from-an-unsorted-linke.solutionCode:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	ListNode* deleteDuplicatesUnsorted(ListNode* head) {
		unordered_map<int, int> cnt;
		for (ListNode* cur = head; cur; cur = cur->next) {
			cnt[cur->val]++;
		}
		ListNode* dummy = new ListNode(0, head);
		for (ListNode *pre = dummy, *cur = head; cur; cur = cur->next) {
			if (cnt[cur->val] > 1) {
				pre->next = cur->next;
			} else {
				pre = cur;
			}
		}
		return dummy->next;
	}
};

