class Solution {
public:
	int maxLength(vector<int>& ribbons, int k) {
		int left = 0, right = *max_element(ribbons.begin(), ribbons.end());
		while (left < right) {
			int mid = (left + right + 1) >> 1;
			int cnt = 0;
			for (int ribbon : ribbons) {
				cnt += ribbon / mid;
			}
			if (cnt >= k) {
				left = mid;
			} else {
				right = mid - 1;
			}
		}
		return left;
	}
};

