class Solution {
public:
	int maxFrequency(vector<int>& nums, int k) {
		int n = nums.size();
		sort(nums.begin(), nums.end());
		long long s[n + 1];
		s[0] = 0;
		for (int i = 1; i <= n; ++i) {
			s[i] = s[i - 1] + nums[i - 1];
		}
		int l = 1, r = n;
		auto check = [&](int m) {
			for (int i = m; i <= n; ++i) {
				if (1LL * nums[i - 1] * m - (s[i] - s[i - m]) <= k) {
					return true;
				}
			}
			return false;
		};
		while (l < r) {
			int mid = (l + r + 1) >> 1;
			if (check(mid)) {
				l = mid;
			} else {
				r = mid - 1;
			}
		}
		return l;
	}
};

