			long long y = 0;
			int r = x < 0 ? s.size() - 1 : s.size();
			for (int j = i; j < r; ++j) {
				y = y * 10 + s[j] - '0';
				if (y > 1e10) {
					break;
				}
				if ((x < 0 || x - y == 1) && dfs(j + 1, y)) {
