maximum-xor-for-each-query.solutionCode:
class Solution {
public:
	vector<int> getMaximumXor(vector<int>& nums, int maximumBit) {
		int xs = 0;
		for (int& x : nums) {
			xs ^= x;
		}
		int n = nums.size();
		vector<int> ans(n);
		for (int i = 0; i < n; ++i) {
			int x = nums[n - i - 1];
			int k = 0;
			for (int j = maximumBit - 1; ~j; --j) {
				if ((xs >> j & 1) == 0) {
					k |= 1 << j;
				}
			}
			ans[i] = k;
			xs ^= x;
		}
		return ans;
	}
};

