number-of-orders-in-the-backlog.solutionCode:
class Solution {
public:
	int getNumberOfBacklogOrders(vector<vector<int>>& orders) {
		using pii = pair<int, int>;
		priority_queue<pii, vector<pii>, greater<pii>> sell;
		priority_queue<pii> buy;
		for (auto& e : orders) {
			int p = e[0], a = e[1], t = e[2];
			if (t == 0) {
				while (a && !sell.empty() && sell.top().first <= p) {
					auto [x, y] = sell.top();
					sell.pop();
					if (a >= y) {
						a -= y;
					} else {
						sell.push({x, y - a});
						a = 0;
					}
				}
				if (a) {
					buy.push({p, a});
				}
			} else {
				while (a && !buy.empty() && buy.top().first >= p) {
					auto [x, y] = buy.top();
					buy.pop();
					if (a >= y) {
						a -= y;
					} else {
						buy.push({x, y - a});
						a = 0;
					}
				}
				if (a) {
					sell.push({p, a});
				}
			}
		}
		long ans = 0;
		while (!buy.empty()) {
			ans += buy.top().second;
			buy.pop();
		}
		while (!sell.empty()) {
			ans += sell.top().second;
			sell.pop();
		}
		const int mod = 1e9 + 7;
		return ans % mod;
	}
};

minimum-space-wasted-from-packaging.solutionCode:
class Solution {
public:
	int minWastedSpace(vector<int>& packages, vector<vector<int>>& boxes) {
		int n = packages.size(), m = boxes.size();
		sort(packages.begin(), packages.end());
		const int mod = 1e9 + 7;
		const long long inf = 1LL << 62;
		long long ans = inf;
		for (auto& box : boxes) {
			sort(box.begin(), box.end());
			if (packages.back() > box.back()) {
				continue;
			}
			int i = 0;
			long long s = 0;
			for (auto& b : box) {
				int j = upper_bound(packages.begin() + i, packages.end(), b) - packages.begin();
				s += 1LL * (j - i) * b;
				i = j;
			}
			ans = min(ans, s);
		}
		return ans == inf ? -1 : (ans - accumulate(packages.begin(), packages.end(), 0LL)) % mod;
	}
};

maximize-number-of-nice-divisors.solutionCode:
class Solution {
public:
	int maxNiceDivisors(int primeFactors) {
		if (primeFactors < 4) {
			return primeFactors;
		}
		const int mod = 1e9 + 7;
		auto qpow = [&](long long a, long long n) {
			long long ans = 1;
			for (; n; n >>= 1) {
				if (n & 1) {
					ans = ans * a % mod;
				}
				a = a * a % mod;
			}
			return (int) ans;
		};
		if (primeFactors % 3 == 0) {
			return qpow(3, primeFactors / 3);
		}
		if (primeFactors % 3 == 1) {
			return qpow(3, primeFactors / 3 - 1) * 4L % mod;
		}
		return qpow(3, primeFactors / 3) * 2 % mod;
	}
};

