class Solution {
public:
	bool canReach(string s, int minJump, int maxJump) {
		int n = s.size();
		vector<int> pre(n + 1);
		pre[1] = 1;
		vector<bool> f(n);
		f[0] = true;
		for (int i = 1; i < n; ++i) {
			if (s[i] == '0') {
				int l = max(0, i - maxJump);
				int r = i - minJump;
				f[i] = l <= r && pre[r + 1] - pre[l];
			}
			pre[i + 1] = pre[i] + f[i];
		}
		return f[n - 1];
	}
};

minimum-speed-to-arrive-on-time.solutionCode:
class Solution {
public:
	int minSpeedOnTime(vector<int>& dist, double hour) {
		if (dist.size() > ceil(hour)) {
			return -1;
		}
		const int m = 1e7;
		int l = 1, r = m + 1;
		int n = dist.size();
		auto check = [&](int v) {
			double s = 0;
			for (int i = 0; i < n; ++i) {
				double t = dist[i] * 1.0 / v;
				s += i == n - 1 ? t : ceil(t);
			}
			return s <= hour;
		};
		while (l < r) {
			int mid = (l + r) >> 1;
			if (check(mid)) {
				r = mid;
			} else {
				l = mid + 1;
			}
		}
		return l > m ? -1 : l;
	}
};

