			int x = e[0], y = e[1];
			arr.emplace_back(x - y, -(x + y));
		}
		sort(arr.begin(), arr.end());
		int n = arr.size();
		int ans = 0, cur = INT_MIN;
		for (int i = 0; i < n; ++i) {
			int l = arr[i].first, r = -arr[i].second;
			if (r <= cur) {
				continue;
			}
			cur = r;
			ans += i == n - 1 || (i < n - 1 && arr[i] != arr[i + 1]);
		}
		return ans;
	}
};

minimum-sum-of-squared-difference.solutionCode:
using ll = long long;

class Solution {
public:
	long long minSumSquareDiff(vector<int>& nums1, vector<int>& nums2, int k1, int k2) {
		int n = nums1.size();
		vector<int> d(n);
		ll s = 0;
		int mx = 0;
		int k = k1 + k2;
		for (int i = 0; i < n; ++i) {
			d[i] = abs(nums1[i] - nums2[i]);
			s += d[i];
			mx = max(mx, d[i]);
		}
		if (s <= k) return 0;
		int left = 0, right = mx;
		while (left < right) {
			int mid = (left + right) >> 1;
			ll t = 0;
			for (int v : d) t += max(v - mid, 0);
			if (t <= k)
				right = mid;
			else
				left = mid + 1;
		}
		for (int i = 0; i < n; ++i) {
			k -= max(0, d[i] - left);
			d[i] = min(d[i], left);
		}
		for (int i = 0; i < n && k; ++i) {
			if (d[i] == left) {
				--k;
				--d[i];
			}
		}
		ll ans = 0;
		for (int v : d) ans += 1ll * v * v;
		return ans;
	}
};

number-of-increasing-paths-in-a-grid.solutionCode:
class Solution {
public:
	int countPaths(vector<vector<int>>& grid) {
		const int mod = 1e9 + 7;
		int m = grid.size(), n = grid[0].size();
		int f[m][n];
		memset(f, 0, sizeof(f));
		function<int(int, int)> dfs = [&](int i, int j) -> int {
			if (f[i][j]) {
				return f[i][j];
			}
			int ans = 1;
			int dirs[5] = {-1, 0, 1, 0, -1};
			for (int k = 0; k < 4; ++k) {
				int x = i + dirs[k], y = j + dirs[k + 1];
				if (x >= 0 && x < m && y >= 0 && y < n && grid[i][j] < grid[x][y]) {
					ans = (ans + dfs(x, y)) % mod;
				}
			}
			return f[i][j] = ans;
		};
		int ans = 0;
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				ans = (ans + dfs(i, j)) % mod;
			}
		}
		return ans;
	}
};

