minimum-flips-in-binary-tree-to-get-resu.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int minimumFlips(TreeNode* root, bool result) {
		function<pair<int, int>(TreeNode*)> dfs = [&](TreeNode* root) -> pair<int, int> {
			if (!root) {
				return {1 << 30, 1 << 30};
			}
			int x = root->val;
			if (x < 2) {
				return {x, x ^ 1};
			}
			auto [l0, l1] = dfs(root->left);
			auto [r0, r1] = dfs(root->right);
			int a = 0, b = 0;
			if (x == 2) {
				a = l0 + r0;
				b = min({l0 + r1, l1 + r0, l1 + r1});
			} else if (x == 3) {
				a = min({l0 + r0, l0 + r1, l1 + r0});
				b = l1 + r1;
			} else if (x == 4) {
				a = min(l0 + r0, l1 + r1);
				b = min(l0 + r1, l1 + r0);
			} else {
				a = min(l1, r1);
				b = min(l0, r0);
			}
			return {a, b};
		};
		auto [a, b] = dfs(root);
		return result ? b : a;
	}
};

minimum-score-after-removals-on-a-tree.solutionCode:
class Solution {
public:
	int minimumScore(vector<int>& nums, vector<vector<int>>& edges) {
		int n = nums.size();
		vector<int> g[n];
		for (const auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		int s = 0, s1 = 0;
		int ans = INT_MAX;
		for (int x : nums) {
			s ^= x;
		}
		auto dfs = [&](this auto&& dfs, int i, int fa) -> int {
			int res = nums[i];
			for (int j : g[i]) {
				if (j != fa) {
					res ^= dfs(j, i);
				}
			}
			return res;
		};
		auto dfs2 = [&](this auto&& dfs2, int i, int fa) -> int {
			int res = nums[i];
			for (int j : g[i]) {
				if (j != fa) {
					int s2 = dfs2(j, i);
					res ^= s2;
					int mx = max({s ^ s1, s2, s1 ^ s2});
					int mn = min({s ^ s1, s2, s1 ^ s2});
					ans = min(ans, mx - mn);
				}
			}
			return res;
		};
		for (int i = 0; i < n; ++i) {
			for (int j : g[i]) {
				s1 = dfs(i, j);
				dfs2(i, j);
			}
		}
		return ans;
	}
};

