class Solution {
public:
	long long countPairs(int n, vector<vector<int>>& edges) {
		vector<int> g[n];
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		bool vis[n];
		memset(vis, 0, sizeof(vis));
		function<int(int)> dfs = [&](int i) {
			if (vis[i]) {
				return 0;
			}
			vis[i] = true;
			int cnt = 1;
			for (int j : g[i]) {
				cnt += dfs(j);
			}
			return cnt;
		};
		long long ans = 0, s = 0;
		for (int i = 0; i < n; ++i) {
			int t = dfs(i);
			ans += s * t;
			s += t;
		}
		return ans;
	}
};

