find-the-k-sum-of-an-array.solutionCode:
class Solution {
public:
	long long kSum(vector<int>& nums, int k) {
		long long mx = 0;
		int n = nums.size();
		for (int i = 0; i < n; ++i) {
			if (nums[i] > 0) {
				mx += nums[i];
			} else {
				nums[i] *= -1;
			}
		}
		sort(nums.begin(), nums.end());
		using pli = pair<long long, int>;
		priority_queue<pli, vector<pli>, greater<pli>> pq;
		pq.push({0, 0});
		while (--k) {
			auto p = pq.top();
			pq.pop();
			long long s = p.first;
			int i = p.second;
			if (i < n) {
				pq.push({s + nums[i], i + 1});
				if (i) {
					pq.push({s + nums[i] - nums[i - 1], i + 1});
				}
			}
		}
		return mx - pq.top().first;
	}
};

