class Solution {
public:
	int idealArrays(int n, int maxValue) {
		const int mod = 1e9 + 7;
		vector<vector<int>> c(n, vector<int>(16));
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j <= i && j < 16; ++j) {
				if (j == 0) {
					c[i][j] = 1;
				} else {
					c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % mod;
				}
			}
		}

		vector<vector<long long>> f(maxValue + 1, vector<long long>(16));
		for (int i = 1; i <= maxValue; ++i) {
			f[i][1] = 1;
		}

		for (int j = 1; j < 15; ++j) {
			for (int i = 1; i <= maxValue; ++i) {
				for (int k = 2; k * i <= maxValue; ++k) {
					f[k * i][j + 1] = (f[k * i][j + 1] + f[i][j]) % mod;
				}
			}
		}

		long long ans = 0;
		for (int i = 1; i <= maxValue; ++i) {
			for (int j = 1; j < 16; ++j) {
				ans = (ans + f[i][j] * c[n - 1][j - 1]) % mod;
			}
		}

		return ans;
	}
};

build-a-matrix-with-conditions.solutionCode:
class Solution {
public:
	int k;

	vector<vector<int>> buildMatrix(int k, vector<vector<int>>& rowConditions, vector<vector<int>>& colConditions) {
		this->k = k;
		auto row = f(rowConditions);
		auto col = f(colConditions);
		if (row.empty() || col.empty()) return {};
		vector<vector<int>> ans(k, vector<int>(k));
		vector<int> m(k + 1);
		for (int i = 0; i < k; ++i) {
			m[col[i]] = i;
		}
		for (int i = 0; i < k; ++i) {
			ans[i][m[row[i]]] = row[i];
		}
		return ans;
	}

	vector<int> f(vector<vector<int>>& cond) {
		vector<vector<int>> g(k + 1);
		vector<int> indeg(k + 1);
		for (auto& e : cond) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			++indeg[b];
		}
		queue<int> q;
		for (int i = 1; i < k + 1; ++i) {
			if (!indeg[i]) {
				q.push(i);
			}
		}
		vector<int> res;
		while (!q.empty()) {
			for (int n = q.size(); n; --n) {
				int i = q.front();
				res.push_back(i);
				q.pop();
				for (int j : g[i]) {
					if (--indeg[j] == 0) {
						q.push(j);
					}
				}
			}
		}
		return res.size() == k ? res : vector<int>();
	}
};

