		vector<bool> vis(n);
		for (int j = n - 1; ~j; --j) {
			int v = arr[j].first, i = arr[j].second;
			if (i && vis[i - 1]) merge(i, i - 1);
			if (j < n - 1 && vis[i + 1]) merge(i, i + 1);
			if (v > threshold / size[find(i)]) return size[find(i)];
			vis[i] = true;
		}
		return -1;
	}

	int find(int x) {
		if (p[x] != x) p[x] = find(p[x]);
		return p[x];
	}

	void merge(int a, int b) {
		int pa = find(a), pb = find(b);
		if (pa == pb) return;
		p[pa] = pb;
		size[pb] += size[pa];
	}
};

amount-of-time-for-binary-tree-to-be-inf.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int amountOfTime(TreeNode* root, int start) {
		unordered_map<int, vector<int>> g;
		function<void(TreeNode*, TreeNode*)> dfs = [&](TreeNode* node, TreeNode* fa) {
			if (!node) {
				return;
			}
			if (fa) {
				g[node->val].push_back(fa->val);
				g[fa->val].push_back(node->val);
			}
			dfs(node->left, node);
			dfs(node->right, node);
		};
		function<int(int, int)> dfs2 = [&](int node, int fa) -> int {
			int ans = 0;
			for (int nxt : g[node]) {
				if (nxt != fa) {
					ans = max(ans, 1 + dfs2(nxt, node));
				}
			}
			return ans;
		};
		dfs(root, nullptr);
		return dfs2(start, -1);
	}
};

maximum-score-of-spliced-array.solutionCode:
class Solution {
public:
	int maximumsSplicedArray(vector<int>& nums1, vector<int>& nums2) {
		int s1 = 0, s2 = 0, n = nums1.size();
		for (int i = 0; i < n; ++i) {
			s1 += nums1[i];
			s2 += nums2[i];
		}
		return max(s2 + f(nums1, nums2), s1 + f(nums2, nums1));
	}

	int f(vector<int>& nums1, vector<int>& nums2) {
		int t = nums1[0] - nums2[0];
		int mx = t;
		for (int i = 1; i < nums1.size(); ++i) {
			int v = nums1[i] - nums2[i];
			if (t > 0)
				t += v;
			else
				t = v;
			mx = max(mx, t);
		}
		return mx;
	}
};

