find-k-th-smallest-pair-distance.solutionCode:
class Solution {
public:
	int smallestDistancePair(vector<int>& nums, int k) {
		sort(nums.begin(), nums.end());
		int left = 0, right = nums.back() - nums.front();
		while (left < right) {
			int mid = (left + right) >> 1;
			if (count(mid, k, nums) >= k)
				right = mid;
			else
				left = mid + 1;
		}
		return left;
	}

	int count(int dist, int k, vector<int>& nums) {
		int cnt = 0;
		for (int i = 0; i < nums.size(); ++i) {
			int target = nums[i] - dist;
			int j = lower_bound(nums.begin(), nums.end(), target) - nums.begin();
			cnt += i - j;
		}
		return cnt;
	}
};

basic-calculator-iii.solutionCode:
class Solution {
public:
	// Define an operation function that performs mathematical operations based on the operator
	int operate(int b, char ch, int a) {
		// Note the order of ab
		switch (ch) {
		case '+':
			return a + b; // Addition
		case '-':
			return a - b; // Subtraction
		case '*':
			return a * b; // Multiplication
		case '/':
			return a / b; // Division
		default:
			break;
		}
		return 0; // Default return 0, handle invalid operators
	}

	// Calculate the value of the string expression
	int calculate(string s) {
		int preority[250]; // Operator precedence array
		preority['+'] = 1;
		preority['-'] = 1;
		preority['*'] = 2;
		preority['/'] = 2;
		preority['('] = 0;
		preority[')'] = 0;

		stack<char> op; // Operator stack
		stack<int> num; // Operand stack
		int stringsize = s.size(); // Length of the string
		int i = 0;
		char ch;

		// Traverse the string
		for (; i < stringsize; i++) {
			ch = s[i];
			if (ch == ' ') {
				continue; // Skip spaces
			}
			if (ch >= '0' && ch <= '9') {
				int realnum = ch - '0'; // Convert character to number
				// Handle multi-digit numbers
				while (s[i + 1] >= '0' && s[i + 1] <= '9') {
					i++;
					realnum *= 10;
					realnum += s[i] - '0';
				}
				num.push(realnum); // Push the number onto the stack
			} else {
				// Handle operators
				if (op.empty() || ch == '(' || preority[ch] > preority[op.top()]) {
					// Special case, handle the first character being '-' or '+'
					if (num.empty() && (ch == '-' || ch == '+')) {
						num.push(0);
					}
					op.push(ch); // Push the operator onto the stack
					// Handle expressions inside parentheses
					if (ch == '(') {
						int j = i;
						while (j + 1 < stringsize) {
							// Preprocess the first operator inside the parentheses
							if (s[j + 1] == '-' || s[j + 1] == '+') {
								num.push(0);
							}
							if (s[j + 1] != ' ') {
								break;
							}
							j++;
						}
					}
				} else if (ch == ')') {
					// Handle right parentheses
					char ch2 = ')';
					ch2 = op.top();
					op.pop();
					while (ch2 != '(') {
						int a = num.top();
						num.pop();
						int b = num.top();
						num.pop();
						num.push(operate(a, ch2, b)); // Calculate and push the result
						ch2 = op.top();
						op.pop();
					}
				} else if (preority[ch] <= preority[op.top()]) {
					// Handle cases where the precedence is less than or equal to the top of the stack
					char ch2;
					ch2 = op.top();
					while (!op.empty() && preority[ch] <= preority[op.top()] && ch2 != '(') {
						op.pop();
						int a = num.top();
						num.pop();
						int b = num.top();
						num.pop();
						num.push(operate(a, ch2, b)); // Calculate and push the result
						if (!op.empty()) {
							ch2 = op.top();
						} else {
							break;
						}
					}
					op.push(ch); // Push the current operator onto the stack
				}
			}
		}

		// Handle the remaining expressions in the stack
		while (!op.empty()) {
			ch = op.top();
			op.pop();
			int a = num.top();
			num.pop();
			int b = num.top();
			num.pop();
			num.push(operate(a, ch, b)); // Calculate and push the result
		}

		return num.top(); // Return the final result
	}
};

parse-lisp-expression.solutionCode:
class Solution {
public:
	int i = 0;
	string expr;
	unordered_map<string, vector<int>> scope;

	int evaluate(string expression) {
		expr = expression;
		return eval();
	}

	int eval() {
		if (expr[i] != '(') return islower(expr[i]) ? scope[parseVar()].back() : parseInt();
		int ans = 0;
		++i;
		if (expr[i] == 'l') {
			i += 4;
			vector<string> vars;
			while (1) {
				string var = parseVar();
				if (expr[i] == ')') {
					ans = scope[var].back();
					break;
				}
				++i;
				vars.push_back(var);
				scope[var].push_back(eval());
				++i;
				if (!islower(expr[i])) {
					ans = eval();
					break;
				}
			}
			for (string v : vars) scope[v].pop_back();
		} else {
			bool add = expr[i] == 'a';
			i += add ? 4 : 5;
			int a = eval();
			++i;
			int b = eval();
			ans = add ? a + b : a * b;
		}
		++i;
		return ans;
	}

	string parseVar() {
		int j = i;
		while (i < expr.size() && expr[i] != ' ' && expr[i] != ')') ++i;
		return expr.substr(j, i - j);
	}

	int parseInt() {
		int sign = 1, v = 0;
		if (expr[i] == '-') {
			sign = -1;
			++i;
		}
		while (i < expr.size() && expr[i] >= '0' && expr[i] <= '9') {
			v = v * 10 + (expr[i] - '0');
			++i;
		}
		return sign * v;
	}
};

rotated-digits.solutionCode:
class Solution {
public:
	int rotatedDigits(int n) {
		int d[10] = {0, 1, 5, -1, -1, 2, 9, -1, 8, 6};
		auto check = [&](int x) -> bool {
			int y = 0, t = x;
			int k = 1;
			while (t) {
				int v = t % 10;
				if (d[v] == -1) {
					return false;
				}
				y = d[v] * k + y;
				k *= 10;
				t /= 10;
			}
			return x != y;
		};
		int ans = 0;
		for (int i = 1; i <= n; ++i) {
			ans += check(i);
		}
		return ans;
	}
};

rabbits-in-forest.solutionCode:
class Solution {
public:
	int numRabbits(vector<int>& answers) {
		unordered_map<int, int> cnt;
		for (int x : answers) {
			++cnt[x];
		}
		int ans = 0;
		for (auto& [x, v] : cnt) {
			int group = x + 1;
			ans += (v + group - 1) / group * group;
		}
		return ans;
	}
};

partition-labels.solutionCode:
class Solution {
public:
	vector<int> partitionLabels(string s) {
		int last[26] = {0};
		int n = s.size();
		for (int i = 0; i < n; ++i) {
			last[s[i] - 'a'] = i;
		}
		vector<int> ans;
		int mx = 0, j = 0;
		for (int i = 0; i < n; ++i) {
			mx = max(mx, last[s[i] - 'a']);
			if (mx == i) {
				ans.push_back(i - j + 1);
				j = i + 1;
			}
		}
		return ans;
	}
};

count-different-palindromic-subsequences.solutionCode:
using ll = long long;

class Solution {
public:
	int countPalindromicSubsequences(string s) {
		int mod = 1e9 + 7;
		int n = s.size();
		vector<vector<vector<ll>>> dp(n, vector<vector<ll>>(n, vector<ll>(4)));
		for (int i = 0; i < n; ++i) dp[i][i][s[i] - 'a'] = 1;
		for (int l = 2; l <= n; ++l) {
			for (int i = 0; i + l <= n; ++i) {
				int j = i + l - 1;
				for (char c = 'a'; c <= 'd'; ++c) {
					int k = c - 'a';
					if (s[i] == c && s[j] == c)
						dp[i][j][k] = 2 + accumulate(dp[i + 1][j - 1].begin(), dp[i + 1][j - 1].end(), 0ll) % mod;
					else if (s[i] == c)
						dp[i][j][k] = dp[i][j - 1][k];
					else if (s[j] == c)
						dp[i][j][k] = dp[i + 1][j][k];
					else
						dp[i][j][k] = dp[i + 1][j - 1][k];
				}
			}
		}
		ll ans = accumulate(dp[0][n - 1].begin(), dp[0][n - 1].end(), 0ll);
		return (int) (ans % mod);
	}
};

