design-linked-list.solutionCode:
class MyLinkedList {
private:
	ListNode* dummy = new ListNode();
	int cnt = 0;

public:
	MyLinkedList() {
	}

	int get(int index) {
		if (index < 0 || index >= cnt) {
			return -1;
		}
		auto cur = dummy->next;
		while (index--) {
			cur = cur->next;
		}
		return cur->val;
	}

	void addAtHead(int val) {
		addAtIndex(0, val);
	}

	void addAtTail(int val) {
		addAtIndex(cnt, val);
	}

	void addAtIndex(int index, int val) {
		if (index > cnt) {
			return;
		}
		auto pre = dummy;
		while (index-- > 0) {
			pre = pre->next;
		}
		pre->next = new ListNode(val, pre->next);
		++cnt;
	}

	void deleteAtIndex(int index) {
		if (index >= cnt) {
			return;
		}
		auto pre = dummy;
		while (index-- > 0) {
			pre = pre->next;
		}
		auto t = pre->next;
		pre->next = t->next;
		t->next = nullptr;
		--cnt;
	}
};

/**
 * Your MyLinkedList object will be instantiated and called as such:
 * MyLinkedList* obj = new MyLinkedList();
 * int param_1 = obj->get(index);
 * obj->addAtHead(val);
 * obj->addAtTail(val);
 * obj->addAtIndex(index,val);
 * obj->deleteAtIndex(index);
 */

minimum-ascii-delete-sum-for-two-strings.solutionCode:
class Solution {
public:
	int minimumDeleteSum(string s1, string s2) {
		int m = s1.size(), n = s2.size();
		int f[m + 1][n + 1];
		memset(f, 0, sizeof f);
		for (int i = 1; i <= m; ++i) {
			f[i][0] = f[i - 1][0] + s1[i - 1];
		}
		for (int j = 1; j <= n; ++j) {
			f[0][j] = f[0][j - 1] + s2[j - 1];
		}
		for (int i = 1; i <= m; ++i) {
			for (int j = 1; j <= n; ++j) {
				if (s1[i - 1] == s2[j - 1]) {
					f[i][j] = f[i - 1][j - 1];
				} else {
					f[i][j] = min(f[i - 1][j] + s1[i - 1], f[i][j - 1] + s2[j - 1]);
				}
			}
		}
		return f[m][n];
	}
};

delete-and-earn.solutionCode:
class Solution {
public:
	int deleteAndEarn(vector<int>& nums) {
		vector<int> vals(10010);
		for (int& num : nums) {
			vals[num] += num;
		}
		return rob(vals);
	}

	int rob(vector<int>& nums) {
		int a = 0, b = nums[0];
		for (int i = 1; i < nums.size(); ++i) {
			int c = max(nums[i] + a, b);
			a = b;
			b = c;
		}
		return b;
	}
};

flood-fill.solutionCode:
class Solution {
public:
	vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
		int m = image.size(), n = image[0].size();
		int oc = image[sr][sc];
		if (oc == color) {
			return image;
		}
		const int dirs[5] = {-1, 0, 1, 0, -1};
		auto dfs = [&](this auto&& dfs, int i, int j) -> void {
			image[i][j] = color;
			for (int k = 0; k < 4; ++k) {
				int x = i + dirs[k], y = j + dirs[k + 1];
				if (x >= 0 && x < m && y >= 0 && y < n && image[x][y] == oc) {
					dfs(x, y);
				}
			}
		};
		dfs(sr, sc);
		return image;
	}
};

asteroid-collision.solutionCode:
class Solution {
public:
	vector<int> asteroidCollision(vector<int>& asteroids) {
		vector<int> stk;
		for (int x : asteroids) {
			if (x > 0) {
				stk.push_back(x);
			} else {
				while (stk.size() && stk.back() > 0 && stk.back() < -x) {
					stk.pop_back();
				}
				if (stk.size() && stk.back() == -x) {
					stk.pop_back();
				} else if (stk.empty() || stk.back() < 0) {
					stk.push_back(x);
				}
			}
		}
		return stk;
	}
};

preimage-size-of-factorial-zeroes-functi.solutionCode:
class Solution {
public:
	int preimageSizeFZF(int k) {
		return g(k + 1) - g(k);
	}

	int g(int k) {
		long long left = 0, right = 1ll * 5 * k;
		while (left < right) {
			long long mid = (left + right) >> 1;
			if (f(mid) >= k) {
				right = mid;
			} else {
				left = mid + 1;
			}
		}
		return (int) left;
	}

	int f(long x) {
		int res = 0;
		while (x) {
			x /= 5;
			res += x;
		}
		return res;
	}
};

