sentence-similarity-ii.solutionCode:
class Solution {
public:
	vector<int> p;
	bool areSentencesSimilarTwo(vector<string>& sentence1, vector<string>& sentence2, vector<vector<string>>& similarPairs) {
		if (sentence1.size() != sentence2.size())
			return false;
		int n = similarPairs.size();
		p.resize(n << 1);
		for (int i = 0; i < p.size(); ++i)
			p[i] = i;
		unordered_map<string, int> words;
		int idx = 0;
		for (auto e : similarPairs) {
			string a = e[0], b = e[1];
			if (!words.count(a))
				words[a] = idx++;
			if (!words.count(b))
				words[b] = idx++;
			p[find(words[a])] = find(words[b]);
		}
		for (int i = 0; i < sentence1.size(); ++i) {
			if (sentence1[i] == sentence2[i])
				continue;
			if (!words.count(sentence1[i]) || !words.count(sentence2[i]) || find(words[sentence1[i]]) != find(words[sentence2[i]]))
				return false;
		}
		return true;
	}

	int find(int x) {
		if (p[x] != x)
			p[x] = find(p[x]);
		return p[x];
	}
};

largest-plus-sign.solutionCode:
class Solution {
public:
	int orderOfLargestPlusSign(int n, vector<vector<int>>& mines) {
		vector<vector<int>> dp(n, vector<int>(n, n));
		for (auto& e : mines) dp[e[0]][e[1]] = 0;
		for (int i = 0; i < n; ++i) {
			int left = 0, right = 0, up = 0, down = 0;
			for (int j = 0, k = n - 1; j < n; ++j, --k) {
				left = dp[i][j] ? left + 1 : 0;
				right = dp[i][k] ? right + 1 : 0;
				up = dp[j][i] ? up + 1 : 0;
				down = dp[k][i] ? down + 1 : 0;
				dp[i][j] = min(dp[i][j], left);
				dp[i][k] = min(dp[i][k], right);
				dp[j][i] = min(dp[j][i], up);
				dp[k][i] = min(dp[k][i], down);
			}
		}
		int ans = 0;
		for (auto& e : dp) ans = max(ans, *max_element(e.begin(), e.end()));
		return ans;
	}
};

set-intersection-size-at-least-two.solutionCode:
class Solution {
public:
	int intersectionSizeTwo(vector<vector<int>>& intervals) {
		sort(intervals.begin(), intervals.end(), [&](vector<int>& a, vector<int>& b) {
			return a[1] == b[1] ? a[0] > b[0] : a[1] < b[1];
		});
		int ans = 0;
		int s = -1, e = -1;
		for (auto& v : intervals) {
			int a = v[0], b = v[1];
			if (a <= s) continue;
			if (a > e) {
				ans += 2;
				s = b - 1;
				e = b;
			} else {
				ans += 1;
				s = e;
				e = b;
			}
		}
		return ans;
	}
};

daily-temperatures.solutionCode:
class Solution {
public:
	vector<int> dailyTemperatures(vector<int>& temperatures) {
		int n = temperatures.size();
		stack<int> stk;
		vector<int> ans(n);
		for (int i = n - 1; ~i; --i) {
			while (!stk.empty() && temperatures[stk.top()] <= temperatures[i]) {
				stk.pop();
			}
			if (!stk.empty()) {
				ans[i] = stk.top() - i;
			}
			stk.push(i);
		}
		return ans;
	}
};

