class Trie {
public:
	Trie* children[26] = {nullptr};
	bool isEnd = false;

	void insert(const string& w) {
		Trie* node = this;
		for (char c : w) {
			int idx = c - 'a';
			if (node->children[idx] == nullptr) {
				node->children[idx] = new Trie();
			}
			node = node->children[idx];
		}
		node->isEnd = true;
	}

	bool search(const string& w) {
		Trie* node = this;
		for (char c : w) {
			int idx = c - 'a';
			if (node->children[idx] == nullptr || !node->children[idx]->isEnd) {
				return false;
			}
			node = node->children[idx];
		}
		return true;
	}
};

class Solution {
public:
	string longestWord(vector<string>& words) {
		Trie trie;
		for (const string& w : words) {
			trie.insert(w);
		}

		string ans = "";
		for (const string& w : words) {
			if (trie.search(w) && (ans.length() < w.length() || (ans.length() == w.length() && w < ans))) {
				ans = w;
			}
		}
		return ans;
	}
};

closest-leaf-in-a-binary-tree.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int findClosestLeaf(TreeNode* root, int k) {
		unordered_map<TreeNode*, vector<TreeNode*>> g;
		function<void(TreeNode*, TreeNode*)> dfs = [&](TreeNode* root, TreeNode* fa) {
			if (root) {
				g[root].push_back(fa);
				g[fa].push_back(root);
				dfs(root->left, root);
				dfs(root->right, root);
			}
		};
		dfs(root, nullptr);
		queue<TreeNode*> q;
		unordered_set<TreeNode*> vis;
		for (auto& [node, _] : g) {
			if (node && node->val == k) {
				q.push(node);
				vis.insert(node);
			}
		}
		while (1) {
			auto node = q.front();
			q.pop();
			if (node) {
				if (node->left == node->right) {
					return node->val;
				}
				for (auto& nxt : g[node]) {
					if (vis.count(nxt)) {
						continue;
					}
					q.push(nxt);
					vis.insert(nxt);
				}
			}
		}
	}
};

