class Solution {
public:
	int maxProfit(vector<int>& prices, int fee) {
		int n = prices.size();
		int f[n][2];
		memset(f, -1, sizeof(f));
		function<int(int, int)> dfs = [&](int i, int j) {
			if (i >= prices.size()) {
				return 0;
			}
			if (f[i][j] != -1) {
				return f[i][j];
			}
			int ans = dfs(i + 1, j);
			if (j) {
				ans = max(ans, prices[i] + dfs(i + 1, 0) - fee);
			} else {
				ans = max(ans, -prices[i] + dfs(i + 1, 1));
			}
			return f[i][j] = ans;
		};
		return dfs(0, 0);
	}
};

