contain-virus.solutionCode:
class Solution {
public:
	const vector<int> dirs = {-1, 0, 1, 0, -1};
	vector<int> c;
	vector<vector<int>> areas;
	vector<unordered_set<int>> boundaries;
	vector<vector<int>> infected;
	vector<vector<bool>> vis;
	int m;
	int n;

	int containVirus(vector<vector<int>>& isInfected) {
		infected = isInfected;
		m = infected.size();
		n = infected[0].size();
		vis.assign(m, vector<bool>(n));
		int ans = 0;
		while (1) {
			for (int i = 0; i < m; ++i)
				for (int j = 0; j < n; ++j) vis[i][j] = false;
			c.clear();
			areas.clear();
			boundaries.clear();
			for (int i = 0; i < m; ++i) {
				for (int j = 0; j < n; ++j) {
					if (infected[i][j] == 1 && !vis[i][j]) {
						c.push_back(0);
						areas.push_back({});
						boundaries.push_back({});
						dfs(i, j);
					}
				}
			}
			if (areas.empty()) break;
			int idx = getMax();
			ans += c[idx];
			for (int t = 0; t < areas.size(); ++t) {
				if (t == idx) {
					for (int v : areas[t]) {
						int i = v / n, j = v % n;
						infected[i][j] = -1;
					}
				} else {
					for (int v : areas[t]) {
						int i = v / n, j = v % n;
						for (int k = 0; k < 4; ++k) {
							int x = i + dirs[k], y = j + dirs[k + 1];
							if (x >= 0 && x < m && y >= 0 && y < n && infected[x][y] == 0) infected[x][y] = 1;
						}
					}
				}
			}
		}
		return ans;
	}

	int getMax() {
		int idx = 0;
		int mx = boundaries[0].size();
		for (int i = 1; i < boundaries.size(); ++i) {
			int t = boundaries[i].size();
			if (mx < t) {
				mx = t;
				idx = i;
			}
		}
		return idx;
	}

	void dfs(int i, int j) {
		vis[i][j] = true;
		areas.back().push_back(i * n + j);
		for (int k = 0; k < 4; ++k) {
			int x = i + dirs[k], y = j + dirs[k + 1];
			if (x >= 0 && x < m && y >= 0 && y < n) {
				if (infected[x][y] == 1 && !vis[x][y])
					dfs(x, y);
				else if (infected[x][y] == 0) {
					c.back() += 1;
					boundaries.back().insert(x * n + y);
				}
			}
		}
	}
};

my-calendar-iii.solutionCode:
class Node {
public:
	Node* left;
	Node* right;
	int l;
	int r;
	int mid;
	int v;
	int add;

	Node(int l, int r) {
		this->l = l;
		this->r = r;
		this->mid = (l + r) >> 1;
		this->left = this->right = nullptr;
		v = add = 0;
	}
};

class SegmentTree {
private:
	Node* root;

public:
	SegmentTree() {
		root = new Node(1, 1e9 + 1);
	}

	void modify(int l, int r, int v) {
		modify(l, r, v, root);
	}

	void modify(int l, int r, int v, Node* node) {
		if (l > r) {
			return;
		}
		if (node->l >= l && node->r <= r) {
			node->v += v;
			node->add += v;
			return;
		}
		pushdown(node);
		if (l <= node->mid) {
			modify(l, r, v, node->left);
		}
		if (r > node->mid) {
			modify(l, r, v, node->right);
		}
		pushup(node);
	}

	int query(int l, int r) {
		return query(l, r, root);
	}

	int query(int l, int r, Node* node) {
		if (l > r) {
			return 0;
		}
		if (node->l >= l && node->r <= r) return node->v;
		pushdown(node);
		int v = 0;
		if (l <= node->mid) {
			v = max(v, query(l, r, node->left));
		}
		if (r > node->mid) {
			v = max(v, query(l, r, node->right));
		}
		return v;
	}

	void pushup(Node* node) {
		node->v = max(node->left->v, node->right->v);
	}

	void pushdown(Node* node) {
		if (!node->left) {
			node->left = new Node(node->l, node->mid);
		}
		if (!node->right) {
			node->right = new Node(node->mid + 1, node->r);
		}
		if (node->add) {
			Node* left = node->left;
			Node* right = node->right;
			left->v += node->add;
			right->v += node->add;
			left->add += node->add;
			right->add += node->add;
			node->add = 0;
		}
	}
