class Solution {
public:
	int swimInWater(vector<vector<int>>& grid) {
		int n = grid.size();
		int m = n * n;
		vector<int> p(m);
		iota(p.begin(), p.end(), 0);

		auto find = [&](this auto&& find, int x) -> int {
			if (p[x] != x) {
				p[x] = find(p[x]);
			}
			return p[x];
		};

		vector<int> hi(m);
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				hi[grid[i][j]] = i * n + j;
			}
		}

		array<int, 5> dirs{-1, 0, 1, 0, -1};

		for (int t = 0; t < m; ++t) {
			int id = hi[t];
			int x = id / n, y = id % n;
			for (int k = 0; k < 4; ++k) {
				int nx = x + dirs[k], ny = y + dirs[k + 1];
				if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] <= t) {
					int a = find(x * n + y);
					int b = find(nx * n + ny);
					p[a] = b;
				}
			}
			if (find(0) == find(m - 1)) {
				return t;
			}
		}
		return 0;
	}
};

