class Solution {
public:
	bool reachingPoints(int sx, int sy, int tx, int ty) {
		while (tx > sx && ty > sy && tx != ty) {
			if (tx > ty)
				tx %= ty;
			else
				ty %= tx;
		}
		if (tx == sx && ty == sy) return true;
		if (tx == sx) return ty > sy && (ty - sy) % tx == 0;
