class Solution {
public:
	string minWindow(string s1, string s2) {
		int m = s1.size(), n = s2.size();
		int f[m + 1][n + 1];
		memset(f, 0, sizeof(f));
		for (int i = 1; i <= m; ++i) {
			for (int j = 1; j <= n; ++j) {
				if (s1[i - 1] == s2[j - 1]) {
					f[i][j] = j == 1 ? i : f[i - 1][j - 1];
				} else {
					f[i][j] = f[i - 1][j];
				}
			}
		}
		int p = 0, k = m + 1;
		for (int i = 1; i <= m; ++i) {
			if (s1[i - 1] == s2[n - 1] && f[i][n]) {
				int j = f[i][n] - 1;
				if (i - j < k) {
					k = i - j;
					p = j;
				}
			}
		}
		return k > m ? "" : s1.substr(p, k);
	}
};

