class Solution {
public:
	int minSwapsCouples(vector<int>& row) {
		int n = row.size() / 2;
		int p[n];
		iota(p, p + n, 0);
		function<int(int)> find = [&](int x) -> int {
			if (p[x] != x) {
				p[x] = find(p[x]);
			}
			return p[x];
		};
		for (int i = 0; i < n << 1; i += 2) {
			int a = row[i] >> 1, b = row[i + 1] >> 1;
			p[find(a)] = find(b);
		}
		int ans = n;
		for (int i = 0; i < n; ++i) {
