class Solution {
public:
	int almostPalindromic(string s) {
		int n = s.size();

		auto f = [&](int l, int r) {
			while (l >= 0 && r < n && s[l] == s[r]) {
				--l;
				++r;
			}

			int l1 = l - 1, r1 = r;
			int l2 = l, r2 = r + 1;

			while (l1 >= 0 && r1 < n && s[l1] == s[r1]) {
				--l1;
				++r1;
			}
			while (l2 >= 0 && r2 < n && s[l2] == s[r2]) {
				--l2;
				++r2;
			}

			return min(n, max(r1 - l1 - 1, r2 - l2 - 1));
		};

		int ans = 0;
		for (int i = 0; i < n; ++i) {
			ans = max(ans, f(i, i));
			ans = max(ans, f(i, i + 1));
		}

		return ans;
	}
};

maximum-bitwise-and-after-increment-oper.solutionCode:
class Solution {
public:
	int maximumAND(const vector<int>& nums, int k, int m) {
		int max_val = ranges::max(nums) + k;
		int mx = max_val > 0 ? 32 - __builtin_clz(max_val) : 0;

		int ans = 0;
		vector<int> cost(nums.size());

		for (int bit = mx - 1; bit >= 0; bit--) {
			int target = ans | (1 << bit);
			for (size_t i = 0; i < nums.size(); i++) {
				int x = nums[i];
				int diff = target & ~x;
				int j = diff == 0 ? 0 : 32 - __builtin_clz(diff);
				long long mask = (1L << j) - 1;
				cost[i] = (target & mask) - (x & mask);
			}

			ranges::sort(cost);
			long long sum = accumulate(cost.begin(), cost.begin() + m, 0LL);
			if (sum <= k) {
				ans = target;
			}
		}

		return ans;
	}
};

longest-alternating-subarray-after-remov.solutionCode:
class Solution {
public:
	int longestAlternating(vector<int>& nums) {
		int n = nums.size();
		vector<int> l1(n, 1), l2(n, 1), r1(n, 1), r2(n, 1);

		int ans = 0;

		for (int i = 1; i < n; i++) {
			if (nums[i - 1] < nums[i]) {
				l1[i] = l2[i - 1] + 1;
			} else if (nums[i - 1] > nums[i]) {
				l2[i] = l1[i - 1] + 1;
			}
			ans = max(ans, l1[i]);
			ans = max(ans, l2[i]);
		}

		for (int i = n - 2; i >= 0; i--) {
			if (nums[i + 1] > nums[i]) {
				r1[i] = r2[i + 1] + 1;
			} else if (nums[i + 1] < nums[i]) {
				r2[i] = r1[i + 1] + 1;
			}
		}

		for (int i = 1; i < n - 1; i++) {
			if (nums[i - 1] < nums[i + 1]) {
				ans = max(ans, l2[i - 1] + r2[i + 1]);
			} else if (nums[i - 1] > nums[i + 1]) {
				ans = max(ans, l1[i - 1] + r1[i + 1]);
			}
		}

		return ans;
	}
};

