minimum-operations-to-make-all-grid-elem.solutionCode:
class Solution {
public:
	long long minOperations(vector<vector<int>>& grid, int k) {
		int m = grid.size();
		int n = grid[0].size();
		int mx = grid[0][0];
		for (auto& row : grid) {
			for (int val : row) {
				mx = max(mx, val);
			}
		}

		auto check = [&](int target) -> long long {
			vector<vector<long long>> diff(m + 2, vector<long long>(n + 2, 0));
			long long total_ops = 0;

			for (int i = 1; i <= m; ++i) {
				for (int j = 1; j <= n; ++j) {
					diff[i][j] += diff[i - 1][j] + diff[i][j - 1] - diff[i - 1][j - 1];
					long long cur_val = grid[i - 1][j - 1] + diff[i][j];

					if (cur_val > target) {
						return -1;
					}

					if (cur_val < target) {
						if (i + k - 1 > m || j + k - 1 > n) {
							return -1;
						}

						long long needed = target - cur_val;
						total_ops += needed;
						diff[i][j] += needed;
						diff[i + k][j] -= needed;
						diff[i][j + k] -= needed;
						diff[i + k][j + k] += needed;
					}
				}
			}

			return total_ops;
		};

		for (int t = mx; t <= mx + 1; ++t) {
			long long res = check(t);
			if (res != -1) {
				return res;
			}
		}

		return -1;
	}
};

minimum-removals-to-achieve-target-xor.solutionCode:
class Solution {
public:
	int minRemovals(vector<int>& nums, int target) {
		int mx = ranges::max(nums);
		int m = 0;
		while ((1 << m) <= mx) {
			++m;
		}
		if ((1 << m) <= target) {
			return -1;
		}

		int n = nums.size();
		vector<vector<int>> f(n + 1, vector<int>(1 << m, INT_MIN));
		f[0][0] = 0;

		for (int i = 1; i <= n; i++) {
			int x = nums[i - 1];
			for (int j = 0; j < (1 << m); j++) {
				f[i][j] = max(f[i - 1][j], f[i - 1][j ^ x] + 1);
			}
		}

		if (f[n][target] < 0) {
			return -1;
		}
		return n - f[n][target];
	}
};

design-auction-system.solutionCode:
class AuctionSystem {
	unordered_map<int, set<pair<int, int>>> items;
	unordered_map<int, unordered_map<int, int>> users;

public:
	AuctionSystem() {
	}

	void addBid(int userId, int itemId, int bidAmount) {
		if (users[userId].count(itemId)) {
			removeBid(userId, itemId);
		}
		users[userId][itemId] = bidAmount;
		items[itemId].insert({bidAmount, userId});
	}

	void updateBid(int userId, int itemId, int newAmount) {
		int oldAmount = users[userId][itemId];
		auto& s = items[itemId];
		s.erase({oldAmount, userId});
		s.insert({newAmount, userId});
		users[userId][itemId] = newAmount;
	}

	void removeBid(int userId, int itemId) {
		int oldAmount = users[userId][itemId];
		auto& s = items[itemId];
		s.erase({oldAmount, userId});
		users[userId].erase(itemId);
	}

	int getHighestBidder(int itemId) {
		auto it = items.find(itemId);
		if (it == items.end() || it->second.empty()) {
			return -1;
		}
		return it->second.rbegin()->second;
	}
};

/**
 * Your AuctionSystem object will be instantiated and called as such:
 * AuctionSystem* obj = new AuctionSystem();
