int N = 100001;
int MOD = 1e9 + 7;
long long f[100001];
long long g[100001];

long long qmi(long long a, long long k, long long p) {
	long long res = 1;
	while (k != 0) {
		if ((k & 1) == 1) {
			res = res * a % p;
		}
		k >>= 1;
		a = a * a % p;
	}
	return res;
}

int init = []() {
	f[0] = 1;
	g[0] = 1;
	for (int i = 1; i < N; ++i) {
		f[i] = f[i - 1] * i % MOD;
		g[i] = qmi(f[i], MOD - 2, MOD);
	}
	return 0;
}();

long long comb(int n, int k) {
	return f[n] * g[k] % MOD * g[n - k] % MOD;
}

class Solution {
public:
	int countVisiblePeople(int n, int pos, int k) {
		int l = pos, r = n - pos - 1;
		long long ans = 0;

		for (int a = 0; a <= min(k, l); ++a) {
			int b = k - a;
			if (b <= r) {
				ans = (ans + 2 * comb(l, a) % MOD * comb(r, b) % MOD) % MOD;
			}
		}
		return ans;
	}
};

