class Solution {

	// Trie node for storing prefix XOR values in binary form
	class TrieNode {
		TrieNode[] children = new TrieNode[2]; // 0 and 1 branches
		int count = 0; // number of prefix values passing through this node
	}

	TrieNode root = new TrieNode();

	// Insert or remove a prefix XOR value from the trie
	void updateTrie(int value, int delta) {
		TrieNode current = root;
		for (int bit = 14; bit >= 0; bit--) {
			int currentBit = (value >> bit) & 1;
			if (current.children[currentBit] == null) {
				current.children[currentBit] = new TrieNode();
			}
			current = current.children[currentBit];
			current.count += delta;
		}
	}

	// Find maximum XOR of given value with any value currently in the trie
	int getMaxXor(int value) {
		TrieNode current = root;
		int maxXor = 0;

		for (int bit = 14; bit >= 0; bit--) {
			int currentBit = (value >> bit) & 1;
			int oppositeBit = 1 - currentBit;

			if (current.children[oppositeBit] != null && current.children[oppositeBit].count > 0) {
				maxXor |= (1 << bit);
				current = current.children[oppositeBit];
			} else {
				current = current.children[currentBit];
			}
		}

		return maxXor;
	}

	public int maxXor(int[] nums, int limit) {
		int length = nums.length;

		// Prefix XOR array
		int[] prefixXor = new int[length + 1];
		for (int i = 0; i < length; i++) {
			prefixXor[i + 1] = prefixXor[i] ^ nums[i];
		}

		// Monotonic queues to maintain max and min in sliding window
		Deque<Integer> maxDeque = new ArrayDeque<>();
		Deque<Integer> minDeque = new ArrayDeque<>();

		int left = 0;
		int result = 0;

		updateTrie(prefixXor[0], 1);

		for (int right = 0; right < length; right++) {

			// Maintain decreasing deque for maximum
			while (!maxDeque.isEmpty() && nums[maxDeque.peekLast()] <= nums[right]) {
				maxDeque.pollLast();
			}

			// Maintain increasing deque for minimum
			while (!minDeque.isEmpty() && nums[minDeque.peekLast()] >= nums[right]) {
				minDeque.pollLast();
			}

			maxDeque.addLast(right);
			minDeque.addLast(right);

			// Shrink window if max - min exceeds limit
			while (nums[maxDeque.peekFirst()] - nums[minDeque.peekFirst()] > limit) {

				if (maxDeque.peekFirst() == left) {
					maxDeque.pollFirst();
				}

				if (minDeque.peekFirst() == left) {
					minDeque.pollFirst();
				}

				updateTrie(prefixXor[left], -1);
				left++;
			}

			result = Math.max(result, getMaxXor(prefixXor[right + 1]));
			updateTrie(prefixXor[right + 1], 1);
		}

		return result;
	}
}

maximum-value-of-concatenated-binary-seg.solutionCode:
class Solution {
public:
	static constexpr int MOD = 1'000'000'007;

	int maxValue(vector<int>& nums1, vector<int>& nums0) {
		vector<pair<int, int>> pairs;
		int b = 0;
		for (int i = 0; i < nums1.size(); ++i) {
			pairs.emplace_back(nums1[i], nums0[i]);
			b += nums1[i] + nums0[i];
		}

		sort(pairs.begin(), pairs.end(), [](const auto& a, const auto& b) {
			auto group = [](const pair<int, int>& p) {
				if (p.second == 0) {
					return 0;
				}
				if (p.first > 0) {
					return 1;
				}
				return 2;
			};

			int g1 = group(a), g2 = group(b);
			if (g1 != g2) {
				return g1 < g2;
			}
			if (g1 == 0) {
				return a.first > b.first;
			}
			if (g1 == 1) {
				if (a.first != b.first) {
					return a.first > b.first;
				}
				return a.second < b.second;
			}
			return a.second < b.second;
		});

		vector<long long> p(b, 1);
		for (int i = 1; i < b; ++i) {
			p[i] = p[i - 1] * 2 % MOD;
		}

		long long ans = 0;
		--b;
		for (auto& [cnt1, cnt0] : pairs) {
			while (cnt1--) {
				ans = (ans + p[b--]) % MOD;
			}
			b -= cnt0;
		}
		return (int) ans;
	}
};

maximum-distinct-path-sum-in-a-binary-tr.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int maxSum(TreeNode* root) {
		unordered_map<TreeNode*, vector<TreeNode*>> g;
		unordered_set<int> vis;

		auto dfs = [&](this auto&& dfs, TreeNode* node, TreeNode* p) -> void {
			if (!node) return;
			g[node].push_back(p);
			g[node].push_back(node->left);
			g[node].push_back(node->right);
			dfs(node->left, node);
			dfs(node->right, node);
		};

		auto dfs2 = [&](this auto&& dfs2, TreeNode* node) -> int {
			if (!node || vis.count(node->val)) return 0;
			vis.insert(node->val);
			int res = node->val;
			int best = 0;
			for (auto nxt : g[node]) {
				best = max(best, dfs2(nxt));
			}
			vis.erase(node->val);
			return res + best;
		};

		dfs(root, nullptr);

		int ans = INT_MIN;
		for (auto& [node, _] : g) {
			ans = max(ans, dfs2(node));
			vis.clear();
		}
		return ans;
	}
};

