longest-arithmetic-sequence-after-changi.solutionCode:
class Solution {
public:
	int longestArithmetic(vector<int>& nums) {
		int n = nums.size();
		vector<int> d(n);
		for (int i = 1; i < n; i++) {
			d[i] = nums[i] - nums[i - 1];
		}

		vector<int> f(n, 2), g(n, 2);
		f[0] = 1;
		g[n - 1] = 1;

		for (int i = 2; i < n; i++) {
			if (d[i] == d[i - 1]) {
				f[i] = f[i - 1] + 1;
			}
		}

		for (int i = n - 3; i >= 0; i--) {
			if (d[i + 1] == d[i + 2]) {
				g[i] = g[i + 1] + 1;
			}
		}

		int ans = 3;
		for (int i = 0; i < n; i++) {
			ans = max(ans, max(f[i], g[i]));
			if (i > 0) {
				ans = max(ans, f[i - 1] + 1);
			}
			if (i + 1 < n) {
				ans = max(ans, g[i + 1] + 1);
			}
			if (i > 0 && i < n - 1) {
				int diff = nums[i + 1] - nums[i - 1];
				if (diff % 2 == 0) {
					diff /= 2;
					int k = 3;
					if (i > 1 && diff == d[i - 1]) {
						k += f[i - 1] - 1;
					}
					if (i < n - 2 && diff == d[i + 2]) {
						k += g[i + 1] - 1;
					}
					ans = max(ans, k);
				}
			}
		}
		return ans;
	}
};

