class Solution {
public:
	long long maxScore(vector<int>& nums1, vector<int>& nums2, int K) {
		int n = nums1.size(), m = nums2.size();
		long long NEG = LLONG_MIN / 4;
		vector f(n + 1, vector(m + 1, vector<long long>(K + 1, NEG)));
		f[0][0][0] = 0;
		for (int i = 0; i <= n; i++) {
			for (int j = 0; j <= m; j++) {
				for (int k = 0; k <= K; k++) {
					if (i > 0) {
						f[i][j][k] = max(f[i][j][k], f[i - 1][j][k]);
					}
					if (j > 0) {
						f[i][j][k] = max(f[i][j][k], f[i][j - 1][k]);
					}
					if (i > 0 && j > 0 && k > 0) {
						f[i][j][k] = max(
							f[i][j][k],
							f[i - 1][j - 1][k - 1] + 1LL * nums1[i - 1] * nums2[j - 1]);
					}
				}
			}
		}
		return f[n][m][K];
	}
};

count-fancy-numbers-in-a-range.solutionCode:
class Solution {
public:
	long long countFancy(long long l, long long r) {
		auto check = [&](int s) -> bool {
			if (s < 100) {
				return s % 11 != 0;
			}
			int mid = (s / 10) % 10;
			int last = s % 10;
			return mid > 1 && mid < last;
		};

		string num = to_string(l - 1);
		int n = num.size();
		vector f(n, vector(9 * n + 1, vector(10, vector<long long>(4, -1))));

		auto dfs = [&](this auto&& dfs, int pos, int s, int prev, int st, bool lim) -> long long {
			if (pos >= n) {
				if (st != 3) return 1;
				return check(s) ? 1LL : 0LL;
			}

			if (!lim && f[pos][s][prev][st] != -1) {
				return f[pos][s][prev][st];
			}

			int up = lim ? num[pos] - '0' : 9;
			long long res = 0;

			for (int i = 0; i <= up; i++) {
				int nxtSt = st;

				if (st == 0) {
					if (prev == 0)
						nxtSt = 0;
					else if (i > prev)
						nxtSt = 1;
					else if (i < prev)
						nxtSt = 2;
					else
						nxtSt = 3;
				} else if (st == 1) {
					if (i > prev)
						nxtSt = 1;
					else
						nxtSt = 3;
				} else if (st == 2) {
					if (i < prev)
						nxtSt = 2;
					else
						nxtSt = 3;
				} else {
					nxtSt = 3;
				}

				res += dfs(pos + 1, s + i, i, nxtSt, lim && i == up);
			}

			if (!lim) {
				f[pos][s][prev][st] = res;
			}

			return res;
		};

		long long a = dfs(0, 0, 0, 0, true);

		num = to_string(r);
		n = num.size();
		f.assign(n, vector(9 * n + 1, vector(10, vector<long long>(4, -1))));

		long long b = dfs(0, 0, 0, 0, true);

		return b - a;
	}
};

sum-of-k-digit-numbers-in-a-range.solutionCode:
class Solution {
public:
	int sumOfNumbers(int l, int r, int k) {
		const int mod = 1'000'000'007;

		long long n = 1LL * r - l + 1;

		// ((l + r) * (r - l + 1) / 2) % mod
		long long sum = 1LL * (l + r) * n / 2 % mod;

		// pow(r - l + 1, k - 1, mod)
		long long part1 = qpow(n % mod, k - 1, mod);

		// (pow(10, k, mod) - 1)
		long long part2 = (qpow(10, k, mod) - 1 + mod) % mod;

		// Fermat inverse of 9
		long long inv9 = qpow(9, mod - 2, mod);

		long long ans = sum;
		ans = ans * part1 % mod;
		ans = ans * part2 % mod;
		ans = ans * inv9 % mod;

		return (int) ans;
	}

private:
	long long qpow(long long a, long long n, int mod) {
		long long ans = 1;
		a %= mod;
		while (n > 0) {
			if (n & 1) {
				ans = ans * a % mod;
			}
			a = a * a % mod;
			n >>= 1;
		}
		return ans;
	}
};

