good-subsequence-queries.solutionCode:
class Node {
public:
	int l, r;
	int g;

	Node(int l, int r)
		: l(l)
		, r(r)
		, g(0) {}
};

class SegmentTree {
public:
	vector<Node*> tr;

	SegmentTree(int n)
		: tr(n << 2) {
		build(1, 1, n);
	}

	void build(int u, int l, int r) {
		tr[u] = new Node(l, r);
		if (l == r) {
			return;
		}
		int mid = (l + r) >> 1;
		build(u << 1, l, mid);
		build(u << 1 | 1, mid + 1, r);
	}

	void pushup(int u) {
		tr[u]->g = gcd(tr[u << 1]->g, tr[u << 1 | 1]->g);
	}

	void modify(int u, int x, int v) {
		if (tr[u]->l == tr[u]->r) {
			tr[u]->g = v;
			return;
		}
		int mid = (tr[u]->l + tr[u]->r) >> 1;
		if (x <= mid) {
			modify(u << 1, x, v);
		} else {
			modify(u << 1 | 1, x, v);
		}
		pushup(u);
	}

	int query(int u, int l, int r) {
		if (l > r) {
			return 0;
		}
		if (tr[u]->l >= l && tr[u]->r <= r) {
			return tr[u]->g;
		}
		int mid = (tr[u]->l + tr[u]->r) >> 1;
		if (r <= mid) {
			return query(u << 1, l, r);
		}
		if (l > mid) {
			return query(u << 1 | 1, l, r);
		}
		return gcd(query(u << 1, l, mid), query(u << 1 | 1, mid + 1, r));
	}

	~SegmentTree() {
		for (auto node : tr) {
			delete node;
		}
	}
};

class Solution {
public:
	int countGoodSubseq(vector<int>& nums, int p, vector<vector<int>>& queries) {
		int n = nums.size();
		SegmentTree tree(n);
		int cnt = 0;
		for (int i = 0; i < n; ++i) {
			if (nums[i] % p == 0) {
				tree.modify(1, i + 1, nums[i]);
				++cnt;
			}
		}

		int ans = 0;
		for (auto& q : queries) {
			int idx = q[0], val = q[1];
			if (nums[idx] % p == 0) {
				tree.modify(1, idx + 1, 0);
				--cnt;
			}
			if (val % p == 0) {
				tree.modify(1, idx + 1, val);
				++cnt;
			}
			nums[idx] = val;

			if (tree.tr[1]->g != p) {
				continue;
			}
			if (cnt < n || n > 6) {
				++ans;
				continue;
			}
			for (int i = 1; i <= n; ++i) {
				int leftG = tree.query(1, 1, i - 1);
				int rightG = tree.query(1, i + 1, n);
				if (gcd(leftG, rightG) == p) {
					++ans;
					break;
				}
			}
		}
		return ans;
	}
};

maximum-sum-of-alternating-subsequence-w.solutionCode:
class Solution {
public:
	long long maxAlternatingSum(vector<int>& nums, int K) {
		int n = nums.size();

		// 离散化
		int idx[n];
		map<int, int> mp;
		for (int x : nums) mp[x] = 1;
		int m = 0;
		for (auto& p : mp) p.second = ++m;
		for (int i = 0; i < n; i++) idx[i] = mp[nums[i]];

		const long long INF = 1e18;
		// tree[0]：前缀最大值（用于查询 < nums[i] 的最大 f[j][0]）
		// tree[1]：后缀最大值（用于查询 > nums[i] 的最大 f[j][1]）
		long long tree[2][m + 1];
		for (int i = 0; i < 2; i++)
			for (int j = 0; j <= m; j++) tree[i][j] = -INF;

		// 树状数组模板开始

		auto lb = [&](int x) { return x & (-x); };

		auto update = [&](long long* tree, int pos, long long val) {
			for (; pos <= m; pos += lb(pos)) tree[pos] = max(tree[pos], val);
		};

		auto query = [&](long long* tree, int pos) {
			long long ret = -INF;
			for (; pos; pos -= lb(pos)) ret = max(ret, tree[pos]);
			return ret;
		};

		// 树状数组模板结束

		long long ans = 0;
		long long f[n + 1][2];
		for (int i = 0; i <= n; i++)
			for (int j = 0; j < 2; j++) f[i][j] = -INF;
		// 滑动窗口：只有 j <= i - K 的位置才加入树状数组
		for (int i = 1, j = 1; i <= n; i++) {
			while (i - j >= K) {
				update(tree[0], idx[j - 1], f[j][0]);
				update(tree[1], m + 1 - idx[j - 1], f[j][1]);
				j++;
			}
			// 谷：从 tree[1] 查询值 > nums[i] 的最大 f[j][1]
			f[i][0] = max(0LL, query(tree[1], m - idx[i - 1])) + nums[i - 1];
			// 峰：从 tree[0] 查询值 < nums[i] 的最大 f[j][0]
			f[i][1] = max(0LL, query(tree[0], idx[i - 1] - 1)) + nums[i - 1];
			ans = max({ans, f[i][0], f[i][1]});
		}
		return ans;
	}
};

