		int cnt = 1, l = 1;

		for (int r = 1; r < n; r++) {
			if (nums[r] != nums[r - 1]) {
				cnt = 1;
			} else {
				cnt++;
			}

			if (cnt <= k) {
				nums[l] = nums[r];
				l++;
			}
		}

		nums.resize(l);
		return nums;
	}
};

minimum-operations-to-sort-a-permutation.solutionCode:
class Solution {
public:
	int minOperations(vector<int>& nums) {
		int n = nums.size();

		int zero = ranges::find(nums, 0) - nums.begin();

		auto check = [&](int step) -> bool {
			for (int i = 1; i < n; i++) {
				int prev = (zero + (i - 1) * step + n) % n;
				int curr = (zero + i * step + n) % n;

				if (nums[prev] > nums[curr]) {
					return false;
				}
			}
			return true;
		};

		int ans = INT_MAX;

		if (check(1)) {
			ans = min(ans, zero);
			ans = min(ans, n - zero + 2);
		}

		if (check(-1)) {
			ans = min(ans, zero + 2);
			ans = min(ans, n - zero);
		}

		return ans == INT_MAX ? -1 : ans;
	}
};

