class Solution {
public:
	vector<vector<int>> colorGrid(int n, int m, vector<vector<int>>& sources) {
		vector<vector<int>> ans(n, vector<int>(m, 0));
		vector<array<int, 3>> q;
		int dirs[] = {-1, 0, 1, 0, -1};
		for (auto& s : sources) {
			ans[s[0]][s[1]] = s[2];
			q.push_back({s[0], s[1], s[2]});
		}
		while (!q.empty()) {
			unordered_map<long long, int> vis;
			for (auto& curr : q) {
				int r = curr[0], c = curr[1], color = curr[2];
				for (int i = 0; i < 4; i++) {
					int x = r + dirs[i], y = c + dirs[i + 1];
					if (x >= 0 && x < n && y >= 0 && y < m && ans[x][y] == 0) {
						long long key = (long long) x * m + y;
						if (color > vis[key]) {
							vis[key] = color;
						}
					}
				}
			}
			q.clear();
			for (auto const& [key, color] : vis) {
				int x = key / m;
				int y = key % m;
				ans[x][y] = color;
				q.push_back({x, y, color});
			}
		}
		return ans;
	}
};

power-update-after-k-th-largest-insertio.solutionCode:
class Solution {
public:
	using ll = long long;

	void add(map<int, int>& mp, int x) {
		++mp[x];
	}

	void remove(map<int, int>& mp, int x) {
		if (--mp[x] == 0) {
			mp.erase(x);
		}
	}

	ll qpow(ll a, int b, int mod) {
		ll ans = 1;

		while (b) {
			if (b & 1) {
				ans = ans * a % mod;
			}

			a = a * a % mod;
			b >>= 1;
		}

		return ans;
	}

	vector<int> powerUpdate(vector<int>& nums, int p, vector<vector<int>>& queries) {
		map<int, int> l, r;

		int sz1 = 0, sz2 = nums.size();

		for (int x : nums) {
			add(r, x);
		}

		const int mod = 1e9 + 7;

		vector<int> ans;

		for (auto& q : queries) {
			int val = q[0];
			int k = q[1];

			add(r, val);
			++sz2;

			int v = r.begin()->first;

			remove(r, v);
			--sz2;

			add(l, v);
			++sz1;

			while (sz2 < k) {
				v = l.rbegin()->first;

				remove(l, v);
				--sz1;

				add(r, v);
				++sz2;
			}

			while (sz2 > k) {
				v = r.begin()->first;

				remove(r, v);
				--sz2;

				add(l, v);
				++sz1;
			}

			int x = r.begin()->first;

			p = qpow(p, x, mod);

			ans.push_back(p);
		}

		return ans;
	}
};

