class Solution {
public:
	vector<int> countWordOccurrences(vector<string>& chunks, vector<string>& queries) {
		string s = "";
		for (const string& chunk : chunks) {
			s += chunk;
		}
		int n = s.length();
		unordered_map<string, int> cnt;
		int i = 0;
		while (i < n) {
			if (s[i] == ' ' || s[i] == '-') {
				i++;
				continue;
			}
			int j = i;
			while (j < n && s[j] != ' ' && (s[j] != '-' || (j + 1 < n && s[j + 1] != ' ' && s[j + 1] != '-'))) {
				j++;
			}
			cnt[s.substr(i, j - i)]++;
			i = j;
		}
		vector<int> ans;
		ans.reserve(queries.size());
		for (const string& q : queries) {
			ans.push_back(cnt[q]);
		}
		return ans;
	}
};

minimum-cost-to-move-between-indices.solutionCode:
class Solution {
public:
	vector<int> minCost(vector<int>& nums, vector<vector<int>>& queries) {
		int n = nums.size();
		vector<int> s1(n, 0);
		vector<int> s2(n, 0);
		for (int i = 1; i < n; i++) {
			int c1 = (i > 1 && nums[i - 1] - nums[i - 2] <= nums[i] - nums[i - 1]) ? nums[i] - nums[i - 1] : 1;
			int c2 = (i < n - 1 && nums[i] - nums[i - 1] > nums[i + 1] - nums[i]) ? nums[i] - nums[i - 1] : 1;
			s1[i] = s1[i - 1] + c1;
			s2[i] = s2[i - 1] + c2;
		}
		int m = queries.size();
		vector<int> ans(m);
		for (int i = 0; i < m; i++) {
			int l = queries[i][0];
			int r = queries[i][1];
			ans[i] = (l < r) ? s1[r] - s1[l] : s2[l] - s2[r];
		}
		return ans;
	}
};

