class Solution {
public:
	bool carPooling(vector<vector<int>>& trips, int capacity) {
		int d[1001]{};
		for (auto& trip : trips) {
			int x = trip[0], f = trip[1], t = trip[2];
			d[f] += x;
			d[t] -= x;
		}
		int s = 0;
		for (int x : d) {
			s += x;
			if (s > capacity) {
				return false;
			}
		}
		return true;
	}
};

