			dfs(a + b + c);
		}
	}
};

minimum-cost-to-merge-stones.solutionCode:
class Solution {
public:
	int mergeStones(vector<int>& stones, int K) {
		int n = stones.size();
		if ((n - 1) % (K - 1)) {
			return -1;
		}
		int s[n + 1];
		s[0] = 0;
		for (int i = 1; i <= n; ++i) {
			s[i] = s[i - 1] + stones[i - 1];
		}
		int f[n + 1][n + 1][K + 1];
		memset(f, 0x3f, sizeof(f));
		for (int i = 1; i <= n; ++i) {
			f[i][i][1] = 0;
		}
		for (int l = 2; l <= n; ++l) {
			for (int i = 1; i + l - 1 <= n; ++i) {
				int j = i + l - 1;
				for (int k = 1; k <= K; ++k) {
					for (int h = i; h < j; ++h) {
						f[i][j][k] = min(f[i][j][k], f[i][h][1] + f[h + 1][j][k - 1]);
					}
				}
				f[i][j][1] = f[i][j][K] + s[j] - s[i - 1];
			}
		}
		return f[1][n][1];
	}
};

next-greater-node-in-linked-list.solutionCode:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	vector<int> nextLargerNodes(ListNode* head) {
		vector<int> nums;
		for (; head; head = head->next) {
			nums.push_back(head->val);
		}
		stack<int> stk;
		int n = nums.size();
		vector<int> ans(n);
		for (int i = n - 1; ~i; --i) {
			while (!stk.empty() && stk.top() <= nums[i]) {
				stk.pop();
			}
			if (!stk.empty()) {
				ans[i] = stk.top();
			}
			stk.push(nums[i]);
		}
		return ans;
	}
};

