class Solution {
public:
	int numSubmatrixSumTarget(vector<vector<int>>& matrix, int target) {
		int m = matrix.size(), n = matrix[0].size();
		int ans = 0;
		for (int i = 0; i < m; ++i) {
			vector<int> col(n);
			for (int j = i; j < m; ++j) {
				for (int k = 0; k < n; ++k) {
					col[k] += matrix[j][k];
				}
				ans += f(col, target);
			}
		}
		return ans;
	}

	int f(vector<int>& nums, int target) {
		unordered_map<int, int> d{{0, 1}};
		int cnt = 0, s = 0;
		for (int& x : nums) {
			s += x;
			if (d.count(s - target)) {
				cnt += d[s - target];
			}
			++d[s];
		}
		return cnt;
	}
};

maximum-difference-between-node-and-ance.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int maxAncestorDiff(TreeNode* root) {
		int ans = 0;
		function<void(TreeNode*, int, int)> dfs = [&](TreeNode* root, int mi, int mx) {
			if (!root) {
				return;
			}
			ans = max({ans, abs(mi - root->val), abs(mx - root->val)});
			mi = min(mi, root->val);
			mx = max(mx, root->val);
			dfs(root->left, mi, mx);
			dfs(root->right, mi, mx);
		};
		dfs(root, root->val, root->val);
		return ans;
	}
};

last-stone-weight-ii.solutionCode:
class Solution {
public:
	int lastStoneWeightII(vector<int>& stones) {
		int s = accumulate(stones.begin(), stones.end(), 0);
		int m = stones.size(), n = s >> 1;
		vector<vector<int>> dp(m + 1, vector<int>(n + 1));
		for (int i = 1; i <= m; ++i) {
			for (int j = 0; j <= n; ++j) {
				dp[i][j] = dp[i - 1][j];
				if (stones[i - 1] <= j) dp[i][j] = max(dp[i][j], dp[i - 1][j - stones[i - 1]] + stones[i - 1]);
			}
		}
		return s - dp[m][n] * 2;
	}
};

