		for (int i = 0; i < d; ++i) {
			ans -= arr[i];
		}
		for (int i = d; i < arr.size(); ++i) {
			ans += arr[i];
		}
		string s = to_string(ans);
		return s.substr(0, s.find('.') + 4);
	}
};

escape-a-large-maze.solutionCode:
class Solution {
public:
	bool isEscapePossible(vector<vector<int>>& blocked, vector<int>& source, vector<int>& target) {
		const int n = 1e6;
		int m = blocked.size() * blocked.size() / 2;
		using ll = long long;
		unordered_set<ll> s;
		const int dirs[5] = {-1, 0, 1, 0, -1};
		auto f = [&](int i, int j) {
			return (ll) i * n + j;
		};
		for (const auto& b : blocked) {
			s.insert(f(b[0], b[1]));
		}
		int sx = source[0], sy = source[1];
		int tx = target[0], ty = target[1];
		unordered_set<ll> vis1, vis2;
		auto dfs = [&](this auto&& dfs, int sx, int sy, int tx, int ty, unordered_set<ll>& vis) -> bool {
			vis.insert(f(sx, sy));
			if (vis.size() > m) {
				return true;
			}
			for (int k = 0; k < 4; ++k) {
				int x = sx + dirs[k], y = sy + dirs[k + 1];
				if (x >= 0 && x < n && y >= 0 && y < n) {
					if (x == tx && y == ty) {
						return true;
					}
					auto key = f(x, y);
					if (!s.contains(key) && !vis.contains(key) && dfs(x, y, tx, ty, vis)) {
						return true;
					}
				}
			}
			return false;
		};
		return dfs(sx, sy, tx, ty, vis1) && dfs(tx, ty, sx, sy, vis2);
	}
};

statistics-from-a-large-sample.solutionCode:
class Solution {
public:
	vector<double> sampleStats(vector<int>& count) {
		auto find = [&](int i) -> int {
			for (int k = 0, t = 0;; ++k) {
				t += count[k];
				if (t >= i) {
					return k;
				}
			}
		};
		int mi = 1 << 30, mx = -1;
		long long s = 0;
		int cnt = 0, mode = 0;
		for (int k = 0; k < count.size(); ++k) {
			if (count[k]) {
				mi = min(mi, k);
				mx = max(mx, k);
				s += 1LL * k * count[k];
				cnt += count[k];
				if (count[k] > count[mode]) {
					mode = k;
				}
			}
		}
		double median = cnt % 2 == 1 ? find(cnt / 2 + 1) : (find(cnt / 2) + find(cnt / 2 + 1)) / 2.0;
		return vector<double>{(double) mi, (double) mx, s * 1.0 / cnt, median, (double) mode};
	}
};

capacity-to-ship-packages-within-d-days.solutionCode:
class Solution {
public:
	int shipWithinDays(vector<int>& weights, int days) {
		int left = 0, right = 0;
		for (auto& w : weights) {
			left = max(left, w);
			right += w;
		}
		auto check = [&](int mx) {
			int ws = 0, cnt = 1;
			for (auto& w : weights) {
				ws += w;
				if (ws > mx) {
					ws = w;
					++cnt;
				}
			}
			return cnt <= days;
		};
		while (left < right) {
			int mid = (left + right) >> 1;
			if (check(mid)) {
				right = mid;
			} else {
				left = mid + 1;
			}
		}
		return left;
	}
};

