		sort(arr.begin(), arr.end());
		vector<bool> vis1(n), vis2(m);
		vector<int> ans(n);
		for (auto& [_, i, j] : arr) {
			if (!vis1[i] && !vis2[j]) {
				vis1[i] = true;
				vis2[j] = true;
				ans[i] = j;
			}
		}
		return ans;
	}
};

