class Solution {
public:
	string smallestSubsequence(string s) {
		int n = s.size();
		int last[26] = {0};
		for (int i = 0; i < n; ++i) {
			last[s[i] - 'a'] = i;
		}
		string ans;
		int mask = 0;
		for (int i = 0; i < n; ++i) {
			char c = s[i];
			if ((mask >> (c - 'a')) & 1) {
				continue;
			}
			while (!ans.empty() && ans.back() > c && last[ans.back() - 'a'] > i) {
				mask ^= 1 << (ans.back() - 'a');
				ans.pop_back();
			}
			ans.push_back(c);
			mask |= 1 << (c - 'a');
		}
		return ans;
	}
};

