class Solution {
public:
	int maxSumAfterPartitioning(vector<int>& arr, int k) {
		int n = arr.size();
		int f[n + 1];
		memset(f, 0, sizeof(f));
		for (int i = 1; i <= n; ++i) {
			int mx = 0;
			for (int j = i; j > max(0, i - k); --j) {
				mx = max(mx, arr[j - 1]);
				f[i] = max(f[i], f[j - 1] + mx * (i - j + 1));
			}
		}
		return f[n];
	}
};

