class Trie {
private:
	Trie* children[26]{};
	bool isEnd = false;

public:
	void insert(string& w) {
		Trie* node = this;
		reverse(w.begin(), w.end());
		for (char& c : w) {
			int idx = c - 'a';
			if (!node->children[idx]) {
				node->children[idx] = new Trie();
			}
			node = node->children[idx];
		}
		node->isEnd = true;
	}

	bool search(string& w) {
		Trie* node = this;
		for (int i = w.size() - 1, j = 0; ~i && j < 201; --i, ++j) {
			int idx = w[i] - 'a';
			if (!node->children[idx]) {
				return false;
			}
			node = node->children[idx];
			if (node->isEnd) {
				return true;
			}
		}
		return false;
	}
};

