class Solution {
public:
	int largestSumAfterKNegations(vector<int>& nums, int k) {
		unordered_map<int, int> cnt;
		for (int& x : nums) {
			++cnt[x];
		}
		for (int x = -100; x < 0 && k > 0; ++x) {
			if (cnt[x]) {
				int m = min(cnt[x], k);
				cnt[x] -= m;
				cnt[-x] += m;
				k -= m;
			}
		}
		if ((k & 1) && !cnt[0]) {
			for (int x = 1; x <= 100; ++x) {
				if (cnt[x]) {
					--cnt[x];
					++cnt[-x];
					break;
				}
			}
		}
		int ans = 0;
		for (auto& [x, v] : cnt) {
			ans += x * v;
		}
		return ans;
	}
};

