class Solution {
public:
	vector<vector<int>> colorBorder(vector<vector<int>>& grid, int row, int col, int color) {
		int m = grid.size();
		int n = grid[0].size();
		bool vis[m][n];
		memset(vis, false, sizeof(vis));
		int dirs[5] = {-1, 0, 1, 0, -1};
		function<void(int, int, int)> dfs = [&](int i, int j, int c) {
			vis[i][j] = true;
			for (int k = 0; k < 4; ++k) {
				int x = i + dirs[k];
				int y = j + dirs[k + 1];
				if (x >= 0 && x < m && y >= 0 && y < n) {
					if (!vis[x][y]) {
						if (grid[x][y] == c) {
							dfs(x, y, c);
						} else {
							grid[i][j] = color;
						}
					}
				} else {
					grid[i][j] = color;
				}
			}
		};
		dfs(row, col, grid[row][col]);
		return grid;
	}
};

shortest-common-supersequence.solutionCode:
class Solution {
public:
	string shortestCommonSupersequence(string str1, string str2) {
		int m = str1.size(), n = str2.size();
		vector<vector<int>> f(m + 1, vector<int>(n + 1));
		for (int i = 1; i <= m; ++i) {
			for (int j = 1; j <= n; ++j) {
				if (str1[i - 1] == str2[j - 1])
					f[i][j] = f[i - 1][j - 1] + 1;
				else
					f[i][j] = max(f[i - 1][j], f[i][j - 1]);
			}
		}
		int i = m, j = n;
		string ans;
		while (i || j) {
			if (i == 0)
				ans += str2[--j];
			else if (j == 0)
				ans += str1[--i];
			else {
				if (f[i][j] == f[i - 1][j])
					ans += str1[--i];
				else if (f[i][j] == f[i][j - 1])
					ans += str2[--j];
				else
					ans += str1[--i], --j;
			}
		}
		reverse(ans.begin(), ans.end());
		return ans;
	}
};

digit-count-in-range.solutionCode:
class Solution {
public:
	int d;
	int a[11];
	int dp[11][11];

	int digitsCount(int d, int low, int high) {
		this->d = d;
		return f(high) - f(low - 1);
	}

	int f(int n) {
		memset(dp, -1, sizeof dp);
		int len = 0;
		while (n) {
			a[++len] = n % 10;
			n /= 10;
		}
		return dfs(len, 0, true, true);
	}

	int dfs(int pos, int cnt, bool lead, bool limit) {
		if (pos <= 0) {
			return cnt;
		}
		if (!lead && !limit && dp[pos][cnt] != -1) {
			return dp[pos][cnt];
		}
		int up = limit ? a[pos] : 9;
		int ans = 0;
		for (int i = 0; i <= up; ++i) {
			if (i == 0 && lead) {
				ans += dfs(pos - 1, cnt, lead, limit && i == up);
			} else {
				ans += dfs(pos - 1, cnt + (i == d), false, limit && i == up);
			}
		}
		if (!lead && !limit) {
			dp[pos][cnt] = ans;
		}
		return ans;
	}
};

