class Solution {
public:
	int missingElement(vector<int>& nums, int k) {
		auto missing = [&](int i) {
			return nums[i] - nums[0] - i;
		};
		int n = nums.size();
		if (k > missing(n - 1)) {
			return nums[n - 1] + k - missing(n - 1);
		}
		int l = 0, r = n - 1;
		while (l < r) {
			int mid = (l + r) >> 1;
			if (missing(mid) >= k) {
				r = mid;
			} else {
				l = mid + 1;
			}
		}
		return nums[l - 1] + k - missing(l - 1);
	}
};

