	}
};

shortest-path-in-binary-matrix.solutionCode:
class Solution {
public:
	int shortestPathBinaryMatrix(vector<vector<int>>& grid) {
		if (grid[0][0]) {
			return -1;
		}
		int n = grid.size();
		grid[0][0] = 1;
		queue<pair<int, int>> q;
		q.emplace(0, 0);
		for (int ans = 1; !q.empty(); ++ans) {
			for (int k = q.size(); k; --k) {
				auto [i, j] = q.front();
				q.pop();
				if (i == n - 1 && j == n - 1) {
					return ans;
				}
				for (int x = i - 1; x <= i + 1; ++x) {
					for (int y = j - 1; y <= j + 1; ++y) {
						if (x >= 0 && x < n && y >= 0 && y < n && !grid[x][y]) {
							grid[x][y] = 1;
							q.emplace(x, y);
						}
					}
				}
			}
		}
		return -1;
	}
};

recover-a-tree-from-preorder-traversal.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
	TreeNode* recoverFromPreorder(string S) {
		stack<TreeNode*> st;
		int depth = 0;
		int num = 0;
		for (int i = 0; i < S.length(); ++i) {
			if (S[i] == '-') {
				depth++;
			} else {
				num = 10 * num + S[i] - '0';
			}
			if (i + 1 >= S.length() || (isdigit(S[i]) && S[i + 1] == '-')) {
				TreeNode* newNode = new TreeNode(num);
				while (st.size() > depth) {
					st.pop();
				}
				if (!st.empty()) {
					if (st.top()->left == nullptr) {
						st.top()->left = newNode;
					} else {
						st.top()->right = newNode;
					}
				}
				st.push(newNode);
				depth = 0;
				num = 0;
			}
		}
		TreeNode* res;
		while (!st.empty()) {
			res = st.top();
			st.pop();
		}
		return res;
	}
};

campus-bikes-ii.solutionCode:
class Solution {
public:
	int assignBikes(vector<vector<int>>& workers, vector<vector<int>>& bikes) {
		int n = workers.size(), m = bikes.size();
		int f[n + 1][1 << m];
		memset(f, 0x3f, sizeof(f));
		f[0][0] = 0;
		for (int i = 1; i <= n; ++i) {
			for (int j = 0; j < 1 << m; ++j) {
				for (int k = 0; k < m; ++k) {
					if (j >> k & 1) {
						int d = abs(workers[i - 1][0] - bikes[k][0]) + abs(workers[i - 1][1] - bikes[k][1]);
						f[i][j] = min(f[i][j], f[i - 1][j ^ (1 << k)] + d);
					}
				}
			}
		}
		return *min_element(f[n], f[n] + (1 << m));
	}
};

find-in-mountain-array.solutionCode:
/**
 * // This is the MountainArray's API interface.
 * // You should not implement it, or speculate about its implementation
 * class MountainArray {
 *   public:
 *     int get(int index);
 *     int length();
 * };
 */

class Solution {
public:
	int findInMountainArray(int target, MountainArray& mountainArr) {
		int n = mountainArr.length();
		int l = 0, r = n - 1;
		while (l < r) {
			int mid = (l + r) >> 1;
			if (mountainArr.get(mid) > mountainArr.get(mid + 1)) {
				r = mid;
			} else {
				l = mid + 1;
			}
		}
		auto search = [&](int l, int r, int k) -> int {
			while (l < r) {
				int mid = (l + r) >> 1;
				if (k * mountainArr.get(mid) >= k * target) {
					r = mid;
				} else {
					l = mid + 1;
				}
			}
			return mountainArr.get(l) == target ? l : -1;
		};
		int ans = search(0, l, 1);
		return ans == -1 ? search(l + 1, n - 1, -1) : ans;
	}
};

