class Solution {
public:
	string longestNiceSubstring(string s) {
		int n = s.size();
		int k = -1, mx = 0;
		for (int i = 0; i < n; ++i) {
			unordered_set<char> ss;
			for (int j = i; j < n; ++j) {
				ss.insert(s[j]);
				bool ok = true;
				for (auto& a : ss) {
					char b = a ^ 32;
					if (!(ss.count(a) && ss.count(b))) {
						ok = false;
						break;
					}
				}
				if (ok && mx < j - i + 1) {
					mx = j - i + 1;
					k = i;
				}
			}
		}
		return k == -1 ? "" : s.substr(k, mx);
	}
};

