maximum-score-of-a-good-subarray.solutionCode:
class Solution {
public:
	int maximumScore(vector<int>& nums, int k) {
		int n = nums.size();
		vector<int> left(n, -1);
		vector<int> right(n, n);
		stack<int> stk;
		for (int i = 0; i < n; ++i) {
			int v = nums[i];
			while (!stk.empty() && nums[stk.top()] >= v) {
				stk.pop();
			}
			if (!stk.empty()) {
				left[i] = stk.top();
			}
			stk.push(i);
		}
		stk = stack<int>();
		for (int i = n - 1; i >= 0; --i) {
			int v = nums[i];
			while (!stk.empty() && nums[stk.top()] > v) {
				stk.pop();
			}
			if (!stk.empty()) {
				right[i] = stk.top();
			}
			stk.push(i);
		}
		int ans = 0;
		for (int i = 0; i < n; ++i) {
			if (left[i] + 1 <= k && k <= right[i] - 1) {
				ans = max(ans, nums[i] * (right[i] - left[i] - 1));
			}
		}
		return ans;
	}
};

