maximum-average-pass-ratio.solutionCode:
class Solution {
public:
	double maxAverageRatio(vector<vector<int>>& classes, int extraStudents) {
		priority_queue<tuple<double, int, int>> pq;
		for (auto& e : classes) {
			int a = e[0], b = e[1];
			double x = (double) (a + 1) / (b + 1) - (double) a / b;
			pq.push({x, a, b});
		}
		while (extraStudents--) {
			auto [_, a, b] = pq.top();
			pq.pop();
			a++;
			b++;
			double x = (double) (a + 1) / (b + 1) - (double) a / b;
			pq.push({x, a, b});
		}
		double ans = 0;
		while (pq.size()) {
			auto [_, a, b] = pq.top();
			pq.pop();
			ans += (double) a / b;
		}
		return ans / classes.size();
	}
};

