class Solution {
public:
	vector<double> getCollisionTimes(vector<vector<int>>& cars) {
		int n = cars.size();
		vector<double> ans(n, -1.0);
		stack<int> stk;
		for (int i = n - 1; ~i; --i) {
			while (stk.size()) {
				int j = stk.top();
				if (cars[i][1] > cars[j][1]) {
					double t = (cars[j][0] - cars[i][0]) * 1.0 / (cars[i][1] - cars[j][1]);
					if (ans[j] < 0 || t <= ans[j]) {
						ans[i] = t;
						break;
					}
				}
				stk.pop();
			}
			stk.push(i);
		}
		return ans;
	}
};

