count-ways-to-make-array-with-product.solutionCode:
int N = 10020;
int MOD = 1e9 + 7;
long f[10020];
long g[10020];
vector<int> p[10020];

long qmi(long a, long k, long p) {
	long res = 1;
	while (k != 0) {
		if ((k & 1) == 1) {
			res = res * a % p;
		}
		k >>= 1;
		a = a * a % p;
	}
	return res;
}

int init = []() {
	f[0] = 1;
	g[0] = 1;
	for (int i = 1; i < N; ++i) {
		f[i] = f[i - 1] * i % MOD;
		g[i] = qmi(f[i], MOD - 2, MOD);
		int x = i;
		for (int j = 2; j <= x / j; ++j) {
			if (x % j == 0) {
				int cnt = 0;
				while (x % j == 0) {
					++cnt;
					x /= j;
				}
				p[i].push_back(cnt);
			}
		}
		if (x > 1) {
			p[i].push_back(1);
		}
	}
	return 0;
}();

int comb(int n, int k) {
	return (f[n] * g[k] % MOD) * g[n - k] % MOD;
}

class Solution {
public:
	vector<int> waysToFillArray(vector<vector<int>>& queries) {
		vector<int> ans;
		for (auto& q : queries) {
			int n = q[0], k = q[1];
			long long t = 1;
			for (int x : p[k]) {
				t = t * comb(x + n - 1, n - 1) % MOD;
			}
			ans.push_back(t);
		}
		return ans;
	}
};

