/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	ListNode* swapNodes(ListNode* head, int k) {
		ListNode* fast = head;
		while (--k) {
			fast = fast->next;
		}
		ListNode* slow = head;
		ListNode* p = fast;
		while (fast->next) {
			fast = fast->next;
			slow = slow->next;
		}
		ListNode* q = slow;
		swap(p->val, q->val);
		return head;
	}
};

count-pairs-of-nodes.solutionCode:
class Solution {
public:
	vector<int> countPairs(int n, vector<vector<int>>& edges, vector<int>& queries) {
		vector<int> cnt(n);
		unordered_map<int, int> g;
		for (auto& e : edges) {
			int a = e[0] - 1, b = e[1] - 1;
			++cnt[a];
			++cnt[b];
			int k = min(a, b) * n + max(a, b);
			++g[k];
		}
		vector<int> s = cnt;
		sort(s.begin(), s.end());
		vector<int> ans(queries.size());
		for (int i = 0; i < queries.size(); ++i) {
			int t = queries[i];
			for (int j = 0; j < n; ++j) {
				int x = s[j];
				int k = upper_bound(s.begin() + j + 1, s.end(), t - x) - s.begin();
				ans[i] += n - k;
			}
			for (auto& [k, v] : g) {
				int a = k / n, b = k % n;
				if (cnt[a] + cnt[b] > t && cnt[a] + cnt[b] - v <= t) {
					--ans[i];
				}
			}
		}
		return ans;
	}
};

maximum-number-of-events-that-can-be-att.solutionCode:
class Solution {
public:
	int maxValue(vector<vector<int>>& events, int k) {
		ranges::sort(events);
		int n = events.size();
		int f[n][k + 1];
		memset(f, 0, sizeof(f));
		auto dfs = [&](this auto&& dfs, int i, int k) -> int {
			if (i >= n || k <= 0) {
				return 0;
			}
			if (f[i][k] > 0) {
				return f[i][k];
			}

			int ed = events[i][1], val = events[i][2];
			vector<int> t = {ed};

			int p = upper_bound(events.begin() + i + 1, events.end(), t,
						[](const auto& a, const auto& b) { return a[0] < b[0]; })
				- events.begin();

			f[i][k] = max(dfs(i + 1, k), dfs(p, k - 1) + val);
			return f[i][k];
		};

		return dfs(0, k);
	}
};

