class Solution {
public:
	bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
		vector<vector<int>> g(numCourses);
		vector<int> indeg(numCourses);
		for (auto& p : prerequisites) {
			int a = p[0], b = p[1];
			g[b].push_back(a);
			++indeg[a];
		}
		queue<int> q;
		for (int i = 0; i < numCourses; ++i) {
			if (indeg[i] == 0) {
				q.push(i);
			}
		}
		while (!q.empty()) {
			int i = q.front();
			q.pop();
			--numCourses;
			for (int j : g[i]) {
				if (--indeg[j] == 0) {
					q.push(j);
				}
			}
		}
		return numCourses == 0;
	}
};

