class Solution {
public:
	int n;
	vector<string> ans;
	unordered_map<char, int> cnt;

	vector<string> generatePalindromes(string s) {
		n = s.size();
		for (char c : s) ++cnt[c];
		string mid = "";
		for (auto& [k, v] : cnt) {
			if (v & 1) {
				if (mid != "") {
					return ans;
				}
				mid += k;
			}
		}
		dfs(mid);
		return ans;
	}

	void dfs(string t) {
		if (t.size() == n) {
			ans.push_back(t);
			return;
		}
		for (auto& [k, v] : cnt) {
			if (v > 1) {
				v -= 2;
				dfs(k + t + k);
				v += 2;
			}
		}
	}
};

