					stk.pop();
					stk.push(t * v);
				} else {
					int t = stk.top();
					stk.pop();
					stk.push(t / v);
				}
				sign = c;
				v = 0;
			}
		}
		int ans = 0;
		while (!stk.empty()) {
			ans += stk.top();
			stk.pop();
		}
		return ans;
	}
};

