class Solution {
public:
	vector<int> maxSlidingWindow(vector<int>& nums, int k) {
		priority_queue<pair<int, int>> q;
		int n = nums.size();
		for (int i = 0; i < k - 1; ++i) {
			q.push({nums[i], -i});
		}
		vector<int> ans;
		for (int i = k - 1; i < n; ++i) {
			q.push({nums[i], -i});
			while (-q.top().second <= i - k) {
				q.pop();
			}
			ans.emplace_back(q.top().first);
		}
		return ans;
	}
};

