class Solution {
public:
	bool validTree(int n, vector<vector<int>>& edges) {
		vector<int> p(n);
		iota(p.begin(), p.end(), 0);
		function<int(int)> find = [&](int x) {
			if (p[x] != x) {
				p[x] = find(p[x]);
			}
			return p[x];
		};
		for (auto& e : edges) {
			int pa = find(e[0]), pb = find(e[1]);
			if (pa == pb) {
				return false;
			}
			p[pa] = pb;
			--n;
		}
		return n == 1;
	}
};

