		k = n - k;
		auto quickSort = [&](auto&& quickSort, int l, int r) -> int {
			if (l == r) {
				return nums[l];
			}
			int i = l - 1, j = r + 1;
			int x = nums[(l + r) >> 1];
			while (i < j) {
				while (nums[++i] < x) {
				}
				while (nums[--j] > x) {
				}
				if (i < j) {
					swap(nums[i], nums[j]);
				}
			}
			if (j < k) {
				return quickSort(quickSort, j + 1, r);
			}
			return quickSort(quickSort, l, j);
		};
		return quickSort(quickSort, 0, n - 1);
	}
};

