		for (int i = n - 1, right = 1; ~i; --i) {
			ans[i] *= right;
			right *= nums[i];
		}
		return ans;
	}
};

closest-binary-search-tree-value.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int closestValue(TreeNode* root, double target) {
		int ans = root->val;
		double diff = INT_MAX;
		function<void(TreeNode*)> dfs = [&](TreeNode* node) {
			if (!node) {
				return;
			}
			double nxt = abs(node->val - target);
			if (nxt < diff || (nxt == diff && node->val < ans)) {
				diff = nxt;
				ans = node->val;
			}
			node = target < node->val ? node->left : node->right;
			dfs(node);
		};
		dfs(root);
		return ans;
	}
};

the-skyline-problem.solutionCode:
class Solution {
public:
	vector<pair<int, int>> getSkyline(vector<vector<int>>& buildings) {
		set<int> poss;
		map<int, int> m;
		for (auto v : buildings) {
			poss.insert(v[0]);
			poss.insert(v[1]);
		}

		int i = 0;
		for (int pos : poss)
			m.insert(pair<int, int>(pos, i++));

		vector<int> highs(m.size(), 0);
		for (auto v : buildings) {
			const int b = m[v[0]], e = m[v[1]];
			for (int i = b; i < e; ++i)
				highs[i] = max(highs[i], v[2]);
		}

		vector<pair<int, int>> res;
		vector<int> mm(poss.begin(), poss.end());
		for (int i = 0; i < highs.size(); ++i) {
			if (highs[i] != highs[i + 1])
				res.push_back(pair<int, int>(mm[i], highs[i]));
			else {
				const int start = i;
				res.push_back(pair<int, int>(mm[start], highs[i]));
				while (highs[i] == highs[i + 1])
					++i;
			}
		}
		return res;
	}
};

