shortest-palindrome.solutionCode:
typedef unsigned long long ull;

class Solution {
public:
	string shortestPalindrome(string s) {
		int base = 131;
		ull mul = 1;
		ull prefix = 0;
		ull suffix = 0;
		int idx = 0, n = s.size();
		for (int i = 0; i < n; ++i) {
			int t = s[i] - 'a' + 1;
			prefix = prefix * base + t;
			suffix = suffix + mul * t;
			mul *= base;
			if (prefix == suffix) idx = i + 1;
		}
		if (idx == n) return s;
		string x = s.substr(idx, n - idx);
		reverse(x.begin(), x.end());
		return x + s;
	}
};

