class WordDictionary {
private:
	trie* root;

public:
	WordDictionary()
		: root(new trie) {}

	void addWord(string word) {
		root->insert(word);
	}

	bool search(string word) {
		return dfs(word, 0, root);
	}

private:
	bool dfs(const string& word, int i, trie* cur) {
		if (i == word.size()) {
			return cur->is_end;
		}
		char c = word[i];
		if (c != '.') {
			trie* child = cur->children[c - 'a'];
			if (child != nullptr && dfs(word, i + 1, child)) {
				return true;
