class Solution {
public:
	int numSquares(int n) {
		int m = sqrt(n);
		int f[m + 1][n + 1];
		memset(f, 0x3f, sizeof(f));
		f[0][0] = 0;
		for (int i = 1; i <= m; ++i) {
			for (int j = 0; j <= n; ++j) {
				f[i][j] = f[i - 1][j];
				if (j >= i * i) {
					f[i][j] = min(f[i][j], f[i][j - i * i] + 1);
				}
			}
		}
		return f[m][n];
	}
};

