		int n1 = 0, n2 = 0;
		int m1 = 0, m2 = 1;
		for (int m : nums) {
			if (m == m1)
				++n1;
			else if (m == m2)
				++n2;
			else if (n1 == 0) {
				m1 = m;
				++n1;
			} else if (n2 == 0) {
				m2 = m;
				++n2;
			} else {
				--n1;
				--n2;
