				if (u != n) ans.push_back('0' + v + '0');
			}
			return ans;
		};

		int a = low.size(), b = high.size();
		int ans = 0;
		ll l = stoll(low), r = stoll(high);
		for (n = a; n <= b; ++n) {
			for (auto& s : dfs(n)) {
				ll v = stoll(s);
				if (l <= v && v <= r) {
					++ans;
				}
			}
		}
		return ans;
	}
};

