		if (word1 == word2) {
			for (int i = 0, j = -1; i < n; ++i) {
				if (wordsDict[i] == word1) {
					if (j != -1) {
						ans = min(ans, i - j);
					}
					j = i;
				}
			}
		} else {
			for (int k = 0, i = -1, j = -1; k < n; ++k) {
				if (wordsDict[k] == word1) {
					i = k;
				}
				if (wordsDict[k] == word2) {
					j = k;
				}
				if (i != -1 && j != -1) {
					ans = min(ans, abs(i - j));
				}
			}
		}
		return ans;
	}
};

