class Solution {
public:
	vector<int> splitIntoFibonacci(string num) {
		int n = num.size();
		vector<int> ans;
		function<bool(int)> dfs = [&](int i) -> bool {
			if (i == n) {
				return ans.size() > 2;
			}
			long long x = 0;
			for (int j = i; j < n; ++j) {
				if (j > i && num[i] == '0') {
					break;
				}
				x = x * 10 + num[j] - '0';
				if (x > INT_MAX || (ans.size() > 1 && x > (long long) ans[ans.size() - 1] + ans[ans.size() - 2])) {
					break;
				}
				if (ans.size() < 2 || x == (long long) ans[ans.size() - 1] + ans[ans.size() - 2]) {
					ans.push_back(x);
					if (dfs(j + 1)) {
						return true;
					}
					ans.pop_back();
				}
			}
			return false;
		};
		dfs(0);
		return ans;
	}
};

