class Solution {
public:
	vector<int> sumOfDistancesInTree(int n, vector<vector<int>>& edges) {
		vector<vector<int>> g(n);
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		vector<int> ans(n);
		vector<int> size(n);

		function<void(int, int, int)> dfs1 = [&](int i, int fa, int d) {
			ans[0] += d;
			size[i] = 1;
			for (int& j : g[i]) {
				if (j != fa) {
					dfs1(j, i, d + 1);
					size[i] += size[j];
				}
			}
		};

		function<void(int, int, int)> dfs2 = [&](int i, int fa, int t) {
			ans[i] = t;
			for (int& j : g[i]) {
				if (j != fa) {
					dfs2(j, i, t - size[j] + n - size[j]);
				}
			}
		};

		dfs1(0, -1, 0);
		dfs2(0, -1, ans[0]);
		return ans;
	}
};

magic-squares-in-grid.solutionCode:
class Solution {
public:
	int numMagicSquaresInside(vector<vector<int>>& grid) {
		int m = grid.size();
		int n = grid[0].size();
		int ans = 0;
		auto check = [&](int i, int j) {
			if (i + 3 > m || j + 3 > n) {
				return 0;
			}
			vector<int> cnt(16);
			vector<int> row(3);
			vector<int> col(3);
			int a = 0, b = 0;
			for (int x = i; x < i + 3; ++x) {
				for (int y = j; y < j + 3; ++y) {
					int v = grid[x][y];
					if (v < 1 || v > 9 || ++cnt[v] > 1) {
						return 0;
					}
					row[x - i] += v;
					col[y - j] += v;
					if (x - i == y - j) {
						a += v;
					}
					if (x - i + y - j == 2) {
						b += v;
					}
				}
			}
			if (a != b) {
				return 0;
			}
			for (int k = 0; k < 3; ++k) {
				if (row[k] != a || col[k] != a) {
					return 0;
				}
			}
			return 1;
		};
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				ans += check(i, j);
			}
		}
		return ans;
	}
};

