		int l = 1, r = ranges::max(piles);
		while (l < r) {
			int mid = (l + r) >> 1;
			int s = 0;
			for (int x : piles) {
				s += (x + mid - 1) / mid;
			}
			if (s <= h) {
				r = mid;
			} else {
				l = mid + 1;
			}
		}
		return l;
	}
};

race-car.solutionCode:
class Solution {
public:
	int racecar(int target) {
		vector<int> dp(target + 1);
		for (int i = 1; i <= target; ++i) {
			int k = 32 - __builtin_clz(i);
			if (i == (1 << k) - 1) {
				dp[i] = k;
				continue;
			}
			dp[i] = dp[(1 << k) - 1 - i] + k + 1;
			for (int j = 0; j < k; ++j) {
				dp[i] = min(dp[i], dp[i - (1 << (k - 1)) + (1 << j)] + k - 1 + j + 2);
			}
		}
		return dp[target];
	}
};

