shortest-subarray-with-sum-at-least-k.solutionCode:
class Solution {
public:
	int shortestSubarray(vector<int>& nums, int k) {
		int n = nums.size();
		vector<long> s(n + 1);
		for (int i = 0; i < n; ++i) s[i + 1] = s[i] + nums[i];
		deque<int> q;
		int ans = n + 1;
		for (int i = 0; i <= n; ++i) {
			while (!q.empty() && s[i] - s[q.front()] >= k) {
				ans = min(ans, i - q.front());
				q.pop_front();
			}
			while (!q.empty() && s[q.back()] >= s[i]) q.pop_back();
			q.push_back(i);
		}
		return ans > n ? -1 : ans;
	}
};

shortest-path-to-get-all-keys.solutionCode:
class Solution {
public:
	const static inline vector<int> dirs = {-1, 0, 1, 0, -1};

	int shortestPathAllKeys(vector<string>& grid) {
		int m = grid.size(), n = grid[0].size();
		int k = 0;
		int si = 0, sj = 0;
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				char c = grid[i][j];
				// 累加钥匙数量
				if (islower(c)) ++k;
				// 起点
				else if (c == '@')
					si = i, sj = j;
			}
		}
		queue<tuple<int, int, int>> q{{{si, sj, 0}}};
		vector<vector<vector<bool>>> vis(m, vector<vector<bool>>(n, vector<bool>(1 << k)));
		vis[si][sj][0] = true;
		int ans = 0;
		while (!q.empty()) {
			for (int t = q.size(); t; --t) {
				auto [i, j, state] = q.front();
				q.pop();
				// 找到所有钥匙，返回当前步数
				if (state == (1 << k) - 1) return ans;
				// 往四个方向搜索
				for (int h = 0; h < 4; ++h) {
					int x = i + dirs[h], y = j + dirs[h + 1];
					// 在边界范围内
					if (x >= 0 && x < m && y >= 0 && y < n) {
						char c = grid[x][y];
						// 是墙，或者是锁，但此时没有对应的钥匙，无法通过
						if (c == '#' || (isupper(c) && (state >> (c - 'A') & 1) == 0)) continue;
						int nxt = state;
						// 是钥匙，更新状态
						if (islower(c)) nxt |= 1 << (c - 'a');
						// 此状态未访问过，入队
						if (!vis[x][y][nxt]) {
							vis[x][y][nxt] = true;
							q.push({x, y, nxt});
						}
					}
				}
			}
			// 步数加一
			++ans;
		}
		return -1;
	}
};

smallest-subtree-with-all-the-deepest-no.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	TreeNode* subtreeWithAllDeepest(TreeNode* root) {
		using pti = pair<TreeNode*, int>;
		auto dfs = [&](this auto&& dfs, TreeNode* root) -> pti {
			if (!root) {
				return {nullptr, 0};
			}
			auto [l, ld] = dfs(root->left);
			auto [r, rd] = dfs(root->right);
			if (ld > rd) {
				return {l, ld + 1};
			}
			if (ld < rd) {
				return {r, rd + 1};
			}
			return {root, ld + 1};
		};
		return dfs(root).first;
	}
};

push-dominoes.solutionCode:
class Solution {
public:
	string pushDominoes(string dominoes) {
		int n = dominoes.size();
		queue<int> q;
		vector<int> time(n, -1);
		vector<string> force(n);
		for (int i = 0; i < n; i++) {
			if (dominoes[i] == '.') continue;
			q.emplace(i);
			time[i] = 0;
			force[i].push_back(dominoes[i]);
		}

		string ans(n, '.');
		while (!q.empty()) {
			int i = q.front();
			q.pop();
			if (force[i].size() == 1) {
				char f = force[i][0];
				ans[i] = f;
				int j = (f == 'L') ? (i - 1) : (i + 1);
				if (j >= 0 && j < n) {
					int t = time[i];
					if (time[j] == -1) {
						q.emplace(j);
						time[j] = t + 1;
						force[j].push_back(f);
					} else if (time[j] == t + 1)
						force[j].push_back(f);
				}
			}
		}
		return ans;
	}
};

