using ll = long long;

class Solution {
public:
	const int mod = 1e9 + 7;

	int nthMagicalNumber(int n, int a, int b) {
		int c = lcm(a, b);
		ll l = 0, r = 1ll * (a + b) * n;
		while (l < r) {
			ll mid = l + r >> 1;
			if (mid / a + mid / b - mid / c >= n)
				r = mid;
			else
				l = mid + 1;
		}
		return l % mod;
	}
};

reachable-nodes-in-subdivided-graph.solutionCode:
class Solution {
public:
	int reachableNodes(vector<vector<int>>& edges, int maxMoves, int n) {
		using pii = pair<int, int>;
		vector<vector<pii>> g(n);
		for (auto& e : edges) {
			int u = e[0], v = e[1], cnt = e[2] + 1;
			g[u].emplace_back(v, cnt);
			g[v].emplace_back(u, cnt);
		}
		priority_queue<pii, vector<pii>, greater<pii>> q;
		q.emplace(0, 0);
		int dist[n];
		memset(dist, 0x3f, sizeof dist);
		dist[0] = 0;
		while (!q.empty()) {
			auto [d, u] = q.top();
			q.pop();
			for (auto& [v, cnt] : g[u]) {
				if (d + cnt < dist[v]) {
					dist[v] = d + cnt;
					q.emplace(dist[v], v);
				}
			}
		}
		int ans = 0;
		for (int& d : dist) ans += d <= maxMoves;
		for (auto& e : edges) {
			int u = e[0], v = e[1], cnt = e[2];
			int a = min(cnt, max(0, maxMoves - dist[u]));
			int b = min(cnt, max(0, maxMoves - dist[v]));
			ans += min(cnt, a + b);
		}
		return ans;
	}
};

split-array-with-same-average.solutionCode:
class Solution {
public:
	bool splitArraySameAverage(vector<int>& nums) {
		int n = nums.size();
		if (n == 1) return false;
		int s = accumulate(nums.begin(), nums.end(), 0);
		for (int& v : nums) v = v * n - s;
		int m = n >> 1;
		unordered_set<int> vis;
		for (int i = 1; i < 1 << m; ++i) {
			int t = 0;
			for (int j = 0; j < m; ++j)
				if (i >> j & 1) t += nums[j];
			if (t == 0) return true;
			vis.insert(t);
		}
		for (int i = 1; i < 1 << (n - m); ++i) {
			int t = 0;
			for (int j = 0; j < (n - m); ++j)
				if (i >> j & 1) t += nums[m + j];
			if (t == 0 || (i != (1 << (n - m)) - 1 && vis.count(-t))) return true;
		}
		return false;
	}
};

walking-robot-simulation.solutionCode:
class Solution {
public:
	int robotSim(vector<int>& commands, vector<vector<int>>& obstacles) {
		int dirs[5] = {0, 1, 0, -1, 0};
		auto f = [](int x, int y) {
			return x * 60010 + y;
		};
		unordered_set<int> s;
		for (auto& e : obstacles) {
			s.insert(f(e[0], e[1]));
		}
		int ans = 0, k = 0;
		int x = 0, y = 0;
		for (int c : commands) {
			if (c == -2) {
				k = (k + 3) % 4;
			} else if (c == -1) {
				k = (k + 1) % 4;
			} else {
				while (c--) {
					int nx = x + dirs[k], ny = y + dirs[k + 1];
					if (s.count(f(nx, ny))) {
						break;
					}
					x = nx;
					y = ny;
					ans = max(ans, x * x + y * y);
				}
			}
		}
		return ans;
	}
};

all-possible-full-binary-trees.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	vector<TreeNode*> allPossibleFBT(int n) {
		vector<vector<TreeNode*>> f(n + 1);
		function<vector<TreeNode*>(int)> dfs = [&](int n) -> vector<TreeNode*> {
			if (f[n].size()) {
				return f[n];
			}
			if (n == 1) {
				return vector<TreeNode*>{new TreeNode()};
			}
			vector<TreeNode*> ans;
			for (int i = 0; i < n - 1; ++i) {
				int j = n - 1 - i;
				for (auto left : dfs(i)) {
					for (auto right : dfs(j)) {
						ans.push_back(new TreeNode(0, left, right));
					}
				}
			}
			return f[n] = ans;
		};
		return dfs(n);
	}
};

making-a-large-island.solutionCode:
class Solution {
public:
	int largestIsland(vector<vector<int>>& grid) {
		int n = grid.size();
		int p[n][n];
		memset(p, 0, sizeof(p));
		int cnt[n * n + 1];
		memset(cnt, 0, sizeof(cnt));
		const int dirs[5] = {-1, 0, 1, 0, -1};
		int root = 0;
		int ans = 0;
		function<int(int, int)> dfs = [&](int i, int j) {
			p[i][j] = root;
			++cnt[root];
			for (int k = 0; k < 4; ++k) {
				int x = i + dirs[k];
				int y = j + dirs[k + 1];
				if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] && !p[x][y]) {
					dfs(x, y);
				}
			}
			return cnt[root];
		};
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j] && !p[i][j]) {
					++root;
					ans = max(ans, dfs(i, j));
				}
			}
		}
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				if (!grid[i][j]) {
					unordered_set<int> s;
					for (int k = 0; k < 4; ++k) {
						int x = i + dirs[k];
						int y = j + dirs[k + 1];
						if (x >= 0 && x < n && y >= 0 && y < n) {
							s.insert(p[x][y]);
						}
					}
					int t = 1;
					for (int x : s) {
						t += cnt[x];
					}
					ans = max(ans, t);
				}
			}
		}
		return ans;
	}
};

