	int primePalindrome(int n) {
		while (1) {
			if (reverse(n) == n && isPrime(n)) return n;
			if (n > 10000000 && n < 100000000) n = 100000000;
			++n;
		}
	}

	bool isPrime(int x) {
		if (x < 2) return false;
		for (int v = 2; v * v <= x; ++v)
			if (x % v == 0)
				return false;
		return true;
	}

	int reverse(int x) {
		int res = 0;
		while (x) {
			res = res * 10 + x % 10;
			x /= 10;
		}
		return res;
	}
};

