rectangle-area-ii.solutionCode:
class Node {
public:
	int l, r, cnt, length;
};

class SegmentTree {
public:
	vector<Node*> tr;
	vector<int> nums;

	SegmentTree(vector<int>& nums) {
		this->nums = nums;
		int n = nums.size() - 1;
		tr.resize(n << 2);
		for (int i = 0; i < tr.size(); ++i) tr[i] = new Node();
		build(1, 0, n - 1);
	}

	void build(int u, int l, int r) {
		tr[u]->l = l;
		tr[u]->r = r;
		if (l != r) {
			int mid = (l + r) >> 1;
			build(u << 1, l, mid);
			build(u << 1 | 1, mid + 1, r);
		}
	}

	void modify(int u, int l, int r, int k) {
		if (tr[u]->l >= l && tr[u]->r <= r)
			tr[u]->cnt += k;
		else {
			int mid = (tr[u]->l + tr[u]->r) >> 1;
			if (l <= mid) modify(u << 1, l, r, k);
			if (r > mid) modify(u << 1 | 1, l, r, k);
		}
		pushup(u);
	}

	int query() {
		return tr[1]->length;
	}

	void pushup(int u) {
		if (tr[u]->cnt)
			tr[u]->length = nums[tr[u]->r + 1] - nums[tr[u]->l];
		else if (tr[u]->l == tr[u]->r)
			tr[u]->length = 0;
		else
			tr[u]->length = tr[u << 1]->length + tr[u << 1 | 1]->length;
	}
};

class Solution {
public:
	const int mod = 1e9 + 7;

	int rectangleArea(vector<vector<int>>& rectangles) {
		int n = rectangles.size();
		vector<vector<int>> segs(n << 1);
		set<int> ts;
		int i = 0;
		for (auto& e : rectangles) {
			int x1 = e[0], y1 = e[1], x2 = e[2], y2 = e[3];
			segs[i++] = {x1, y1, y2, 1};
			segs[i++] = {x2, y1, y2, -1};
			ts.insert(y1);
			ts.insert(y2);
		}
		sort(segs.begin(), segs.end());
		unordered_map<int, int> m;
		i = 0;
		for (int v : ts) m[v] = i++;
		vector<int> nums(ts.begin(), ts.end());
		SegmentTree* tree = new SegmentTree(nums);
		long long ans = 0;
		for (int i = 0; i < segs.size(); ++i) {
			auto e = segs[i];
			int x = e[0], y1 = e[1], y2 = e[2], k = e[3];
			if (i > 0) ans += (long long) tree->query() * (x - segs[i - 1][0]);
			tree->modify(1, m[y1], m[y2] - 1, k);
		}
		ans %= mod;
		return (int) ans;
	}
};

profitable-schemes.solutionCode:
class Solution {
public:
	int profitableSchemes(int n, int minProfit, vector<int>& group, vector<int>& profit) {
		int m = group.size();
		int f[m][n + 1][minProfit + 1];
		memset(f, -1, sizeof(f));
		const int mod = 1e9 + 7;
		function<int(int, int, int)> dfs = [&](int i, int j, int k) -> int {
			if (i >= m) {
				return k == minProfit ? 1 : 0;
			}
			if (f[i][j][k] != -1) {
				return f[i][j][k];
			}
			int ans = dfs(i + 1, j, k);
			if (j + group[i] <= n) {
				ans += dfs(i + 1, j + group[i], min(k + profit[i], minProfit));
			}
			ans %= mod;
			return f[i][j][k] = ans;
		};
		return dfs(0, 0, 0);
	}
};

all-nodes-distance-k-in-binary-tree.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
	vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
		unordered_map<TreeNode*, TreeNode*> g;
		vector<int> ans;

		auto dfs = [&](this auto&& dfs, TreeNode* node, TreeNode* fa) {
			if (!node) return;
			g[node] = fa;
			dfs(node->left, node);
			dfs(node->right, node);
		};

		auto dfs2 = [&](this auto&& dfs2, TreeNode* node, TreeNode* fa, int k) {
			if (!node) return;
			if (k == 0) {
				ans.push_back(node->val);
				return;
			}
			for (auto&& nxt : {node->left, node->right, g[node]}) {
				if (nxt != fa) {
					dfs2(nxt, node, k - 1);
				}
			}
		};

		dfs(root, nullptr);
		dfs2(target, nullptr, k);
		return ans;
	}
};

