class Solution {
public:
	string decodeAtIndex(string s, int k) {
		long long m = 0;
		for (char& c : s) {
			if (isdigit(c)) {
				m *= (c - '0');
			} else {
				++m;
			}
		}
		for (int i = s.size() - 1;; --i) {
			k %= m;
			if (k == 0 && isalpha(s[i])) {
				return string(1, s[i]);
			}
			if (isdigit(s[i])) {
				m /= (s[i] - '0');
			} else {
				--m;
			}
		}
	}
};

stone-game.solutionCode:
class Solution {
public:
	bool stoneGame(vector<int>& piles) {
		int n = piles.size();
		int f[n][n];
		memset(f, 0, sizeof(f));
		auto dfs = [&](this auto&& dfs, int i, int j) -> int {
			if (i > j) {
				return 0;
			}
			if (f[i][j]) {
				return f[i][j];
			}
			return f[i][j] = max(piles[i] - dfs(i + 1, j), piles[j] - dfs(i, j - 1));
		};
		return dfs(0, n - 1) > 0;
	}
};

expressive-words.solutionCode:
class Solution {
public:
	int expressiveWords(string s, vector<string>& words) {
		auto check = [](string& s, string& t) -> int {
			int m = s.size(), n = t.size();
			if (n > m) return 0;
			int i = 0, j = 0;
			while (i < m && j < n) {
				if (s[i] != t[j]) return 0;
				int k = i;
				while (k < m && s[k] == s[i]) ++k;
				int c1 = k - i;
				i = k, k = j;
				while (k < n && t[k] == t[j]) ++k;
				int c2 = k - j;
				j = k;
				if (c1 < c2 || (c1 < 3 && c1 != c2)) return 0;
			}
			return i == m && j == n;
		};

		int ans = 0;
		for (string& t : words) ans += check(s, t);
		return ans;
	}
};

