class Solution {
public:
	double new21Game(int n, int k, int maxPts) {
		vector<double> f(k);
		auto dfs = [&](this auto&& dfs, int i) -> double {
			if (i >= k) {
				return i <= n ? 1 : 0;
			}
			if (i == k - 1) {
				return min(n - k + 1, maxPts) * 1.0 / maxPts;
			}
			if (f[i]) {
				return f[i];
			}
			return f[i] = dfs(i + 1) + (dfs(i + 1) - dfs(i + maxPts + 1)) / maxPts;
		};
		return dfs(0);
	}
};

