class Solution {
public:
	vector<int> loudAndRich(vector<vector<int>>& richer, vector<int>& quiet) {
		int n = quiet.size();
		vector<vector<int>> g(n);
		for (auto& r : richer) {
			g[r[1]].push_back(r[0]);
		}
		vector<int> ans(n, -1);
		function<void(int)> dfs = [&](int i) {
			if (ans[i] != -1) {
				return;
			}
			ans[i] = i;
			for (int j : g[i]) {
				dfs(j);
				if (quiet[ans[j]] < quiet[ans[i]]) {
					ans[i] = ans[j];
				}
			}
		};
		for (int i = 0; i < n; ++i) {
			dfs(i);
		}
		return ans;
	}
};

largest-sum-of-averages.solutionCode:
class Solution {
public:
	double largestSumOfAverages(vector<int>& nums, int k) {
		int n = nums.size();
		int s[n + 1];
		double f[n][k + 1];
		memset(f, 0, sizeof(f));
		s[0] = 0;
		for (int i = 0; i < n; ++i) {
			s[i + 1] = s[i] + nums[i];
		}
		auto dfs = [&](this auto&& dfs, int i, int k) -> double {
			if (i == n) {
				return 0;
			}
			if (k == 1) {
				return (s[n] - s[i]) * 1.0 / (n - i);
			}
			if (f[i][k] > 0) {
				return f[i][k];
			}
			double ans = 0;
			for (int j = i + 1; j < n; ++j) {
				ans = max(ans, (s[j] - s[i]) * 1.0 / (j - i) + dfs(j, k - 1));
			}
			return f[i][k] = ans;
		};
		return dfs(0, k);
	}
};

