class Solution {
public:
	vector<int> exclusiveTime(int n, vector<string>& logs) {
		vector<int> ans(n);
		stack<int> stk;
		int pre = 0;
		for (const auto& log : logs) {
			int i, cur;
			char c[10];
			sscanf(log.c_str(), "%d:%[^:]:%d", &i, c, &cur);
			if (c[0] == 's') {
				if (stk.size()) {
					ans[stk.top()] += cur - pre;
				}
				stk.push(i);
				pre = cur;
			} else {
				ans[stk.top()] += cur - pre + 1;
				stk.pop();
				pre = cur + 1;
			}
		}
		return ans;
	}
};

