		int n = s.size();
		vector<int> d(n);
		iota(d.begin(), d.end(), 0);
		for (int i = n - 2; ~i; --i) {
			if (s[i] <= s[d[i + 1]]) {
				d[i] = d[i + 1];
			}
		}
