class Solution {
public:
	bool judgeSquareSum(int c) {
		long long a = 0, b = sqrt(c);
		while (a <= b) {
			long long s = a * a + b * b;
			if (s == c) {
				return true;
			}
			if (s < c) {
				++a;
			} else {
				--b;
			}
		}
		return false;
	}
};

