shopping-offers.solutionCode:
class Solution {
public:
	int shoppingOffers(vector<int>& price, vector<vector<int>>& special, vector<int>& needs) {
		const int bits = 4;
		int n = needs.size();
		unordered_map<int, int> f;
		int mask = 0;
		for (int i = 0; i < n; ++i) {
			mask |= needs[i] << (i * bits);
		}
		function<int(int)> dfs = [&](int cur) {
			if (f.contains(cur)) {
				return f[cur];
			}
			int ans = 0;
			for (int i = 0; i < n; ++i) {
				ans += price[i] * ((cur >> (i * bits)) & 0xf);
			}
			for (const auto& offer : special) {
				int nxt = cur;
				bool ok = true;
				for (int j = 0; j < n; ++j) {
					if (((cur >> (j * bits)) & 0xf) < offer[j]) {
						ok = false;
						break;
					}
					nxt -= offer[j] << (j * bits);
				}
				if (ok) {
					ans = min(ans, offer[n] + dfs(nxt));
				}
			}
			f[cur] = ans;
			return ans;
		};
		return dfs(mask);
	}
};

