class Solution {
public:
	double findMaxAverage(vector<int>& nums, int k) {
		double eps = 1e-5;
		double l = *min_element(nums.begin(), nums.end());
		double r = *max_element(nums.begin(), nums.end());
		auto check = [&](double v) {
			double s = 0;
			for (int i = 0; i < k; ++i) {
				s += nums[i] - v;
			}
			if (s >= 0) {
				return true;
			}
			double t = 0;
			double mi = 0;
			for (int i = k; i < nums.size(); ++i) {
				s += nums[i] - v;
				t += nums[i - k] - v;
				mi = min(mi, t);
				if (s >= mi) {
					return true;
				}
			}
			return false;
		};
		while (r - l >= eps) {
			double mid = (l + r) / 2;
			if (check(mid)) {
				l = mid;
			} else {
				r = mid;
			}
		}
		return l;
	}
};

