		if (isEmpty()) return -1;
		return q[front];
	}

	int Rear() {
		if (isEmpty()) return -1;
		int idx = (front + size - 1) % capacity;
		return q[idx];
	}

	bool isEmpty() {
		return size == 0;
	}

	bool isFull() {
		return size == capacity;
	}
};

