class Solution {
public:
	vector<int> smallestRange(vector<vector<int>>& nums) {
		int n = 0;
		for (auto& v : nums) n += v.size();
		vector<pair<int, int>> t(n);
		int k = nums.size();
		for (int i = 0, j = 0; i < k; ++i) {
			for (int v : nums[i]) {
				t[j++] = {v, i};
			}
		}
		sort(t.begin(), t.end());
		int j = 0;
		unordered_map<int, int> cnt;
		vector<int> ans = {-1000000, 1000000};
		for (int i = 0; i < n; ++i) {
			int b = t[i].first;
			int v = t[i].second;
			++cnt[v];
			while (cnt.size() == k) {
				int a = t[j].first;
				int w = t[j].second;
				int x = b - a - (ans[1] - ans[0]);
				if (x < 0 || (x == 0 && a < ans[0])) {
					ans[0] = a;
					ans[1] = b;
				}
				if (--cnt[w] == 0) {
					cnt.erase(w);
				}
				++j;
			}
		}
		return ans;
	}
};

