class Solution {
public:
	int waysToReachTarget(int target, vector<vector<int>>& types) {
		int n = types.size();
		const int mod = 1e9 + 7;
		int f[n + 1][target + 1];
		memset(f, 0, sizeof(f));
		f[0][0] = 1;
		for (int i = 1; i <= n; ++i) {
			int count = types[i - 1][0], marks = types[i - 1][1];
			for (int j = 0; j <= target; ++j) {
				for (int k = 0; k <= count; ++k) {
					if (j >= k * marks) {
						f[i][j] = (f[i][j] + f[i - 1][j - k * marks]) % mod;
					}
				}
			}
		}
		return f[n][target];
	}
};

