find-score-of-an-array-after-marking-all.solutionCode:
class Solution {
public:
	long long findScore(vector<int>& nums) {
		int n = nums.size();
		vector<bool> vis(n);
		using pii = pair<int, int>;
		priority_queue<pii, vector<pii>, greater<pii>> q;
		for (int i = 0; i < n; ++i) {
			q.emplace(nums[i], i);
		}
		long long ans = 0;
		while (!q.empty()) {
			auto [x, i] = q.top();
			q.pop();
			ans += x;
			vis[i] = true;
			if (i + 1 < n) {
				vis[i + 1] = true;
			}
			if (i - 1 >= 0) {
				vis[i - 1] = true;
			}
			while (!q.empty() && vis[q.top().second]) {
				q.pop();
			}
		}
		return ans;
	}
};

