const int N = 4001;
int f[N][N];
int g[N][N];

class Solution {
public:
	long long countQuadruplets(vector<int>& nums) {
		int n = nums.size();
		memset(f, 0, sizeof f);
		memset(g, 0, sizeof g);
		for (int j = 1; j < n - 2; ++j) {
			int cnt = 0;
			for (int l = j + 1; l < n; ++l) {
				if (nums[l] > nums[j]) {
					++cnt;
				}
			}
			for (int k = j + 1; k < n - 1; ++k) {
				if (nums[j] > nums[k]) {
					f[j][k] = cnt;
				} else {
					--cnt;
				}
			}
		}
		long long ans = 0;
		for (int k = 2; k < n - 1; ++k) {
			int cnt = 0;
			for (int i = 0; i < k; ++i) {
				if (nums[i] < nums[k]) {
					++cnt;
				}
			}
			for (int j = k - 1; j > 0; --j) {
				if (nums[j] > nums[k]) {
					g[j][k] = cnt;
					ans += 1ll * f[j][k] * g[j][k];
				} else {
					--cnt;
				}
			}
		}
		return ans;
	}
};

maximum-tastiness-of-candy-basket.solutionCode:
class Solution {
public:
	int maximumTastiness(vector<int>& price, int k) {
		sort(price.begin(), price.end());
		int l = 0, r = price.back() - price[0];
		auto check = [&](int x) -> bool {
			int cnt = 0, pre = -x;
			for (int& cur : price) {
				if (cur - pre >= x) {
					pre = cur;
					++cnt;
				}
			}
			return cnt >= k;
		};
		while (l < r) {
			int mid = (l + r + 1) >> 1;
			if (check(mid)) {
				l = mid;
			} else {
				r = mid - 1;
			}
		}
		return l;
	}
};

