count-anagrams.solutionCode:
class Solution {
public:
	const int mod = 1e9 + 7;

	int countAnagrams(string s) {
		stringstream ss(s);
		string w;
		long ans = 1, mul = 1;
		while (ss >> w) {
			int cnt[26] = {0};
			for (int i = 1; i <= w.size(); ++i) {
				int c = w[i - 1] - 'a';
				++cnt[c];
				ans = ans * i % mod;
				mul = mul * cnt[c] % mod;
			}
		}
		return ans * pow(mul, mod - 2) % mod;
	}

	long pow(long x, int n) {
		long res = 1L;
		for (; n; n /= 2) {
			if (n % 2) res = res * x % mod;
			x = x * x % mod;
		}
		return res;
	}
};

