count-number-of-possible-root-nodes.solutionCode:
class Solution {
public:
	int rootCount(vector<vector<int>>& edges, vector<vector<int>>& guesses, int k) {
		int n = edges.size() + 1;
		vector<int> g[n];
		unordered_map<long long, int> gs;
		auto f = [&](int i, int j) {
			return 1LL * i * n + j;
		};
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		for (auto& e : guesses) {
			int a = e[0], b = e[1];
			gs[f(a, b)]++;
		}
		int ans = 0;
		int cnt = 0;

		function<void(int, int)> dfs1 = [&](int i, int fa) {
			for (int& j : g[i]) {
				if (j != fa) {
					cnt += gs[f(i, j)];
					dfs1(j, i);
				}
			}
		};

		function<void(int, int)> dfs2 = [&](int i, int fa) {
			ans += cnt >= k;
			for (int& j : g[i]) {
				if (j != fa) {
					int a = gs[f(i, j)];
					int b = gs[f(j, i)];
					cnt -= a;
					cnt += b;
					dfs2(j, i);
					cnt -= b;
					cnt += a;
				}
			}
		};
		dfs1(0, -1);
		dfs2(0, -1);
		return ans;
	}
};

