maximum-frequency-score-of-a-subarray.solutionCode:
class Solution {
public:
	int maxFrequencyScore(vector<int>& nums, int k) {
		using ll = long long;
		const int mod = 1e9 + 7;
		auto qpow = [&](ll a, ll n) {
			ll ans = 1;
			for (; n; n >>= 1) {
				if (n & 1) {
					ans = ans * a % mod;
				}
				a = a * a % mod;
			}
			return ans;
		};
		unordered_map<int, int> cnt;
		for (int i = 0; i < k; ++i) {
			cnt[nums[i]]++;
		}
		ll cur = 0;
		for (auto& [k, v] : cnt) {
			cur = (cur + qpow(k, v)) % mod;
		}
		ll ans = cur;
		for (int i = k; i < nums.size(); ++i) {
			int a = nums[i - k], b = nums[i];
			if (a != b) {
				cur += cnt[b] ? (b - 1) * qpow(b, cnt[b]) % mod : b;
				cur -= cnt[a] > 1 ? (a - 1) * qpow(a, cnt[a] - 1) % mod : a;
				cur = (cur + mod) % mod;
				ans = max(ans, cur);
				cnt[b]++;
				cnt[a]--;
			}
		}
		return ans;
	}
};

count-the-number-of-k-big-indices.solutionCode:
class BinaryIndexedTree {
public:
	BinaryIndexedTree(int _n)
		: n(_n)
		, c(_n + 1) {}

	void update(int x, int delta) {
		while (x <= n) {
			c[x] += delta;
			x += x & -x;
		}
	}

	int query(int x) {
		int s = 0;
		while (x) {
			s += c[x];
			x -= x & -x;
		}
		return s;
	}

private:
	int n;
	vector<int> c;
};

class Solution {
public:
	int kBigIndices(vector<int>& nums, int k) {
		int n = nums.size();
		BinaryIndexedTree* tree1 = new BinaryIndexedTree(n);
		BinaryIndexedTree* tree2 = new BinaryIndexedTree(n);
		for (int& v : nums) {
			tree2->update(v, 1);
		}
		int ans = 0;
		for (int& v : nums) {
			tree2->update(v, -1);
			ans += tree1->query(v - 1) >= k && tree2->query(v - 1) >= k;
			tree1->update(v, 1);
		}
		return ans;
	}
};

maximum-number-of-points-from-grid-queri.solutionCode:
class Solution {
public:
	const int dirs[5] = {-1, 0, 1, 0, -1};

	vector<int> maxPoints(vector<vector<int>>& grid, vector<int>& queries) {
		int k = queries.size();
		vector<pair<int, int>> qs(k);
		for (int i = 0; i < k; ++i) qs[i] = {queries[i], i};
		sort(qs.begin(), qs.end());
		vector<int> ans(k);
		int m = grid.size(), n = grid[0].size();
		bool vis[m][n];
		memset(vis, 0, sizeof vis);
		vis[0][0] = true;
		priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> q;
		q.push({grid[0][0], 0, 0});
		int cnt = 0;
		for (auto& e : qs) {
			int v = e.first;
			k = e.second;
			while (!q.empty() && get<0>(q.top()) < v) {
				auto [_, i, j] = q.top();
				q.pop();
				++cnt;
				for (int h = 0; h < 4; ++h) {
					int x = i + dirs[h], y = j + dirs[h + 1];
					if (x >= 0 && x < m && y >= 0 && y < n && !vis[x][y]) {
						vis[x][y] = true;
						q.push({grid[x][y], x, y});
					}
				}
