subsequence-with-the-minimum-score.solutionCode:
class Solution {
public:
	int minimumScore(string s, string t) {
		int m = s.size(), n = t.size();
		vector<int> f(n, 1e6);
		vector<int> g(n, -1);
		for (int i = 0, j = 0; i < m && j < n; ++i) {
			if (s[i] == t[j]) {
				f[j] = i;
				++j;
			}
		}
		for (int i = m - 1, j = n - 1; i >= 0 && j >= 0; --i) {
			if (s[i] == t[j]) {
				g[j] = i;
				--j;
			}
		}

		auto check = [&](int len) {
			for (int k = 0; k < n; ++k) {
				int i = k - 1, j = k + len;
				int l = i >= 0 ? f[i] : -1;
				int r = j < n ? g[j] : m + 1;
				if (l < r) {
					return true;
				}
			}
			return false;
		};

		int l = 0, r = n;
		while (l < r) {
			int mid = (l + r) >> 1;
			if (check(mid)) {
				r = mid;
			} else {
				l = mid + 1;
			}
		}
		return l;
	}
};

count-collisions-of-monkeys-on-a-polygon.solutionCode:
class Solution {
public:
	int monkeyMove(int n) {
		const int mod = 1e9 + 7;
		using ll = long long;
		auto qpow = [&](ll a, int n) {
			ll ans = 1;
			for (; n; n >>= 1) {
				if (n & 1) {
					ans = ans * a % mod;
				}
				a = a * a % mod;
			}
			return ans;
		};
		return (qpow(2, n) - 2 + mod) % mod;
	}
};

maximize-the-minimum-powered-city.solutionCode:
class Solution {
public:
	long long maxPower(vector<int>& stations, int r, int k) {
		int n = stations.size();
		long long d[n + 1];
		memset(d, 0, sizeof d);
		for (int i = 0; i < n; ++i) {
			int left = max(0, i - r), right = min(i + r, n - 1);
			d[left] += stations[i];
			d[right + 1] -= stations[i];
		}
		long long s[n + 1];
		s[0] = d[0];
		for (int i = 1; i < n + 1; ++i) {
			s[i] = s[i - 1] + d[i];
		}
		auto check = [&](long long x, int k) {
			memset(d, 0, sizeof d);
			long long t = 0;
			for (int i = 0; i < n; ++i) {
				t += d[i];
				long long dist = x - (s[i] + t);
				if (dist > 0) {
					if (k < dist) {
						return false;
					}
					k -= dist;
					int j = min(i + r, n - 1);
					int left = max(0, j - r), right = min(j + r, n - 1);
					d[left] += dist;
					d[right + 1] -= dist;
					t += dist;
				}
			}
			return true;
		};
		long long left = 0, right = 1e12;
		while (left < right) {
			long long mid = (left + right + 1) >> 1;
			if (check(mid, k)) {
				left = mid;
			} else {
				right = mid - 1;
			}
		}
		return left;
	}
};

substring-xor-queries.solutionCode:
class Solution {
public:
	vector<vector<int>> substringXorQueries(string s, vector<vector<int>>& queries) {
		unordered_map<int, vector<int>> d;
		int n = s.size();
		for (int i = 0; i < n; ++i) {
			int x = 0;
			for (int j = 0; j < 32 && i + j < n; ++j) {
				x = x << 1 | (s[i + j] - '0');
				if (!d.count(x)) {
					d[x] = {i, i + j};
				}
				if (x == 0) {
					break;
				}
			}
		}
		vector<vector<int>> ans;
		for (auto& q : queries) {
			int first = q[0], second = q[1];
			int val = first ^ second;
			if (d.count(val)) {
				ans.emplace_back(d[val]);
			} else {
				ans.push_back({-1, -1});
			}
		}
		return ans;
	}
};

