closest-prime-numbers-in-range.solutionCode:
class Solution {
public:
	vector<int> closestPrimes(int left, int right) {
		int cnt = 0;
		bool st[right + 1];
		memset(st, 0, sizeof st);
		int prime[right + 1];
		for (int i = 2; i <= right; ++i) {
			if (!st[i]) {
				prime[cnt++] = i;
			}
			for (int j = 0; prime[j] <= right / i; ++j) {
				st[prime[j] * i] = true;
				if (i % prime[j] == 0) {
					break;
				}
			}
		}
		int i = -1, j = -1;
		for (int k = 0; k < cnt; ++k) {
			if (prime[k] >= left && prime[k] <= right) {
				if (i == -1) {
					i = k;
				}
				j = k;
			}
		}
		vector<int> ans = {-1, -1};
		if (i == j || i == -1) return ans;
		int mi = 1 << 30;
		for (int k = i; k < j; ++k) {
			int d = prime[k + 1] - prime[k];
			if (d < mi) {
				mi = d;
				ans[0] = prime[k];
				ans[1] = prime[k + 1];
			}
		}
		return ans;
	}
};

maximum-number-of-integers-to-choose-fro.solutionCode:
class Solution {
public:
	int maxCount(vector<int>& banned, int n, long long maxSum) {
		banned.push_back(0);
		banned.push_back(n + 1);
		sort(banned.begin(), banned.end());
		banned.erase(unique(banned.begin(), banned.end()), banned.end());
		int ans = 0;
		for (int k = 1; k < banned.size(); ++k) {
			int i = banned[k - 1], j = banned[k];
			int left = 0, right = j - i - 1;
			while (left < right) {
				int mid = left + ((right - left + 1) / 2);
				if ((i + 1 + i + mid) * 1LL * mid / 2 <= maxSum) {
					left = mid;
				} else {
					right = mid - 1;
				}
			}
			ans += left;
			maxSum -= (i + 1 + i + left) * 1LL * left / 2;
			if (maxSum <= 0) {
				break;
			}
		}
		return ans;
	}
};

