minimum-cost-to-split-an-array.solutionCode:
class Solution {
public:
	int minCost(vector<int>& nums, int k) {
		int n = nums.size();
		int f[n];
		memset(f, 0, sizeof f);
		function<int(int)> dfs = [&](int i) {
			if (i >= n) {
				return 0;
			}
			if (f[i]) {
				return f[i];
			}
			int cnt[n];
			memset(cnt, 0, sizeof cnt);
			int one = 0;
			int ans = 1 << 30;
			for (int j = i; j < n; ++j) {
				int x = ++cnt[nums[j]];
				if (x == 1) {
					++one;
				} else if (x == 2) {
					--one;
				}
				ans = min(ans, k + j - i + 1 - one + dfs(j + 1));
			}
			return f[i] = ans;
		};
		return dfs(0);
	}
};

dice-roll-simulation.solutionCode:
class Solution {
public:
	int dieSimulator(int n, vector<int>& rollMax) {
		int f[n][7][16];
		memset(f, 0, sizeof f);
		const int mod = 1e9 + 7;
		function<int(int, int, int)> dfs = [&](int i, int j, int x) -> int {
			if (i >= n) {
				return 1;
			}
			if (f[i][j][x]) {
				return f[i][j][x];
			}
			long ans = 0;
			for (int k = 1; k <= 6; ++k) {
				if (k != j) {
					ans += dfs(i + 1, k, 1);
				} else if (x < rollMax[j - 1]) {
					ans += dfs(i + 1, j, x + 1);
				}
			}
			ans %= mod;
			return f[i][j][x] = ans;
		};
		return dfs(0, 0, 0);
	}
};

