	int ans;

	void dfs(int i, int j, int t) {
		if (j == m) {
			++i;
			j = 0;
		}
		if (i == n) {
			ans = t;
			return;
		}
		if (filled[i] >> j & 1) {
			dfs(i, j + 1, t);
		} else if (t + 1 < ans) {
			int r = 0, c = 0;
			for (int k = i; k < n; ++k) {
				if (filled[k] >> j & 1) {
					break;
				}
				++r;
			}
			for (int k = j; k < m; ++k) {
				if (filled[i] >> k & 1) {
					break;
				}
				++c;
			}
			int mx = min(r, c);
			for (int w = 1; w <= mx; ++w) {
				for (int k = 0; k < w; ++k) {
					filled[i + w - 1] |= 1 << (j + k);
					filled[i + k] |= 1 << (j + w - 1);
				}
				dfs(i, j + w, t + 1);
			}
			for (int x = i; x < i + mx; ++x) {
				for (int y = j; y < j + mx; ++y) {
					filled[x] ^= 1 << y;
				}
			}
		}
	}
};

palindrome-partitioning-iii.solutionCode:
class Solution {
public:
	int palindromePartition(string s, int k) {
		int n = s.size();
		vector<vector<int>> g(n, vector<int>(n));
		for (int i = n - 1; i >= 0; --i) {
			for (int j = i; j < n; ++j) {
				g[i][j] = s[i] != s[j] ? 1 : 0;
				if (i + 1 < j) g[i][j] += g[i + 1][j - 1];
			}
		}
		vector<vector<int>> f(n + 1, vector<int>(k + 1));
		for (int i = 1; i <= n; ++i) {
			for (int j = 1; j <= min(i, k); ++j) {
				if (j == 1) {
					f[i][j] = g[0][i - 1];
				} else {
					f[i][j] = 10000;
					for (int h = j - 1; h < i; ++h) {
						f[i][j] = min(f[i][j], f[h][j - 1] + g[h][i - 1]);
					}
				}
			}
		}
		return f[n][k];
	}
};

