class Solution {
public:
	int maximizeSweetness(vector<int>& sweetness, int k) {
		int l = 0, r = accumulate(sweetness.begin(), sweetness.end(), 0);
		auto check = [&](int x) {
			int s = 0, cnt = 0;
			for (int v : sweetness) {
				s += v;
				if (s >= x) {
					s = 0;
					++cnt;
				}
			}
			return cnt > k;
		};
		while (l < r) {
			int mid = (l + r + 1) >> 1;
			if (check(mid)) {
				l = mid;
			} else {
				r = mid - 1;
			}
		}
		return l;
	}
};

stepping-numbers.solutionCode:
class Solution {
public:
	vector<int> countSteppingNumbers(int low, int high) {
		vector<int> ans;
		if (low == 0) {
			ans.push_back(0);
		}
		queue<long long> q;
		for (int i = 1; i < 10; ++i) {
			q.push(i);
		}
		while (!q.empty()) {
			long long v = q.front();
			q.pop();
			if (v > high) {
				break;
			}
			if (v >= low) {
				ans.push_back(v);
			}
			int x = v % 10;
			if (x > 0) {
				q.push(v * 10 + x - 1);
			}
			if (x < 9) {
				q.push(v * 10 + x + 1);
			}
		}
		return ans;
	}
};

