class Solution {
public:
	int numWays(int steps, int arrLen) {
		int f[steps][steps + 1];
		memset(f, -1, sizeof f);
		const int mod = 1e9 + 7;
		function<int(int, int)> dfs = [&](int i, int j) -> int {
			if (i > j || i >= arrLen || i < 0 || j < 0) {
				return 0;
			}
			if (i == 0 && j == 0) {
				return 1;
			}
			if (f[i][j] != -1) {
				return f[i][j];
			}
			int ans = 0;
			for (int k = -1; k <= 1; ++k) {
				ans = (ans + dfs(i + k, j - 1)) % mod;
			}
			return f[i][j] = ans;
		};
		return dfs(0, steps);
	}
};

design-skiplist.solutionCode:
struct Node {
	int val;
	vector<Node*> next;
	Node(int v, int level)
		: val(v)
		, next(level, nullptr) {}
};

class Skiplist {
public:
	const int p = RAND_MAX / 4;
	const int maxLevel = 32;
	Node* head;
	int level;

	Skiplist() {
		head = new Node(-1, maxLevel);
		level = 0;
	}

	bool search(int target) {
		Node* curr = head;
		for (int i = level - 1; ~i; --i) {
			curr = findClosest(curr, i, target);
			if (curr->next[i] && curr->next[i]->val == target) return true;
		}
		return false;
	}

	void add(int num) {
		Node* curr = head;
		int lv = randomLevel();
		Node* node = new Node(num, lv);
		level = max(level, lv);
		for (int i = level - 1; ~i; --i) {
			curr = findClosest(curr, i, num);
			if (i < lv) {
				node->next[i] = curr->next[i];
				curr->next[i] = node;
			}
		}
	}

	bool erase(int num) {
		Node* curr = head;
		bool ok = false;
		for (int i = level - 1; ~i; --i) {
			curr = findClosest(curr, i, num);
			if (curr->next[i] && curr->next[i]->val == num) {
				curr->next[i] = curr->next[i]->next[i];
				ok = true;
			}
		}
		while (level > 1 && !head->next[level - 1]) --level;
		return ok;
	}

	Node* findClosest(Node* curr, int level, int target) {
		while (curr->next[level] && curr->next[level]->val < target) curr = curr->next[level];
		return curr;
	}

	int randomLevel() {
		int lv = 1;
		while (lv < maxLevel && rand() < p) ++lv;
		return lv;
	}
};

/**
 * Your Skiplist object will be instantiated and called as such:
 * Skiplist* obj = new Skiplist();
 * bool param_1 = obj->search(target);
 * obj->add(num);
 * bool param_3 = obj->erase(num);
 */

