		memset(f, 0, sizeof f);
		for (int i = 0; i < n; ++i) {
			f[i][i] = 1;
		}
		for (int i = n - 2; i >= 0; --i) {
			for (int j = i + 1; j < n; ++j) {
				if (i + 1 == j) {
