class Solution {
public:
	int numberOfWays(int numPeople) {
		const int mod = 1e9 + 7;
		int f[numPeople + 1];
		memset(f, 0, sizeof(f));
		function<int(int)> dfs = [&](int i) {
			if (i < 2) {
				return 1;
			}
			if (f[i]) {
				return f[i];
			}
			for (int l = 0; l < i; l += 2) {
				int r = i - l - 2;
				f[i] = (f[i] + 1LL * dfs(l) * dfs(r) % mod) % mod;
			}
			return f[i];
		};
		return dfs(numPeople);
	}
};

minimum-moves-to-move-a-box-to-their-tar.solutionCode:
class Solution {
public:
	int minPushBox(vector<vector<char>>& grid) {
		int m = grid.size(), n = grid[0].size();
		int si, sj, bi, bj;
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j] == 'S') {
					si = i, sj = j;
				} else if (grid[i][j] == 'B') {
					bi = i, bj = j;
				}
			}
		}
		auto f = [&](int i, int j) {
			return i * n + j;
		};
		auto check = [&](int i, int j) {
			return i >= 0 && i < m && j >= 0 && j < n && grid[i][j] != '#';
		};
		int dirs[5] = {-1, 0, 1, 0, -1};
		deque<tuple<int, int, int>> q;
		q.emplace_back(f(si, sj), f(bi, bj), 0);
		bool vis[m * n][m * n];
		memset(vis, false, sizeof(vis));
		vis[f(si, sj)][f(bi, bj)] = true;
		while (!q.empty()) {
			auto [s, b, d] = q.front();
			q.pop_front();
			si = s / n, sj = s % n;
			bi = b / n, bj = b % n;
			if (grid[bi][bj] == 'T') {
				return d;
			}
			for (int k = 0; k < 4; ++k) {
				int sx = si + dirs[k], sy = sj + dirs[k + 1];
				if (!check(sx, sy)) {
					continue;
				}
				if (sx == bi && sy == bj) {
					int bx = bi + dirs[k], by = bj + dirs[k + 1];
					if (!check(bx, by) || vis[f(sx, sy)][f(bx, by)]) {
						continue;
					}
					vis[f(sx, sy)][f(bx, by)] = true;
					q.emplace_back(f(sx, sy), f(bx, by), d + 1);
				} else if (!vis[f(sx, sy)][f(bi, bj)]) {
					vis[f(sx, sy)][f(bi, bj)] = true;
					q.emplace_front(f(sx, sy), f(bi, bj), d);
				}
			}
		}
		return -1;
	}
};

circular-permutation-in-binary-represent.solutionCode:
class Solution {
public:
	vector<int> circularPermutation(int n, int start) {
		int g[1 << n];
		int j = 0;
		for (int i = 0; i < 1 << n; ++i) {
			g[i] = i ^ (i >> 1);
			if (g[i] == start) {
				j = i;
			}
		}
		vector<int> ans;
		for (int i = j; i < j + (1 << n); ++i) {
			ans.push_back(g[i % (1 << n)]);
		}
		return ans;
	}
};

