class Solution {
public:
	int smallestDivisor(vector<int>& nums, int threshold) {
		int l = 1;
		int r = *max_element(nums.begin(), nums.end());
		while (l < r) {
			int mid = (l + r) >> 1;
			int s = 0;
			for (int x : nums) {
				s += (x + mid - 1) / mid;
			}
			if (s <= threshold) {
				r = mid;
			} else {
				l = mid + 1;
			}
		}
		return l;
	}
};

maximum-candies-you-can-get-from-boxes.solutionCode:
class Solution {
public:
	int maxCandies(
		vector<int>& status,
		vector<int>& candies,
		vector<vector<int>>& keys,
		vector<vector<int>>& containedBoxes,
		vector<int>& initialBoxes) {
		queue<int> q;
		unordered_set<int> has, took;
		int ans = 0;

		for (int box : initialBoxes) {
			has.insert(box);
			if (status[box]) {
				q.push(box);
				took.insert(box);
				ans += candies[box];
			}
		}

		while (!q.empty()) {
			int box = q.front();
			q.pop();

			for (int k : keys[box]) {
				if (!status[k]) {
					status[k] = 1;
					if (has.count(k) && !took.count(k)) {
						q.push(k);
						took.insert(k);
						ans += candies[k];
					}
				}
			}

			for (int b : containedBoxes[box]) {
				has.insert(b);
				if (status[b] && !took.count(b)) {
					q.push(b);
					took.insert(b);
					ans += candies[b];
				}
			}
		}

		return ans;
	}
};

