	void dfs(string& url, HtmlParser& htmlParser) {
		if (vis.count(url)) return;
		vis.insert(url);
		ans.push_back(url);
		for (string next : htmlParser.getUrls(url))
			if (host(url) == host(next))
				dfs(next, htmlParser);
	}

	string host(string url) {
		int i = 7;
		string res;
		for (; i < url.size(); ++i) {
			if (url[i] == '/') break;
			res += url[i];
		}
		return res;
	}
};

maximum-score-words-formed-by-letters.solutionCode:
class Solution {
public:
	int maxScoreWords(vector<string>& words, vector<char>& letters, vector<int>& score) {
		int cnt[26]{};
		for (char& c : letters) {
			cnt[c - 'a']++;
		}
		int n = words.size();
		int ans = 0;
		for (int i = 0; i < 1 << n; ++i) {
			int cur[26]{};
			for (int j = 0; j < n; ++j) {
				if (i >> j & 1) {
					for (char& c : words[j]) {
						cur[c - 'a']++;
					}
				}
			}
			bool ok = true;
			int t = 0;
			for (int j = 0; j < 26; ++j) {
				if (cur[j] > cnt[j]) {
					ok = false;
					break;
				}
				t += cur[j] * score[j];
			}
			if (ok && ans < t) {
				ans = t;
			}
		}
		return ans;
	}
};

