class Solution {
public:
	vector<vector<int>> generateMatrix(int n) {
		vector<vector<int>> ans(n, vector<int>(n, 0));
		const int dirs[5] = {0, 1, 0, -1, 0};
		int i = 0, j = 0, k = 0;
		for (int v = 1; v <= n * n; ++v) {
			ans[i][j] = v;
			int x = i + dirs[k], y = j + dirs[k + 1];
			if (x < 0 || x >= n || y < 0 || y >= n || ans[x][y] != 0) {
				k = (k + 1) % 4;
			}
			i += dirs[k];
			j += dirs[k + 1];
		}
		return ans;
	}
