rotate-list.solutionCode:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	ListNode* rotateRight(ListNode* head, int k) {
		if (!head || !head->next) {
			return head;
		}
		ListNode* cur = head;
		int n = 0;
		while (cur) {
			++n;
			cur = cur->next;
		}
		k %= n;
		if (k == 0) {
			return head;
		}
		ListNode* fast = head;
		ListNode* slow = head;
		while (k--) {
			fast = fast->next;
		}
		while (fast->next) {
			fast = fast->next;
			slow = slow->next;
		}
		ListNode* ans = slow->next;
		slow->next = nullptr;
		fast->next = head;
		return ans;
	}
};

substring-with-concatenation-of-all-word.solutionCode:
class Solution {
public:
	vector<int> findSubstring(string s, vector<string>& words) {
		unordered_map<string, int> cnt;
		for (const auto& w : words) {
			cnt[w]++;
		}

		vector<int> ans;
		int m = s.length(), n = words.size(), k = words[0].length();

		for (int i = 0; i < k; ++i) {
			int l = i, r = i;
			unordered_map<string, int> cnt1;
			while (r + k <= m) {
				string t = s.substr(r, k);
				r += k;

				if (!cnt.contains(t)) {
					cnt1.clear();
					l = r;
					continue;
				}

				cnt1[t]++;

				while (cnt1[t] > cnt[t]) {
					string w = s.substr(l, k);
					if (--cnt1[w] == 0) {
						cnt1.erase(w);
					}
					l += k;
				}

				if (r - l == n * k) {
					ans.push_back(l);
				}
			}
		}

		return ans;
	}
};

