		string ans;
		bitset<10> vis;
		for (int i = 0; i < n; ++i) {
			int fact = 1;
			for (int j = 1; j < n - i; ++j) fact *= j;
			for (int j = 1; j <= n; ++j) {
				if (vis[j]) continue;
				if (k > fact)
					k -= fact;
