		for (int j = 0; j <= n; ++j) {
			f[0][j] = j;
		}
		for (int i = 1; i <= m; ++i) {
			f[i][0] = i;
			for (int j = 1; j <= n; ++j) {
				if (word1[i - 1] == word2[j - 1]) {
					f[i][j] = f[i - 1][j - 1];
				} else {
					f[i][j] = min({f[i - 1][j], f[i][j - 1], f[i - 1][j - 1]}) + 1;
