class Solution {
public:
	int minimumIndex(vector<int>& nums) {
		int x = 0, cnt = 0;
		unordered_map<int, int> freq;
		for (int v : nums) {
			++freq[v];
			if (freq[v] > cnt) {
				cnt = freq[v];
				x = v;
			}
		}
		int cur = 0;
		for (int i = 1; i <= nums.size(); ++i) {
			if (nums[i - 1] == x) {
				++cur;
				if (cur * 2 > i && (cnt - cur) * 2 > nums.size() - i) {
					return i - 1;
				}
			}
		}
		return -1;
	}
};

