find-shortest-path-with-k-hops.solutionCode:
class Solution {
public:
	int shortestPathWithHops(int n, vector<vector<int>>& edges, int s, int d, int k) {
		vector<pair<int, int>> g[n];
		for (auto& e : edges) {
			int u = e[0], v = e[1], w = e[2];
			g[u].emplace_back(v, w);
			g[v].emplace_back(u, w);
		}
		priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> pq;
		pq.emplace(0, s, 0);
		int dist[n][k + 1];
		memset(dist, 0x3f, sizeof(dist));
		dist[s][0] = 0;
		while (!pq.empty()) {
			auto [dis, u, t] = pq.top();
			pq.pop();
			for (auto [v, w] : g[u]) {
				if (t + 1 <= k && dist[v][t + 1] > dis) {
					dist[v][t + 1] = dis;
					pq.emplace(dis, v, t + 1);
				}
				if (dist[v][t] > dis + w) {
					dist[v][t] = dis + w;
					pq.emplace(dis + w, v, t);
				}
			}
		}
		return *min_element(dist[d], dist[d] + k + 1);
	}
};

minimum-operations-to-make-numbers-non-p.solutionCode:
class Solution {
public:
	int minOperations(vector<int>& nums, int x, int y) {
		int l = 0, r = *max_element(nums.begin(), nums.end());
		auto check = [&](int t) {
			long long cnt = 0;
			for (int v : nums) {
				if (v > 1LL * t * y) {
					cnt += (v - 1LL * t * y + x - y - 1) / (x - y);
				}
			}
			return cnt <= t;
		};
		while (l < r) {
			int mid = (l + r) >> 1;
			if (check(mid)) {
				r = mid;
			} else {
				l = mid + 1;
			}
		}
		return l;
	}
};

count-nodes-that-are-great-enough.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int countGreatEnoughNodes(TreeNode* root, int k) {
		int ans = 0;
		function<priority_queue<int>(TreeNode*)> dfs = [&](TreeNode* root) {
			if (!root) {
				return priority_queue<int>();
			}
			auto left = dfs(root->left);
			auto right = dfs(root->right);
			while (right.size()) {
				left.push(right.top());
				right.pop();
				if (left.size() > k) {
					left.pop();
				}
			}
			if (left.size() == k && left.top() < root->val) {
				++ans;
			}
			left.push(root->val);
			if (left.size() > k) {
				left.pop();
			}
			return left;
		};
		dfs(root);
		return ans;
	}
};

