number-of-unique-categories.solutionCode:
/**
 * Definition for a category handler.
 * class CategoryHandler {
 * public:
 *     CategoryHandler(vector<int> categories);
 *     bool haveSameCategory(int a, int b);
 * };
 */
class Solution {
public:
	int numberOfCategories(int n, CategoryHandler* categoryHandler) {
		vector<int> p(n);
		iota(p.begin(), p.end(), 0);
		function<int(int)> find = [&](int x) {
			if (p[x] != x) {
				p[x] = find(p[x]);
			}
			return p[x];
		};
		for (int a = 0; a < n; ++a) {
			for (int b = a + 1; b < n; ++b) {
				if (categoryHandler->haveSameCategory(a, b)) {
					p[find(a)] = find(b);
				}
			}
		}
		int ans = 0;
		for (int i = 0; i < n; ++i) {
			ans += i == p[i];
		}
		return ans;
	}
};

