class Solution {
public:
	long long countPalindromePaths(vector<int>& parent, string s) {
		int n = parent.size();
		vector<vector<pair<int, int>>> g(n);
		unordered_map<int, int> cnt;
		cnt[0] = 1;
		for (int i = 1; i < n; ++i) {
			int p = parent[i];
			g[p].emplace_back(i, 1 << (s[i] - 'a'));
		}
		long long ans = 0;
		function<void(int, int)> dfs = [&](int i, int xo) {
			for (auto [j, v] : g[i]) {
				int x = xo ^ v;
				ans += cnt[x];
				for (int k = 0; k < 26; ++k) {
					ans += cnt[x ^ (1 << k)];
				}
				++cnt[x];
				dfs(j, x);
			}
		};
		dfs(0, 0);
		return ans;
	}
};

