		unordered_set<string> ss(dictionary.begin(), dictionary.end());
		int n = s.size();
		int f[n + 1];
		f[0] = 0;
		for (int i = 1; i <= n; ++i) {
			f[i] = f[i - 1] + 1;
			for (int j = 0; j < i; ++j) {
				if (ss.count(s.substr(j, i - j))) {
					f[i] = min(f[i], f[j]);
