class Solution {
public:
	vector<vector<int>> differenceOfDistinctValues(vector<vector<int>>& grid) {
		int m = grid.size(), n = grid[0].size();
		vector<vector<int>> ans(m, vector<int>(n));
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				int x = i, y = j;
				unordered_set<int> s;
				while (x > 0 && y > 0) {
					s.insert(grid[--x][--y]);
				}
				int tl = s.size();
				x = i;
				y = j;
				s.clear();
				while (x < m - 1 && y < n - 1) {
					s.insert(grid[++x][++y]);
				}
				int br = s.size();
				ans[i][j] = abs(tl - br);
			}
		}
		return ans;
	}
};

