class Solution {
public:
	int numberOfGoodSubarraySplits(vector<int>& nums) {
		const int mod = 1e9 + 7;
		int ans = 1, j = -1;
		for (int i = 0; i < nums.size(); ++i) {
			if (nums[i] == 0) {
				continue;
			}
			if (j > -1) {
				ans = 1LL * ans * (i - j) % mod;
			}
			j = i;
		}
		return j == -1 ? 0 : ans;
	}
};

painting-the-walls.solutionCode:
class Solution {
public:
	int paintWalls(vector<int>& cost, vector<int>& time) {
		int n = cost.size();
		int f[n][n << 1 | 1];
		memset(f, -1, sizeof(f));
		function<int(int, int)> dfs = [&](int i, int j) -> int {
			if (n - i <= j - n) {
				return 0;
			}
			if (i >= n) {
				return 1 << 30;
			}
			if (f[i][j] == -1) {
				f[i][j] = min(dfs(i + 1, j + time[i]) + cost[i], dfs(i + 1, j - 1));
			}
			return f[i][j];
		};
		return dfs(0, n);
	}
