class Solution {
public:
	int minimizeConcatenatedLength(vector<string>& words) {
		int n = words.size();
		int f[n][26][26];
		memset(f, 0, sizeof(f));
		function<int(int, int, int)> dfs = [&](int i, int a, int b) {
			if (i >= n) {
				return 0;
			}
			if (f[i][a][b]) {
				return f[i][a][b];
			}
			auto s = words[i];
			int m = s.size();
			int x = dfs(i + 1, a, s[m - 1] - 'a') - (s[0] - 'a' == b);
			int y = dfs(i + 1, s[0] - 'a', b) - (s[m - 1] - 'a' == a);
			return f[i][a][b] = m + min(x, y);
		};
		return words[0].size() + dfs(1, words[0].front() - 'a', words[0].back() - 'a');
	}
};

special-permutations.solutionCode:
class Solution {
public:
	int specialPerm(vector<int>& nums) {
		const int mod = 1e9 + 7;
		int n = nums.size();
		int m = 1 << n;
		int f[m][n];
		memset(f, 0, sizeof(f));
		for (int i = 1; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if ((i >> j & 1) == 1) {
					int ii = i ^ (1 << j);
					if (ii == 0) {
						f[i][j] = 1;
						continue;
					}
					for (int k = 0; k < n; ++k) {
						if (nums[j] % nums[k] == 0 || nums[k] % nums[j] == 0) {
							f[i][j] = (f[i][j] + f[ii][k]) % mod;
						}
					}
				}
			}
		}
		int ans = 0;
		for (int x : f[m - 1]) {
			ans = (ans + x) % mod;
		}
		return ans;
	}
};

