class Solution {
public:
	int numberOfWays(int n, int x) {
		const int mod = 1e9 + 7;
		int f[n + 1][n + 1];
		memset(f, 0, sizeof(f));
		f[0][0] = 1;
		for (int i = 1; i <= n; ++i) {
			long long k = (long long) pow(i, x);
			for (int j = 0; j <= n; ++j) {
				f[i][j] = f[i - 1][j];
				if (k <= j) {
					f[i][j] = (f[i][j] + f[i - 1][j - k]) % mod;
				}
			}
		}
		return f[n][n];
	}
};

