class Solution {
public:
	vector<int> countServers(int n, vector<vector<int>>& logs, int x, vector<int>& queries) {
		sort(logs.begin(), logs.end(), [](const auto& a, const auto& b) {
			return a[1] < b[1];
		});
		int m = queries.size();
		vector<pair<int, int>> qs(m);
		for (int i = 0; i < m; ++i) {
			qs[i] = {queries[i], i};
		}
		sort(qs.begin(), qs.end());
		unordered_map<int, int> cnt;
		vector<int> ans(m);
		int j = 0, k = 0;
		for (auto& [r, i] : qs) {
			int l = r - x;
			while (k < logs.size() && logs[k][1] <= r) {
				++cnt[logs[k++][0]];
			}
			while (j < logs.size() && logs[j][1] < l) {
				if (--cnt[logs[j][0]] == 0) {
					cnt.erase(logs[j][0]);
				}
				++j;
			}
			ans[i] = n - cnt.size();
		}
		return ans;
	}
};

robot-collisions.solutionCode:
class Solution {
public:
	vector<int> survivedRobotsHealths(vector<int>& positions, vector<int>& healths, string directions) {
		int n = positions.size();
		vector<int> idx(n);
		iota(idx.begin(), idx.end(), 0);

		sort(idx.begin(), idx.end(), [&](int a, int b) {
			return positions[a] < positions[b];
		});

		vector<int> stk;

		for (int i : idx) {
			if (directions[i] == 'R') {
				stk.push_back(i);
				continue;
			}

			while (!stk.empty() && healths[i] > 0) {
				int j = stk.back();

				if (healths[j] > healths[i]) {
					healths[j]--;
					healths[i] = 0;
				} else if (healths[j] < healths[i]) {
					healths[i]--;
					healths[j] = 0;
					stk.pop_back();
				} else {
					healths[i] = healths[j] = 0;
					stk.pop_back();
					break;
				}
			}
		}

		vector<int> ans;
		for (int h : healths) {
			if (h > 0) {
				ans.push_back(h);
			}
		}
		return ans;
	}
};

