		int n = s.size();
		int ans = 0;
		for (int i = 0, j = 0; i < n; ++i) {
			cnt[s[i]]++;
			while (cnt.size() > 2) {
				cnt[s[j]]--;
				if (cnt[s[j]] == 0) {
