class Solution {
public:
	int minCut(string s) {
		int n = s.size();
		bool g[n][n];
		memset(g, true, sizeof(g));
		for (int i = n - 1; ~i; --i) {
			for (int j = i + 1; j < n; ++j) {
				g[i][j] = s[i] == s[j] && g[i + 1][j - 1];
			}
		}
		int f[n];
		iota(f, f + n, 0);
		for (int i = 1; i < n; ++i) {
			for (int j = 0; j <= i; ++j) {
				if (g[j][i]) {
					f[i] = min(f[i], j ? 1 + f[j - 1] : 0);
				}
			}
		}
		return f[n - 1];
	}
};

