		Node* dummy = new Node(0);
		Node* tail = dummy;
		unordered_map<Node*, Node*> d;
		for (Node* cur = head; cur; cur = cur->next) {
			Node* node = new Node(cur->val);
			tail->next = node;
			tail = node;
			d[cur] = node;
		}
		for (Node* cur = head; cur; cur = cur->next) {
			d[cur]->random = cur->random ? d[cur->random] : nullptr;
		}
		return dummy->next;
	}
};

