class Solution {
public:
	int compareVersion(string version1, string version2) {
		int m = version1.size(), n = version2.size();
		for (int i = 0, j = 0; i < m || j < n; ++i, ++j) {
			int a = 0, b = 0;
			while (i < m && version1[i] != '.') {
				a = a * 10 + (version1[i++] - '0');
			}
			while (j < n && version2[j] != '.') {
				b = b * 10 + (version2[j++] - '0');
			}
			if (a != b) {
				return a < b ? -1 : 1;
			}
		}
		return 0;
	}
};

maximum-gap.solutionCode:
using pii = pair<int, int>;

class Solution {
public:
	const int inf = 0x3f3f3f3f;
	int maximumGap(vector<int>& nums) {
		int n = nums.size();
		if (n < 2) return 0;
		int mi = inf, mx = -inf;
		for (int v : nums) {
			mi = min(mi, v);
			mx = max(mx, v);
		}
		int bucketSize = max(1, (mx - mi) / (n - 1));
		int bucketCount = (mx - mi) / bucketSize + 1;
		vector<pii> buckets(bucketCount, {inf, -inf});
		for (int v : nums) {
			int i = (v - mi) / bucketSize;
			buckets[i].first = min(buckets[i].first, v);
			buckets[i].second = max(buckets[i].second, v);
		}
		int ans = 0;
		int prev = inf;
		for (auto [curmin, curmax] : buckets) {
			if (curmin > curmax) continue;
			ans = max(ans, curmin - prev);
			prev = curmax;
		}
		return ans;
	}
};

