		vector<vector<int>> ans;
		vector<int> t;
		function<void(TreeNode*, int)> dfs = [&](TreeNode* root, int s) {
			if (!root) return;
			s -= root->val;
			t.emplace_back(root->val);
			if (!root->left && !root->right && s == 0) ans.emplace_back(t);
			dfs(root->left, s);
			dfs(root->right, s);
			t.pop_back();
		};
		dfs(root, targetSum);
		return ans;
	}
};

