class Solution {
public:
	int numDistinct(string s, string t) {
		int m = s.size(), n = t.size();
		unsigned long long f[m + 1][n + 1];
		memset(f, 0, sizeof(f));
		for (int i = 0; i < m + 1; ++i) {
			f[i][0] = 1;
		}
		for (int i = 1; i < m + 1; ++i) {
			for (int j = 1; j < n + 1; ++j) {
				f[i][j] = f[i - 1][j];
				if (s[i - 1] == t[j - 1]) {
					f[i][j] += f[i - 1][j - 1];
				}
			}
		}
		return f[m][n];
	}
};

