class Solution {
public:
	vector<vector<string>> partition(string s) {
		int n = s.size();
		bool f[n][n];
		memset(f, true, sizeof(f));
		for (int i = n - 1; i >= 0; --i) {
			for (int j = i + 1; j < n; ++j) {
				f[i][j] = s[i] == s[j] && f[i + 1][j - 1];
			}
		}
		vector<vector<string>> ans;
		vector<string> t;
		auto dfs = [&](this auto&& dfs, int i) -> void {
			if (i == n) {
				ans.emplace_back(t);
				return;
			}
			for (int j = i; j < n; ++j) {
				if (f[i][j]) {
					t.emplace_back(s.substr(i, j - i + 1));
					dfs(j + 1);
					t.pop_back();
				}
			}
		};
		dfs(0);
		return ans;
	}
};

