class Solution {
public:
	void reverseWords(vector<char>& s) {
		auto reverse = [&](int i, int j) {
			for (; i < j; ++i, --j) {
				swap(s[i], s[j]);
			}
		};
		int n = s.size();
		for (int i = 0, j = 0; j < n; ++j) {
			if (s[j] == ' ') {
				reverse(i, j - 1);
				i = j + 1;
			} else if (j == n - 1) {
				reverse(i, j);
			}
		}
		reverse(0, n - 1);
	}
};

