class Solution {
public:
	void flatten(TreeNode* root) {
		while (root) {
			if (root->left) {
				TreeNode* pre = root->left;
				while (pre->right) {
					pre = pre->right;
				}
				pre->right = root->right;
				root->right = root->left;
				root->left = nullptr;
			}
			root = root->right;
		}
	}
};

