	string toHex(int num) {
		if (num == 0) return "0";
		string s = "";
		for (int i = 7; i >= 0; --i) {
			int x = (num >> (4 * i)) & 0xf;
			if (s.size() > 0 || x != 0) {
				char c = x < 10 ? (char) (x + '0') : (char) (x - 10 + 'a');
				s += c;
			}
		}
		return s;
	}
};

