	int countBattleships(vector<vector<char>>& board) {
		int m = board.size(), n = board[0].size();
		int ans = 0;
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if (board[i][j] == '.') {
					continue;
				}
				if (i > 0 && board[i - 1][j] == 'X') {
					continue;
				}
				if (j > 0 && board[i][j - 1] == 'X') {
					continue;
				}
				++ans;
			}
		}
		return ans;
	}
};

