class Solution {
public:
	bool predictTheWinner(vector<int>& nums) {
		int n = nums.size();
		vector<vector<int>> f(n, vector<int>(n));
		auto dfs = [&](this auto&& dfs, int i, int j) -> int {
			if (i > j) {
				return 0;
			}
			if (f[i][j]) {
				return f[i][j];
			}
			return f[i][j] = max(nums[i] - dfs(i + 1, j), nums[j] - dfs(i, j - 1));
		};
		return dfs(0, n - 1) >= 0;
	}
};

