class Solution {
public:
	int getMaxRepetitions(string s1, int n1, string s2, int n2) {
		int m = s1.size(), n = s2.size();
		vector<pair<int, int>> d;
		for (int i = 0; i < n; ++i) {
			int j = i;
			int cnt = 0;
			for (int k = 0; k < m; ++k) {
				if (s1[k] == s2[j]) {
					if (++j == n) {
						++cnt;
						j = 0;
					}
				}
			}
			d.emplace_back(cnt, j);
		}
		int ans = 0;
		for (int j = 0; n1; --n1) {
			ans += d[j].first;
			j = d[j].second;
		}
		return ans / n2;
	}
};

