class Trie {
public:
	Trie* children[2];

	Trie()
		: children{nullptr, nullptr} {}

	void insert(int x) {
		Trie* node = this;
		for (int i = 30; ~i; --i) {
			int v = x >> i & 1;
			if (!node->children[v]) {
				node->children[v] = new Trie();
			}
			node = node->children[v];
		}
	}

	int search(int x) {
		Trie* node = this;
		int ans = 0;
		for (int i = 30; ~i; --i) {
			int v = x >> i & 1;
			if (node->children[v ^ 1]) {
				ans |= 1 << i;
				node = node->children[v ^ 1];
			} else {
				node = node->children[v];
			}
		}
		return ans;
	}
};

class Solution {
