		int vk = INT_MIN;
		stack<int> stk;
		for (int i = nums.size() - 1; ~i; --i) {
			if (nums[i] < vk) {
				return true;
			}
			while (!stk.empty() && stk.top() < nums[i]) {
				vk = stk.top();
