class Solution {
public:
	int longestPalindrome(string s) {
		int cnt[128]{};
		for (char c : s) {
			++cnt[c];
		}
		int ans = 0;
		for (int v : cnt) {
			ans += v / 2 * 2;
		}
		ans += ans < s.size();
		return ans;
	}
};

sequence-reconstruction.solutionCode:
class Solution {
public:
	bool sequenceReconstruction(vector<int>& nums, vector<vector<int>>& sequences) {
		int n = nums.size();
		vector<int> indeg(n);
		vector<int> g[n];
		for (auto& seq : sequences) {
			for (int i = 1; i < seq.size(); ++i) {
				int a = seq[i - 1] - 1, b = seq[i] - 1;
				g[a].push_back(b);
				++indeg[b];
			}
		}
		queue<int> q;
		for (int i = 0; i < n; ++i) {
			if (indeg[i] == 0) {
				q.push(i);
			}
		}
		while (q.size() == 1) {
			int i = q.front();
			q.pop();
			for (int j : g[i]) {
				if (--indeg[j] == 0) {
					q.push(j);
				}
			}
		}
		return q.empty();
	}
};

optimal-account-balancing.solutionCode:
class Solution {
public:
	int minTransfers(vector<vector<int>>& transactions) {
		int g[12]{};
		for (auto& t : transactions) {
			g[t[0]] -= t[2];
			g[t[1]] += t[2];
		}
		vector<int> nums;
		for (int x : g) {
			if (x) {
				nums.push_back(x);
			}
		}
		int m = nums.size();
		int f[1 << m];
		memset(f, 0x3f, sizeof(f));
		f[0] = 0;
		for (int i = 1; i < 1 << m; ++i) {
			int s = 0;
			for (int j = 0; j < m; ++j) {
				if (i >> j & 1) {
					s += nums[j];
				}
			}
			if (s == 0) {
				f[i] = __builtin_popcount(i) - 1;
				for (int j = (i - 1) & i; j; j = (j - 1) & i) {
					f[i] = min(f[i], f[j] + f[i ^ j]);
				}
			}
		}
		return f[(1 << m) - 1];
	}
};

reverse-pairs.solutionCode:
class Solution {
public:
	int reversePairs(vector<int>& nums) {
		int n = nums.size();
		int t[n];
		function<int(int, int)> mergeSort = [&](int l, int r) -> int {
			if (l >= r) {
				return 0;
			}
			int mid = (l + r) >> 1;
			int ans = mergeSort(l, mid) + mergeSort(mid + 1, r);
			int i = l, j = mid + 1, k = 0;
			while (i <= mid && j <= r) {
				if (nums[i] <= nums[j] * 2LL) {
					++i;
				} else {
					ans += mid - i + 1;
					++j;
				}
			}
			i = l;
			j = mid + 1;
			while (i <= mid && j <= r) {
				if (nums[i] <= nums[j]) {
					t[k++] = nums[i++];
				} else {
					t[k++] = nums[j++];
				}
			}
			while (i <= mid) {
				t[k++] = nums[i++];
			}
			while (j <= r) {
				t[k++] = nums[j++];
			}
			for (i = l; i <= r; ++i) {
				nums[i] = t[i - l];
			}
			return ans;
		};
		return mergeSort(0, n - 1);
	}
};

