pacific-atlantic-water-flow.solutionCode:
class Solution {
public:
	vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {
		int m = heights.size(), n = heights[0].size();
		vector<vector<bool>> vis1(m, vector<bool>(n, false)), vis2(m, vector<bool>(n, false));
		queue<pair<int, int>> q1, q2;
		vector<int> dirs = {-1, 0, 1, 0, -1};

		for (int i = 0; i < m; ++i) {
			q1.emplace(i, 0);
			vis1[i][0] = true;
			q2.emplace(i, n - 1);
			vis2[i][n - 1] = true;
		}
		for (int j = 0; j < n; ++j) {
			q1.emplace(0, j);
			vis1[0][j] = true;
			q2.emplace(m - 1, j);
			vis2[m - 1][j] = true;
		}

		auto bfs = [&](queue<pair<int, int>>& q, vector<vector<bool>>& vis) {
			while (!q.empty()) {
				auto [x, y] = q.front();
				q.pop();
				for (int k = 0; k < 4; ++k) {
					int nx = x + dirs[k], ny = y + dirs[k + 1];
					if (nx >= 0 && nx < m && ny >= 0 && ny < n
						&& !vis[nx][ny]
						&& heights[nx][ny] >= heights[x][y]) {
						vis[nx][ny] = true;
						q.emplace(nx, ny);
					}
				}
			}
		};

		bfs(q1, vis1);
		bfs(q2, vis2);

		vector<vector<int>> ans;
		for (int i = 0; i < m; ++i)
			for (int j = 0; j < n; ++j)
				if (vis1[i][j] && vis2[i][j])
					ans.push_back({i, j});
		return ans;
	}
};

sum-of-left-leaves.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int sumOfLeftLeaves(TreeNode* root) {
		if (!root) {
			return 0;
		}
		int ans = sumOfLeftLeaves(root->right);
		if (root->left) {
			if (!root->left->left && !root->left->right) {
				ans += root->left->val;
			} else {
				ans += sumOfLeftLeaves(root->left);
			}
		}
		return ans;
	}
};

validate-ip-address.solutionCode:
class Solution {
public:
	string validIPAddress(string queryIP) {
		if (isIPv4(queryIP)) {
			return "IPv4";
		}
		if (isIPv6(queryIP)) {
			return "IPv6";
		}
		return "Neither";
	}

private:
	bool isIPv4(const string& s) {
		if (s.empty() || s.back() == '.') {
			return false;
		}
		vector<string> ss = split(s, '.');
		if (ss.size() != 4) {
			return false;
		}
		for (const string& t : ss) {
			if (t.empty() || (t.size() > 1 && t[0] == '0')) {
				return false;
			}
			int x = convert(t);
			if (x < 0 || x > 255) {
				return false;
			}
		}
		return true;
	}

	bool isIPv6(const string& s) {
		if (s.empty() || s.back() == ':') {
			return false;
		}
		vector<string> ss = split(s, ':');
		if (ss.size() != 8) {
			return false;
		}
		for (const string& t : ss) {
			if (t.size() < 1 || t.size() > 4) {
				return false;
			}
			for (char c : t) {
				if (!isxdigit(c)) {
					return false;
				}
			}
		}
		return true;
	}

	int convert(const string& s) {
		int x = 0;
		for (char c : s) {
			if (!isdigit(c)) {
				return -1;
			}
			x = x * 10 + (c - '0');
			if (x > 255) {
				return x;
			}
		}
		return x;
	}

	vector<string> split(const string& s, char delimiter) {
		vector<string> tokens;
		string token;
		istringstream iss(s);
		while (getline(iss, token, delimiter)) {
			tokens.push_back(token);
		}
		return tokens;
	}
};

non-decreasing-subsequences.solutionCode:
class Solution {
public:
	vector<vector<int>> findSubsequences(vector<int>& nums) {
		vector<vector<int>> ans;
		vector<int> t;
		dfs(0, -1000, t, nums, ans);
		return ans;
	}

	void dfs(int u, int last, vector<int>& t, vector<int>& nums, vector<vector<int>>& ans) {
		if (u == nums.size()) {
			if (t.size() > 1) ans.push_back(t);
			return;
		}
		if (nums[u] >= last) {
			t.push_back(nums[u]);
			dfs(u + 1, nums[u], t, nums, ans);
			t.pop_back();
		}
		if (nums[u] != last) dfs(u + 1, last, t, nums, ans);
	}
};

minimum-genetic-mutation.solutionCode:
class Solution {
public:
	int minMutation(string startGene, string endGene, vector<string>& bank) {
		queue<pair<string, int>> q{{{startGene, 0}}};
		unordered_set<string> vis = {startGene};
		while (!q.empty()) {
			auto [gene, depth] = q.front();
			q.pop();
			if (gene == endGene) {
				return depth;
			}
			for (const string& next : bank) {
				int c = 2;
				for (int k = 0; k < 8 && c; ++k) {
					c -= gene[k] != next[k];
				}
				if (c && !vis.contains(next)) {
					vis.insert(next);
					q.push({next, depth + 1});
				}
			}
		}
		return -1;
	}
};

