	Trie* trie = new Trie();

	vector<string> findAllConcatenatedWordsInADict(vector<string>& words) {
		sort(words.begin(), words.end(), [&](const string& a, const string& b) {
			return a.size() < b.size();
		});
		vector<string> ans;
		for (auto& w : words) {
			if (dfs(w))
				ans.push_back(w);
			else
				trie->insert(w);
		}
		return ans;
	}

	bool dfs(string w) {
		if (w == "") return true;
		Trie* node = trie;
		for (int i = 0; i < w.size(); ++i) {
			int idx = w[i] - 'a';
			if (!node->children[idx]) return false;
			node = node->children[idx];
			if (node->isEnd && dfs(w.substr(i + 1))) return true;
		}
		return false;
	}
};

flatten-a-multilevel-doubly-linked-list.solutionCode:
/*
// Definition for a Node.
class Node {
public:
	int val;
	Node* prev;
	Node* next;
	Node* child;
};
*/

class Solution {
public:
	Node* flatten(Node* head) {
		flattenGetTail(head);
		return head;
	}

	Node* flattenGetTail(Node* head) {
		Node* cur = head;
		Node* tail = nullptr;

		while (cur) {
			Node* next = cur->next;
			if (cur->child) {
				Node* child = cur->child;
				Node* childTail = flattenGetTail(cur->child);

				cur->child = nullptr;
				cur->next = child;
				child->prev = cur;
				childTail->next = next;

				if (next)
					next->prev = childTail;

				tail = childTail;
			} else {
				tail = cur;
			}

			cur = next;
		}

		return tail;
	}
};

