class Solution {
public:
	int n;

	int findKthNumber(int n, int k) {
		this->n = n;
		--k;
		long long curr = 1;
		while (k) {
			int cnt = count(curr);
			if (k >= cnt) {
				k -= cnt;
				++curr;
			} else {
				--k;
				curr *= 10;
			}
		}
		return (int) curr;
	}

	int count(long long curr) {
		long long next = curr + 1;
		int cnt = 0;
		while (curr <= n) {
			cnt += min(n - curr + 1, next - curr);
			next *= 10;
			curr *= 10;
		}
		return cnt;
	}
};

path-sum-iii.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int pathSum(TreeNode* root, int targetSum) {
		unordered_map<long long, int> cnt;
		cnt[0] = 1;
		auto dfs = [&](this auto&& dfs, TreeNode* node, long long s) -> int {
			if (!node) {
				return 0;
			}
			s += node->val;
			int ans = cnt[s - targetSum];
			++cnt[s];
			ans += dfs(node->left, s) + dfs(node->right, s);
			--cnt[s];
			return ans;
		};
		return dfs(root, 0);
	}
};

