class Solution {
public:
	vector<int> findDiagonalOrder(vector<vector<int>>& mat) {
		int m = mat.size();
		int n = mat[0].size();
		vector<int> ans;
		vector<int> t;
		for (int k = 0; k < m + n - 1; ++k) {
			int i = (k < n) ? 0 : k - n + 1;
			int j = (k < n) ? k : n - 1;
			while (i < m && j >= 0) {
				t.push_back(mat[i][j]);
				++i;
				--j;
			}
			if (k % 2 == 0) {
				ranges::reverse(t);
			}
			ans.insert(ans.end(), t.begin(), t.end());
			t.clear();
		}
		return ans;
	}
};

circular-array-loop.solutionCode:
class Solution {
public:
	bool circularArrayLoop(vector<int>& nums) {
		int n = nums.size();
		for (int i = 0; i < n; ++i) {
			if (!nums[i]) continue;
			int slow = i, fast = next(nums, i);
			while (nums[slow] * nums[fast] > 0 && nums[slow] * nums[next(nums, fast)] > 0) {
				if (slow == fast) {
					if (slow != next(nums, slow)) return true;
					break;
				}
				slow = next(nums, slow);
				fast = next(nums, next(nums, fast));
			}
			int j = i;
			while (nums[j] * nums[next(nums, j)] > 0) {
				nums[j] = 0;
				j = next(nums, j);
			}
		}
		return false;
	}

	int next(vector<int>& nums, int i) {
		int n = nums.size();
		return (i + nums[i] % n + n) % n;
	}
};

