/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
		stack<int> s1;
		stack<int> s2;
		for (; l1; l1 = l1->next) s1.push(l1->val);
		for (; l2; l2 = l2->next) s2.push(l2->val);
		ListNode* dummy = new ListNode();
		int carry = 0;
		while (!s1.empty() || !s2.empty() || carry) {
			int s = carry;
			if (!s1.empty()) {
				s += s1.top();
				s1.pop();
			}
			if (!s2.empty()) {
				s += s2.top();
				s2.pop();
			}
			// ListNode* node = new ListNode(s % 10, dummy->next);
			// dummy->next = node;
			dummy->next = new ListNode(s % 10, dummy->next);
			carry = s / 10;
		}
		return dummy->next;
	}
};

strong-password-checker.solutionCode:
class Solution {
public:
	int strongPasswordChecker(string password) {
		int types = countTypes(password);
		int n = password.size();
		if (n < 6) return max(6 - n, 3 - types);
		if (n <= 20) {
			int replace = 0, cnt = 0;
			char prev = '~';
			for (char& curr : password) {
				if (curr == prev)
					++cnt;
				else {
					replace += cnt / 3;
					cnt = 1;
					prev = curr;
				}
			}
			replace += cnt / 3;
			return max(replace, 3 - types);
		}
		int replace = 0, remove = n - 20;
		int remove2 = 0;
		int cnt = 0;
		char prev = '~';
		for (char& curr : password) {
			if (curr == prev)
				++cnt;
			else {
				if (remove > 0 && cnt >= 3) {
					if (cnt % 3 == 0) {
						--remove;
						--replace;
					} else if (cnt % 3 == 1)
						++remove2;
				}
				replace += cnt / 3;
				cnt = 1;
				prev = curr;
			}
		}
		if (remove > 0 && cnt >= 3) {
			if (cnt % 3 == 0) {
				--remove;
				--replace;
			} else if (cnt % 3 == 1)
				++remove2;
		}
		replace += cnt / 3;

		int use2 = min(min(replace, remove2), remove / 2);
		replace -= use2;
		remove -= use2 * 2;

		int use3 = min(replace, remove / 3);
		replace -= use3;
		remove -= use3 * 3;
		return (n - 20) + max(replace, 3 - types);
	}

	int countTypes(string& s) {
		int a = 0, b = 0, c = 0;
		for (char& ch : s) {
			if (islower(ch))
				a = 1;
			else if (isupper(ch))
				b = 1;
			else if (isdigit(ch))
				c = 1;
		}
		return a + b + c;
	}
};

