class Solution {
public:
	int findTargetSumWays(vector<int>& nums, int target) {
		int s = accumulate(nums.begin(), nums.end(), 0);
		if (s < target || (s - target) % 2) {
			return 0;
		}
		int m = nums.size();
		int n = (s - target) / 2;
		int f[m + 1][n + 1];
		memset(f, 0, sizeof(f));
		f[0][0] = 1;
		for (int i = 1; i <= m; ++i) {
			for (int j = 0; j <= n; ++j) {
				f[i][j] = f[i - 1][j];
				if (j >= nums[i - 1]) {
					f[i][j] += f[i - 1][j - nums[i - 1]];
				}
			}
		}
		return f[m][n];
	}
};

