	vector<int> applyOperations(vector<int>& nums) {
		int n = nums.size();
		for (int i = 0; i < n - 1; ++i) {
			if (nums[i] == nums[i + 1]) {
				nums[i] <<= 1;
				nums[i + 1] = 0;
