range-product-queries-of-powers.solutionCode:
class Solution {
public:
	vector<int> productQueries(int n, vector<vector<int>>& queries) {
		vector<int> powers;
		while (n) {
			int x = n & -n;
			powers.push_back(x);
			n -= x;
		}
		vector<int> ans;
		const int mod = 1e9 + 7;
		for (const auto& q : queries) {
			int l = q[0], r = q[1];
			long long x = 1;
			for (int j = l; j <= r; ++j) {
				x = x * powers[j] % mod;
			}
			ans.push_back(x);
		}
		return ans;
	}
};

minimum-total-cost-to-make-arrays-unequa.solutionCode:
class Solution {
public:
	long long minimumTotalCost(vector<int>& nums1, vector<int>& nums2) {
		long long ans = 0;
		int same = 0;
		int n = nums1.size();
		int cnt[n + 1];
		memset(cnt, 0, sizeof cnt);
		for (int i = 0; i < n; ++i) {
			if (nums1[i] == nums2[i]) {
				ans += i;
				++same;
				++cnt[nums1[i]];
			}
		}
		int m = 0, lead = 0;
		for (int i = 0; i < n + 1; ++i) {
			int t = cnt[i] * 2 - same;
			if (t > 0) {
				m = t;
				lead = i;
				break;
			}
		}
		for (int i = 0; i < n; ++i) {
			if (m > 0 && nums1[i] != nums2[i] && nums1[i] != lead && nums2[i] != lead) {
				ans += i;
				--m;
			}
		}
		return m > 0 ? -1 : ans;
	}
};

maximize-total-tastiness-of-purchased-fr.solutionCode:
class Solution {
public:
	int maxTastiness(vector<int>& price, vector<int>& tastiness, int maxAmount, int maxCoupons) {
		int n = price.size();
		memset(f, 0, sizeof f);
		function<int(int i, int j, int k)> dfs;
		dfs = [&](int i, int j, int k) {
			if (i == n) return 0;
			if (f[i][j][k]) return f[i][j][k];
			int ans = dfs(i + 1, j, k);
			if (j >= price[i]) ans = max(ans, dfs(i + 1, j - price[i], k) + tastiness[i]);
			if (j >= price[i] / 2 && k) ans = max(ans, dfs(i + 1, j - price[i] / 2, k - 1) + tastiness[i]);
			f[i][j][k] = ans;
			return ans;
		};
		return dfs(0, maxAmount, maxCoupons);
	}

private:
	int f[101][1001][6];
};

