		vector<vector<int>> g(n);
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].emplace_back(b);
			g[b].emplace_back(a);
		}
		vector<int> ts(n, n);
		function<bool(int i, int fa, int t)> dfs1 = [&](int i, int fa, int t) -> bool {
			if (i == 0) {
				ts[i] = t;
				return true;
			}
			for (int j : g[i]) {
				if (j != fa && dfs1(j, i, t + 1)) {
					ts[j] = min(ts[j], t + 1);
					return true;
				}
			}
			return false;
		};
		dfs1(bob, -1, 0);
		ts[bob] = 0;
		int ans = INT_MIN;
		function<void(int i, int fa, int t, int v)> dfs2 = [&](int i, int fa, int t, int v) {
			if (t == ts[i])
				v += amount[i] >> 1;
			else if (t < ts[i])
				v += amount[i];
			if (g[i].size() == 1 && g[i][0] == fa) {
				ans = max(ans, v);
				return;
			}
			for (int j : g[i])
				if (j != fa) dfs2(j, i, t + 1, v);
		};
		dfs2(0, -1, 0, 0);
		return ans;
	}
};

