using ll = long long;

class Solution {
public:
	long long minCost(vector<int>& nums, vector<int>& cost) {
		int n = nums.size();
		vector<pair<int, int>> arr(n);
		for (int i = 0; i < n; ++i) arr[i] = {nums[i], cost[i]};
		sort(arr.begin(), arr.end());
		vector<ll> f(n + 1), g(n + 1);
		for (int i = 1; i <= n; ++i) {
			auto [a, b] = arr[i - 1];
			f[i] = f[i - 1] + 1ll * a * b;
			g[i] = g[i - 1] + b;
		}
		ll ans = 1e18;
		for (int i = 1; i <= n; ++i) {
			auto [a, _] = arr[i - 1];
			ll l = 1ll * a * g[i - 1] - f[i - 1];
			ll r = f[n] - f[i] - 1ll * a * (g[n] - g[i]);
			ans = min(ans, l + r);
		}
		return ans;
	}
};

number-of-good-paths.solutionCode:
class Solution {
public:
	int numberOfGoodPaths(vector<int>& vals, vector<vector<int>>& edges) {
		int n = vals.size();
		vector<int> p(n);
		iota(p.begin(), p.end(), 0);
		function<int(int)> find;
		find = [&](int x) {
			if (p[x] != x) {
				p[x] = find(p[x]);
			}
			return p[x];
		};
		vector<vector<int>> g(n);
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		unordered_map<int, unordered_map<int, int>> size;
		vector<pair<int, int>> arr(n);
		for (int i = 0; i < n; ++i) {
			arr[i] = {vals[i], i};
			size[i][vals[i]] = 1;
		}
		sort(arr.begin(), arr.end());
		int ans = n;
		for (auto [v, a] : arr) {
			for (int b : g[a]) {
				if (vals[b] > v) {
					continue;
				}
				int pa = find(a), pb = find(b);
				if (pa != pb) {
					ans += size[pa][v] * size[pb][v];
					p[pa] = pb;
					size[pb][v] += size[pa][v];
				}
			}
		}
		return ans;
	}
};

minimum-time-to-kill-all-monsters.solutionCode:
class Solution {
public:
	long long minimumTime(vector<int>& power) {
		int n = power.size();
		long long f[1 << n];
		memset(f, -1, sizeof(f));
		auto dfs = [&](this auto&& dfs, int mask) -> long long {
			if (mask == 0) {
				return 0;
			}
			if (f[mask] != -1) {
				return f[mask];
			}
			f[mask] = LLONG_MAX;
			int gain = 1 + (n - __builtin_popcount(mask));
			for (int i = 0; i < n; ++i) {
				if (mask >> i & 1) {
					f[mask] = min(f[mask], dfs(mask ^ (1 << i)) + (power[i] + gain - 1) / gain);
				}
			}
			return f[mask];
		};
		return dfs((1 << n) - 1);
	}
};

minimum-number-of-operations-to-sort-a-b.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int minimumOperations(TreeNode* root) {
		queue<TreeNode*> q{{root}};
		int ans = 0;
		auto f = [](vector<int>& t) {
			int n = t.size();
			vector<int> alls(t.begin(), t.end());
			sort(alls.begin(), alls.end());
			unordered_map<int, int> m;
			int ans = 0;
			for (int i = 0; i < n; ++i) m[alls[i]] = i;
			for (int i = 0; i < n; ++i) t[i] = m[t[i]];
			for (int i = 0; i < n; ++i) {
				while (t[i] != i) {
					swap(t[i], t[t[i]]);
					++ans;
				}
			}
			return ans;
		};
		while (!q.empty()) {
			vector<int> t;
			for (int n = q.size(); n; --n) {
				auto node = q.front();
				q.pop();
				t.emplace_back(node->val);
				if (node->left) q.push(node->left);
				if (node->right) q.push(node->right);
			}
			ans += f(t);
		}
		return ans;
	}
};

