class Solution {
public:
	int minimumOperations(vector<int>& nums) {
		int i = 0, j = nums.size() - 1;
		long a = nums[i], b = nums[j];
		int ans = 0;
		while (i < j) {
			if (a < b) {
				a += nums[++i];
				++ans;
			} else if (b < a) {
				b += nums[--j];
				++ans;
			} else {
				a = nums[++i];
				b = nums[--j];
			}
		}
		return ans;
	}
};

remove-nodes-from-linked-list.solutionCode:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	ListNode* removeNodes(ListNode* head) {
		vector<int> nums;
		while (head) {
			nums.emplace_back(head->val);
			head = head->next;
		}
		vector<int> stk;
		for (int v : nums) {
			while (!stk.empty() && stk.back() < v) {
				stk.pop_back();
			}
			stk.push_back(v);
		}
		ListNode* dummy = new ListNode();
		head = dummy;
		for (int v : stk) {
			head->next = new ListNode(v);
			head = head->next;
		}
		return dummy->next;
	}
};

