/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	ListNode* deleteNodes(ListNode* head, int m, int n) {
		auto pre = head;
		while (pre) {
			for (int i = 0; i < m - 1 && pre; ++i) {
				pre = pre->next;
			}
			if (!pre) {
				return head;
			}
			auto cur = pre;
			for (int i = 0; i < n && cur; ++i) {
				cur = cur->next;
			}
			pre->next = cur ? cur->next : nullptr;
			pre = pre->next;
		}
		return head;
	}
};

number-of-ways-of-cutting-a-pizza.solutionCode:
class Solution {
public:
	int ways(vector<string>& pizza, int k) {
		const int mod = 1e9 + 7;
		int m = pizza.size(), n = pizza[0].size();
		vector<vector<vector<int>>> f(m, vector<vector<int>>(n, vector<int>(k, -1)));
		vector<vector<int>> s(m + 1, vector<int>(n + 1));
		for (int i = 1; i <= m; ++i) {
			for (int j = 1; j <= n; ++j) {
				int x = pizza[i - 1][j - 1] == 'A' ? 1 : 0;
				s[i][j] = s[i - 1][j] + s[i][j - 1] - s[i - 1][j - 1] + x;
			}
		}
		function<int(int, int, int)> dfs = [&](int i, int j, int k) -> int {
			if (k == 0) {
				return s[m][n] - s[i][n] - s[m][j] + s[i][j] > 0 ? 1 : 0;
			}
			if (f[i][j][k] != -1) {
				return f[i][j][k];
			}
			int ans = 0;
			for (int x = i + 1; x < m; ++x) {
				if (s[x][n] - s[i][n] - s[x][j] + s[i][j] > 0) {
					ans = (ans + dfs(x, j, k - 1)) % mod;
				}
			}
			for (int y = j + 1; y < n; ++y) {
				if (s[m][y] - s[i][y] - s[m][j] + s[i][j] > 0) {
					ans = (ans + dfs(i, y, k - 1)) % mod;
				}
			}
			return f[i][j][k] = ans;
		};
		return dfs(0, 0, k - 1);
	}
};

