/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	bool isValidSequence(TreeNode* root, vector<int>& arr) {
		function<bool(TreeNode*, int)> dfs = [&](TreeNode* root, int u) -> bool {
			if (!root || root->val != arr[u]) return false;
			if (u == arr.size() - 1) return !root->left && !root->right;
			return dfs(root->left, u + 1) || dfs(root->right, u + 1);
		};
		return dfs(root, 0);
	}
};

longest-happy-string.solutionCode:
class Solution {
public:
	string longestDiverseString(int a, int b, int c) {
		using pci = pair<char, int>;
		auto cmp = [](pci x, pci y) { return x.second < y.second; };
		priority_queue<pci, vector<pci>, decltype(cmp)> pq(cmp);

		if (a > 0) pq.push({'a', a});
		if (b > 0) pq.push({'b', b});
		if (c > 0) pq.push({'c', c});

		string ans;
		while (!pq.empty()) {
			pci cur = pq.top();
			pq.pop();
			int n = ans.size();
			if (n >= 2 && ans[n - 1] == cur.first && ans[n - 2] == cur.first) {
				if (pq.empty()) break;
				pci nxt = pq.top();
				pq.pop();
				ans.push_back(nxt.first);
				if (--nxt.second > 0) {
					pq.push(nxt);
				}
				pq.push(cur);
			} else {
				ans.push_back(cur.first);
				if (--cur.second > 0) {
					pq.push(cur);
				}
			}
		}

		return ans;
	}
};

