probability-of-a-two-boxes-having-the-sa.solutionCode:
class Solution {
public:
	double getProbability(vector<int>& balls) {
		int n = accumulate(balls.begin(), balls.end(), 0) / 2;
		int mx = *max_element(balls.begin(), balls.end());
		int m = max(mx, n << 1);
		long long c[m + 1][m + 1];
		memset(c, 0, sizeof(c));
		for (int i = 0; i <= m; ++i) {
			c[i][0] = 1;
			for (int j = 1; j <= i; ++j) {
				c[i][j] = c[i - 1][j - 1] + c[i - 1][j];
			}
		}
		int k = balls.size();
		long long f[k][n + 1][k << 1 | 1];
		memset(f, -1, sizeof(f));
		function<long long(int, int, int)> dfs = [&](int i, int j, int diff) -> long long {
			if (i >= k) {
				return j == 0 && diff == k ? 1 : 0;
			}
			if (j < 0) {
				return 0;
			}
			if (f[i][j][diff] != -1) {
				return f[i][j][diff];
			}
			long long ans = 0;
			for (int x = 0; x <= balls[i]; ++x) {
				int y = x == balls[i] ? 1 : (x == 0 ? -1 : 0);
				ans += dfs(i + 1, j - x, diff + y) * c[balls[i]][x];
			}
			return f[i][j][diff] = ans;
		};
		return dfs(0, n, k) * 1.0 / c[n << 1][n];
	}
};

number-of-ways-to-wear-different-hats-to.solutionCode:
class Solution {
public:
	int numberWays(vector<vector<int>>& hats) {
		int n = hats.size();
		int m = 0;
		for (auto& h : hats) {
			m = max(m, *max_element(h.begin(), h.end()));
		}
		vector<vector<int>> g(m + 1);
		for (int i = 0; i < n; ++i) {
			for (int& v : hats[i]) {
				g[v].push_back(i);
			}
		}
		const int mod = 1e9 + 7;
		int f[m + 1][1 << n];
		memset(f, 0, sizeof(f));
		f[0][0] = 1;
		for (int i = 1; i <= m; ++i) {
			for (int j = 0; j < 1 << n; ++j) {
				f[i][j] = f[i - 1][j];
				for (int k : g[i]) {
					if (j >> k & 1) {
						f[i][j] = (f[i][j] + f[i - 1][j ^ (1 << k)]) % mod;
					}
				}
			}
		}
		return f[m][(1 << n) - 1];
	}
};

find-critical-and-pseudo-critical-edges-.solutionCode:
class UnionFind {
public:
	vector<int> p;
	int n;

	UnionFind(int _n)
		: n(_n)
		, p(_n) {
		iota(p.begin(), p.end(), 0);
	}

	bool unite(int a, int b) {
		if (find(a) == find(b)) return false;
		p[find(a)] = find(b);
		--n;
		return true;
	}

	int find(int x) {
		if (p[x] != x) p[x] = find(p[x]);
		return p[x];
	}
};

class Solution {
public:
	vector<vector<int>> findCriticalAndPseudoCriticalEdges(int n, vector<vector<int>>& edges) {
		for (int i = 0; i < edges.size(); ++i) edges[i].push_back(i);
		sort(edges.begin(), edges.end(), [](auto& a, auto& b) { return a[2] < b[2]; });
		int v = 0;
		UnionFind uf(n);
		for (auto& e : edges) {
			int f = e[0], t = e[1], w = e[2];
			if (uf.unite(f, t)) v += w;
		}
		vector<vector<int>> ans(2);
		for (auto& e : edges) {
			int f = e[0], t = e[1], w = e[2], i = e[3];
			UnionFind ufa(n);
			int k = 0;
			for (auto& ne : edges) {
				int x = ne[0], y = ne[1], z = ne[2], j = ne[3];
				if (j != i && ufa.unite(x, y)) k += z;
			}
			if (ufa.n > 1 || (ufa.n == 1 && k > v)) {
				ans[0].push_back(i);
				continue;
			}

			UnionFind ufb(n);
			ufb.unite(f, t);
			k = w;
			for (auto& ne : edges) {
				int x = ne[0], y = ne[1], z = ne[2], j = ne[3];
				if (j != i && ufb.unite(x, y)) k += z;
			}
			if (k == v) ans[1].push_back(i);
		}
		return ans;
	}
};

