class Solution {
public:
	vector<int> peopleIndexes(vector<vector<string>>& favoriteCompanies) {
		int n = favoriteCompanies.size();
		unordered_map<string, int> d;
		int idx = 0;
		vector<unordered_set<int>> nums(n);

		for (int i = 0; i < n; ++i) {
			for (const auto& s : favoriteCompanies[i]) {
				if (!d.contains(s)) {
					d[s] = idx++;
				}
				nums[i].insert(d[s]);
			}
		}

		auto check = [](const unordered_set<int>& a, const unordered_set<int>& b) {
			for (int x : a) {
				if (!b.contains(x)) {
					return false;
				}
			}
			return true;
		};

		vector<int> ans;
		for (int i = 0; i < n; ++i) {
			bool ok = true;
			for (int j = 0; j < n && ok; ++j) {
				if (i != j && check(nums[i], nums[j])) {
					ok = false;
				}
			}
			if (ok) {
				ans.push_back(i);
			}
		}

		return ans;
	}
};

max-dot-product-of-two-subsequences.solutionCode:
class Solution {
public:
	int maxDotProduct(vector<int>& nums1, vector<int>& nums2) {
		int m = nums1.size(), n = nums2.size();
		int f[m + 1][n + 1];
		memset(f, 0xc0, sizeof f);
		for (int i = 1; i <= m; ++i) {
			for (int j = 1; j <= n; ++j) {
				int v = nums1[i - 1] * nums2[j - 1];
				f[i][j] = max(f[i - 1][j], f[i][j - 1]);
				f[i][j] = max(f[i][j], max(0, f[i - 1][j - 1]) + v);
			}
		}
		return f[m][n];
	}
};

