minimum-cost-of-a-path-with-special-road.solutionCode:
class Solution {
public:
	int minimumCost(vector<int>& start, vector<int>& target, vector<vector<int>>& specialRoads) {
		auto dist = [](int x1, int y1, int x2, int y2) {
			return abs(x1 - x2) + abs(y1 - y2);
		};
		int ans = 1 << 30;
		int n = 1e6;
		priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> pq;
		pq.push({0, start[0], start[1]});
		unordered_set<long long> vis;
		while (!pq.empty()) {
			auto [d, x, y] = pq.top();
			pq.pop();
			long long k = 1LL * x * n + y;
			if (vis.count(k)) {
				continue;
			}
			vis.insert(k);
			ans = min(ans, d + dist(x, y, target[0], target[1]));
			for (auto& r : specialRoads) {
				int x1 = r[0], y1 = r[1], x2 = r[2], y2 = r[3], cost = r[4];
				pq.push({d + dist(x, y, x1, y1) + cost, x2, y2});
			}
		}
		return ans;
	}
};

split-a-circular-linked-list.solutionCode:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	vector<ListNode*> splitCircularLinkedList(ListNode* list) {
		ListNode* a = list;
		ListNode* b = list;
		while (b->next != list && b->next->next != list) {
			a = a->next;
			b = b->next->next;
		}
		if (b->next != list) {
			b = b->next;
		}
		ListNode* list2 = a->next;
		b->next = list2;
		a->next = list;
		return {list, list2};
	}
};

sum-of-distances.solutionCode:
class Solution {
public:
	vector<long long> distance(vector<int>& nums) {
		int n = nums.size();
		vector<long long> ans(n);
		unordered_map<int, vector<int>> d;
		for (int i = 0; i < n; ++i) {
			d[nums[i]].push_back(i);
		}
		for (auto& [_, idx] : d) {
			int m = idx.size();
			long long left = 0;
			long long right = -1LL * m * idx[0];
			for (int i : idx) {
				right += i;
			}
			for (int i = 0; i < m; ++i) {
				ans[idx[i]] = left + right;
				if (i + 1 < m) {
					left += (idx[i + 1] - idx[i]) * (i + 1);
					right -= (idx[i + 1] - idx[i]) * (m - i - 1);
				}
			}
		}
		return ans;
	}
};

