class Solution {
public:
	int minOperations(vector<int>& nums) {
		int n = nums.size();
		int cnt = 0;
		for (int x : nums) {
			if (x == 1) {
				++cnt;
			}
		}
		if (cnt) {
			return n - cnt;
		}
		int mi = n + 1;
		for (int i = 0; i < n; ++i) {
			int g = 0;
			for (int j = i; j < n; ++j) {
				g = gcd(g, nums[j]);
				if (g == 1) {
					mi = min(mi, j - i + 1);
				}
			}
		}
		return mi > n ? -1 : n - 1 + mi - 1;
	}
};

minimize-the-total-price-of-the-trips.solutionCode:
class Solution {
public:
	int minimumTotalPrice(int n, vector<vector<int>>& edges, vector<int>& price, vector<vector<int>>& trips) {
		vector<vector<int>> g(n);
		vector<int> cnt(n);
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		function<bool(int, int, int)> dfs = [&](int i, int fa, int k) -> bool {
			++cnt[i];
			if (i == k) {
				return true;
			}
			bool ok = false;
			for (int j : g[i]) {
				if (j != fa) {
					ok = dfs(j, i, k);
					if (ok) {
						break;
					}
				}
			}
			if (!ok) {
				--cnt[i];
			}
			return ok;
		};
		function<pair<int, int>(int, int)> dfs2 = [&](int i, int fa) -> pair<int, int> {
			int a = cnt[i] * price[i];
			int b = a >> 1;
			for (int j : g[i]) {
				if (j != fa) {
					auto [x, y] = dfs2(j, i);
					a += min(x, y);
					b += x;
				}
			}
			return {a, b};
		};
		for (auto& t : trips) {
			int start = t[0], end = t[1];
			dfs(start, -1, end);
		}
		auto [a, b] = dfs2(0, -1);
		return min(a, b);
	}
};

shortest-cycle-in-a-graph.solutionCode:
class Solution {
public:
	int findShortestCycle(int n, vector<vector<int>>& edges) {
		vector<vector<int>> g(n);
		for (auto& e : edges) {
			int u = e[0], v = e[1];
			g[u].push_back(v);
			g[v].push_back(u);
		}
		const int inf = 1 << 30;
		auto bfs = [&](int u, int v) -> int {
			int dist[n];
			fill(dist, dist + n, inf);
			dist[u] = 0;
			queue<int> q{{u}};
			while (!q.empty()) {
				int i = q.front();
				q.pop();
				for (int j : g[i]) {
					if ((i == u && j == v) || (i == v && j == u) || dist[j] != inf) {
						continue;
					}
					dist[j] = dist[i] + 1;
					q.push(j);
				}
			}
			return dist[v] + 1;
		};
		int ans = inf;
		for (auto& e : edges) {
			int u = e[0], v = e[1];
			ans = min(ans, bfs(u, v));
		}
		return ans < inf ? ans : -1;
	}
};

