class Solution {
public:
	int collectTheCoins(vector<int>& coins, vector<vector<int>>& edges) {
		int n = coins.size();
		unordered_set<int> g[n];
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].insert(b);
			g[b].insert(a);
		}
		queue<int> q;
		for (int i = 0; i < n; ++i) {
			if (coins[i] == 0 && g[i].size() == 1) {
				q.push(i);
			}
		}
		while (!q.empty()) {
			int i = q.front();
			q.pop();
			for (int j : g[i]) {
				g[j].erase(i);
				if (coins[j] == 0 && g[j].size() == 1) {
					q.push(j);
				}
			}
			g[i].clear();
		}
		for (int k = 0; k < 2; ++k) {
			vector<int> q;
			for (int i = 0; i < n; ++i) {
				if (g[i].size() == 1) {
					q.push_back(i);
				}
			}
			for (int i : q) {
				for (int j : g[i]) {
					g[j].erase(i);
				}
				g[i].clear();
			}
		}
		int ans = 0;
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			if (g[a].size() && g[b].size()) {
				ans += 2;
			}
		}
		return ans;
	}
};

beautiful-pairs.solutionCode:
class Solution {
public:
	vector<int> beautifulPair(vector<int>& nums1, vector<int>& nums2) {
		int n = nums1.size();
		unordered_map<long long, vector<int>> pl;
		for (int i = 0; i < n; ++i) {
			pl[f(nums1[i], nums2[i])].push_back(i);
		}
		vector<tuple<int, int, int>> points;
		for (int i = 0; i < n; ++i) {
			long long z = f(nums1[i], nums2[i]);
			if (pl[z].size() > 1) {
				return {i, pl[z][1]};
			}
			points.emplace_back(nums1[i], nums2[i], i);
		}

		function<tuple<int, int, int>(int, int)> dfs = [&](int l, int r) -> tuple<int, int, int> {
			if (l >= r) {
				return {1 << 30, -1, -1};
			}
			int m = (l + r) >> 1;
			int x = get<0>(points[m]);
			auto t1 = dfs(l, m);
			auto t2 = dfs(m + 1, r);
			if (get<0>(t1) > get<0>(t2) || (get<0>(t1) == get<0>(t2) && (get<1>(t1) > get<1>(t2) || (get<1>(t1) == get<1>(t2) && get<2>(t1) > get<2>(t2))))) {
				swap(t1, t2);
			}
			vector<tuple<int, int, int>> t;
			for (int i = l; i <= r; ++i) {
				if (abs(get<0>(points[i]) - x) <= get<0>(t1)) {
					t.emplace_back(points[i]);
				}
			}
			sort(t.begin(), t.end(), [](const tuple<int, int, int>& a, const tuple<int, int, int>& b) {
				return get<1>(a) < get<1>(b);
			});
			for (int i = 0; i < t.size(); ++i) {
				for (int j = i + 1; j < t.size(); ++j) {
					if (get<1>(t[j]) - get<1>(t[i]) > get<0>(t1)) {
						break;
					}
					int pi = min(get<2>(t[i]), get<2>(t[j]));
					int pj = max(get<2>(t[i]), get<2>(t[j]));
					int d = dist(get<0>(t[i]), get<1>(t[i]), get<0>(t[j]), get<1>(t[j]));
					if (d < get<0>(t1) || (d == get<0>(t1) && (pi < get<1>(t1) || (pi == get<1>(t1) && pj < get<2>(t1))))) {
						t1 = {d, pi, pj};
					}
				}
			}
			return t1;
		};

		sort(points.begin(), points.end());
		auto [_, pi, pj] = dfs(0, points.size() - 1);
		return {pi, pj};
	}

	long long f(int x, int y) {
		return x * 100000LL + y;
	}

	int dist(int x1, int y1, int x2, int y2) {
		return abs(x1 - x2) + abs(y1 - y2);
	}
};

find-the-substring-with-maximum-cost.solutionCode:
class Solution {
public:
	int maximumCostSubstring(string s, string chars, vector<int>& vals) {
		vector<int> d(26);
		iota(d.begin(), d.end(), 1);
		int m = chars.size();
		for (int i = 0; i < m; ++i) {
			d[chars[i] - 'a'] = vals[i];
		}
		int ans = 0, tot = 0, mi = 0;
		for (char& c : s) {
			int v = d[c - 'a'];
			tot += v;
			ans = max(ans, tot - mi);
			mi = min(mi, tot);
