class Solution {
public:
	long long maximumOr(vector<int>& nums, int k) {
		int n = nums.size();
		long long suf[n + 1];
		memset(suf, 0, sizeof(suf));
		for (int i = n - 1; i >= 0; --i) {
			suf[i] = suf[i + 1] | nums[i];
		}
		long long ans = 0, pre = 0;
		for (int i = 0; i < n; ++i) {
			ans = max(ans, pre | (1LL * nums[i] << k) | suf[i + 1]);
			pre |= nums[i];
		}
		return ans;
	}
};

