		int n = nums.size();
		int cnt[101]{};
		for (int i = 0; i < k; ++i) {
			++cnt[nums[i] + 50];
		}
		vector<int> ans(n - k + 1);
		auto f = [&](int x) {
			int s = 0;
			for (int i = 0; i < 50; ++i) {
				s += cnt[i];
				if (s >= x) {
					return i - 50;
				}
			}
			return 0;
		};
		ans[0] = f(x);
		for (int i = k, j = 1; i < n; ++i) {
			++cnt[nums[i] + 50];
			--cnt[nums[i - k] + 50];
			ans[j++] = f(x);
		}
		return ans;
	}
};

the-knight’s-tour.solutionCode:
class Solution {
public:
	vector<vector<int>> tourOfKnight(int m, int n, int r, int c) {
		vector<vector<int>> g(m, vector<int>(n, -1));
		g[r][c] = 0;
		int dirs[9] = {-2, -1, 2, 1, -2, 1, 2, -1, -2};
		bool ok = false;
		function<void(int, int)> dfs = [&](int i, int j) {
			if (g[i][j] == m * n - 1) {
				ok = true;
				return;
			}
			for (int k = 0; k < 8; ++k) {
				int x = i + dirs[k], y = j + dirs[k + 1];
				if (x >= 0 && x < m && y >= 0 && y < n && g[x][y] == -1) {
					g[x][y] = g[i][j] + 1;
					dfs(x, y);
					if (ok) {
						return;
					}
					g[x][y] = -1;
				}
			}
		};
		dfs(r, c);
		return g;
	}
};

