class Solution {
public:
	int nthSuperUglyNumber(int n, vector<int>& primes) {
		priority_queue<int, vector<int>, greater<int>> q;
		q.push(1);
		int x = 0;
		while (n--) {
			x = q.top();
			q.pop();
			for (int& k : primes) {
				if (x <= INT_MAX / k) {
					q.push(k * x);
				}
				if (x % k == 0) {
					break;
				}
			}
		}
		return x;
	}
};

