class BinaryIndexedTree {
public:
	int n;
	vector<int> c;

	BinaryIndexedTree(int _n)
		: n(_n)
		, c(_n + 1) {}

	void update(int x, int delta) {
		while (x <= n) {
			c[x] += delta;
			x += lowbit(x);
		}
	}

	int query(int x) {
		int s = 0;
		while (x > 0) {
			s += c[x];
			x -= lowbit(x);
		}
		return s;
	}

	int lowbit(int x) {
		return x & -x;
	}
};

class Solution {
public:
	vector<int> countSmaller(vector<int>& nums) {
		unordered_set<int> s(nums.begin(), nums.end());
		vector<int> alls(s.begin(), s.end());
		sort(alls.begin(), alls.end());
		unordered_map<int, int> m;
		int n = alls.size();
		for (int i = 0; i < n; ++i) m[alls[i]] = i + 1;
		BinaryIndexedTree* tree = new BinaryIndexedTree(n);
		vector<int> ans(nums.size());
		for (int i = nums.size() - 1; i >= 0; --i) {
			int x = m[nums[i]];
			tree->update(x, 1);
			ans[i] = tree->query(x - 1);
		}
		return ans;
	}
};

design-snake-game.solutionCode:
class SnakeGame {
public:
	SnakeGame(int width, int height, vector<vector<int>>& food) {
		m = height;
		n = width;
		this->food = food;
		score = 0;
		idx = 0;
		q.push_back(0);
		vis.insert(0);
	}

	int move(string direction) {
		int p = q.front();
		int i = p / n, j = p % n;
		int x = i, y = j;
		if (direction == "U") {
			--x;
		} else if (direction == "D") {
			++x;
		} else if (direction == "L") {
			--y;
		} else {
			++y;
		}
		if (x < 0 || x >= m || y < 0 || y >= n) {
			return -1;
		}
		if (idx < food.size() && x == food[idx][0] && y == food[idx][1]) {
			++score;
			++idx;
		} else {
			int tail = q.back();
			q.pop_back();
			vis.erase(tail);
		}
		int cur = f(x, y);
		if (vis.count(cur)) {
			return -1;
		}
		q.push_front(cur);
		vis.insert(cur);
		return score;
	}

private:
	int m;
	int n;
	vector<vector<int>> food;
	int score;
	int idx;
	deque<int> q;
	unordered_set<int> vis;

	int f(int i, int j) {
		return i * n + j;
	}
};

