class Solution {
public:
	int lengthOfLongestSubstringKDistinct(string s, int k) {
		unordered_map<char, int> cnt;
		int l = 0;
		for (char& c : s) {
			++cnt[c];
			if (cnt.size() > k) {
				if (--cnt[s[l]] == 0) {
					cnt.erase(s[l]);
				}
				++l;
			}
		}
		return s.size() - l;
	}
};

