class Solution {
public:
	int lengthLongestPath(string input) {
		int i = 0, n = input.size();
		int ans = 0;
		stack<int> stk;
		while (i < n) {
			int ident = 0;
			for (; input[i] == '\t'; ++i) {
				++ident;
			}

			int cur = 0;
			bool isFile = false;
			for (; i < n && input[i] != '\n'; ++i) {
				++cur;
				if (input[i] == '.') {
					isFile = true;
				}
			}
			++i;

			// popd
			while (!stk.empty() && stk.size() > ident) {
				stk.pop();
			}

			if (stk.size() > 0) {
				cur += stk.top() + 1;
			}

			// pushd
			if (!isFile) {
				stk.push(cur);
				continue;
			}

			ans = max(ans, cur);
		}
		return ans;
	}
};

house-robber-iii.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	int rob(TreeNode* root) {
		function<pair<int, int>(TreeNode*)> dfs = [&](TreeNode* root) -> pair<int, int> {
			if (!root) {
				return make_pair(0, 0);
			}
			auto [la, lb] = dfs(root->left);
			auto [ra, rb] = dfs(root->right);
			return make_pair(root->val + lb + rb, max(la, lb) + max(ra, rb));
		};
		auto [a, b] = dfs(root);
		return max(a, b);
	}
};

