class Solution {
public:
	vector<int> sortTransformedArray(vector<int>& nums, int a, int b, int c) {
		int n = nums.size();
		vector<int> ans(n);
		int i = 0, j = n - 1;

		auto f = [&](int x) {
			return a * x * x + b * x + c;
		};

		for (int k = 0; k < n; k++) {
			int y1 = f(nums[i]);
			int y2 = f(nums[j]);
			if (a > 0) {
				if (y1 > y2) {
					ans[n - k - 1] = y1;
					i++;
				} else {
					ans[n - k - 1] = y2;
					j--;
				}
			} else {
				if (y1 > y2) {
					ans[k] = y2;
					j--;
				} else {
					ans[k] = y1;
					i++;
				}
			}
		}
		return ans;
	}
};

