class UnionFind {
public:
	UnionFind(int n) {
		p = vector<int>(n);
		size = vector<int>(n, 1);
		iota(p.begin(), p.end(), 0);
	}

	bool unite(int a, int b) {
		int pa = find(a), pb = find(b);
		if (pa == pb) {
			return false;
		}
		if (size[pa] > size[pb]) {
			p[pb] = pa;
			size[pa] += size[pb];
		} else {
			p[pa] = pb;
			size[pb] += size[pa];
		}
		return true;
	}

	int find(int x) {
		if (p[x] != x) {
			p[x] = find(p[x]);
		}
		return p[x];
	}

private:
	vector<int> p, size;
};

class Solution {
public:
	vector<int> numIslands2(int m, int n, vector<vector<int>>& positions) {
		int grid[m][n];
		memset(grid, 0, sizeof(grid));
		UnionFind uf(m * n);
		int dirs[5] = {-1, 0, 1, 0, -1};
		int cnt = 0;
		vector<int> ans;
		for (auto& p : positions) {
			int i = p[0], j = p[1];
			if (grid[i][j]) {
				ans.push_back(cnt);
				continue;
			}
			grid[i][j] = 1;
			++cnt;
			for (int k = 0; k < 4; ++k) {
				int x = i + dirs[k], y = j + dirs[k + 1];
				if (x >= 0 && x < m && y >= 0 && y < n && grid[x][y] && uf.unite(i * n + j, x * n + y)) {
					--cnt;
				}
			}
			ans.push_back(cnt);
		}
		return ans;
	}
};

