		int m = matrix.size(), n = matrix[0].size();
		int f[m][n];
		memset(f, 0, sizeof(f));
		int ans = 0;
		int dirs[5] = {-1, 0, 1, 0, -1};

		function<int(int, int)> dfs = [&](int i, int j) -> int {
			if (f[i][j]) {
				return f[i][j];
			}
			for (int k = 0; k < 4; ++k) {
				int x = i + dirs[k], y = j + dirs[k + 1];
				if (x >= 0 && x < m && y >= 0 && y < n && matrix[x][y] > matrix[i][j]) {
					f[i][j] = max(f[i][j], dfs(x, y));
				}
			}
			return ++f[i][j];
		};

		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				ans = max(ans, dfs(i, j));
			}
		}
