		int left = matrix[0][0], right = matrix[n - 1][n - 1];
		while (left < right) {
			int mid = left + right >> 1;
			if (check(matrix, mid, k, n)) {
				right = mid;
			} else {
				left = mid + 1;
			}
		}
		return left;
	}

private:
	bool check(vector<vector<int>>& matrix, int mid, int k, int n) {
		int count = 0;
		int i = n - 1, j = 0;
		while (i >= 0 && j < n) {
			if (matrix[i][j] <= mid) {
				count += (i + 1);
				++j;
			} else {
				--i;
			}
		}
		return count >= k;
	}
};

