class Solution {
public:
	int lastRemaining(int n) {
		int a1 = 1, an = n, step = 1;
		for (int i = 0, cnt = n; cnt > 1; cnt >>= 1, step <<= 1, ++i) {
			if (i % 2) {
				an -= step;
				if (cnt % 2) a1 += step;
			} else {
				a1 += step;
				if (cnt % 2) an -= step;
			}
		}
		return a1;
	}
};

count-numbers-with-unique-digits.solutionCode:
class Solution {
public:
	int countNumbersWithUniqueDigits(int n) {
		int f[n + 1][1 << 10];
		memset(f, -1, sizeof(f));
		auto dfs = [&](this auto&& dfs, int i, int mask, bool lead) -> int {
			if (i < 0) {
				return 1;
			}
			if (!lead && f[i][mask] != -1) {
				return f[i][mask];
			}
			int ans = 0;
			for (int j = 0; j <= 9; ++j) {
				if (mask >> j & 1) {
					continue;
				}
				if (lead && j == 0) {
					ans += dfs(i - 1, mask, true);
				} else {
					ans += dfs(i - 1, mask | 1 << i, false);
				}
			}
			if (!lead) {
				f[i][mask] = ans;
			}
			return ans;
		};
		return dfs(n - 1, 0, true);
	}
};

super-pow.solutionCode:
class Solution {
public:
	int superPow(int a, vector<int>& b) {
		using ll = long long;
		const int mod = 1337;
		ll ans = 1;
		auto qpow = [&](ll a, int n) {
			ll ans = 1;
			for (; n; n >>= 1) {
				if (n & 1) {
					ans = ans * a % mod;
				}
				a = a * a % mod;
			}
			return (int) ans;
		};
		for (int i = b.size() - 1; ~i; --i) {
			ans = ans * qpow(a, b[i]) % mod;
			a = qpow(a, 10);
		}
		return ans;
	}
};

