class Solution {
public:
	int longestSubstring(string s, int k) {
		function<int(int, int)> dfs = [&](int l, int r) -> int {
			int cnt[26] = {0};
			for (int i = l; i <= r; ++i) {
				cnt[s[i] - 'a']++;
			}
			char split = 0;
			for (int i = 0; i < 26; ++i) {
				if (cnt[i] > 0 && cnt[i] < k) {
					split = 'a' + i;
					break;
				}
			}
			if (split == 0) {
				return r - l + 1;
			}
			int i = l;
			int ans = 0;
			while (i <= r) {
				while (i <= r && s[i] == split) {
					++i;
				}
				if (i >= r) {
					break;
				}
				int j = i;
				while (j <= r && s[j] != split) {
					++j;
				}
				int t = dfs(i, j - 1);
				ans = max(ans, t);
				i = j;
			}
			return ans;
		};
		return dfs(0, s.size() - 1);
	}
};

perfect-rectangle.solutionCode:
#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
	bool isRectangleCover(vector<vector<int>>& rectangles) {
		long long area = 0;
		int minX = rectangles[0][0], minY = rectangles[0][1];
		int maxX = rectangles[0][2], maxY = rectangles[0][3];

		using pii = pair<int, int>;
		map<pii, int> cnt;

		for (auto& r : rectangles) {
			area += (r[2] - r[0]) * (r[3] - r[1]);

			minX = min(minX, r[0]);
			minY = min(minY, r[1]);
			maxX = max(maxX, r[2]);
			maxY = max(maxY, r[3]);

			++cnt[{r[0], r[1]}];
			++cnt[{r[0], r[3]}];
			++cnt[{r[2], r[3]}];
			++cnt[{r[2], r[1]}];
		}

		if (area != (long long) (maxX - minX) * (maxY - minY) || cnt[{minX, minY}] != 1 || cnt[{minX, maxY}] != 1 || cnt[{maxX, maxY}] != 1 || cnt[{maxX, minY}] != 1) {
			return false;
		}

		cnt.erase({minX, minY});
		cnt.erase({minX, maxY});
		cnt.erase({maxX, maxY});
		cnt.erase({maxX, minY});

		return all_of(cnt.begin(), cnt.end(), [](pair<pii, int> e) {
			return e.second == 2 || e.second == 4;
		});
	}
};

minimum-height-trees.solutionCode:
class Solution {
public:
	vector<int> findMinHeightTrees(int n, vector<vector<int>>& edges) {
		if (n == 1) {
			return {0};
		}
		vector<vector<int>> g(n);
		vector<int> degree(n);
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
			++degree[a];
			++degree[b];
		}
		queue<int> q;
		for (int i = 0; i < n; ++i) {
			if (degree[i] == 1) {
				q.push(i);
			}
		}
		vector<int> ans;
		while (!q.empty()) {
			ans.clear();
			for (int i = q.size(); i > 0; --i) {
				int a = q.front();
				q.pop();
				ans.push_back(a);
				for (int b : g[a]) {
					if (--degree[b] == 1) {
						q.push(b);
					}
				}
			}
		}
		return ans;
	}
};

