class Solution {
public:
	int minArea(vector<vector<char>>& image, int x, int y) {
		int m = image.size(), n = image[0].size();
		int left = 0, right = x;
		while (left < right) {
			int mid = (left + right) >> 1;
			int c = 0;
			while (c < n && image[mid][c] == '0') ++c;
			if (c < n)
				right = mid;
			else
				left = mid + 1;
		}
		int u = left;
		left = x;
		right = m - 1;
		while (left < right) {
			int mid = (left + right + 1) >> 1;
			int c = 0;
			while (c < n && image[mid][c] == '0') ++c;
			if (c < n)
				left = mid;
			else
				right = mid - 1;
		}
		int d = left;
		left = 0;
		right = y;
		while (left < right) {
			int mid = (left + right) >> 1;
			int r = 0;
			while (r < m && image[r][mid] == '0') ++r;
			if (r < m)
				right = mid;
			else
				left = mid + 1;
		}
		int l = left;
		left = y;
		right = n - 1;
		while (left < right) {
			int mid = (left + right + 1) >> 1;
			int r = 0;
			while (r < m && image[r][mid] == '0') ++r;
			if (r < m)
				left = mid;
			else
				right = mid - 1;
		}
		int r = left;
		return (d - u + 1) * (r - l + 1);
	}
};

