public:
	int minSpaceWastedKResizing(vector<int>& nums, int k) {
		++k;
		int n = nums.size();
		vector<vector<int>> g(n, vector<int>(n));
		for (int i = 0; i < n; ++i) {
			int s = 0, mx = 0;
			for (int j = i; j < n; ++j) {
				mx = max(mx, nums[j]);
				s += nums[j];
				g[i][j] = mx * (j - i + 1) - s;
			}
		}
		int inf = 0x3f3f3f3f;
		vector<vector<int>> f(n + 1, vector<int>(k + 1, inf));
		f[0][0] = 0;
		for (int i = 1; i <= n; ++i) {
			for (int j = 1; j <= k; ++j) {
				for (int h = 0; h < i; ++h) {
					f[i][j] = min(f[i][j], f[h][j - 1] + g[h][i - 1]);
				}
			}
		}
		return f[n][k];
	}
};

