class Solution {
public:
	vector<vector<int>> rotateGrid(vector<vector<int>>& grid, int k) {
		int m = grid.size(), n = grid[0].size();
		auto rotate = [&](int p, int k) {
			vector<int> nums;
			for (int j = p; j < n - p - 1; ++j) {
				nums.push_back(grid[p][j]);
			}
			for (int i = p; i < m - p - 1; ++i) {
				nums.push_back(grid[i][n - p - 1]);
			}
			for (int j = n - p - 1; j > p; --j) {
				nums.push_back(grid[m - p - 1][j]);
			}
			for (int i = m - p - 1; i > p; --i) {
				nums.push_back(grid[i][p]);
			}
			int l = nums.size();
			k %= l;
			if (k == 0) {
				return;
			}
			for (int j = p; j < n - p - 1; ++j) {
				grid[p][j] = nums[k++ % l];
			}
			for (int i = p; i < m - p - 1; ++i) {
				grid[i][n - p - 1] = nums[k++ % l];
			}
			for (int j = n - p - 1; j > p; --j) {
				grid[m - p - 1][j] = nums[k++ % l];
			}
			for (int i = m - p - 1; i > p; --i) {
				grid[i][p] = nums[k++ % l];
			}
		};
		for (int p = 0; p < min(m, n) / 2; ++p) {
			rotate(p, k);
		}
		return grid;
	}
};

design-movie-rental-system.solutionCode:
class MovieRentingSystem {
private:
	unordered_map<int, set<pair<int, int>>> available; // movie -> {(price, shop)}
	unordered_map<long long, int> priceMap;
	set<tuple<int, int, int>> rented; // {(price, shop, movie)}

	long long f(int shop, int movie) {
		return ((long long) shop << 30) | movie;
	}

public:
	MovieRentingSystem(int n, vector<vector<int>>& entries) {
		for (auto& e : entries) {
			int shop = e[0], movie = e[1], price = e[2];
			available[movie].insert({price, shop});
			priceMap[f(shop, movie)] = price;
		}
	}

	vector<int> search(int movie) {
		vector<int> res;
		if (!available.count(movie)) {
			return res;
		}
		int cnt = 0;
		for (auto& [price, shop] : available[movie]) {
			res.push_back(shop);
			if (++cnt == 5) {
				break;
			}
		}
		return res;
	}

	void rent(int shop, int movie) {
		int price = priceMap[f(shop, movie)];
		available[movie].erase({price, shop});
		rented.insert({price, shop, movie});
	}

	void drop(int shop, int movie) {
		int price = priceMap[f(shop, movie)];
		rented.erase({price, shop, movie});
		available[movie].insert({price, shop});
	}

	vector<vector<int>> report() {
		vector<vector<int>> res;
		int cnt = 0;
		for (auto& [price, shop, movie] : rented) {
			res.push_back({shop, movie});
			if (++cnt == 5) {
				break;
			}
		}
		return res;
	}
};

