		vector<long long> f(n);
		const int mod = 1e9 + 7;
		for (int i = 1; i < n; ++i) {
			f[i] = (f[i - 1] + 1 + f[i - 1] - f[nextVisit[i - 1]] + 1 + mod) % mod;
