class Solution {
public:
	bool validPath(int n, vector<vector<int>>& edges, int source, int destination) {
		vector<int> g[n];
		vector<bool> vis(n);
		for (const auto& e : edges) {
			int u = e[0], v = e[1];
			g[u].push_back(v);
			g[v].push_back(u);
		}
		function<bool(int)> dfs = [&](int i) -> bool {
			if (i == destination) {
				return true;
			}
			vis[i] = true;
			for (int j : g[i]) {
				if (!vis[j] && dfs(j)) {
					return true;
				}
			}
			return false;
		};
		return dfs(source);
	}
};

