	int numberOfUniqueGoodSubsequences(string binary) {
		const int mod = 1e9 + 7;
		int f = 0, g = 0;
		int ans = 0;
		for (char& c : binary) {
			if (c == '0') {
				g = (g + f) % mod;
				ans = 1;
			} else {
				f = (f + g + 1) % mod;
			}
		}
		ans = (ans + f + g) % mod;
		return ans;
	}
};

