	def waysToBuildRooms(self, prevRoom: List[int]) -> int:
		modulo = 10**9 + 7
		ingoing = defaultdict(set)
		outgoing = defaultdict(set)

		for i in range(1, len(prevRoom)):
			ingoing[i].add(prevRoom[i])
			outgoing[prevRoom[i]].add(i)
		ans = [1]

		def recurse(i):
			if len(outgoing[i]) == 0:
				return 1

			nodes_in_tree = 0
			for v in outgoing[i]:
				cn = recurse(v)
				if nodes_in_tree != 0:
					ans[0] *= comb(nodes_in_tree + cn, cn)
					ans[0] %= modulo
				nodes_in_tree += cn
			return nodes_in_tree + 1

		recurse(0)
		return ans[0] % modulo

count-number-of-special-subsequences.solutionCode:
class Solution {
public:
	int countSpecialSubsequences(vector<int>& nums) {
		const int mod = 1e9 + 7;
		int n = nums.size();
		int f[n][3];
		memset(f, 0, sizeof(f));
		f[0][0] = nums[0] == 0;
		for (int i = 1; i < n; ++i) {
			if (nums[i] == 0) {
				f[i][0] = (2 * f[i - 1][0] % mod + 1) % mod;
				f[i][1] = f[i - 1][1];
				f[i][2] = f[i - 1][2];
			} else if (nums[i] == 1) {
				f[i][0] = f[i - 1][0];
				f[i][1] = (f[i - 1][0] + 2 * f[i - 1][1] % mod) % mod;
				f[i][2] = f[i - 1][2];
			} else {
				f[i][0] = f[i - 1][0];
				f[i][1] = f[i - 1][1];
				f[i][2] = (f[i - 1][1] + 2 * f[i - 1][2] % mod) % mod;
			}
		}
		return f[n - 1][2];
	}
};

