			int pre = 0;
			for (int i = 0; i < n; ++i) {
				if (i == k) {
					continue;
				}
				if (pre >= nums[i]) {
					return false;
				}
				pre = nums[i];
			}
			return true;
		};
		int i = 0;
		while (i + 1 < n && nums[i] < nums[i + 1]) {
			++i;
		}
		return check(i) || check(i + 1);
	}
};

last-day-where-you-can-still-cross.solutionCode:
class Solution {
public:
	int latestDayToCross(int row, int col, vector<vector<int>>& cells) {
		int l = 1, r = cells.size();
		int g[row][col];
		int dirs[5] = {0, 1, 0, -1, 0};
		auto check = [&](int k) -> bool {
			memset(g, 0, sizeof(g));
			for (int i = 0; i < k; ++i) {
				g[cells[i][0] - 1][cells[i][1] - 1] = 1;
			}
			queue<pair<int, int>> q;
			for (int j = 0; j < col; ++j) {
				if (g[0][j] == 0) {
					q.emplace(0, j);
					g[0][j] = 1;
				}
			}
			while (!q.empty()) {
				auto [x, y] = q.front();
				q.pop();
				if (x == row - 1) {
					return true;
				}
				for (int i = 0; i < 4; ++i) {
					int nx = x + dirs[i];
					int ny = y + dirs[i + 1];
					if (nx >= 0 && nx < row && ny >= 0 && ny < col && g[nx][ny] == 0) {
						q.emplace(nx, ny);
						g[nx][ny] = 1;
					}
				}
			}
			return false;
		};
		while (l < r) {
			int mid = (l + r + 1) >> 1;
			if (check(mid)) {
				l = mid;
			} else {
				r = mid - 1;
			}
		}
		return l;
	}
};

