class Solution {
public:
	vector<int> goodDaysToRobBank(vector<int>& security, int time) {
		int n = security.size();
		if (n <= time * 2) return {};
		vector<int> left(n);
		vector<int> right(n);
		for (int i = 1; i < n; ++i)
			if (security[i] <= security[i - 1])
				left[i] = left[i - 1] + 1;
		for (int i = n - 2; i >= 0; --i)
			if (security[i] <= security[i + 1])
				right[i] = right[i + 1] + 1;
		vector<int> ans;
		for (int i = time; i < n - time; ++i)
			if (time <= min(left[i], right[i]))
				ans.push_back(i);
		return ans;
	}
};

