minimum-difference-in-sums-after-removal.solutionCode:
class Solution {
public:
	long long minimumDifference(vector<int>& nums) {
		int m = nums.size();
		int n = m / 3;

		using ll = long long;
		ll s = 0;
		ll pre[m + 1];
		priority_queue<int> q1;
		for (int i = 1; i <= n * 2; ++i) {
			int x = nums[i - 1];
			s += x;
			q1.push(x);
			if (q1.size() > n) {
				s -= q1.top();
				q1.pop();
			}
			pre[i] = s;
		}
		s = 0;
		ll suf[m + 1];
		priority_queue<int, vector<int>, greater<int>> q2;
		for (int i = m; i > n; --i) {
			int x = nums[i - 1];
			s += x;
			q2.push(x);
			if (q2.size() > n) {
				s -= q2.top();
				q2.pop();
			}
			suf[i] = s;
		}
		ll ans = 1e18;
		for (int i = n; i <= n * 2; ++i) {
			ans = min(ans, pre[i] - suf[i + 1]);
		}
		return ans;
	}
};

find-substring-with-given-hash-value.solutionCode:
class Solution {
public:
	string subStrHash(string s, int power, int modulo, int k, int hashValue) {
		long long h = 0, p = 1;
		int n = s.size();
		for (int i = n - 1; i >= n - k; --i) {
			int val = s[i] - 'a' + 1;
			h = ((h * power % modulo) + val) % modulo;
			if (i != n - k) {
				p = p * power % modulo;
			}
		}
		int j = n - k;
		for (int i = n - k - 1; i >= 0; --i) {
			int pre = s[i + k] - 'a' + 1;
			int cur = s[i] - 'a' + 1;
			h = ((h - pre * p % modulo + modulo) * power % modulo + cur) % modulo;
			if (h == hashValue) {
				j = i;
			}
		}
		return s.substr(j, k);
	}
};

