maximum-employees-to-be-invited-to-a-mee.solutionCode:
class Solution {
public:
	int maximumInvitations(vector<int>& favorite) {
		return max(maxCycle(favorite), topologicalSort(favorite));
	}

	int maxCycle(vector<int>& fa) {
		int n = fa.size();
		vector<bool> vis(n);
		int ans = 0;
		for (int i = 0; i < n; ++i) {
			if (vis[i]) continue;
			vector<int> cycle;
			int j = i;
			while (!vis[j]) {
				cycle.push_back(j);
				vis[j] = true;
				j = fa[j];
			}
			for (int k = 0; k < cycle.size(); ++k) {
				if (cycle[k] == j) {
					ans = max(ans, (int) cycle.size() - k);
					break;
				}
			}
		}
		return ans;
	}

	int topologicalSort(vector<int>& fa) {
		int n = fa.size();
		vector<int> indeg(n);
		vector<int> dist(n, 1);
		for (int v : fa) ++indeg[v];
		queue<int> q;
		for (int i = 0; i < n; ++i)
			if (indeg[i] == 0) q.push(i);
		while (!q.empty()) {
			int i = q.front();
			q.pop();
			dist[fa[i]] = max(dist[fa[i]], dist[i] + 1);
			if (--indeg[fa[i]] == 0) q.push(fa[i]);
		}
		int ans = 0;
		for (int i = 0; i < n; ++i)
			if (i == fa[fa[i]]) ans += dist[i];
		return ans;
	}
};

watering-plants-ii.solutionCode:
class Solution {
public:
	int minimumRefill(vector<int>& plants, int capacityA, int capacityB) {
		int a = capacityA, b = capacityB;
		int ans = 0;
		int i = 0, j = plants.size() - 1;
		for (; i < j; ++i, --j) {
			if (a < plants[i]) {
				++ans;
				a = capacityA;
			}
			a -= plants[i];
			if (b < plants[j]) {
				++ans;
				b = capacityB;
			}
			b -= plants[j];
		}
		ans += i == j && max(a, b) < plants[i];
		return ans;
	}
};

choose-numbers-from-two-arrays-in-range.solutionCode:
class Solution {
public:
	int countSubranges(vector<int>& nums1, vector<int>& nums2) {
		int n = nums1.size();
		int s1 = accumulate(nums1.begin(), nums1.end(), 0);
		int s2 = accumulate(nums2.begin(), nums2.end(), 0);
		int f[n][s1 + s2 + 1];
		memset(f, 0, sizeof(f));
		int ans = 0;
		const int mod = 1e9 + 7;
		for (int i = 0; i < n; ++i) {
			int a = nums1[i], b = nums2[i];
			f[i][a + s2]++;
			f[i][-b + s2]++;
			if (i) {
				for (int j = 0; j <= s1 + s2; ++j) {
					if (j >= a) {
						f[i][j] = (f[i][j] + f[i - 1][j - a]) % mod;
					}
					if (j + b <= s1 + s2) {
						f[i][j] = (f[i][j] + f[i - 1][j + b]) % mod;
					}
				}
			}
			ans = (ans + f[i][s2]) % mod;
		}
		return ans;
	}
};

number-of-ways-to-divide-a-long-corridor.solutionCode:
class Solution {
public:
	int numberOfWays(string corridor) {
		int n = corridor.size();
		int f[n][3];
		memset(f, -1, sizeof(f));
		const int mod = 1e9 + 7;
		auto dfs = [&](this auto&& dfs, int i, int k) -> int {
			if (i >= n) {
				return k == 2;
			}
			if (f[i][k] != -1) {
				return f[i][k];
			}
			k += corridor[i] == 'S';
			if (k > 2) {
				return 0;
			}
			f[i][k] = dfs(i + 1, k);
			if (k == 2) {
				f[i][k] = (f[i][k] + dfs(i + 1, 0)) % mod;
			}
			return f[i][k];
		};
		return dfs(0, 0);
	}
};

