class Bitset {
public:
	string a, b;
	int cnt = 0;

	Bitset(int size) {
		a = string(size, '0');
		b = string(size, '1');
	}

	void fix(int idx) {
		if (a[idx] == '0') a[idx] = '1', ++cnt;
		b[idx] = '0';
	}

	void unfix(int idx) {
		if (a[idx] == '1') a[idx] = '0', --cnt;
		b[idx] = '1';
	}

	void flip() {
		swap(a, b);
		cnt = a.size() - cnt;
	}

	bool all() {
		return cnt == a.size();
	}

	bool one() {
		return cnt > 0;
	}

	int count() {
		return cnt;
	}

	string toString() {
		return a;
	}
};

