class Solution {
public:
	string abbreviateProduct(int left, int right) {
		int cnt2 = 0, cnt5 = 0;
		for (int i = left; i <= right; ++i) {
			int x = i;
			for (; x % 2 == 0; x /= 2) {
				++cnt2;
			}
			for (; x % 5 == 0; x /= 5) {
				++cnt5;
			}
		}
		int c = min(cnt2, cnt5);
		cnt2 = cnt5 = c;
		long long suf = 1;
		long double pre = 1;
		bool gt = false;
		for (int i = left; i <= right; ++i) {
			for (suf *= i; cnt2 && suf % 2 == 0; suf /= 2) {
				--cnt2;
			}
			for (; cnt5 && suf % 5 == 0; suf /= 5) {
				--cnt5;
			}
			if (suf >= 1e10) {
				gt = true;
				suf %= (long long) 1e10;
			}
			for (pre *= i; pre > 1e5; pre /= 10) {
			}
		}
		if (gt) {
			char buf[10];
			snprintf(buf, sizeof(buf), "%0*lld", 5, suf % (int) 1e5);
			return to_string((int) pre) + "..." + string(buf) + "e" + to_string(c);
		}
		return to_string(suf) + "e" + to_string(c);
	}
};

pour-water-between-buckets-to-make-water.solutionCode:
class Solution {
public:
	double equalizeWater(vector<int>& buckets, int loss) {
		double l = 0, r = *max_element(buckets.begin(), buckets.end());
		auto check = [&](double v) {
			double a = 0, b = 0;
			for (int x : buckets) {
				if (x > v) {
					a += x - v;
				} else {
					b += (v - x) * 100 / (100 - loss);
				}
			}
			return a >= b;
		};
		while (r - l > 1e-5) {
			double mid = (l + r) / 2;
			if (check(mid)) {
				l = mid;
			} else {
				r = mid;
			}
		}
		return l;
	}
};

create-binary-tree-from-descriptions.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	TreeNode* createBinaryTree(vector<vector<int>>& descriptions) {
		unordered_map<int, TreeNode*> nodes;
		unordered_set<int> children;
		for (const auto& d : descriptions) {
			int parent = d[0], child = d[1], isLeft = d[2];
			if (!nodes.contains(parent)) {
				nodes[parent] = new TreeNode(parent);
			}
			if (!nodes.contains(child)) {
				nodes[child] = new TreeNode(child);
			}
			if (isLeft) {
				nodes[parent]->left = nodes[child];
			} else {
				nodes[parent]->right = nodes[child];
			}
			children.insert(child);
		}
		for (const auto& [k, v] : nodes) {
			if (!children.contains(k)) {
				return v;
			}
		}
		return nullptr;
	}
};

