class BinaryIndexedTree {
public:
	int n;
	vector<int> c;

	BinaryIndexedTree(int _n)
		: n(_n)
		, c(_n + 1) {}

	void update(int x, int delta) {
		while (x <= n) {
			c[x] += delta;
			x += lowbit(x);
		}
	}

	int query(int x) {
		int s = 0;
		while (x > 0) {
			s += c[x];
			x -= lowbit(x);
		}
		return s;
	}

	int lowbit(int x) {
		return x & -x;
	}
};

class Solution {
public:
	long long goodTriplets(vector<int>& nums1, vector<int>& nums2) {
		int n = nums1.size();
		vector<int> pos(n);
		for (int i = 0; i < n; ++i) pos[nums2[i]] = i + 1;
		BinaryIndexedTree* tree = new BinaryIndexedTree(n);
		long long ans = 0;
		for (int& num : nums1) {
			int p = pos[num];
			int left = tree->query(p);
			int right = n - p - (tree->query(n) - tree->query(p));
			ans += 1ll * left * right;
			tree->update(p, 1);
		}
		return ans;
	}
};

