class Solution {
public:
	int minOperations(vector<vector<int>>& grid, int x) {
		int m = grid.size(), n = grid[0].size();
		int mod = grid[0][0] % x;
		int nums[m * n];
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j] % x != mod) {
					return -1;
				}
				nums[i * n + j] = grid[i][j];
			}
		}
		sort(nums, nums + m * n);
		int mid = nums[(m * n) >> 1];
		int ans = 0;
		for (int v : nums) {
			ans += abs(v - mid) / x;
		}
		return ans;
	}
};

delete-the-middle-node-of-a-linked-list.solutionCode:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	ListNode* deleteMiddle(ListNode* head) {
		ListNode* dummy = new ListNode(0, head);
		ListNode* slow = dummy;
		ListNode* fast = head;
		while (fast && fast->next) {
			slow = slow->next;
			fast = fast->next->next;
		}
		slow->next = slow->next->next;
		return dummy->next;
	}
};

