class Solution {
public:
	long long kMirror(int k, int n) {
		long long ans = 0;
		for (int l = 1;; ++l) {
			int x = pow(10, (l - 1) / 2);
			int y = pow(10, (l + 1) / 2);
			for (int i = x; i < y; ++i) {
				long long v = i;
				int j = (l % 2 == 0) ? i : i / 10;
				while (j > 0) {
					v = v * 10 + j % 10;
					j /= 10;
				}
				if (check(v, k)) {
					ans += v;
					if (--n == 0) {
						return ans;
					}
				}
			}
		}
	}

private:
	bool check(long long x, int k) {
		vector<int> s;
		while (x > 0) {
			s.push_back(x % k);
			x /= k;
		}
		for (int i = 0, j = s.size() - 1; i < j; ++i, --j) {
			if (s[i] != s[j]) {
				return false;
			}
		}
		return true;
	}
};

