maximum-product-of-the-length-of-two-pal.solutionCode:
class Solution {
public:
	int maxProduct(string s) {
		int n = s.size();
		vector<bool> p(1 << n, true);
		for (int k = 1; k < 1 << n; ++k) {
			for (int i = 0, j = n - 1; i < j; ++i, --j) {
				while (i < j && !(k >> i & 1)) {
					++i;
				}
				while (i < j && !(k >> j & 1)) {
					--j;
				}
				if (i < j && s[i] != s[j]) {
					p[k] = false;
					break;
				}
			}
		}
		int ans = 0;
		for (int i = 1; i < 1 << n; ++i) {
			if (p[i]) {
				int a = __builtin_popcount(i);
				int mx = ((1 << n) - 1) ^ i;
				for (int j = mx; j; j = (j - 1) & mx) {
					if (p[j]) {
						int b = __builtin_popcount(j);
						ans = max(ans, a * b);
					}
				}
			}
		}
		return ans;
	}
};

maximum-number-of-ways-to-partition-an-a.solutionCode:
class Solution {
public:
	int waysToPartition(vector<int>& nums, int k) {
		int n = nums.size();
		long long s[n];
		s[0] = nums[0];
		unordered_map<long long, int> right;
		for (int i = 0; i < n - 1; ++i) {
			right[s[i]]++;
			s[i + 1] = s[i] + nums[i + 1];
		}
		int ans = 0;
		if (s[n - 1] % 2 == 0) {
			ans = right[s[n - 1] / 2];
		}
		unordered_map<long long, int> left;
		for (int i = 0; i < n; ++i) {
			int d = k - nums[i];
			if ((s[n - 1] + d) % 2 == 0) {
				int t = left[(s[n - 1] + d) / 2] + right[(s[n - 1] - d) / 2];
				ans = max(ans, t);
			}
			left[s[i]]++;
			right[s[i]]--;
		}
		return ans;
	}
};

