plates-between-candles.solutionCode:
class Solution {
public:
	vector<int> platesBetweenCandles(string s, vector<vector<int>>& queries) {
		int n = s.size();
		vector<int> presum(n + 1);
		for (int i = 0; i < n; ++i) presum[i + 1] = presum[i] + (s[i] == '*');
		vector<int> left(n);
		vector<int> right(n);
		for (int i = 0, l = -1; i < n; ++i) {
			if (s[i] == '|') l = i;
			left[i] = l;
		}
		for (int i = n - 1, r = -1; i >= 0; --i) {
			if (s[i] == '|') r = i;
			right[i] = r;
		}
		vector<int> ans(queries.size());
		for (int k = 0; k < queries.size(); ++k) {
			int i = right[queries[k][0]];
			int j = left[queries[k][1]];
			if (i >= 0 && j >= 0 && i < j) ans[k] = presum[j] - presum[i + 1];
		}
		return ans;
	}
};

minimum-cost-to-separate-sentence-into-r.solutionCode:
class Solution {
public:
	int minimumCost(string sentence, int k) {
		istringstream iss(sentence);
		vector<int> s = {0};
		string w;
		while (iss >> w) {
			s.push_back(s.back() + w.size());
		}
		int n = s.size() - 1;
		int f[n];
		memset(f, -1, sizeof(f));
		auto dfs = [&](this auto&& dfs, int i) -> int {
			if (s[n] - s[i] + n - i - 1 <= k) {
				return 0;
			}
			if (f[i] != -1) {
				return f[i];
			}
			int ans = INT_MAX;
			for (int j = i + 1; j < n && s[j] - s[i] + j - i - 1 <= k; ++j) {
				int m = s[j] - s[i] + j - i - 1;
				ans = min(ans, dfs(j) + (k - m) * (k - m));
			}
			return f[i] = ans;
		};
		return dfs(0);
	}
};

parallel-courses-iii.solutionCode:
class Solution {
public:
	int minimumTime(int n, vector<vector<int>>& relations, vector<int>& time) {
		vector<vector<int>> g(n);
		vector<int> indeg(n);
		for (auto& e : relations) {
			int a = e[0] - 1, b = e[1] - 1;
			g[a].push_back(b);
			++indeg[b];
		}
		queue<int> q;
		vector<int> f(n);
		int ans = 0;
		for (int i = 0; i < n; ++i) {
			int v = indeg[i], t = time[i];
			if (v == 0) {
				q.push(i);
				f[i] = t;
				ans = max(ans, t);
			}
		}
		while (!q.empty()) {
			int i = q.front();
			q.pop();
			for (int j : g[i]) {
				if (--indeg[j] == 0) {
					q.push(j);
				}
				f[j] = max(f[j], f[i] + time[j]);
				ans = max(ans, f[j]);
			}
		}
		return ans;
	}
};

check-if-word-can-be-placed-in-crossword.solutionCode:
class Solution {
public:
	bool placeWordInCrossword(vector<vector<char>>& board, string word) {
		int m = board.size(), n = board[0].size();
		int k = word.size();
		auto check = [&](int i, int j, int a, int b) {
			int x = i + a * k, y = j + b * k;
			if (x >= 0 && x < m && y >= 0 && y < n && board[x][y] != '#') {
				return false;
			}
			for (char& c : word) {
				if (i < 0 || i >= m || j < 0 || j >= n || (board[i][j] != ' ' && board[i][j] != c)) {
					return false;
				}
				i += a;
				j += b;
			}
			return true;
		};
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				bool leftToRight = (j == 0 || board[i][j - 1] == '#') && check(i, j, 0, 1);
				bool rightToLeft = (j == n - 1 || board[i][j + 1] == '#') && check(i, j, 0, -1);
				bool upToDown = (i == 0 || board[i - 1][j] == '#') && check(i, j, 1, 0);
				bool downToUp = (i == m - 1 || board[i + 1][j] == '#') && check(i, j, -1, 0);
				if (leftToRight || rightToLeft || upToDown || downToUp) {
					return true;
				}
			}
		}
		return false;
	}
};

