class Solution {
public:
	int networkBecomesIdle(vector<vector<int>>& edges, vector<int>& patience) {
		int n = patience.size();
		vector<int> g[n];
		for (auto& e : edges) {
			int u = e[0], v = e[1];
			g[u].push_back(v);
			g[v].push_back(u);
		}
		queue<int> q{{0}};
		bool vis[n];
		memset(vis, false, sizeof(vis));
		vis[0] = true;
		int ans = 0, d = 0;
		while (!q.empty()) {
			++d;
			int t = d * 2;
			for (int i = q.size(); i; --i) {
				int u = q.front();
				q.pop();
				for (int v : g[u]) {
					if (!vis[v]) {
						vis[v] = true;
						q.push(v);
						ans = max(ans, (t - 1) / patience[v] * patience[v] + t + 1);
					}
				}
			}
		}
		return ans;
	}
};

longest-subsequence-repeated-k-times.solutionCode:
class Solution {
public:
	string longestSubsequenceRepeatedK(string s, int k) {
		auto check = [&](const string& t, int k) -> bool {
			int i = 0;
			for (char c : s) {
				if (c == t[i]) {
					i++;
					if (i == t.size()) {
						if (--k == 0) {
							return true;
						}
						i = 0;
					}
				}
			}
			return false;
		};
		int cnt[26] = {};
		for (char c : s) {
			cnt[c - 'a']++;
		}

		vector<char> cs;
		for (char c = 'a'; c <= 'z'; ++c) {
			if (cnt[c - 'a'] >= k) {
				cs.push_back(c);
			}
		}

		queue<string> q;
		q.push("");
		string ans;
		while (!q.empty()) {
			string cur = q.front();
			q.pop();
			for (char c : cs) {
				string nxt = cur + c;
				if (check(nxt, k)) {
					ans = nxt;
					q.push(nxt);
				}
			}
		}
		return ans;
	}
};

maximum-path-quality-of-a-graph.solutionCode:
class Solution {
public:
	int maximalPathQuality(vector<int>& values, vector<vector<int>>& edges, int maxTime) {
		int n = values.size();
		vector<pair<int, int>> g[n];
		for (auto& e : edges) {
			int u = e[0], v = e[1], t = e[2];
			g[u].emplace_back(v, t);
			g[v].emplace_back(u, t);
		}
		bool vis[n];
		memset(vis, false, sizeof(vis));
		vis[0] = true;
		int ans = 0;
		auto dfs = [&](this auto&& dfs, int u, int cost, int value) -> void {
			if (u == 0) {
				ans = max(ans, value);
			}
			for (auto& [v, t] : g[u]) {
				if (cost + t <= maxTime) {
					if (vis[v]) {
						dfs(v, cost + t, value);
					} else {
						vis[v] = true;
						dfs(v, cost + t, value + values[v]);
						vis[v] = false;
					}
				}
			}
		};
		dfs(0, 0, values[0]);
		return ans;
	}
};

