class BinaryIndexedTree {
private:
	int n;
	vector<int> c;

public:
	BinaryIndexedTree(int n)
		: n(n)
		, c(n + 1, 0) {}

	void update(int x, int v) {
		for (; x <= n; x += x & -x) {
			c[x] += v;
		}
	}

	int query(int x) {
		int s = 0;
		for (; x > 0; x -= x & -x) {
			s += c[x];
		}
		return s;
	}
};

class Solution {
public:
	int subarraysWithMoreZerosThanOnes(vector<int>& nums) {
		int n = nums.size();
		int base = n + 1;
		BinaryIndexedTree tree(n + base);
		tree.update(base, 1);
		const int mod = 1e9 + 7;
		int ans = 0, s = 0;
		for (int x : nums) {
			s += (x == 0) ? -1 : 1;
			ans += tree.query(s - 1 + base);
			ans %= mod;
			tree.update(s + base, 1);
		}
		return ans;
	}
};

