class Solution {
public:
	long long maxTaxiEarnings(int n, vector<vector<int>>& rides) {
		sort(rides.begin(), rides.end());
		int m = rides.size();
		long long f[m];
		memset(f, -1, sizeof(f));
		function<long long(int)> dfs = [&](int i) -> long long {
			if (i >= m) {
				return 0;
			}
			if (f[i] != -1) {
				return f[i];
			}
			auto& r = rides[i];
			int st = r[0], ed = r[1], tip = r[2];
			int j = lower_bound(rides.begin() + i + 1, rides.end(), ed, [](auto& a, int val) { return a[0] < val; }) - rides.begin();
			return f[i] = max(dfs(i + 1), dfs(j) + ed - st + tip);
		};
		return dfs(0);
	}
};

find-the-minimum-and-maximum-number-of-n.solutionCode:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	vector<int> nodesBetweenCriticalPoints(ListNode* head) {
		vector<int> ans = {1 << 30, 0};
		int first = -1, last = -1;
		for (int i = 0; head->next->next; head = head->next, ++i) {
			int a = head->val, b = head->next->val, c = head->next->next->val;
			if (b < min(a, c) || b > max(a, c)) {
				if (last == -1) {
					first = i;
					last = i;
				} else {
					ans[0] = min(ans[0], i - last);
					last = i;
					ans[1] = max(ans[1], last - first);
				}
			}
		}
		return first == last ? vector<int>{-1, -1} : ans;
	}
};

