class UnionFind {
public:
	UnionFind(int n) {
		p = vector<int>(n);
		size = vector<int>(n, 1);
		iota(p.begin(), p.end(), 0);
	}

	bool unite(int a, int b) {
		int pa = find(a), pb = find(b);
		if (pa == pb) {
			return false;
		}
		if (size[pa] > size[pb]) {
			p[pb] = pa;
			size[pa] += size[pb];
		} else {
			p[pa] = pb;
			size[pb] += size[pa];
		}
		return true;
	}

	int find(int x) {
		if (p[x] != x) {
			p[x] = find(p[x]);
		}
		return p[x];
	}

private:
	vector<int> p, size;
};

class Solution {
public:
	int removeStones(vector<vector<int>>& stones) {
		int n = stones.size();
		UnionFind uf(n);
		int ans = 0;
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < i; ++j) {
				if (stones[i][0] == stones[j][0] || stones[i][1] == stones[j][1]) {
					ans += uf.unite(i, j);
				}
			}
		}
		return ans;
	}
};

