		int n = nums.size();
		stack<int> stk;
		for (int i = 0; i < n; ++i) {
			if (stk.empty() || nums[stk.top()] > nums[i]) stk.push(i);
		}
		int ans = 0;
		for (int i = n - 1; i; --i) {
			while (!stk.empty() && nums[stk.top()] <= nums[i]) {
				ans = max(ans, i - stk.top());
				stk.pop();
			}
			if (stk.empty()) break;
		}
		return ans;
	}
};

