			if (l >= r) {
				return;
			}
			int i = l - 1, j = r + 1;
			int x = nums[(l + r) >> 1];
			while (i < j) {
				while (nums[++i] < x) {
				}
				while (nums[--j] > x) {
				}
				if (i < j) {
					swap(nums[i], nums[j]);
				}
			}
			quick_sort(l, j);
			quick_sort(j + 1, r);
		};
		quick_sort(0, nums.size() - 1);
		return nums;
	}
