		const int inf = 1 << 30;
		int pmi = 0, pmx = -inf;
		int ans = -inf, s = 0, smi = inf;
		for (int x : nums) {
			s += x;
			ans = max(ans, s - pmi);
			smi = min(smi, s - pmx);
			pmi = min(pmi, s);
			pmx = max(pmx, s);
		}
		return max(ans, s - smi);
	}
};

