/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	TreeNode* insertIntoMaxTree(TreeNode* root, int val) {
		if (!root || root->val < val) return new TreeNode(val, root, nullptr);
		root->right = insertIntoMaxTree(root->right, val);
		return root;
	}
};

least-operators-to-express-number.solutionCode:
class Solution {
public:
	int leastOpsExpressTarget(int x, int target) {
		unordered_map<int, int> f;
		function<int(int)> dfs = [&](int v) -> int {
			if (x >= v) {
				return min(v * 2 - 1, 2 * (x - v));
			}
			if (f.count(v)) {
				return f[v];
			}
			int k = 2;
			long long y = x * x;
			while (y < v) {
				y *= x;
				++k;
			}
			int ans = k - 1 + dfs(v - y / x);
			if (y - v < v) {
				ans = min(ans, k + dfs(y - v));
			}
			f[v] = ans;
			return ans;
		};
		return dfs(target);
	}
};

find-the-town-judge.solutionCode:
class Solution {
public:
	int findJudge(int n, vector<vector<int>>& trust) {
		vector<int> cnt1(n + 1);
		vector<int> cnt2(n + 1);
		for (auto& t : trust) {
			int a = t[0], b = t[1];
			++cnt1[a];
			++cnt2[b];
		}
		for (int i = 1; i <= n; ++i) {
			if (cnt1[i] == 0 && cnt2[i] == n - 1) {
				return i;
			}
		}
		return -1;
	}
};

flip-binary-tree-to-match-preorder-trave.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	vector<int> flipMatchVoyage(TreeNode* root, vector<int>& voyage) {
		bool ok = true;
		int i = 0;
		vector<int> ans;
		function<void(TreeNode*)> dfs = [&](TreeNode* root) {
			if (!root || !ok) {
				return;
			}
			if (root->val != voyage[i]) {
				ok = false;
				return;
			}
			++i;
			if (!root->left || root->left->val == voyage[i]) {
				dfs(root->left);
				dfs(root->right);
			} else {
				ans.push_back(root->val);
				dfs(root->right);
				dfs(root->left);
			}
		};
		dfs(root);
		return ok ? ans : vector<int>{-1};
	}
};

vowel-spellchecker.solutionCode:
class Solution {
public:
	vector<string> spellchecker(vector<string>& wordlist, vector<string>& queries) {
		unordered_set<string> s(wordlist.begin(), wordlist.end());
		unordered_map<string, string> low;
		unordered_map<string, string> pat;
		auto f = [](string& w) {
			string res;
			for (char& c : w) {
				if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
					res += '*';
				} else {
					res += c;
				}
			}
			return res;
		};
		for (const auto& w : wordlist) {
			string t = w;
			transform(t.begin(), t.end(), t.begin(), ::tolower);
			if (!low.contains(t)) {
				low[t] = w;
			}
			t = f(t);
			if (!pat.contains(t)) {
				pat[t] = w;
			}
		}
		vector<string> ans;
		for (auto& q : queries) {
			if (s.contains(q)) {
				ans.emplace_back(q);
				continue;
			}
			transform(q.begin(), q.end(), q.begin(), ::tolower);
			if (low.contains(q)) {
				ans.emplace_back(low[q]);
				continue;
			}
			q = f(q);
			if (pat.contains(q)) {
				ans.emplace_back(pat[q]);
				continue;
			}
			ans.emplace_back("");
		}
		return ans;
	}
};

beautiful-array.solutionCode:
class Solution {
public:
	vector<int> beautifulArray(int n) {
		if (n == 1) return {1};
		vector<int> left = beautifulArray((n + 1) >> 1);
		vector<int> right = beautifulArray(n >> 1);
		vector<int> ans(n);
		int i = 0;
		for (int& x : left) ans[i++] = x * 2 - 1;
		for (int& x : right) ans[i++] = x * 2;
		return ans;
	}
};

unique-email-addresses.solutionCode:
class Solution {
public:
	int numUniqueEmails(vector<string>& emails) {
		unordered_set<string> s;
		for (const string& email : emails) {
			size_t atPos = email.find('@');
			string local = email.substr(0, atPos);
			string domain = email.substr(atPos + 1);
			string t;
			for (char c : local) {
				if (c == '.') {
					continue;
				}
				if (c == '+') {
					break;
				}
				t.push_back(c);
			}
			s.insert(t + "@" + domain);
		}
		return s.size();
	}
};

squares-of-a-sorted-array.solutionCode:
class Solution {
public:
	vector<int> sortedSquares(vector<int>& nums) {
		int n = nums.size();
		vector<int> ans(n);
		for (int i = 0, j = n - 1, k = n - 1; i <= j; --k) {
			int a = nums[i] * nums[i];
			int b = nums[j] * nums[j];
			if (a > b) {
				ans[k] = a;
				++i;
			} else {
				ans[k] = b;
				--j;
			}
		}
		return ans;
	}
};

