class Solution {
public:
	vector<int> diStringMatch(string s) {
		int n = s.size();
		int low = 0, high = n;
		vector<int> ans(n + 1);
		for (int i = 0; i < n; ++i) {
			if (s[i] == 'I') {
				ans[i] = low++;
			} else {
				ans[i] = high--;
			}
		}
		ans[n] = low;
		return ans;
	}
};

long-pressed-name.solutionCode:
class Solution {
public:
	bool isLongPressedName(string name, string typed) {
		int m = name.length(), n = typed.length();
		int i = 0, j = 0;
		while (i < m && j < n) {
			if (name[i] != typed[j]) {
				return false;
			}
			int x = i + 1;
			while (x < m && name[x] == name[i]) {
				++x;
			}
			int y = j + 1;
			while (y < n && typed[y] == typed[j]) {
				++y;
			}
			if (x - i > y - j) {
				return false;
			}
			i = x;
			j = y;
		}
		return i == m && j == n;
	}
};

triples-with-bitwise-and-equal-to-zero.solutionCode:
class Solution {
public:
	int countTriplets(vector<int>& nums) {
		int mx = ranges::max(nums);
		int cnt[mx + 1];
		memset(cnt, 0, sizeof cnt);
		for (int& x : nums) {
			for (int& y : nums) {
				cnt[x & y]++;
			}
		}
		int ans = 0;
		for (int xy = 0; xy <= mx; ++xy) {
			for (int& z : nums) {
				if ((xy & z) == 0) {
					ans += cnt[xy];
				}
			}
		}
		return ans;
	}
};

binary-tree-cameras.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
struct Status {
	int a, b, c;
};

class Solution {
public:
	int minCameraCover(TreeNode* root) {
		auto [a, b, _] = dfs(root);
		return min(a, b);
	}

	Status dfs(TreeNode* root) {
		if (!root) {
			return {1 << 29, 0, 0};
		}
		auto [la, lb, lc] = dfs(root->left);
		auto [ra, rb, rc] = dfs(root->right);
		int a = 1 + min({la, lb, lc}) + min({ra, rb, rc});
		int b = min({la + ra, la + rb, lb + ra});
		int c = lb + rb;
		return {a, b, c};
	};
};

check-completeness-of-a-binary-tree.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	bool isCompleteTree(TreeNode* root) {
		queue<TreeNode*> q{{root}};
		while (q.front()) {
			root = q.front();
			q.pop();
			q.push(root->left);
			q.push(root->right);
		}
		while (!q.empty() && !q.front()) q.pop();
		return q.empty();
	}
};

subarray-sums-divisible-by-k.solutionCode:
class Solution {
public:
	int subarraysDivByK(vector<int>& nums, int k) {
		unordered_map<int, int> cnt{{0, 1}};
		int ans = 0, s = 0;
		for (int& x : nums) {
			s = ((s + x) % k + k) % k;
			ans += cnt[s]++;
		}
		return ans;
	}
};

flip-equivalent-binary-trees.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	bool flipEquiv(TreeNode* root1, TreeNode* root2) {
		return dfs(root1, root2);
	}

	bool dfs(TreeNode* root1, TreeNode* root2) {
		if (root1 == root2 || (!root1 && !root2)) return true;
		if (!root1 || !root2 || root1->val != root2->val) return false;
		return (dfs(root1->left, root2->left) && dfs(root1->right, root2->right)) || (dfs(root1->left, root2->right) && dfs(root1->right, root2->left));
	}
};

largest-time-for-given-digits.solutionCode:
class Solution {
public:
	string largestTimeFromDigits(vector<int>& arr) {
		int ans = -1;
		for (int i = 0; i < 4; ++i) {
			for (int j = 0; j < 4; ++j) {
				for (int k = 0; k < 4; ++k) {
					if (i != j && j != k && i != k) {
						int h = arr[i] * 10 + arr[j];
						int m = arr[k] * 10 + arr[6 - i - j - k];
						if (h < 24 && m < 60) {
							ans = max(ans, h * 60 + m);
						}
					}
				}
			}
		}
		if (ans < 0) return "";
		int h = ans / 60, m = ans % 60;
		return to_string(h / 10) + to_string(h % 10) + ":" + to_string(m / 10) + to_string(m % 10);
	}
};

