class Solution {
public:
	vector<int> addToArrayForm(vector<int>& num, int k) {
		vector<int> ans;
		for (int i = num.size() - 1; i >= 0 || k > 0; --i) {
			k += (i >= 0 ? num[i] : 0);
			ans.push_back(k % 10);
			k /= 10;
		}
		ranges::reverse(ans);
		return ans;
	}
};

minimum-cost-for-tickets.solutionCode:
class Solution {
public:
	int mincostTickets(vector<int>& days, vector<int>& costs) {
		int valid[3] = {1, 7, 30};
		int n = days.size();
		int f[n];
		memset(f, 0, sizeof(f));
		function<int(int)> dfs = [&](int i) {
			if (i >= n) {
				return 0;
			}
			if (f[i]) {
				return f[i];
			}
			f[i] = INT_MAX;
			for (int k = 0; k < 3; ++k) {
				int j = lower_bound(days.begin(), days.end(), days[i] + valid[k]) - days.begin();
				f[i] = min(f[i], dfs(j) + costs[k]);
			}
			return f[i];
		};
		return dfs(0);
	}
};

number-of-music-playlists.solutionCode:
class Solution {
public:
	int numMusicPlaylists(int n, int goal, int k) {
		const int mod = 1e9 + 7;
		long long f[goal + 1][n + 1];
		memset(f, 0, sizeof(f));
		f[0][0] = 1;
		for (int i = 1; i <= goal; ++i) {
			for (int j = 1; j <= n; ++j) {
				f[i][j] = f[i - 1][j - 1] * (n - j + 1);
				if (j > k) {
					f[i][j] += f[i - 1][j] * (j - k);
				}
				f[i][j] %= mod;
			}
		}
		return f[goal][n];
	}
};

minimum-area-rectangle-ii.solutionCode:
class Solution {
public:
	double minAreaFreeRect(vector<vector<int>>& points) {
		auto f = [](int x, int y) {
			return x * 40001 + y;
		};
		int n = points.size();
		unordered_set<int> s;
		for (auto& p : points) {
			s.insert(f(p[0], p[1]));
		}
		double ans = 1e20;
		for (int i = 0; i < n; ++i) {
			int x1 = points[i][0], y1 = points[i][1];
			for (int j = 0; j < n; ++j) {
				if (j != i) {
					int x2 = points[j][0], y2 = points[j][1];
					for (int k = j + 1; k < n; ++k) {
						if (k != i) {
							int x3 = points[k][0], y3 = points[k][1];
							int x4 = x2 - x1 + x3, y4 = y2 - y1 + y3;
							if (x4 >= 0 && x4 < 40000 && y4 >= 0 && y4 <= 40000 && s.count(f(x4, y4))) {
								if ((x2 - x1) * (x3 - x1) + (y2 - y1) * (y3 - y1) == 0) {
									int ww = (x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1);
									int hh = (x3 - x1) * (x3 - x1) + (y3 - y1) * (y3 - y1);
									ans = min(ans, sqrt(1LL * ww * hh));
								}
							}
						}
					}
				}
			}
		}
		return ans == 1e20 ? 0 : ans;
	}
};

x-of-a-kind-in-a-deck-of-cards.solutionCode:
class Solution {
public:
	bool hasGroupsSizeX(vector<int>& deck) {
		unordered_map<int, int> cnt;
		for (int x : deck) {
			++cnt[x];
		}
		int g = cnt[deck[0]];
		for (auto& [_, x] : cnt) {
			g = gcd(g, x);
		}
		return g >= 2;
	}
};

