vertical-order-traversal-of-a-binary-tre.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	vector<vector<int>> verticalTraversal(TreeNode* root) {
		vector<tuple<int, int, int>> nodes;
		function<void(TreeNode*, int, int)> dfs = [&](TreeNode* root, int i, int j) {
			if (!root) {
				return;
			}
			nodes.emplace_back(j, i, root->val);
			dfs(root->left, i + 1, j - 1);
			dfs(root->right, i + 1, j + 1);
		};
		dfs(root, 0, 0);
		sort(nodes.begin(), nodes.end());
		vector<vector<int>> ans;
		int prev = -2000;
		for (auto [j, _, val] : nodes) {
			if (j != prev) {
				prev = j;
				ans.emplace_back();
			}
			ans.back().push_back(val);
		}
		return ans;
	}
};

three-equal-parts.solutionCode:
class Solution {
public:
	vector<int> threeEqualParts(vector<int>& arr) {
		int n = arr.size();
		int cnt = accumulate(arr.begin(), arr.end(), 0);
		if (cnt % 3) return {-1, -1};
		if (!cnt) return {0, n - 1};
		cnt /= 3;

		auto find = [&](int x) {
			int s = 0;
			for (int i = 0; i < n; ++i) {
				s += arr[i];
				if (s == x) return i;
			}
			return 0;
		};
		int i = find(1), j = find(cnt + 1), k = find(cnt * 2 + 1);
		for (; k < n && arr[i] == arr[j] && arr[j] == arr[k]; ++i, ++j, ++k) {}
		return k == n ? vector<int>{i - 1, j} : vector<int>{-1, -1};
	}
};

