class Solution {
public:
	int minKBitFlips(vector<int>& nums, int k) {
		int n = nums.size();
		int d[n + 1];
		memset(d, 0, sizeof(d));
		int ans = 0, s = 0;
		for (int i = 0; i < n; ++i) {
			s += d[i];
			if (s % 2 == nums[i]) {
				if (i + k > n) {
					return -1;
				}
				++d[i];
				--d[i + k];
				++s;
				++ans;
			}
		}
		return ans;
	}
};

