class Solution {
public:
	int numPermsDISequence(string s) {
		const int mod = 1e9 + 7;
		int n = s.size();
		int f[n + 1][n + 1];
		memset(f, 0, sizeof(f));
		f[0][0] = 1;
		for (int i = 1; i <= n; ++i) {
			if (s[i - 1] == 'D') {
				for (int j = 0; j <= i; ++j) {
					for (int k = j; k < i; ++k) {
						f[i][j] = (f[i][j] + f[i - 1][k]) % mod;
					}
				}
			} else {
				for (int j = 0; j <= i; ++j) {
					for (int k = 0; k < j; ++k) {
						f[i][j] = (f[i][j] + f[i - 1][k]) % mod;
					}
				}
			}
		}
		int ans = 0;
		for (int j = 0; j <= n; ++j) {
			ans = (ans + f[n][j]) % mod;
		}
		return ans;
	}
};

find-the-shortest-superstring.solutionCode:
class Solution {
public:
	string shortestSuperstring(vector<string>& words) {
		int n = words.size();
		vector<vector<int>> g(n, vector<int>(n));
		for (int i = 0; i < n; ++i) {
			auto a = words[i];
			for (int j = 0; j < n; ++j) {
				auto b = words[j];
				if (i != j) {
					for (int k = min(a.size(), b.size()); k > 0; --k) {
						if (a.substr(a.size() - k) == b.substr(0, k)) {
							g[i][j] = k;
							break;
						}
					}
				}
			}
		}
		vector<vector<int>> dp(1 << n, vector<int>(n));
		vector<vector<int>> p(1 << n, vector<int>(n, -1));
		for (int i = 0; i < 1 << n; ++i) {
			for (int j = 0; j < n; ++j) {
				if ((i >> j) & 1) {
					int pi = i ^ (1 << j);
					for (int k = 0; k < n; ++k) {
						if ((pi >> k) & 1) {
							int v = dp[pi][k] + g[k][j];
							if (v > dp[i][j]) {
								dp[i][j] = v;
								p[i][j] = k;
							}
						}
					}
				}
			}
		}
		int j = 0;
		for (int i = 0; i < n; ++i) {
			if (dp[(1 << n) - 1][i] > dp[(1 << n) - 1][j]) {
				j = i;
			}
		}
		vector<int> arr = {j};
		for (int i = (1 << n) - 1; p[i][j] != -1;) {
			int k = i;
			i ^= (1 << j);
			j = p[k][j];
			arr.push_back(j);
		}
		unordered_set<int> vis(arr.begin(), arr.end());
		for (int i = 0; i < n; ++i) {
			if (!vis.count(i)) {
				arr.push_back(i);
			}
		}
		reverse(arr.begin(), arr.end());
		string ans = words[arr[0]];
		for (int i = 1; i < n; ++i) {
			int k = g[arr[i - 1]][arr[i]];
			ans += words[arr[i]].substr(k);
		}
		return ans;
	}
};

unique-paths-iii.solutionCode:
class Solution {
public:
	int uniquePathsIII(vector<vector<int>>& grid) {
		int m = grid.size(), n = grid[0].size();
		int cnt = 0;
		for (auto& row : grid) {
			for (auto& x : row) {
				cnt += x == 0;
			}
		}
		int dirs[5] = {-1, 0, 1, 0, -1};
		bool vis[m][n];
		memset(vis, false, sizeof vis);
		function<int(int, int, int)> dfs = [&](int i, int j, int k) -> int {
			if (grid[i][j] == 2) {
				return k == cnt + 1 ? 1 : 0;
			}
			int ans = 0;
			for (int h = 0; h < 4; ++h) {
				int x = i + dirs[h], y = j + dirs[h + 1];
				if (x >= 0 && x < m && y >= 0 && y < n && !vis[x][y] && grid[x][y] != -1) {
					vis[x][y] = true;
					ans += dfs(x, y, k + 1);
					vis[x][y] = false;
				}
			}
			return ans;
		};
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j] == 1) {
					vis[i][j] = true;
					return dfs(i, j, 0);
				}
			}
		}
		return 0;
	}
};

validate-stack-sequences.solutionCode:
class Solution {
public:
	bool validateStackSequences(vector<int>& pushed, vector<int>& popped) {
		stack<int> stk;
		int i = 0;
		for (int x : pushed) {
			stk.push(x);
			while (stk.size() && stk.top() == popped[i]) {
				stk.pop();
				++i;
			}
		}
		return i == popped.size();
	}
};

shortest-bridge.solutionCode:
class Solution {
public:
	const static inline vector<int> dirs = {-1, 0, 1, 0, -1};

	int shortestBridge(vector<vector<int>>& grid) {
		int n = grid.size();
		queue<pair<int, int>> q;
		function<void(int, int)> dfs = [&](int i, int j) {
			grid[i][j] = 2;
			q.emplace(i, j);
			for (int k = 0; k < 4; ++k) {
				int x = i + dirs[k], y = j + dirs[k + 1];
				if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == 1) {
					dfs(x, y);
				}
			}
		};
		for (int i = 0, x = 1; i < n && x; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j]) {
					dfs(i, j);
					x = 0;
					break;
				}
			}
		}
		int ans = 0;
		while (1) {
			for (int h = q.size(); h; --h) {
				auto [i, j] = q.front();
				q.pop();
				for (int k = 0; k < 4; ++k) {
					int x = i + dirs[k], y = j + dirs[k + 1];
					if (x >= 0 && x < n && y >= 0 && y < n) {
						if (grid[x][y] == 1) return ans;
						if (grid[x][y] == 0) {
							grid[x][y] = 2;
							q.emplace(x, y);
						}
					}
				}
			}
			++ans;
		}
	}
};

