};

numbers-at-most-n-given-digit-set.solutionCode:
class Solution {
public:
	int atMostNGivenDigitSet(vector<string>& digits, int n) {
		string s = to_string(n);
		unordered_set<int> nums;
		for (auto& x : digits) {
			nums.insert(stoi(x));
		}
		int m = s.size();
		int f[m];
		memset(f, -1, sizeof(f));
		auto dfs = [&](this auto&& dfs, int i, bool lead, bool limit) -> int {
			if (i >= m) {
				return lead ? 0 : 1;
			}
			if (!lead && !limit && f[i] != -1) {
				return f[i];
			}
			int up = limit ? s[i] - '0' : 9;
			int ans = 0;
			for (int j = 0; j <= up; ++j) {
				if (j == 0 && lead) {
					ans += dfs(i + 1, true, limit && j == up);
				} else if (nums.count(j)) {
					ans += dfs(i + 1, false, limit && j == up);
				}
			}
			if (!lead && !limit) {
				f[i] = ans;
			}
			return ans;
		};
		return dfs(0, true, true);
	}
};

odd-even-jump.solutionCode:
class Solution {
public:
	int oddEvenJumps(vector<int>& arr) {
		int n = arr.size();
		map<int, int> d;
		int f[n][2];
		int g[n][2];
		memset(f, 0, sizeof(f));
		for (int i = n - 1; ~i; --i) {
			auto it = d.lower_bound(arr[i]);
			g[i][1] = it == d.end() ? -1 : it->second;
			it = d.upper_bound(arr[i]);
			g[i][0] = it == d.begin() ? -1 : prev(it)->second;
			d[arr[i]] = i;
		}
		function<int(int, int)> dfs = [&](int i, int k) -> int {
			if (i == n - 1) {
				return 1;
			}
			if (g[i][k] == -1) {
				return 0;
			}
			if (f[i][k] != 0) {
				return f[i][k];
			}
			return f[i][k] = dfs(g[i][k], k ^ 1);
		};
		int ans = 0;
		for (int i = 0; i < n; ++i) {
			ans += dfs(i, 1);
		}
		return ans;
	}
};

