cousins-in-binary-tree.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	bool isCousins(TreeNode* root, int x, int y) {
		queue<pair<TreeNode*, TreeNode*>> q;
		q.push({root, nullptr});
		int d1 = 0, d2 = 0;
		TreeNode *p1 = nullptr, *p2 = nullptr;
		for (int depth = 0; q.size(); ++depth) {
			for (int n = q.size(); n; --n) {
				auto [node, parent] = q.front();
				q.pop();
				if (node->val == x) {
					d1 = depth;
					p1 = parent;
				} else if (node->val == y) {
					d2 = depth;
					p2 = parent;
				}
				if (node->left) {
					q.push({node->left, node});
				}
				if (node->right) {
					q.push({node->right, node});
				}
			}
		}
		return d1 == d2 && p1 != p2;
	}
};

number-of-squareful-arrays.solutionCode:
class Solution {
public:
	int numSquarefulPerms(vector<int>& nums) {
		int n = nums.size();
		int f[1 << n][n];
		memset(f, 0, sizeof(f));
		for (int j = 0; j < n; ++j) {
			f[1 << j][j] = 1;
		}
		for (int i = 0; i < 1 << n; ++i) {
			for (int j = 0; j < n; ++j) {
				if ((i >> j & 1) == 1) {
					for (int k = 0; k < n; ++k) {
						if ((i >> k & 1) == 1 && k != j) {
							int s = nums[j] + nums[k];
							int t = sqrt(s);
							if (t * t == s) {
								f[i][j] += f[i ^ (1 << j)][k];
							}
						}
					}
				}
			}
		}
		long long ans = 0;
		for (int j = 0; j < n; ++j) {
			ans += f[(1 << n) - 1][j];
		}
		unordered_map<int, int> cnt;
		for (int x : nums) {
			++cnt[x];
		}
		int g[13] = {1};
		for (int i = 1; i < 13; ++i) {
			g[i] = g[i - 1] * i;
		}
		for (auto& [_, v] : cnt) {
			ans /= g[v];
		}
		return ans;
	}
};

