class Solution {
public:
	int sumSubarrayMins(vector<int>& arr) {
		int n = arr.size();
		vector<int> left(n, -1);
		vector<int> right(n, n);
		stack<int> stk;
		for (int i = 0; i < n; ++i) {
			while (!stk.empty() && arr[stk.top()] >= arr[i]) {
				stk.pop();
			}
			if (!stk.empty()) {
				left[i] = stk.top();
			}
			stk.push(i);
		}
		stk = stack<int>();
		for (int i = n - 1; i >= 0; --i) {
			while (!stk.empty() && arr[stk.top()] > arr[i]) {
				stk.pop();
			}
			if (!stk.empty()) {
				right[i] = stk.top();
			}
			stk.push(i);
		}
		long long ans = 0;
		const int mod = 1e9 + 7;
		for (int i = 0; i < n; ++i) {
			ans += 1LL * (i - left[i]) * (right[i] - i) * arr[i] % mod;
			ans %= mod;
		}
		return ans;
	}
};

stamping-the-sequence.solutionCode:
class Solution {
public:
	vector<int> movesToStamp(string stamp, string target) {
		int m = stamp.size(), n = target.size();
		vector<int> indeg(n - m + 1, m);
		vector<int> g[n];
		queue<int> q;
		for (int i = 0; i < n - m + 1; ++i) {
			for (int j = 0; j < m; ++j) {
				if (target[i + j] == stamp[j]) {
					if (--indeg[i] == 0) {
						q.push(i);
					}
				} else {
					g[i + j].push_back(i);
				}
			}
		}
		vector<int> ans;
		vector<bool> vis(n);
		while (q.size()) {
			int i = q.front();
			q.pop();
			ans.push_back(i);
			for (int j = 0; j < m; ++j) {
				if (!vis[i + j]) {
					vis[i + j] = true;
					for (int k : g[i + j]) {
						if (--indeg[k] == 0) {
							q.push(k);
						}
					}
				}
			}
		}
		for (int i = 0; i < n; ++i) {
			if (!vis[i]) {
				return {};
			}
		}
		reverse(ans.begin(), ans.end());
		return ans;
	}
};

