maximum-number-that-sum-of-the-prices-is.solutionCode:
class Solution {
public:
	long long findMaximumNumber(long long k, int x) {
		using ll = long long;
		ll l = 1, r = 1e17;
		ll num = 0;
		ll f[65][65];
		auto dfs = [&](this auto&& dfs, int pos, int cnt, bool limit) -> ll {
			if (pos == 0) {
				return cnt;
			}
			if (!limit && f[pos][cnt] != -1) {
				return f[pos][cnt];
			}
			int up = limit ? num >> (pos - 1) & 1 : 1;
			ll ans = 0;
			for (int i = 0; i <= up; ++i) {
				ans += dfs(pos - 1, cnt + (i == 1 && pos % x == 0), limit && i == up);
			}
			if (!limit) {
				f[pos][cnt] = ans;
			}
			return ans;
		};
		while (l < r) {
			ll mid = (l + r + 1) >> 1;
			num = mid;
			memset(f, -1, sizeof(f));
			int pos = 64 - __builtin_clzll(mid);
			if (dfs(pos, 0, true) <= k) {
				l = mid;
			} else {
				r = mid - 1;
			}
		}
		return l;
	}
};

earliest-second-to-mark-indices-i.solutionCode:
class Solution {
public:
	int earliestSecondToMarkIndices(vector<int>& nums, vector<int>& changeIndices) {
		int n = nums.size();
		int last[n + 1];
		auto check = [&](int t) {
			memset(last, 0, sizeof(last));
			for (int s = 0; s < t; ++s) {
				last[changeIndices[s]] = s;
			}
			int decrement = 0, marked = 0;
			for (int s = 0; s < t; ++s) {
				int i = changeIndices[s];
				if (last[i] == s) {
					if (decrement < nums[i - 1]) {
						return false;
					}
					decrement -= nums[i - 1];
					++marked;
				} else {
					++decrement;
				}
			}
			return marked == n;
		};

		int m = changeIndices.size();
		int l = 1, r = m + 1;
		while (l < r) {
			int mid = (l + r) >> 1;
			if (check(mid)) {
				r = mid;
			} else {
				l = mid + 1;
			}
		}
		return l > m ? -1 : l;
	}
};

