		for (char& c : s) {
			if (c == '?') {
				++k;
			} else {
				++cnt[c - 'a'];
			}
		}
		priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
		for (int i = 0; i < 26; ++i) {
			pq.push({cnt[i], i});
