class Solution {
public:
	int minimumDeletions(string word, int k) {
		int freq[26]{};
		for (char& c : word) {
			++freq[c - 'a'];
		}
		vector<int> nums;
		for (int v : freq) {
			if (v) {
				nums.push_back(v);
			}
		}
		int n = word.size();
		int ans = n;
		auto f = [&](int v) {
			int ans = 0;
			for (int x : nums) {
				if (x < v) {
					ans += x;
				} else if (x > v + k) {
					ans += x - v - k;
				}
			}
			return ans;
		};
		for (int i = 0; i <= n; ++i) {
			ans = min(ans, f(i));
		}
		return ans;
	}
};

