find-the-sum-of-the-power-of-all-subsequ.solutionCode:
class Solution {
public:
	int sumOfPower(vector<int>& nums, int k) {
		const int mod = 1e9 + 7;
		int n = nums.size();
		int f[n + 1][k + 1];
		memset(f, 0, sizeof(f));
		f[0][0] = 1;
		for (int i = 1; i <= n; ++i) {
			for (int j = 0; j <= k; ++j) {
				f[i][j] = (f[i - 1][j] * 2) % mod;
				if (j >= nums[i - 1]) {
					f[i][j] = (f[i][j] + f[i - 1][j - nums[i - 1]]) % mod;
				}
			}
		}
		return f[n][k];
	}
};

