class Solution {
public:
	int maximumSubtreeSize(vector<vector<int>>& edges, vector<int>& colors) {
		int n = edges.size() + 1;
		vector<int> g[n];
		vector<int> size(n, 1);
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		int ans = 0;
		function<bool(int, int)> dfs = [&](int a, int fa) {
			bool ok = true;
			for (int b : g[a]) {
				if (b != fa) {
					bool t = dfs(b, a);
					ok = ok && colors[a] == colors[b] && t;
					size[a] += size[b];
				}
			}
			if (ok) {
				ans = max(ans, size[a]);
			}
			return ok;
		};
		dfs(0, -1);
		return ans;
	}
};

most-frequent-prime.solutionCode:
class Solution {
public:
	int mostFrequentPrime(vector<vector<int>>& mat) {
		int m = mat.size(), n = mat[0].size();
		unordered_map<int, int> cnt;
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				for (int a = -1; a <= 1; ++a) {
					for (int b = -1; b <= 1; ++b) {
						if (a == 0 && b == 0) {
							continue;
						}
						int x = i + a, y = j + b, v = mat[i][j];
						while (x >= 0 && x < m && y >= 0 && y < n) {
							v = v * 10 + mat[x][y];
							if (isPrime(v)) {
								cnt[v]++;
							}
							x += a;
							y += b;
						}
					}
				}
			}
		}
		int ans = -1, mx = 0;
		for (auto& [v, x] : cnt) {
			if (mx < x || (mx == x && ans < v)) {
				mx = x;
				ans = v;
			}
		}
		return ans;
	}

private:
	bool isPrime(int n) {
		for (int i = 2; i <= n / i; ++i) {
			if (n % i == 0) {
				return false;
			}
		}
		return true;
	}
};

