class Solution {
	public int maxIntersectionCount(int[] y) {
		final int n = y.length;
		int ans = 0;
		int intersectionCount = 0;
		TreeMap<Integer, Integer> line = new TreeMap<>();

		for (int i = 1; i < n; ++i) {
			final int start = 2 * y[i - 1];
			final int end = 2 * y[i] + (i == n - 1 ? 0 : y[i] > y[i - 1] ? -1 : 1);
			line.merge(Math.min(start, end), 1, Integer::sum);
			line.merge(Math.max(start, end) + 1, -1, Integer::sum);
		}

		for (final int count : line.values()) {
			intersectionCount += count;
			ans = Math.max(ans, intersectionCount);
		}

		return ans;
	}
}

find-the-sum-of-subsequence-powers.solutionCode:
class Solution {
public:
	int sumOfPowers(vector<int>& nums, int k) {
		unordered_map<long long, int> f;
		const int mod = 1e9 + 7;
		int n = nums.size();
		sort(nums.begin(), nums.end());
		auto dfs = [&](this auto&& dfs, int i, int j, int k, int mi) -> int {
			if (i >= n) {
				return k == 0 ? mi : 0;
			}
			if (n - i < k) {
				return 0;
			}
			long long key = (1LL * mi) << 18 | (i << 12) | (j << 6) | k;
			if (f.contains(key)) {
				return f[key];
			}
			long long ans = dfs(i + 1, j, k, mi);
			if (j == n) {
				ans += dfs(i + 1, i, k - 1, mi);
			} else {
				ans += dfs(i + 1, i, k - 1, min(mi, nums[i] - nums[j]));
			}
			ans %= mod;
			f[key] = ans;
			return f[key];
		};
		return dfs(0, n, k, INT_MAX);
	}
};

maximum-strength-of-k-disjoint-subarrays.solutionCode:
class Solution {
public:
	long long maximumStrength(vector<int>& nums, int k) {
		int n = nums.size();
		long long f[n + 1][k + 1][2];
		memset(f, -0x3f3f3f3f3f3f3f3f, sizeof(f));
		f[0][0][0] = 0;
		for (int i = 1; i <= n; i++) {
			int x = nums[i - 1];
			for (int j = 0; j <= k; j++) {
				long long sign = (j & 1) == 1 ? 1 : -1;
				long long val = sign * x * (k - j + 1);
				f[i][j][0] = max(f[i - 1][j][0], f[i - 1][j][1]);
				f[i][j][1] = max(f[i][j][1], f[i - 1][j][1] + val);
				if (j > 0) {
					long long t = max(f[i - 1][j - 1][0], f[i - 1][j - 1][1]) + val;
					f[i][j][1] = max(f[i][j][1], t);
				}
			}
		}
		return max(f[n][k][0], f[n][k][1]);
	}
};

winner-of-the-linked-list-game.solutionCode:
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
	string gameResult(ListNode* head) {
		int odd = 0, even = 0;
		for (; head != nullptr; head = head->next->next) {
			int a = head->val;
			int b = head->next->val;
			odd += a < b;
			even += a > b;
		}
		if (odd > even) {
			return "Odd";
		}
		if (odd < even) {
			return "Even";
		}
		return "Tie";
	}
};

