class Solution {
public:
	vector<long long> findMaxSum(vector<int>& nums1, vector<int>& nums2, int k) {
		int n = nums1.size();
		vector<pair<int, int>> arr(n);
		for (int i = 0; i < n; ++i) {
			arr[i] = {nums1[i], i};
		}
		ranges::sort(arr);
		priority_queue<int, vector<int>, greater<int>> pq;
		long long s = 0;
		int j = 0;
		vector<long long> ans(n);
		for (int h = 0; h < n; ++h) {
			auto [x, i] = arr[h];
			while (j < h && arr[j].first < x) {
				int y = nums2[arr[j].second];
				pq.push(y);
				s += y;
				if (pq.size() > k) {
					s -= pq.top();
					pq.pop();
				}
				++j;
			}
			ans[i] = s;
		}
		return ans;
	}
};

minimum-operations-to-make-subarray-elem.solutionCode:
class Solution {
public:
	long long minOperations(vector<int>& nums, int k) {
		multiset<int> l, r;
		long long s1 = 0, s2 = 0, ans = 1e18;
		for (int i = 0; i < nums.size(); ++i) {
			l.insert(nums[i]);
			s1 += nums[i];
			int y = *l.rbegin();
			l.erase(l.find(y));
			s1 -= y;
			r.insert(y);
			s2 += y;
			if (r.size() - l.size() > 1) {
				y = *r.begin();
				r.erase(r.find(y));
				s2 -= y;
				l.insert(y);
				s1 += y;
			}
			if (i >= k - 1) {
				long long x = *r.begin();
				ans = min(ans, s2 - x * (int) r.size() + x * (int) l.size() - s1);
				int j = i - k + 1;
				if (r.contains(nums[j])) {
					r.erase(r.find(nums[j]));
					s2 -= nums[j];
				} else {
					l.erase(l.find(nums[j]));
					s1 -= nums[j];
				}
			}
		}
		return ans;
	}
};

closest-equal-element-queries.solutionCode:
class Solution {
public:
	vector<int> solveQueries(vector<int>& nums, vector<int>& queries) {
		int n = nums.size();
		int m = n * 2;
		vector<int> d(m, m);

		unordered_map<int, int> left;
		for (int i = 0; i < m; i++) {
			int x = nums[i % n];
			if (left.count(x)) {
				d[i] = min(d[i], i - left[x]);
			}
			left[x] = i;
		}

		unordered_map<int, int> right;
		for (int i = m - 1; i >= 0; i--) {
			int x = nums[i % n];
			if (right.count(x)) {
				d[i] = min(d[i], right[x] - i);
			}
			right[x] = i;
		}

		for (int i = 0; i < n; i++) {
			d[i] = min(d[i], d[i + n]);
		}

		vector<int> ans;
		for (int query : queries) {
			ans.push_back(d[query] >= n ? -1 : d[query]);
		}
		return ans;
	}
};

