separate-squares-i.solutionCode:
class Solution {
public:
	vector<vector<int>>* squares;
	double s;

	bool check(double y1) {
		double t = 0.0;
		for (const auto& a : *squares) {
			int y = a[1];
			int l = a[2];
			if (y < y1) {
				t += (double) l * min(y1 - y, (double) l);
			}
		}
		return t >= s / 2.0;
	}

	double separateSquares(vector<vector<int>>& squares) {
		this->squares = &squares;
		s = 0.0;
		double l = 0.0;
		double r = 0.0;
		for (const auto& a : squares) {
			s += (double) a[2] * a[2];
			r = max(r, (double) a[1] + a[2]);
		}
		const double eps = 1e-5;
		while (r - l > eps) {
			double mid = (l + r) / 2.0;
			if (check(mid)) {
				r = mid;
			} else {
				l = mid;
			}
		}
		return r;
	}
};

maximum-and-minimum-sums-of-at-most-size.solutionCode:
class Solution {
public:
	long long minMaxSubarraySum(vector<int>& nums, int k) {
		long long totalMaxMinSum = 0;
		long long windowMaxSum = 0, windowMinSum = 0;

		// Format: {idx, num, shares}. Use long long to prevent overflow.
		deque<tuple<int, int, long long>> maxStack, minStack;

		for (int endIdx = 0; endIdx < nums.size(); endIdx++) {
			int startIdx = max(0, endIdx - k + 1);

			// Window start idx slides by 1: must update stacks' info.
			if (startIdx > 0) {
				get<2>(maxStack.front())--; // Decrement stack's front num shares.
				windowMaxSum -= get<1>(maxStack.front());

				// Front num out of window.
				if (get<0>(maxStack.front()) < startIdx)
					maxStack.pop_front();

				get<2>(minStack.front())--; // Decrement stack's front num shares.
				windowMinSum -= get<1>(minStack.front());

				// Front num out of window.
				if (get<0>(minStack.front()) < startIdx)
					minStack.pop_front();
			}

			long long num = nums[endIdx];

			long long maxShares = 1; // Base case.
			windowMaxSum += num;

			while (!maxStack.empty() && get<1>(maxStack.back()) <= num) {
				int prevNum = get<1>(maxStack.back());
				long long prevShares = get<2>(maxStack.back());
				maxStack.pop_back();

				maxShares += prevShares; // Max shares transition.

				// Reflect transition in max sum.
				windowMaxSum += (num - prevNum) * prevShares;
			}

			maxStack.push_back({endIdx, num, maxShares});

			long long minShares = 1; // Base case.
			windowMinSum += num;

			while (!minStack.empty() && get<1>(minStack.back()) >= num) {
				int prevNum = get<1>(minStack.back());
				long long prevShares = get<2>(minStack.back());
				minStack.pop_back();

				minShares += prevShares; // Min shares transition.

				// Reflect transition in min sum.
				windowMinSum += (num - prevNum) * prevShares;
			}

			minStack.push_back({endIdx, num, minShares});

			totalMaxMinSum += windowMaxSum + windowMinSum;
		}

		return totalMaxMinSum;
	}
};

maximize-active-section-with-trade-i.solutionCode:
class Solution {
public:
	int maxActiveSectionsAfterTrade(std::string s) {
		int n = s.length();
		int ans = 0, i = 0;
		int pre = INT_MIN, mx = 0;

		while (i < n) {
			int j = i + 1;
			while (j < n && s[j] == s[i]) {
				j++;
			}
			int cur = j - i;
			if (s[i] == '1') {
				ans += cur;
			} else {
				mx = std::max(mx, pre + cur);
				pre = cur;
			}
			i = j;
		}

		ans += mx;
		return ans;
	}
};

maximum-coin-collection.solutionCode:
class Solution {
public:
	long long maxCoins(vector<int>& lane1, vector<int>& lane2) {
		int n = lane1.size();
		long long ans = -1e18;
		vector<vector<vector<long long>>> f(n, vector<vector<long long>>(2, vector<long long>(3, -1e18)));
		auto dfs = [&](this auto&& dfs, int i, int j, int k) -> long long {
			if (i >= n) {
				return 0LL;
			}
			if (f[i][j][k] != -1e18) {
				return f[i][j][k];
			}
			int x = j == 0 ? lane1[i] : lane2[i];
			long long ans = max((long long) x, dfs(i + 1, j, k) + x);
			if (k > 0) {
				ans = max(ans, dfs(i + 1, j ^ 1, k - 1) + x);
				ans = max(ans, dfs(i, j ^ 1, k - 1));
			}
			return f[i][j][k] = ans;
		};
		for (int i = 0; i < n; ++i) {
			ans = max(ans, dfs(i, 0, 2));
		}
		return ans;
	}
};

