class Solution {
public:
	vector<int> countMentions(int numberOfUsers, vector<vector<string>>& events) {
		ranges::sort(events, [](const vector<string>& a, const vector<string>& b) {
			int x = stoi(a[1]);
			int y = stoi(b[1]);
			if (x == y) {
				return a[0][2] < b[0][2];
			}
			return x < y;
		});

		vector<int> ans(numberOfUsers, 0);
		vector<int> onlineT(numberOfUsers, 0);
		int lazy = 0;

		for (const auto& e : events) {
			string etype = e[0];
			int cur = stoi(e[1]);
			string s = e[2];

			if (etype[0] == 'O') {
				onlineT[stoi(s)] = cur + 60;
			} else if (s[0] == 'A') {
				lazy++;
			} else if (s[0] == 'H') {
				for (int i = 0; i < numberOfUsers; ++i) {
					if (onlineT[i] <= cur) {
						++ans[i];
					}
				}
			} else {
				stringstream ss(s);
				string token;
				while (ss >> token) {
					ans[stoi(token.substr(2))]++;
				}
			}
		}

		if (lazy > 0) {
			for (int i = 0; i < numberOfUsers; ++i) {
				ans[i] += lazy;
			}
		}

		return ans;
	}
};

find-the-lexicographically-largest-strin.solutionCode:
class Solution {
public:
	string answerString(string word, int numFriends) {
		if (numFriends == 1) {
			return word;
		}
		string s = lastSubstring(word);
		return s.substr(0, min(s.length(), word.length() - numFriends + 1));
	}

	string lastSubstring(string& s) {
		int n = s.size();
		int i = 0, j = 1, k = 0;
		while (j + k < n) {
			if (s[i + k] == s[j + k]) {
				++k;
			} else if (s[i + k] < s[j + k]) {
				i += k + 1;
				k = 0;
				if (i >= j) {
					j = i + 1;
				}
			} else {
				j += k + 1;
				k = 0;
			}
		}
		return s.substr(i);
	}
};

