class Solution {
public:
	int minUnlockedIndices(vector<int>& nums, vector<int>& locked) {
		int n = nums.size();
		int first2 = n, first3 = n;
		int last1 = -1, last2 = -1;

		for (int i = 0; i < n; ++i) {
			if (nums[i] == 1) {
				last1 = i;
			} else if (nums[i] == 2) {
				first2 = min(first2, i);
				last2 = i;
			} else {
				first3 = min(first3, i);
			}
		}

		if (first3 < last1) {
			return -1;
		}

		int ans = 0;
		for (int i = 0; i < n; ++i) {
			if (locked[i] == 1 && ((first2 <= i && i < last1) || (first3 <= i && i < last2))) {
				++ans;
			}
		}

		return ans;
	}
};

