class Solution {
public:
	int maximumAmount(vector<vector<int>>& coins) {
		int m = coins.size(), n = coins[0].size();
		vector<vector<vector<int>>> f(m, vector<vector<int>>(n, vector<int>(3, -1)));
		auto dfs = [&](this auto&& dfs, int i, int j, int k) -> int {
			if (i >= m || j >= n) {
				return INT_MIN / 2;
			}
			if (f[i][j][k] != -1) {
				return f[i][j][k];
			}
			if (i == m - 1 && j == n - 1) {
				return k > 0 ? max(0, coins[i][j]) : coins[i][j];
			}
			int ans = coins[i][j] + max(dfs(i + 1, j, k), dfs(i, j + 1, k));
			if (coins[i][j] < 0 && k > 0) {
				ans = max({ans, dfs(i + 1, j, k - 1), dfs(i, j + 1, k - 1)});
			}
			return f[i][j][k] = ans;
		};
		return dfs(0, 0, 2);
	}
};

reschedule-meetings-for-maximum-free-tim.solutionCode:
class Solution {
public:
	int maxFreeTime(int eventTime, vector<int>& startTime, vector<int>& endTime) {
		int n = startTime.size();
		vector<int> pre(n), suf(n);

		pre[0] = startTime[0];
		suf[n - 1] = eventTime - endTime[n - 1];

		for (int i = 1; i < n; ++i) {
			pre[i] = max(pre[i - 1], startTime[i] - endTime[i - 1]);
		}

		for (int i = n - 2; i >= 0; --i) {
			suf[i] = max(suf[i + 1], startTime[i + 1] - endTime[i]);
		}

		int ans = 0;
		for (int i = 0; i < n; ++i) {
			int l = (i == 0) ? 0 : endTime[i - 1];
			int r = (i == n - 1) ? eventTime : startTime[i + 1];
			int w = endTime[i] - startTime[i];
			ans = max(ans, r - l - w);

			if (i > 0 && pre[i - 1] >= w) {
				ans = max(ans, r - l);
			} else if (i + 1 < n && suf[i + 1] >= w) {
				ans = max(ans, r - l);
			}
		}

		return ans;
	}
};

