class Solution {
public:
	bool hasMatch(string s, string p) {
		int i = 0;
		int pos = 0;
		int start = 0, end;
		while ((end = p.find("*", start)) != string::npos) {
			string t = p.substr(start, end - start);
			pos = s.find(t, i);
			if (pos == string::npos) {
				return false;
			}
			i = pos + t.length();
			start = end + 1;
		}
		string t = p.substr(start);
		pos = s.find(t, i);
		if (pos == string::npos) {
			return false;
		}
		return true;
	}
};

maximize-the-distance-between-points-on-.solutionCode:
class Solution {
public:
	int maxDistance(int side, vector<vector<int>>& points, int k) {
		vector<long long> nums;
		for (auto& p : points) {
			int x = p[0];
			int y = p[1];
			if (x == 0) {
				nums.push_back((long long) y);
			} else if (y == side) {
				nums.push_back((long long) side + x);
			} else if (x == side) {
				nums.push_back((long long) side * 3 - y);
			} else {
				nums.push_back((long long) side * 4 - x);
			}
		}
		sort(nums.begin(), nums.end());

		auto check = [&](int lo) -> bool {
			long long total = (long long) side * 4;
			for (long long start : nums) {
				long long end = start + total - lo;
				long long cur = start;
				bool ok = true;
				for (int i = 0; i < k - 1; ++i) {
					auto it = lower_bound(nums.begin(), nums.end(), cur + lo);
					if (it == nums.end() || *it > end) {
						ok = false;
						break;
					}
					cur = *it;
				}
				if (ok) {
					return true;
				}
			}
			return false;
		};

		int l = 1, r = side;
		while (l < r) {
			int mid = (l + r + 1) >> 1;
			if (check(mid)) {
				l = mid;
			} else {
				r = mid - 1;
			}
		}
		return l;
	}
};

maximize-profit-from-task-assignment.solutionCode:
class Solution {
public:
	long long maxProfit(vector<int>& workers, vector<vector<int>>& tasks) {
		unordered_map<int, priority_queue<int>> d;
		for (const auto& t : tasks) {
			d[t[0]].push(t[1]);
		}
		long long ans = 0;
		for (int skill : workers) {
			if (d.contains(skill)) {
				auto& pq = d[skill];
				ans += pq.top();
				pq.pop();
				if (pq.empty()) {
					d.erase(skill);
				}
			}
		}
		int mx = 0;
		for (const auto& [_, pq] : d) {
			mx = max(mx, pq.top());
		}
		ans += mx;
		return ans;
	}
};

