maximize-subarrays-after-removing-one-co.solutionCode:
class Solution {
public:
	long long maxSubarrays(int n, vector<vector<int>>& conflictingPairs) {
		vector<vector<int>> g(n + 1);
		for (auto& pair : conflictingPairs) {
			int a = pair[0], b = pair[1];
			if (a > b) {
				swap(a, b);
			}
			g[a].push_back(b);
		}

		vector<long long> cnt(n + 2, 0);
		long long ans = 0, add = 0;
		int b1 = n + 1, b2 = n + 1;

		for (int a = n; a > 0; --a) {
			for (int b : g[a]) {
				if (b < b1) {
					b2 = b1;
					b1 = b;
				} else if (b < b2) {
					b2 = b;
				}
			}
			ans += b1 - a;
			cnt[b1] += b2 - b1;
			add = max(add, cnt[b1]);
		}

		ans += add;
		return ans;
	}
};

longest-palindromic-subsequence-after-at.solutionCode:
class Solution {
public:
	int longestPalindromicSubsequence(string s, int k) {
		int n = s.size();
		vector f(n, vector(n, vector<int>(k + 1, -1)));
		auto dfs = [&](this auto&& dfs, int i, int j, int k) -> int {
			if (i > j) {
				return 0;
			}
			if (i == j) {
				return 1;
			}
			if (f[i][j][k] != -1) {
				return f[i][j][k];
			}
			int res = max(dfs(i + 1, j, k), dfs(i, j - 1, k));
			int d = abs(s[i] - s[j]);
			int t = min(d, 26 - d);
			if (t <= k) {
				res = max(res, 2 + dfs(i + 1, j - 1, k - t));
			}
			return f[i][j][k] = res;
		};
		return dfs(0, n - 1, k);
	}
};

