check-if-it-is-possible-to-split-array.solutionCode:
class Solution {
public:
	bool canSplitArray(vector<int>& nums, int m) {
		int n = nums.size();
		vector<int> s(n + 1);
		for (int i = 1; i <= n; ++i) {
			s[i] = s[i - 1] + nums[i - 1];
		}
		int f[n][n];
		memset(f, -1, sizeof f);
		function<bool(int, int)> dfs = [&](int i, int j) {
			if (i == j) {
				return true;
			}
			if (f[i][j] != -1) {
				return f[i][j] == 1;
			}
			for (int k = i; k < j; ++k) {
				bool a = k == i || s[k + 1] - s[i] >= m;
				bool b = k == j - 1 || s[j + 1] - s[k + 1] >= m;
				if (a && b && dfs(i, k) && dfs(k + 1, j)) {
					f[i][j] = 1;
					return true;
				}
			}
			f[i][j] = 0;
			return false;
		};
		return dfs(0, n - 1);
	}
};

