class Solution {
public:
	int maxSum(vector<int>& nums, int k) {
		int cnt[31]{};
		for (int x : nums) {
			for (int i = 0; i < 31; ++i) {
				if (x >> i & 1) {
					++cnt[i];
				}
			}
		}
		long long ans = 0;
		const int mod = 1e9 + 7;
		while (k--) {
			int x = 0;
			for (int i = 0; i < 31; ++i) {
				if (cnt[i]) {
					x |= 1 << i;
					--cnt[i];
				}
			}
			ans = (ans + 1LL * x * x) % mod;
		}
		return ans;
	}
};

minimum-time-to-make-array-sum-at-most-x.solutionCode:
class Solution {
public:
	int minimumTime(vector<int>& nums1, vector<int>& nums2, int x) {
		int n = nums1.size();
		vector<pair<int, int>> nums;
		for (int i = 0; i < n; ++i) {
			nums.emplace_back(nums2[i], nums1[i]);
		}
		sort(nums.begin(), nums.end());
		int f[n + 1][n + 1];
		memset(f, 0, sizeof(f));
		for (int i = 1; i <= n; ++i) {
			for (int j = 0; j <= n; ++j) {
				f[i][j] = f[i - 1][j];
				if (j) {
					auto [b, a] = nums[i - 1];
					f[i][j] = max(f[i][j], f[i - 1][j - 1] + a + b * j);
				}
			}
		}
		int s1 = accumulate(nums1.begin(), nums1.end(), 0);
		int s2 = accumulate(nums2.begin(), nums2.end(), 0);
		for (int j = 0; j <= n; ++j) {
			if (s1 + s2 * j - f[n][j] <= x) {
				return j;
			}
		}
		return -1;
	}
};

