		const auto dp = pow({{0, 1}, {n - 1, n - 2}}, k)[0];
		s.append(t);
		s.append(t);
		const auto z = getz(s);
		const int m = n + n;
		int r = 0;
		for (int i = n; i < m; ++i) {
			if (z[i] >= n) {
				r = add(r, dp[!!(i - n)]);
			}
		}
		return r;
	}
};

