class Solution {
public:
	int minimumSeconds(vector<int>& nums) {
		unordered_map<int, vector<int>> d;
		int n = nums.size();
		for (int i = 0; i < n; ++i) {
			d[nums[i]].push_back(i);
		}
		int ans = 1 << 30;
		for (auto& [_, idx] : d) {
			int m = idx.size();
			int t = idx[0] + n - idx[m - 1];
			for (int i = 1; i < m; ++i) {
				t = max(t, idx[i] - idx[i - 1]);
			}
			ans = min(ans, t / 2);
		}
		return ans;
	}
};

minimum-right-shifts-to-sort-the-array.solutionCode:
class Solution {
public:
	int minimumRightShifts(vector<int>& nums) {
		int n = nums.size();
		int i = 1;
		while (i < n && nums[i - 1] < nums[i]) {
			++i;
		}
		int k = i + 1;
		while (k < n && nums[k - 1] < nums[k] && nums[k] < nums[0]) {
			++k;
		}
		return k < n ? -1 : n - i;
	}
};

apply-operations-to-make-two-strings-equ.solutionCode:
class Solution {
public:
	int minOperations(string s1, string s2, int x) {
		vector<int> idx;
		for (int i = 0; i < s1.size(); ++i) {
			if (s1[i] != s2[i]) {
				idx.push_back(i);
			}
		}
		int m = idx.size();
		if (m & 1) {
			return -1;
		}
		if (m == 0) {
			return 0;
		}
		int f[m][m];
		memset(f, -1, sizeof(f));
		function<int(int, int)> dfs = [&](int i, int j) {
			if (i > j) {
				return 0;
			}
			if (f[i][j] != -1) {
				return f[i][j];
			}
			f[i][j] = min({dfs(i + 1, j - 1) + x, dfs(i + 2, j) + idx[i + 1] - idx[i], dfs(i, j - 2) + idx[j] - idx[j - 1]});
			return f[i][j];
		};
		return dfs(0, m - 1);
	}
};

minimum-size-subarray-in-infinite-array.solutionCode:
class Solution {
public:
	int minSizeSubarray(vector<int>& nums, int target) {
		long long s = accumulate(nums.begin(), nums.end(), 0LL);
		int n = nums.size();
		int a = 0;
		if (target > s) {
			a = n * (target / s);
			target -= target / s * s;
		}
		if (target == s) {
			return n;
		}
		unordered_map<int, int> pos{{0, -1}};
		long long pre = 0;
		int b = 1 << 30;
		for (int i = 0; i < n; ++i) {
			pre += nums[i];
			if (pos.count(pre - target)) {
				b = min(b, i - pos[pre - target]);
			}
			if (pos.count(pre - (s - target))) {
				b = min(b, n - (i - pos[pre - (s - target)]));
			}
			pos[pre] = i;
		}
		return b == 1 << 30 ? -1 : a + b;
	}
};

