class Solution {
public:
	int minLengthAfterRemovals(vector<int>& nums) {
		unordered_map<int, int> cnt;
		for (int x : nums) {
			++cnt[x];
		}
		priority_queue<int> pq;
		for (auto& [_, v] : cnt) {
			pq.push(v);
		}
		int ans = nums.size();
		while (pq.size() > 1) {
			int x = pq.top();
			pq.pop();
			int y = pq.top();
			pq.pop();
			x--;
			y--;
			if (x > 0) {
				pq.push(x);
			}
			if (y > 0) {
				pq.push(y);
			}
			ans -= 2;
		}
		return ans;
	}
};

