class Solution {
public:
	int minimumOperations(string num) {
		int n = num.size();
		int f[n][25];
		memset(f, -1, sizeof(f));
		auto dfs = [&](this auto&& dfs, int i, int k) -> int {
			if (i == n) {
				return k == 0 ? 0 : n;
			}
			if (f[i][k] != -1) {
				return f[i][k];
			}
			f[i][k] = dfs(i + 1, k) + 1;
			f[i][k] = min(f[i][k], dfs(i + 1, (k * 10 + num[i] - '0') % 25));
			return f[i][k];
		};
		return dfs(0, 0);
	}
};

