	}
};

count-k-subsequences-of-a-string-with-ma.solutionCode:
class Solution {
public:
	int countKSubsequencesWithMaxBeauty(string s, int k) {
		int f[26]{};
		int cnt = 0;
		for (char& c : s) {
			if (++f[c - 'a'] == 1) {
				++cnt;
			}
		}
		if (cnt < k) {
			return 0;
		}
		vector<int> vs(cnt);
		for (int i = 0, j = 0; i < 26; ++i) {
			if (f[i]) {
				vs[j++] = f[i];
			}
		}
		sort(vs.rbegin(), vs.rend());
		const int mod = 1e9 + 7;
		long long ans = 1;
		int val = vs[k - 1];
		int x = 0;
		for (int v : vs) {
			x += v == val;
		}
		for (int v : vs) {
			if (v == val) {
				break;
			}
			--k;
			ans = ans * v % mod;
		}
		int c[x + 1][x + 1];
		memset(c, 0, sizeof(c));
		for (int i = 0; i <= x; ++i) {
			c[i][0] = 1;
			for (int j = 1; j <= i; ++j) {
				c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % mod;
			}
		}
		auto qpow = [&](long long a, int n) {
			long long ans = 1;
			for (; n; n >>= 1) {
				if (n & 1) {
					ans = ans * a % mod;
				}
				a = a * a % mod;
			}
			return ans;
		};
		ans = (ans * c[x][k] % mod) * qpow(val, k) % mod;
		return ans;
	}
};

apply-operations-to-maximize-score.solutionCode:
class Solution {
public:
	int maximumScore(vector<int>& nums, int k) {
		const int mod = 1e9 + 7;
		int n = nums.size();
		vector<tuple<int, int, int>> arr(n);
		for (int i = 0; i < n; ++i) {
			arr[i] = {i, primeFactors(nums[i]), nums[i]};
		}
		vector<int> left(n, -1);
		vector<int> right(n, n);
		stack<int> stk;
		for (auto [i, f, _] : arr) {
			while (!stk.empty() && get<1>(arr[stk.top()]) < f) {
				stk.pop();
			}
			if (!stk.empty()) {
				left[i] = stk.top();
			}
			stk.push(i);
		}
		stk = stack<int>();
		for (int i = n - 1; ~i; --i) {
			int f = get<1>(arr[i]);
			while (!stk.empty() && get<1>(arr[stk.top()]) <= f) {
				stk.pop();
			}
			if (!stk.empty()) {
				right[i] = stk.top();
			}
			stk.push(i);
		}
		sort(arr.begin(), arr.end(), [](const auto& lhs, const auto& rhs) {
			return get<2>(rhs) < get<2>(lhs);
		});
		long long ans = 1;
		auto qpow = [&](long long a, int n) {
			long long ans = 1;
			for (; n; n >>= 1) {
				if (n & 1) {
					ans = ans * a % mod;
				}
				a = a * a % mod;
			}
			return ans;
		};
		for (auto [i, _, x] : arr) {
			int l = left[i], r = right[i];
			long long cnt = 1LL * (i - l) * (r - i);
			if (cnt <= k) {
				ans = ans * qpow(x, cnt) % mod;
				k -= cnt;
			} else {
				ans = ans * qpow(x, k) % mod;
				break;
			}
		}
		return ans;
	}

	int primeFactors(int n) {
		int i = 2;
		unordered_set<int> ans;
		while (i <= n / i) {
			while (n % i == 0) {
				ans.insert(i);
				n /= i;
			}
			++i;
		}
		if (n > 1) {
			ans.insert(n);
		}
		return ans.size();
	}
};

