longest-balanced-substring-ii.solutionCode:
class Solution {
public:
	int longestBalanced(string s) {
		int x = calc1(s);
		int y = max({calc2(s, 'a', 'b'), calc2(s, 'b', 'c'), calc2(s, 'a', 'c')});
		int z = calc3(s);
		return max({x, y, z});
	}

private:
	int calc1(const string& s) {
		int res = 0;
		int i = 0, n = s.size();
		while (i < n) {
			int j = i + 1;
			while (j < n && s[j] == s[i]) {
				++j;
			}
			res = max(res, j - i);
			i = j;
		}
		return res;
	}

	int calc2(const string& s, char a, char b) {
		int res = 0;
		int i = 0, n = s.size();
		while (i < n) {
			while (i < n && s[i] != a && s[i] != b) {
				++i;
			}

			unordered_map<int, int> pos;
			pos[0] = i - 1;

			int d = 0;
			while (i < n && (s[i] == a || s[i] == b)) {
				d += (s[i] == a) ? 1 : -1;
				auto it = pos.find(d);
				if (it != pos.end()) {
					res = max(res, i - it->second);
				} else {
					pos[d] = i;
				}
				i++;
			}
		}
		return res;
	}

	static long long f(int x, int y) {
		return ((long long) (x + 100000) << 20) | (long long) (y + 100000);
	}

	int calc3(const string& s) {
		unordered_map<long long, int> pos;
		pos[f(0, 0)] = -1;

		int cnt[3] = {0, 0, 0};
		int res = 0;

		for (int i = 0; i < (int) s.size(); i++) {
			char c = s[i];
			++cnt[c - 'a'];
			int x = cnt[0] - cnt[1];
			int y = cnt[1] - cnt[2];
			long long k = f(x, y);

			auto it = pos.find(k);
			if (it != pos.end()) {
				res = max(res, i - it->second);
			} else {
				pos[k] = i;
			}
		}
		return res;
	}
};

find-diameter-endpoints-of-a-tree.solutionCode:
class Solution {
public:
	string findSpecialNodes(int n, vector<vector<int>>& edges) {
		vector<vector<int>> g(n);
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}

		auto bfs = [&](int start) -> pair<int, vector<int>> {
			vector<int> dist(n, -1);
			dist[start] = 0;
			deque<int> q;
			q.push_back(start);
			int far = start;
			while (!q.empty()) {
				int u = q.front();
				q.pop_front();
				if (dist[u] > dist[far]) {
					far = u;
				}
				for (int v : g[u]) {
					if (dist[v] == -1) {
						dist[v] = dist[u] + 1;
						q.push_back(v);
					}
				}
			}
			return {far, dist};
		};

		auto [a, _0] = bfs(0);
		auto [b, dist1] = bfs(a);
		auto [_1, dist2] = bfs(b);
		int d = dist1[b];

		string ans(n, '0');
		for (int i = 0; i < n; i++) {
			if (dist1[i] == d || dist2[i] == d) {
				ans[i] = '1';
			}
		}
		return ans;
	}
};

