class Solution {
public:
	int countTrapezoids(vector<vector<int>>& points) {
		const int mod = 1e9 + 7;
		unordered_map<int, int> cnt;
		for (auto& p : points) {
			cnt[p[1]]++;
		}
		long long ans = 0, s = 0;
		for (auto& [_, v] : cnt) {
			long long t = 1LL * v * (v - 1) / 2;
			ans = (ans + s * t) % mod;
			s += t;
		}
		return (int) ans;
	}
};

