maximize-spanning-tree-stability-with-up.solutionCode:
class UnionFind {
public:
	vector<int> p, size;
	int cnt;

	UnionFind(int n) {
		p.resize(n);
		size.assign(n, 1);
		cnt = n;
		for (int i = 0; i < n; i++) p[i] = i;
	}

	int find(int x) {
		if (p[x] != x) p[x] = find(p[x]);
		return p[x];
	}

	bool unite(int a, int b) {
		int pa = find(a), pb = find(b);
		if (pa == pb) return false;
		if (size[pa] > size[pb]) {
			p[pb] = pa;
			size[pa] += size[pb];
		} else {
			p[pa] = pb;
			size[pb] += size[pa];
		}
		cnt--;
		return true;
	}
};

class Solution {
public:
	int n, k;
	vector<vector<int>> edges;

	bool check(int lim) {
		UnionFind uf(n);

		for (auto& e : edges) {
			int u = e[0], v = e[1], s = e[2];
			if (s >= lim) {
				uf.unite(u, v);
			}
		}

		int rem = k;
		for (auto& e : edges) {
			int u = e[0], v = e[1], s = e[2];
			if (s * 2 >= lim && rem > 0) {
				if (uf.unite(u, v)) {
					rem--;
				}
			}
		}

		return uf.cnt == 1;
	}

	int maxStability(int n, vector<vector<int>>& edges, int k) {
		this->n = n;
		this->edges = edges;
		this->k = k;

		UnionFind uf(n);
		int mn = 1e6;

		for (auto& e : edges) {
			int u = e[0], v = e[1], s = e[2], must = e[3];
			if (must) {
				mn = min(mn, s);
				if (!uf.unite(u, v)) {
					return -1;
				}
			}
		}

		for (auto& e : edges) {
			uf.unite(e[0], e[1]);
		}

		if (uf.cnt > 1) {
			return -1;
		}

		int l = 1, r = mn;
		while (l < r) {
			int mid = (l + r + 1) >> 1;
			if (check(mid)) {
				l = mid;
			} else {
				r = mid - 1;
			}
		}

		return l;
	}
};

