class Solution {
public:
	long long splitArray(vector<int>& nums) {
		int n = nums.size();
		vector<long long> s(n);
		s[0] = nums[0];
		vector<bool> f(n, true), g(n, true);

		for (int i = 1; i < n; ++i) {
			s[i] = s[i - 1] + nums[i];
			f[i] = f[i - 1];
			if (nums[i] <= nums[i - 1]) {
				f[i] = false;
			}
		}
		for (int i = n - 2; i >= 0; --i) {
			g[i] = g[i + 1];
			if (nums[i] <= nums[i + 1]) {
				g[i] = false;
			}
		}

		const long long inf = LLONG_MAX;
		long long ans = inf;
		for (int i = 0; i < n - 1; ++i) {
			if (f[i] && g[i + 1]) {
				long long s1 = s[i];
				long long s2 = s[n - 1] - s[i];
				ans = min(ans, llabs(s1 - s2));
			}
		}
		return ans < inf ? ans : -1;
	}
};

minimum-number-of-primes-to-sum-to-targe.solutionCode:
class Solution {
public:
	int minNumberOfPrimes(int n, int m) {
		static vector<int> primes;
		if (primes.empty()) {
			int x = 2;
			int M = 1000;
			while ((int) primes.size() < M) {
				bool is_prime = true;
				for (int p : primes) {
					if (p * p > x) break;
					if (x % p == 0) {
						is_prime = false;
						break;
					}
				}
				if (is_prime) primes.push_back(x);
				x++;
			}
		}

		vector<int> f(n + 1, INT_MAX);
		f[0] = 0;
		for (int x : vector<int>(primes.begin(), primes.begin() + m)) {
			for (int i = x; i <= n; ++i) {
				if (f[i - x] != INT_MAX) {
					f[i] = min(f[i], f[i - x] + 1);
				}
			}
		}
		return f[n] < INT_MAX ? f[n] : -1;
	}
};

