class UnionFind {
public:
	UnionFind(int n) {
		p = vector<int>(n);
		size = vector<int>(n, 1);
		iota(p.begin(), p.end(), 0);
	}

	bool unite(int a, int b) {
		int pa = find(a), pb = find(b);
		if (pa == pb) {
			return false;
		}
		if (size[pa] > size[pb]) {
			p[pb] = pa;
			size[pa] += size[pb];
		} else {
			p[pa] = pb;
			size[pb] += size[pa];
		}
		return true;
	}

	int find(int x) {
		if (p[x] != x) {
			p[x] = find(p[x]);
		}
		return p[x];
	}

private:
	vector<int> p, size;
};

class Solution {
public:
	vector<int> processQueries(int c, vector<vector<int>>& connections, vector<vector<int>>& queries) {
		UnionFind uf(c + 1);
		for (auto& e : connections) {
			uf.unite(e[0], e[1]);
		}

		vector<set<int>> st(c + 1);
		for (int i = 1; i <= c; i++) {
			st[uf.find(i)].insert(i);
		}

		vector<int> ans;
		for (auto& q : queries) {
			int a = q[0], x = q[1];
			int root = uf.find(x);
			if (a == 1) {
				if (st[root].count(x)) {
					ans.push_back(x);
				} else if (!st[root].empty()) {
					ans.push_back(*st[root].begin());
				} else {
					ans.push_back(-1);
				}
			} else {
				st[root].erase(x);
			}
		}
		return ans;
	}
};

