class Solution {
public:
	int minJumps(vector<int>& nums) {
		int n = nums.size();
		unordered_map<int, vector<int>> g;
		for (int i = 0; i < n; i++) {
			int x = nums[i];
			for (int p : factors[x]) {
				g[p].push_back(i);
			}
		}
		int ans = 0;
		vector<bool> vis(n, false);
		vis[0] = true;
		queue<int> q;
		q.push(0);
		while (true) {
			queue<int> nq;
			while (!q.empty()) {
				int i = q.front();
				q.pop();
				if (i == n - 1) {
					return ans;
				}
				vector<int> idx = g[nums[i]];
				idx.push_back(i + 1);
				if (i > 0) {
					idx.push_back(i - 1);
				}
				for (int j : idx) {
					if (!vis[j]) {
						vis[j] = true;
						nq.push(j);
					}
				}
				g[nums[i]].clear();
			}
			q = nq;
			ans++;
		}
	}
};

sum-of-weighted-modes-in-subarrays.solutionCode:
class Solution {
public:
	long long modeWeight(vector<int>& nums, int k) {
		unordered_map<int, int> cnt;
		priority_queue<pair<int, int>> pq; // {freq, -val}

		for (int i = 0; i < k; i++) {
			int x = nums[i];
			cnt[x]++;
			pq.push({cnt[x], -x});
		}

		auto get_mode = [&]() {
			while (true) {
				auto [freq, negVal] = pq.top();
				int val = -negVal;
				if (cnt[val] == freq) {
					return 1LL * freq * val;
				}
				pq.pop();
			}
		};

		long long ans = 0;
		ans += get_mode();

		for (int i = k; i < nums.size(); i++) {
			int x = nums[i], y = nums[i - k];
			cnt[x]++;
			cnt[y]--;
			pq.push({cnt[x], -x});
			pq.push({cnt[y], -y});
			ans += get_mode();
		}

		return ans;
	}
};

