		ans.clear();
		path.assign(k, 0);

		dfs(k - 1, n, INT_MAX, 0);
		return ans;
	}

private:
	void dfs(int i, int x, int mi, int mx) {
		if (i == 0) {
			int d = max(mx, x) - min(mi, x);
			if (d < cur) {
				cur = d;
				path[i] = x;
				ans = path;
			}
			return;
		}
		for (int y : g[x]) {
			path[i] = y;
			dfs(i - 1, x / y, min(mi, y), max(mx, y));
		}
	}
};

