class Solution {
public:
	string reformatNumber(string number) {
		string s;
		for (char c : number) {
			if (c != ' ' && c != '-') {
				s.push_back(c);
			}
		}
		int n = s.size();
		vector<string> res;
		for (int i = 0; i < n / 3; ++i) {
			res.push_back(s.substr(i * 3, 3));
		}
		if (n % 3 == 1) {
			res.back() = res.back().substr(0, 2);
			res.push_back(s.substr(n - 2));
		} else if (n % 3 == 2) {
			res.push_back(s.substr(n - 2));
		}
		string ans;
		for (auto& v : res) {
			ans += v;
			ans += "-";
		}
		ans.pop_back();
		return ans;
	}
};

add-two-polynomials-represented-as-linke.solutionCode:
/**
 * Definition for polynomial singly-linked list->
 * struct PolyNode {
 *     int coefficient, power;
 *     PolyNode *next;
 *     PolyNode(): coefficient(0), power(0), next(nullptr) {};
 *     PolyNode(int x, int y): coefficient(x), power(y), next(nullptr) {};
 *     PolyNode(int x, int y, PolyNode* next): coefficient(x), power(y), next(next) {};
 * };
 */

class Solution {
public:
	PolyNode* addPoly(PolyNode* poly1, PolyNode* poly2) {
		PolyNode* dummy = new PolyNode();
		PolyNode* curr = dummy;
		while (poly1 && poly2) {
			if (poly1->power > poly2->power) {
				curr->next = poly1;
				poly1 = poly1->next;
				curr = curr->next;
			} else if (poly1->power < poly2->power) {
				curr->next = poly2;
				poly2 = poly2->next;
				curr = curr->next;
			} else {
				int c = poly1->coefficient + poly2->coefficient;
				if (c != 0) {
					curr->next = new PolyNode(c, poly1->power);
					curr = curr->next;
				}
				poly1 = poly1->next;
				poly2 = poly2->next;
			}
		}
		if (!poly1) {
			curr->next = poly2;
		}
		if (!poly2) {
			curr->next = poly1;
		}
		return dummy->next;
	}
};

