class FrontMiddleBackQueue {
public:
	FrontMiddleBackQueue() {
	}

	void pushFront(int val) {
		q1.push_front(val);
		rebalance();
	}

	void pushMiddle(int val) {
		q1.push_back(val);
		rebalance();
	}

	void pushBack(int val) {
		q2.push_back(val);
		rebalance();
	}

	int popFront() {
		if (q1.empty() && q2.empty()) return -1;
		int val = 0;
		if (q1.size()) {
			val = q1.front();
			q1.pop_front();
		} else {
			val = q2.front();
			q2.pop_front();
		}
		rebalance();
		return val;
	}

	int popMiddle() {
		if (q1.empty() && q2.empty()) return -1;
		int val = 0;
		if (q1.size() == q2.size()) {
			val = q1.back();
			q1.pop_back();
		} else {
			val = q2.front();
			q2.pop_front();
		}
		rebalance();
		return val;
	}

	int popBack() {
		if (q2.empty()) return -1;
		int val = q2.back();
		q2.pop_back();
		rebalance();
		return val;
	}

private:
	deque<int> q1;
	deque<int> q2;

	void rebalance() {
		if (q1.size() > q2.size()) {
			q2.push_front(q1.back());
			q1.pop_back();
		}
		if (q2.size() > q1.size() + 1) {
			q1.push_back(q2.front());
			q2.pop_front();
		}
	}
};

