			p[x] = find(p[x]);
		}
		return p[x];
	}

	void reset(int x) {
		p[x] = x;
		size[x] = 1;
	}

private:
	vector<int> p, size;
};

class Solution {
public:
	vector<vector<int>> matrixRankTransform(vector<vector<int>>& matrix) {
		int m = matrix.size(), n = matrix[0].size();
		map<int, vector<pair<int, int>>> d;
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				d[matrix[i][j]].push_back({i, j});
			}
		}
		vector<int> rowMax(m);
		vector<int> colMax(n);
		vector<vector<int>> ans(m, vector<int>(n));
		UnionFind uf(m + n);
		vector<int> rank(m + n);
		for (auto& [_, ps] : d) {
			for (auto& [i, j] : ps) {
				uf.unite(i, j + m);
			}
			for (auto& [i, j] : ps) {
				rank[uf.find(i)] = max({rank[uf.find(i)], rowMax[i], colMax[j]});
			}
			for (auto& [i, j] : ps) {
				ans[i][j] = rowMax[i] = colMax[j] = 1 + rank[uf.find(i)];
			}
			for (auto& [i, j] : ps) {
				uf.reset(i);
				uf.reset(j + m);
			}
		}
		return ans;
	}
};

