class Solution {
public:
	vector<int> decrypt(vector<int>& code, int k) {
		int n = code.size();
		vector<int> ans(n);
		if (k == 0) {
			return ans;
		}
		for (int i = 0; i < n; ++i) {
			if (k > 0) {
				for (int j = i + 1; j < i + k + 1; ++j) {
					ans[i] += code[j % n];
				}
			} else {
				for (int j = i + k; j < i; ++j) {
					ans[i] += code[(j + n) % n];
				}
			}
		}
		return ans;
	}
};

