class Solution {
public:
	int stoneGameVII(vector<int>& stones) {
		int n = stones.size();
		vector<vector<int>> f(n, vector<int>(n));
		vector<int> s(n + 1);
		for (int i = 0; i < n; ++i) {
			s[i + 1] = s[i] + stones[i];
		}
		auto dfs = [&](this auto&& dfs, int i, int j) -> int {
			if (i > j) {
				return 0;
			}
			if (f[i][j]) {
				return f[i][j];
			}
			int a = s[j + 1] - s[i + 1] - dfs(i + 1, j);
			int b = s[j] - s[i] - dfs(i, j - 1);
			return f[i][j] = max(a, b);
		};
		return dfs(0, n - 1);
	}
};

