class Solution {
public:
	int minimumDeviation(vector<int>& nums) {
		int mi = INT_MAX;
		priority_queue<int> pq;
		for (int v : nums) {
			if (v & 1) v <<= 1;
			pq.push(v);
			mi = min(mi, v);
		}
		int ans = pq.top() - mi;
		while (pq.top() % 2 == 0) {
			int x = pq.top() >> 1;
			pq.pop();
			pq.push(x);
			mi = min(mi, x);
			ans = min(ans, pq.top() - mi);
		}
		return ans;
	}
};

number-of-ways-to-form-a-target-string-g.solutionCode:
class Solution {
public:
	int numWays(vector<string>& words, string target) {
		const int mod = 1e9 + 7;
		int m = target.size(), n = words[0].size();
		vector<vector<int>> cnt(n, vector<int>(26));
		for (auto& w : words) {
			for (int j = 0; j < n; ++j) {
				++cnt[j][w[j] - 'a'];
			}
		}
		int f[m][n];
		memset(f, -1, sizeof(f));
		function<int(int, int)> dfs = [&](int i, int j) -> int {
			if (i >= m) {
				return 1;
			}
			if (j >= n) {
				return 0;
			}
			if (f[i][j] != -1) {
				return f[i][j];
			}
			int ans = dfs(i, j + 1);
			ans = (ans + 1LL * dfs(i + 1, j + 1) * cnt[j][target[i] - 'a']) % mod;
			return f[i][j] = ans;
		};
		return dfs(0, 0);
	}
};

even-odd-tree.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	bool isEvenOddTree(TreeNode* root) {
		int even = 1;
		queue<TreeNode*> q{{root}};
		while (!q.empty()) {
			int prev = even ? 0 : 1e7;
			for (int n = q.size(); n; --n) {
				root = q.front();
				q.pop();
				if (even && (root->val % 2 == 0 || prev >= root->val)) {
					return false;
				}
				if (!even && (root->val % 2 == 1 || prev <= root->val)) {
					return false;
				}
				prev = root->val;
				if (root->left) {
					q.push(root->left);
				}
				if (root->right) {
					q.push(root->right);
				}
			}
			even ^= 1;
		}
		return true;
	}
};

find-servers-that-handled-most-number-of.solutionCode:
class Solution {
public:
	vector<int> busiestServers(int k, vector<int>& arrival, vector<int>& load) {
		set<int> free;
		for (int i = 0; i < k; ++i) free.insert(i);
		priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> busy;
		vector<int> cnt(k);
		for (int i = 0; i < arrival.size(); ++i) {
			int start = arrival[i], end = start + load[i];
			while (!busy.empty() && busy.top().first <= start) {
				free.insert(busy.top().second);
				busy.pop();
			}
			if (free.empty()) continue;
			auto p = free.lower_bound(i % k);
			if (p == free.end()) p = free.begin();
			int server = *p;
			++cnt[server];
			busy.emplace(end, server);
			free.erase(server);
		}
		int mx = *max_element(cnt.begin(), cnt.end());
		vector<int> ans;
		for (int i = 0; i < k; ++i)
			if (cnt[i] == mx)
				ans.push_back(i);
		return ans;
	}
};

