class Solution {
public:
	vector<int> countSubgraphsForEachDiameter(int n, vector<vector<int>>& edges) {
		vector<vector<int>> g(n);
		for (auto& e : edges) {
			int u = e[0] - 1, v = e[1] - 1;
			g[u].emplace_back(v);
			g[v].emplace_back(u);
		}
		vector<int> ans(n - 1);
		int nxt = 0, msk = 0, mx = 0;
		function<void(int, int)> dfs = [&](int u, int d) {
			msk ^= 1 << u;
			if (mx < d) {
				mx = d;
				nxt = u;
			}
			for (int& v : g[u]) {
				if (msk >> v & 1) {
					dfs(v, d + 1);
				}
			}
		};
		for (int mask = 1; mask < 1 << n; ++mask) {
			if ((mask & (mask - 1)) == 0) {
				continue;
			}
			msk = mask;
			mx = 0;
			int cur = 31 - __builtin_clz(msk);
			dfs(cur, 0);
			if (msk == 0) {
				msk = mask;
				mx = 0;
				dfs(nxt, 0);
				++ans[mx - 1];
			}
		}
		return ans;
	}
};

