class Solution {
public:
	int furthestBuilding(vector<int>& heights, int bricks, int ladders) {
		priority_queue<int, vector<int>, greater<int>> q;
		int n = heights.size();
		for (int i = 0; i < n - 1; ++i) {
			int a = heights[i], b = heights[i + 1];
			int d = b - a;
			if (d > 0) {
				q.push(d);
				if (q.size() > ladders) {
					bricks -= q.top();
					q.pop();
					if (bricks < 0) {
						return i;
					}
				}
			}
		}
		return n - 1;
	}
};

