class Solution {
public:
	int maxProfit(vector<int>& inventory, int orders) {
		long ans = 0, mod = 1e9 + 7;
		int i = 0, n = inventory.size();
		sort(inventory.rbegin(), inventory.rend());
		while (orders > 0) {
			while (i < n && inventory[i] >= inventory[0]) {
				++i;
			}
			int nxt = i < n ? inventory[i] : 0;
			int cnt = i;
			long x = inventory[0] - nxt;
			long tot = cnt * x;
			if (tot > orders) {
				int decr = orders / cnt;
				long a1 = inventory[0] - decr + 1, an = inventory[0];
				ans += (a1 + an) * decr / 2 * cnt;
				ans += (a1 - 1) * (orders % cnt);
			} else {
				long a1 = nxt + 1, an = inventory[0];
				ans += (a1 + an) * x / 2 * cnt;
				inventory[0] = nxt;
			}
			orders -= tot;
			ans %= mod;
		}
		return ans;
	}
};

multiply-two-polynomials.solutionCode:
class Solution {
	using cd = complex<double>;

	void fft(vector<cd>& a, bool invert) {
		int n = a.size();
		for (int i = 1, j = 0; i < n; ++i) {
			int bit = n >> 1;
			for (; j & bit; bit >>= 1) j ^= bit;
			j ^= bit;
			if (i < j) swap(a[i], a[j]);
		}
		for (int len = 2; len <= n; len <<= 1) {
			double ang = 2 * M_PI / len * (invert ? -1 : 1);
			cd wlen(cos(ang), sin(ang));
			for (int i = 0; i < n; i += len) {
				cd w(1, 0);
				int half = len >> 1;
				for (int j = 0; j < half; ++j) {
					cd u = a[i + j];
					cd v = a[i + j + half] * w;
					a[i + j] = u + v;
					a[i + j + half] = u - v;
					w *= wlen;
				}
			}
		}
		if (invert)
			for (cd& x : a) x /= n;
	}

public:
	vector<long long> multiply(vector<int>& poly1, vector<int>& poly2) {
		if (poly1.empty() || poly2.empty()) return {};
		int m = poly1.size() + poly2.size() - 1;
		int n = 1;
		while (n < m) n <<= 1;

		vector<cd> fa(n), fb(n);
		for (int i = 0; i < n; ++i) {
			fa[i] = i < poly1.size() ? cd(poly1[i], 0) : cd(0, 0);
			fb[i] = i < poly2.size() ? cd(poly2[i], 0) : cd(0, 0);
		}

		fft(fa, false);
		fft(fb, false);
		for (int i = 0; i < n; ++i) fa[i] *= fb[i];
		fft(fa, true);

		vector<long long> res(m);
		for (int i = 0; i < m; ++i) res[i] = llround(fa[i].real());
		return res;
	}
};

