				ms.insert(calc(words[i], words[j]));
			}
		};
		auto remove = [&](int i, int j) {
			if (i >= 0 && i < n && j >= 0 && j < n) {
				int x = calc(words[i], words[j]);
				auto it = ms.find(x);
				if (it != ms.end()) {
					ms.erase(it);
				}
			}
		};
		for (int i = 0; i < n; ++i) {
			remove(i, i + 1);
			remove(i - 1, i);
			add(i - 1, i + 1);
			ans[i] = ms.empty() ? 0 : *ms.rbegin();
			remove(i - 1, i + 1);
			add(i - 1, i);
			add(i, i + 1);
		}
		return ans;
	}
};

minimum-pair-removal-to-sort-array-ii.solutionCode:
class Solution {
public:
	int minimumPairRemoval(vector<int>& nums) {
		int n = nums.size();
		int inv = 0;

		set<pair<long long, int>> sl;
		set<int> idx;
		vector<long long> arr(nums.begin(), nums.end());

		for (int i = 0; i < n; ++i) idx.insert(i);

		for (int i = 0; i < n - 1; ++i) {
			if (nums[i] > nums[i + 1]) {
				++inv;
			}
			sl.insert({(long long) nums[i] + nums[i + 1], i});
		}

		int ans = 0;
		while (inv > 0) {
			++ans;

			auto it = sl.begin();
			long long s = it->first;
			int i = it->second;
			sl.erase(it);

			auto j_it = idx.upper_bound(i);
			int j = *j_it;

			if (arr[i] > arr[j]) {
				--inv;
			}

			auto i_it = idx.find(i);
			if (i_it != idx.begin()) {
				auto h_it = prev(i_it);
				int h = *h_it;

				if (arr[h] > arr[i]) {
					--inv;
				}
				sl.erase({arr[h] + arr[i], h});

				if (arr[h] > s) {
					++inv;
				}
				sl.insert({arr[h] + s, h});
			}

			auto k_it = next(j_it);
			if (k_it != idx.end()) {
				int k = *k_it;

				if (arr[j] > arr[k]) {
					--inv;
				}
				sl.erase({arr[j] + arr[k], j});

				if (s > arr[k]) {
					++inv;
				}
				sl.insert({s + arr[k], i});
			}

			arr[i] = s;
			idx.erase(j);
		}

		return ans;
	}
};

partition-array-to-minimize-xor.solutionCode:
class Solution {
public:
	int minXor(vector<int>& nums, int k) {
		int n = nums.size();
		vector<int> g(n + 1);
		for (int i = 1; i <= n; ++i) {
			g[i] = g[i - 1] ^ nums[i - 1];
		}

		const int inf = numeric_limits<int>::max();
		vector f(n + 1, vector(k + 1, inf));
		f[0][0] = 0;

		for (int i = 1; i <= n; ++i) {
			for (int j = 1; j <= min(i, k); ++j) {
				for (int h = j - 1; h < i; ++h) {
					f[i][j] = min(f[i][j], max(f[h][j - 1], g[i] ^ g[h]));
				}
			}
		}

		return f[n][k];
	}
};

count-odd-letters-from-number.solutionCode:
class Solution {
public:
	int countOddLetters(int n) {
		static const unordered_map<int, string> d = {
			{0, "zero"},
			{1, "one"},
			{2, "two"},
			{3, "three"},
			{4, "four"},
			{5, "five"},
			{6, "six"},
			{7, "seven"},
			{8, "eight"},
			{9, "nine"}};

		int mask = 0;
		while (n > 0) {
			int x = n % 10;
			n /= 10;
			for (char c : d.at(x)) {
				mask ^= 1 << (c - 'a');
			}
		}
		return __builtin_popcount(mask);
	}
};

count-partitions-with-max-min-difference.solutionCode:
class Solution {
public:
	int countPartitions(vector<int>& nums, int k) {
		const int mod = 1e9 + 7;
		multiset<int> sl;
		int n = nums.size();
		vector<int> f(n + 1, 0), g(n + 1, 0);
		f[0] = 1;
		g[0] = 1;
		int l = 1;
		for (int r = 1; r <= n; ++r) {
			int x = nums[r - 1];
			sl.insert(x);
			while (*sl.rbegin() - *sl.begin() > k) {
				sl.erase(sl.find(nums[l - 1]));
				++l;
			}
			f[r] = (g[r - 1] - (l >= 2 ? g[l - 2] : 0) + mod) % mod;
			g[r] = (g[r - 1] + f[r]) % mod;
		}
		return f[n];
	}
};

