find-sum-of-array-product-of-magical-seq.solutionCode:
const int N = 31;
const long long MOD = 1'000'000'007;

long long f[N], g[N];

long long qpow(long long a, long long k) {
	long long res = 1;
	while (k) {
		if (k & 1) res = res * a % MOD;
		a = a * a % MOD;
		k >>= 1;
	}
	return res;
}

int init = []() {
	f[0] = g[0] = 1;
	for (int i = 1; i < N; ++i) {
		f[i] = f[i - 1] * i % MOD;
		g[i] = qpow(f[i], MOD - 2);
	}
	return 0;
}();

long long comb(int m, int n) {
	return f[m] * g[n] % MOD * g[m - n] % MOD;
}

class Solution {
	vector<vector<vector<vector<long long>>>> dp;

	long long dfs(int i, int j, int k, int st) {
		if (k < 0 || (i == nums.size() && j > 0)) {
			return 0;
		}
		if (i == nums.size()) {
			while (st > 0) {
				k -= (st & 1);
				st >>= 1;
			}
			return k == 0 ? 1 : 0;
		}

		long long& res = dp[i][j][k][st];
		if (res != -1) {
			return res;
		}

		res = 0;
		for (int t = 0; t <= j; ++t) {
			int nt = t + st;
			int nk = k - (nt & 1);
			long long p = qpow(nums[i], t);
			long long tmp = comb(j, t) * p % MOD * dfs(i + 1, j - t, nk, nt >> 1) % MOD;
			res = (res + tmp) % MOD;
		}
		return res;
	}

public:
	int magicalSum(int m, int k, vector<int>& nums) {
		int n = nums.size();
		this->nums = nums;
		dp.assign(n + 1, vector<vector<vector<long long>>>(m + 1, vector<vector<long long>>(k + 1, vector<long long>(N, -1))));
		return dfs(0, m, k, 0);
	}

private:
	vector<int> nums;
};

make-a-positive-array.solutionCode:
class Solution {
public:
	int makeArrayPositive(vector<int>& nums) {
		int ans = 0;
		long long preMx = 0, s = 0;
		for (int l = -1, r = 0; r < nums.size(); r++) {
			int x = nums[r];
			s += x;
			if (r - l > 2 && s <= preMx) {
				ans++;
				l = r;
				preMx = s = 0;
			} else if (r - l >= 2) {
				preMx = max(preMx, s - x - nums[r - 1]);
			}
		}
		return ans;
	}
};

implement-router.solutionCode:
class Router {
private:
	int lim;
	unordered_set<long long> vis;
	deque<array<int, 3>> q;
	unordered_map<int, int> idx;
	unordered_map<int, vector<int>> d;

	long long f(int a, int b, int c) {
		return ((long long) a << 46) | ((long long) b << 29) | (long long) c;
	}

public:
	Router(int memoryLimit) {
		lim = memoryLimit;
	}

	bool addPacket(int source, int destination, int timestamp) {
		long long x = f(source, destination, timestamp);
		if (vis.count(x)) {
			return false;
		}
		vis.insert(x);
		if ((int) q.size() >= lim) {
			forwardPacket();
		}
		q.push_back({source, destination, timestamp});
		d[destination].push_back(timestamp);
		return true;
	}

	vector<int> forwardPacket() {
		if (q.empty()) {
			return {};
		}
		auto packet = q.front();
		q.pop_front();
		int s = packet[0], d_ = packet[1], t = packet[2];
		vis.erase(f(s, d_, t));
		idx[d_]++;
		return {s, d_, t};
	}

	int getCount(int destination, int startTime, int endTime) {
		auto& ls = d[destination];
		int k = idx[destination];
		auto i = lower_bound(ls.begin() + k, ls.end(), startTime);
		auto j = lower_bound(ls.begin() + k, ls.end(), endTime + 1);
		return j - i;
	}
};

