class Solution {
public:
	bool checkPrimeFrequency(vector<int>& nums) {
		unordered_map<int, int> cnt;
		for (int x : nums) {
			++cnt[x];
		}

		for (auto& [_, x] : cnt) {
			if (isPrime(x)) {
				return true;
			}
		}
		return false;
	}

private:
	bool isPrime(int x) {
		if (x < 2) {
			return false;
		}
		for (int i = 2; i <= x / i; ++i) {
			if (x % i == 0) {
				return false;
			}
		}
		return true;
	}
};

