class Solution {
public:
	long long minEliminationTime(vector<int>& timeReq, int splitTime) {
		using ll = long long;
		priority_queue<ll, vector<ll>, greater<ll>> pq;
		for (int v : timeReq) {
			pq.push(v);
		}
		while (pq.size() > 1) {
			pq.pop();
			ll x = pq.top();
			pq.pop();
			pq.push(x + splitTime);
		}
		return pq.top();
	}
};

minimum-adjacent-swaps-to-alternate-pari.solutionCode:
class Solution {
public:
	int minSwaps(vector<int>& nums) {
		vector<int> pos[2];
		for (int i = 0; i < nums.size(); ++i) {
			pos[nums[i] & 1].push_back(i);
		}
		if (abs(int(pos[0].size() - pos[1].size())) > 1) {
			return -1;
		}
		auto calc = [&](int k) {
			int res = 0;
			for (int i = 0; i < nums.size(); i += 2) {
				res += abs(pos[k][i / 2] - i);
			}
			return res;
		};
		if (pos[0].size() > pos[1].size()) {
			return calc(0);
		}
		if (pos[0].size() < pos[1].size()) {
			return calc(1);
		}
		return min(calc(0), calc(1));
	}
};

maximize-subarray-gcd-score.solutionCode:
class Solution {
public:
	long long maxGCDScore(vector<int>& nums, int k) {
		int n = nums.size();
		vector<int> cnt(n);
		for (int i = 0; i < n; ++i) {
			for (int x = nums[i]; x % 2 == 0; x /= 2) {
				++cnt[i];
			}
		}

		long long ans = 0;
		for (int l = 0; l < n; ++l) {
			int g = 0;
			int mi = INT32_MAX;
			int t = 0;
			for (int r = l; r < n; ++r) {
				g = gcd(g, nums[r]);
				if (cnt[r] < mi) {
					mi = cnt[r];
					t = 1;
				} else if (cnt[r] == mi) {
					++t;
				}
				long long score = static_cast<long long>(r - l + 1) * (t > k ? g : g * 2);
				ans = max(ans, score);
			}
		}

		return ans;
	}
};

