class Solution {
public:
	bool isPossible(vector<int>& target) {
		priority_queue<int> pq;
		long long s = 0;
		for (int i = 0; i < target.size(); i++) {
			s += target[i];
			pq.push(target[i]);
		}
		while (pq.top() != 1) {
			int mx = pq.top();
			pq.pop();
			long long t = s - mx;
			if (t < 1 || mx - t < 1) {
				return false;
			}
			int x = mx % t;
			if (x == 0) {
				x = t;
			}
			pq.push(x);
			s = s - mx + x;
		}
		return true;
	}
};

