class Solution {
public:
	int minDifficulty(vector<int>& jobDifficulty, int d) {
		int n = jobDifficulty.size();
		int f[n + 1][d + 1];
		memset(f, 0x3f, sizeof(f));
		f[0][0] = 0;
		for (int i = 1; i <= n; ++i) {
			for (int j = 1; j <= min(d, i); ++j) {
				int mx = 0;
				for (int k = i; k; --k) {
					mx = max(mx, jobDifficulty[k - 1]);
					f[i][j] = min(f[i][j], f[k - 1][j - 1] + mx);
				}
			}
		}
		return f[n][d] == 0x3f3f3f3f ? -1 : f[n][d];
	}
};

minimum-cost-to-make-at-least-one-valid-.solutionCode:
class Solution {
public:
	int minCost(vector<vector<int>>& grid) {
		int m = grid.size(), n = grid[0].size();
		vector<vector<bool>> vis(m, vector<bool>(n));
		vector<vector<int>> dirs = {{0, 0}, {0, 1}, {0, -1}, {1, 0}, {-1, 0}};
		deque<pair<int, int>> q;
		q.push_back({0, 0});
		while (!q.empty()) {
			auto p = q.front();
			q.pop_front();
			int i = p.first / n, j = p.first % n, d = p.second;
			if (i == m - 1 && j == n - 1) return d;
			if (vis[i][j]) continue;
			vis[i][j] = true;
			for (int k = 1; k <= 4; ++k) {
				int x = i + dirs[k][0], y = j + dirs[k][1];
				if (x >= 0 && x < m && y >= 0 && y < n) {
					if (grid[i][j] == k)
						q.push_front({x * n + y, d});
					else
						q.push_back({x * n + y, d + 1});
				}
			}
		}
		return -1;
	}
};

