class Solution {
public:
	int sumEvenGrandparent(TreeNode* root) {
		function<int(TreeNode*, int)> dfs = [&](TreeNode* root, int x) {
			if (!root) {
				return 0;
			}
			int ans = dfs(root->left, root->val) + dfs(root->right, root->val);
			if (x % 2 == 0) {
				if (root->left) {
					ans += root->left->val;
				}
				if (root->right) {
					ans += root->right->val;
				}
			}
			return ans;
		};
		return dfs(root, 1);
	}
};

longest-happy-prefix.solutionCode:
typedef unsigned long long ULL;

class Solution {
public:
	string longestPrefix(string s) {
		int base = 131;
		int n = s.size();
		ULL p[n + 10];
		ULL h[n + 10];
		p[0] = 1;
		h[0] = 0;
		for (int i = 0; i < n; ++i) {
			p[i + 1] = p[i] * base;
			h[i + 1] = h[i] * base + s[i];
		}
		for (int l = n - 1; l > 0; --l) {
			ULL prefix = h[l];
			ULL suffix = h[n] - h[n - l] * p[l];
			if (prefix == suffix) return s.substr(0, l);
		}
		return "";
	}
};

the-k-weakest-rows-in-a-matrix.solutionCode:
class Solution {
public:
	int search(vector<int>& m) {
		int l = 0;
		int h = m.size() - 1;
		while (l <= h) {
			int mid = l + (h - l) / 2;
			if (m[mid] == 0)
				h = mid - 1;
			else
				l = mid + 1;
		}
		return l;
	}

	vector<int> kWeakestRows(vector<vector<int>>& mat, int k) {
		vector<pair<int, int>> p;
		vector<int> res;
		for (int i = 0; i < mat.size(); i++) {
			int count = search(mat[i]);
			p.push_back({count, i});
		}
		sort(p.begin(), p.end());
		for (int i = 0; i < k; i++) {
			res.push_back(p[i].second);
		}
		return res;
	}
};

