class CustomStack {
public:
	CustomStack(int maxSize) {
		stk.resize(maxSize);
		add.resize(maxSize);
		i = 0;
	}

	void push(int x) {
		if (i < stk.size()) {
			stk[i++] = x;
		}
	}

	int pop() {
		if (i <= 0) {
			return -1;
		}
		int ans = stk[--i] + add[i];
		if (i > 0) {
			add[i - 1] += add[i];
		}
		add[i] = 0;
		return ans;
	}

	void increment(int k, int val) {
		if (i > 0) {
			add[min(k, i) - 1] += val;
		}
	}

private:
	vector<int> stk;
	vector<int> add;
	int i;
};

