class Solution {
public:
	int minInsertions(string s) {
		int n = s.size();
		int f[n][n];
		memset(f, -1, sizeof(f));
		function<int(int, int)> dfs = [&](int i, int j) -> int {
			if (i >= j) {
				return 0;
			}
			if (f[i][j] != -1) {
				return f[i][j];
			}
			int ans = 1 << 30;
			if (s[i] == s[j]) {
				ans = dfs(i + 1, j - 1);
			} else {
				ans = min(dfs(i + 1, j), dfs(i, j - 1)) + 1;
			}
			return f[i][j] = ans;
		};
		return dfs(0, n - 1);
	}
};

sort-the-matrix-diagonally.solutionCode:
class Solution {
public:
	vector<vector<int>> diagonalSort(vector<vector<int>>& mat) {
		int m = mat.size(), n = mat[0].size();
		vector<int> g[m + n];
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				g[m - i + j].push_back(mat[i][j]);
			}
		}
		for (auto& e : g) {
			sort(e.rbegin(), e.rend());
		}
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				mat[i][j] = g[m - i + j].back();
				g[m - i + j].pop_back();
			}
		}
		return mat;
	}
};

frog-position-after-t-seconds.solutionCode:
class Solution {
public:
	double frogPosition(int n, vector<vector<int>>& edges, int t, int target) {
		vector<vector<int>> g(n + 1);
		for (auto& e : edges) {
			int u = e[0], v = e[1];
			g[u].push_back(v);
			g[v].push_back(u);
		}
		queue<pair<int, double>> q{{{1, 1.0}}};
		bool vis[n + 1];
		memset(vis, false, sizeof(vis));
		vis[1] = true;
		for (; q.size() && t >= 0; --t) {
			for (int k = q.size(); k; --k) {
				auto [u, p] = q.front();
				q.pop();
				int cnt = g[u].size() - (u != 1);
				if (u == target) {
					return cnt * t == 0 ? p : 0;
				}
				for (int v : g[u]) {
					if (!vis[v]) {
						vis[v] = true;
						q.push({v, p / cnt});
					}
				}
			}
		}
		return 0;
	}
};

