sort-integers-by-the-power-value.solutionCode:
class Solution {
public:
	int getKth(int lo, int hi, int k) {
		auto f = [](int x) {
			int ans = 0;
			for (; x != 1; ++ans) {
				if (x % 2 == 0) {
					x /= 2;
				} else {
					x = 3 * x + 1;
				}
			}
			return ans;
		};
		vector<int> nums;
		for (int i = lo; i <= hi; ++i) {
			nums.push_back(i);
		}
		sort(nums.begin(), nums.end(), [&](int x, int y) {
			int fx = f(x), fy = f(y);
			if (fx != fy) {
				return fx < fy;
			} else {
				return x < y;
			}
		});
		return nums[k - 1];
	}
};

