		sort(arr.begin(), arr.end());
		int n = arr.size();
		int s[n + 1];
		s[0] = 0;
		int mx = 0;
		for (int i = 0; i < n; ++i) {
			s[i + 1] = s[i] + arr[i];
			mx = max(mx, arr[i]);
		}
		int ans = 0, diff = 1 << 30;
		for (int value = 0; value <= mx; ++value) {
			int i = upper_bound(arr.begin(), arr.end(), value) - arr.begin();
			int d = abs(s[i] + (n - i) * value - target);
			if (diff > d) {
				diff = d;
				ans = value;
			}
		}
		return ans;
	}
};

