class Solution {
public:
	int largestVariance(string s) {
		int n = s.size();
		int ans = 0;
		for (char a = 'a'; a <= 'z'; ++a) {
			for (char b = 'a'; b <= 'z'; ++b) {
				if (a == b) {
					continue;
				}
				int f[2] = {0, -n};
				for (char c : s) {
					if (c == a) {
						f[0]++;
						f[1]++;
					} else if (c == b) {
						f[1] = max(f[1] - 1, f[0] - 1);
						f[0] = 0;
					}
					ans = max(ans, f[1]);
				}
			}
		}
		return ans;
	}
};

