jump-game-viii.solutionCode:
class Solution {
public:
	long long minCost(vector<int>& nums, vector<int>& costs) {
		int n = nums.size();
		vector<int> g[n];
		stack<int> stk;
		for (int i = n - 1; ~i; --i) {
			while (!stk.empty() && nums[stk.top()] < nums[i]) {
				stk.pop();
			}
			if (!stk.empty()) {
				g[i].push_back(stk.top());
			}
			stk.push(i);
		}
		stk = stack<int>();
		for (int i = n - 1; ~i; --i) {
			while (!stk.empty() && nums[stk.top()] >= nums[i]) {
				stk.pop();
			}
			if (!stk.empty()) {
				g[i].push_back(stk.top());
			}
			stk.push(i);
		}
		vector<long long> f(n, 1e18);
		f[0] = 0;
		for (int i = 0; i < n; ++i) {
			for (int j : g[i]) {
				f[j] = min(f[j], f[i] + costs[j]);
			}
		}
		return f[n - 1];
	}
};

