public:
	int countLatticePoints(vector<vector<int>>& circles) {
		int mx = 0, my = 0;
		for (auto& c : circles) {
			mx = max(mx, c[0] + c[2]);
			my = max(my, c[1] + c[2]);
		}
		int ans = 0;
		for (int i = 0; i <= mx; ++i) {
			for (int j = 0; j <= my; ++j) {
				for (auto& c : circles) {
					int dx = i - c[0], dy = j - c[1];
					if (dx * dx + dy * dy <= c[2] * c[2]) {
						++ans;
						break;
					}
				}
			}
		}
		return ans;
	}
};

maximum-trailing-zeros-in-a-cornered-pat.solutionCode:
class Solution {
public:
	int maxTrailingZeros(vector<vector<int>>& grid) {
		int m = grid.size(), n = grid[0].size();
		vector<vector<int>> r2(m + 1, vector<int>(n + 1));
		vector<vector<int>> c2(m + 1, vector<int>(n + 1));
		vector<vector<int>> r5(m + 1, vector<int>(n + 1));
		vector<vector<int>> c5(m + 1, vector<int>(n + 1));
		for (int i = 1; i <= m; ++i) {
			for (int j = 1; j <= n; ++j) {
				int x = grid[i - 1][j - 1];
				int s2 = 0, s5 = 0;
				for (; x % 2 == 0; x /= 2) {
					++s2;
				}
				for (; x % 5 == 0; x /= 5) {
					++s5;
				}
				r2[i][j] = r2[i][j - 1] + s2;
				c2[i][j] = c2[i - 1][j] + s2;
				r5[i][j] = r5[i][j - 1] + s5;
				c5[i][j] = c5[i - 1][j] + s5;
			}
		}
		int ans = 0;
		for (int i = 1; i <= m; ++i) {
			for (int j = 1; j <= n; ++j) {
				int a = min(r2[i][j] + c2[i - 1][j], r5[i][j] + c5[i - 1][j]);
				int b = min(r2[i][j] + c2[m][j] - c2[i][j], r5[i][j] + c5[m][j] - c5[i][j]);
				int c = min(r2[i][n] - r2[i][j] + c2[i][j], r5[i][n] - r5[i][j] + c5[i][j]);
				int d = min(r2[i][n] - r2[i][j - 1] + c2[m][j] - c2[i][j], r5[i][n] - r5[i][j - 1] + c5[m][j] - c5[i][j]);
				ans = max({ans, a, b, c, d});
			}
		}
		return ans;
	}
};

maximum-total-beauty-of-the-gardens.solutionCode:
class Solution {
public:
	long long maximumBeauty(vector<int>& flowers, long long newFlowers, int target, int full, int partial) {
		sort(flowers.begin(), flowers.end());
		int n = flowers.size();
		long long s[n + 1];
		s[0] = 0;
		for (int i = 1; i <= n; ++i) {
			s[i] = s[i - 1] + flowers[i - 1];
		}
		long long ans = 0;
		int i = flowers.end() - lower_bound(flowers.begin(), flowers.end(), target);
		for (int x = i; x <= n; ++x) {
			newFlowers -= (x == 0 ? 0 : max(target - flowers[n - x], 0));
			if (newFlowers < 0) {
				break;
			}
			int l = 0, r = n - x - 1;
			while (l < r) {
				int mid = (l + r + 1) >> 1;
				if (1LL * flowers[mid] * (mid + 1) - s[mid + 1] <= newFlowers) {
					l = mid;
				} else {
					r = mid - 1;
				}
			}
			int y = 0;
			if (r != -1) {
				long long cost = 1LL * flowers[l] * (l + 1) - s[l + 1];
				long long mx = flowers[l] + (newFlowers - cost) / (l + 1);
				long long threshold = target - 1;
				y = min(mx, threshold);
			}
			ans = max(ans, 1LL * x * full + 1LL * y * partial);
		}
		return ans;
	}
};

