class Solution {
public:
	int maxValueOfCoins(vector<vector<int>>& piles, int k) {
		int n = piles.size();
		vector<vector<int>> f(n + 1, vector<int>(k + 1));
		for (int i = 1; i <= n; i++) {
			vector<int> nums = piles[i - 1];
			vector<int> s(nums.size() + 1);
			for (int j = 1; j <= nums.size(); j++) {
				s[j] = s[j - 1] + nums[j - 1];
			}
			for (int j = 0; j <= k; j++) {
				for (int h = 0; h < s.size() && h <= j; h++) {
					f[i][j] = max(f[i][j], f[i - 1][j - h] + s[h]);
				}
			}
		}
		return f[n][k];
	}
};

maximum-product-after-k-increments.solutionCode:
class Solution {
public:
	int maximumProduct(vector<int>& nums, int k) {
		priority_queue<int, vector<int>, greater<int>> pq;
		for (int x : nums) {
			pq.push(x);
		}
		while (k-- > 0) {
			int smallest = pq.top();
			pq.pop();
			pq.push(smallest + 1);
		}
		const int mod = 1e9 + 7;
		long long ans = 1;
		while (!pq.empty()) {
			ans = (ans * pq.top()) % mod;
			pq.pop();
		}
		return static_cast<int>(ans);
	}
};

sum-of-total-strength-of-wizards.solutionCode:
class Solution {
public:
	int totalStrength(vector<int>& strength) {
		int n = strength.size();
		vector<int> left(n, -1);
		vector<int> right(n, n);
		stack<int> stk;
		for (int i = 0; i < n; ++i) {
			while (!stk.empty() && strength[stk.top()] >= strength[i]) stk.pop();
			if (!stk.empty()) left[i] = stk.top();
			stk.push(i);
		}
		stk = stack<int>();
		for (int i = n - 1; i >= 0; --i) {
			while (!stk.empty() && strength[stk.top()] > strength[i]) stk.pop();
			if (!stk.empty()) right[i] = stk.top();
			stk.push(i);
		}
		int mod = 1e9 + 7;
		vector<int> s(n + 1);
		for (int i = 0; i < n; ++i) s[i + 1] = (s[i] + strength[i]) % mod;
		vector<int> ss(n + 2);
		for (int i = 0; i < n + 1; ++i) ss[i + 1] = (ss[i] + s[i]) % mod;
		int ans = 0;
		for (int i = 0; i < n; ++i) {
			int v = strength[i];
			int l = left[i] + 1, r = right[i] - 1;
			long a = (long) (i - l + 1) * (ss[r + 2] - ss[i + 1]);
			long b = (long) (r - i + 1) * (ss[i + 1] - ss[l]);
			ans = (ans + v * ((a - b) % mod)) % mod;
		}
		return (int) (ans + mod) % mod;
	}
};

