class Solution {
public:
	int countUnguarded(int m, int n, vector<vector<int>>& guards, vector<vector<int>>& walls) {
		int g[m][n];
		memset(g, 0, sizeof(g));
		for (auto& e : guards) {
			g[e[0]][e[1]] = 2;
		}
		for (auto& e : walls) {
			g[e[0]][e[1]] = 2;
		}
		int dirs[5] = {-1, 0, 1, 0, -1};
		for (auto& e : guards) {
			for (int k = 0; k < 4; ++k) {
				int x = e[0], y = e[1];
				int a = dirs[k], b = dirs[k + 1];
				while (x + a >= 0 && x + a < m && y + b >= 0 && y + b < n && g[x + a][y + b] < 2) {
					x += a;
					y += b;
					g[x][y] = 1;
				}
			}
		}
		int ans = 0;
		for (auto& row : g) {
			ans += count(row, row + n, 0);
		}
		return ans;
	}
};

