class Solution:
	def minimumWeight(
		self, n: int, edges: List[List[int]], src1: int, src2: int, dest: int
	) -> int:
		def dijkstra(g, u):
			dist = [inf] * n
			dist[u] = 0
			q = [(0, u)]
			while q:
				d, u = heappop(q)
				if d > dist[u]:
					continue
				for v, w in g[u]:
					if dist[v] > dist[u] + w:
						dist[v] = dist[u] + w
						heappush(q, (dist[v], v))
			return dist

		g = defaultdict(list)
		rg = defaultdict(list)
		for f, t, w in edges:
			g[f].append((t, w))
			rg[t].append((f, w))
		d1 = dijkstra(g, src1)
		d2 = dijkstra(g, src2)
		d3 = dijkstra(rg, dest)
		ans = min(sum(v) for v in zip(d1, d2, d3))
		return -1 if ans >= inf else ans

distance-to-a-cycle-in-undirected-graph.solutionCode:
class Solution {
public:
	vector<int> distanceToCycle(int n, vector<vector<int>>& edges) {
		unordered_set<int> g[n];
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].insert(b);
			g[b].insert(a);
		}
		queue<int> q;
		for (int i = 0; i < n; ++i) {
			if (g[i].size() == 1) {
				q.push(i);
			}
		}
		int f[n];
		int seq[n];
		int k = 0;
		while (!q.empty()) {
			int i = q.front();
			q.pop();
			seq[k++] = i;
			for (int j : g[i]) {
				g[j].erase(i);
				f[i] = j;
				if (g[j].size() == 1) {
					q.push(j);
				}
			}
			g[i].clear();
		}
		vector<int> ans(n);
		for (; k; --k) {
			int i = seq[k - 1];
			ans[i] = ans[f[i]] + 1;
		}
		return ans;
	}
};

