class Solution {
public:
	vector<bool> canMakePaliQueries(string s, vector<vector<int>>& queries) {
		int n = s.size();
		int ss[n + 1][26];
		memset(ss, 0, sizeof(ss));
		for (int i = 1; i <= n; ++i) {
			for (int j = 0; j < 26; ++j) {
				ss[i][j] = ss[i - 1][j];
			}
			ss[i][s[i - 1] - 'a']++;
		}
		vector<bool> ans;
		for (auto& q : queries) {
			int l = q[0], r = q[1], k = q[2];
			int x = 0;
			for (int j = 0; j < 26; ++j) {
				x += (ss[r + 1][j] - ss[l][j]) & 1;
			}
			ans.emplace_back(x / 2 <= k);
		}
		return ans;
	}
};

the-earliest-moment-when-everyone-become.solutionCode:
class Solution {
public:
	int earliestAcq(vector<vector<int>>& logs, int n) {
		sort(logs.begin(), logs.end());
		vector<int> p(n);
		iota(p.begin(), p.end(), 0);
		function<int(int)> find = [&](int x) {
			return p[x] == x ? x : p[x] = find(p[x]);
		};
		for (auto& log : logs) {
			int x = find(log[1]);
			int y = find(log[2]);
			if (x != y) {
				p[x] = y;
				--n;
			}
			if (n == 1) {
				return log[0];
			}
		}
		return -1;
	}
};

lowest-common-ancestor-of-deepest-leaves.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	TreeNode* lcaDeepestLeaves(TreeNode* root) {
		auto dfs = [&](this auto&& dfs, TreeNode* root) -> pair<TreeNode*, int> {
			if (!root) {
				return {nullptr, 0};
			}
			auto [l, d1] = dfs(root->left);
			auto [r, d2] = dfs(root->right);
			if (d1 > d2) {
				return {l, d1 + 1};
			}
			if (d1 < d2) {
				return {r, d2 + 1};
			}
			return {root, d1 + 1};
		};
		return dfs(root).first;
	}
};

smallest-sufficient-team.solutionCode:
class Solution {
public:
	vector<int> smallestSufficientTeam(vector<string>& req_skills, vector<vector<string>>& people) {
		unordered_map<string, int> d;
		int m = req_skills.size(), n = people.size();
		for (int i = 0; i < m; ++i) {
			d[req_skills[i]] = i;
		}
		int p[n];
		memset(p, 0, sizeof(p));
		for (int i = 0; i < n; ++i) {
			for (auto& s : people[i]) {
				p[i] |= 1 << d[s];
			}
		}
		int f[1 << m];
		int g[1 << m];
		int h[1 << m];
		memset(f, 63, sizeof(f));
		f[0] = 0;
		for (int i = 0; i < 1 << m; ++i) {
			if (f[i] == 0x3f3f3f3f) {
				continue;
			}
			for (int j = 0; j < n; ++j) {
				if (f[i] + 1 < f[i | p[j]]) {
					f[i | p[j]] = f[i] + 1;
					g[i | p[j]] = j;
					h[i | p[j]] = i;
				}
			}
		}
		vector<int> ans;
		for (int i = (1 << m) - 1; i; i = h[i]) {
			ans.push_back(g[i]);
		}
		return ans;
	}
};

