class Solution {
public:
	int minCostToSupplyWater(int n, vector<int>& wells, vector<vector<int>>& pipes) {
		for (int i = 0; i < n; ++i) {
			pipes.push_back({0, i + 1, wells[i]});
		}
		sort(pipes.begin(), pipes.end(), [](const vector<int>& a, const vector<int>& b) {
			return a[2] < b[2];
		});
		int p[n + 1];
		iota(p, p + n + 1, 0);
		function<int(int)> find = [&](int x) {
			if (p[x] != x) {
				p[x] = find(p[x]);
			}
			return p[x];
		};
		int ans = 0;
		for (const auto& x : pipes) {
			int pa = find(x[0]), pb = find(x[1]);
			if (pa == pb) {
				continue;
			}
			p[pa] = pb;
			ans += x[2];
			if (--n == 0) {
				break;
			}
		}
		return ans;
	}
};

print-zero-even-odd.solutionCode:
#include <semaphore.h>

class ZeroEvenOdd {
private:
	int n;
	sem_t z, e, o;

public:
	ZeroEvenOdd(int n) {
		this->n = n;
		sem_init(&z, 0, 1);
		sem_init(&e, 0, 0);
		sem_init(&o, 0, 0);
	}

	// printNumber(x) outputs "x", where x is an integer.
	void zero(function<void(int)> printNumber) {
		for (int i = 0; i < n; ++i) {
			sem_wait(&z);
			printNumber(0);
			if (i % 2 == 0) {
				sem_post(&o);
			} else {
				sem_post(&e);
			}
		}
	}

	void even(function<void(int)> printNumber) {
		for (int i = 2; i <= n; i += 2) {
			sem_wait(&e);
			printNumber(i);
			sem_post(&z);
		}
	}

	void odd(function<void(int)> printNumber) {
		for (int i = 1; i <= n; i += 2) {
			sem_wait(&o);
			printNumber(i);
			sem_post(&z);
		}
	}
};

