class Solution {
public:
	vector<string> invalidTransactions(vector<string>& transactions) {
		unordered_map<string, vector<tuple<int, string, int>>> d;
		unordered_set<int> idx;
		for (int i = 0; i < transactions.size(); ++i) {
			vector<string> e = split(transactions[i], ',');
			string name = e[0];
			int time = stoi(e[1]);
			int amount = stoi(e[2]);
			string city = e[3];
			d[name].push_back({time, city, i});
			if (amount > 1000) {
				idx.insert(i);
			}
			for (auto& [t, c, j] : d[name]) {
				if (c != city && abs(time - t) <= 60) {
					idx.insert(i);
					idx.insert(j);
				}
			}
		}
		vector<string> ans;
		for (int i : idx) {
			ans.emplace_back(transactions[i]);
		}
		return ans;
	}

	vector<string> split(string& s, char delim) {
		stringstream ss(s);
		string item;
		vector<string> res;
		while (getline(ss, item, delim)) {
			res.emplace_back(item);
		}
		return res;
	}
};

filling-bookcase-shelves.solutionCode:
class Solution {
public:
	int minHeightShelves(vector<vector<int>>& books, int shelfWidth) {
		int n = books.size();
		int f[n + 1];
		f[0] = 0;
		for (int i = 1; i <= n; ++i) {
			int w = books[i - 1][0], h = books[i - 1][1];
			f[i] = f[i - 1] + h;
			for (int j = i - 1; j > 0; --j) {
				w += books[j - 1][0];
				if (w > shelfWidth) {
					break;
				}
				h = max(h, books[j - 1][1]);
				f[i] = min(f[i], f[j - 1] + h);
			}
		}
		return f[n];
	}
};

