class Solution {
public:
	int movesToMakeZigzag(vector<int>& nums) {
		vector<int> ans(2);
		int n = nums.size();
		for (int i = 0; i < 2; ++i) {
			for (int j = i; j < n; j += 2) {
				int d = 0;
				if (j) d = max(d, nums[j] - nums[j - 1] + 1);
				if (j < n - 1) d = max(d, nums[j] - nums[j + 1] + 1);
				ans[i] += d;
			}
		}
		return min(ans[0], ans[1]);
	}
};

minimum-knight-moves.solutionCode:
class Solution {
public:
	int minKnightMoves(int x, int y) {
		x += 310;
		y += 310;
		int ans = 0;
		queue<pair<int, int>> q;
		q.push({310, 310});
		vector<vector<bool>> vis(700, vector<bool>(700));
		vis[310][310] = true;
		vector<vector<int>> dirs = {{-2, 1}, {-1, 2}, {1, 2}, {2, 1}, {2, -1}, {1, -2}, {-1, -2}, {-2, -1}};
		while (!q.empty()) {
			for (int k = q.size(); k > 0; --k) {
				auto p = q.front();
				q.pop();
				if (p.first == x && p.second == y) return ans;
				for (auto& dir : dirs) {
					int c = p.first + dir[0], d = p.second + dir[1];
					if (!vis[c][d]) {
						vis[c][d] = true;
						q.push({c, d});
					}
				}
			}
			++ans;
		}
		return -1;
	}
};

