class Solution {
public:
	int connectSticks(vector<int>& sticks) {
		priority_queue<int, vector<int>, greater<int>> pq;
		for (auto& x : sticks) {
			pq.push(x);
		}
		int ans = 0;
		while (pq.size() > 1) {
			int x = pq.top();
			pq.pop();
			int y = pq.top();
			pq.pop();
			int z = x + y;
			ans += z;
			pq.push(z);
		}
		return ans;
	}
};

