		int n = calories.size();
		int s[n + 1];
		s[0] = 0;
		for (int i = 0; i < n; ++i) {
			s[i + 1] = s[i] + calories[i];
		}
		int ans = 0;
		for (int i = 0; i < n - k + 1; ++i) {
			int t = s[i + k] - s[i];
			if (t < lower) {
				--ans;
			} else if (t > upper) {
				++ans;
			}
		}
		return ans;
	}
};

