critical-connections-in-a-network.solutionCode:
class Solution {
public:
	vector<vector<int>> criticalConnections(int n, vector<vector<int>>& connections) {
		int now = 0;
		vector<int> dfn(n);
		vector<int> low(n);
		vector<int> g[n];
		for (auto& e : connections) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		vector<vector<int>> ans;
		function<void(int, int)> tarjan = [&](int a, int fa) -> void {
			dfn[a] = low[a] = ++now;
			for (int b : g[a]) {
				if (b == fa) {
					continue;
				}
				if (!dfn[b]) {
					tarjan(b, a);
					low[a] = min(low[a], low[b]);
					if (low[b] > dfn[a]) {
						ans.push_back({a, b});
					}
				} else {
					low[a] = min(low[a], dfn[b]);
				}
			}
		};
		tarjan(0, -1);
		return ans;
	}
};

design-file-system.solutionCode:
class Trie {
public:
	unordered_map<string, Trie*> children;
	int v;

	Trie(int v) {
		this->v = v;
	}

	bool insert(string& w, int v) {
		Trie* node = this;
		auto ps = split(w, '/');
		for (int i = 1; i < ps.size() - 1; ++i) {
			auto p = ps[i];
			if (!node->children.count(p)) {
				return false;
			}
			node = node->children[p];
		}
		if (node->children.count(ps.back())) {
			return false;
		}
		node->children[ps.back()] = new Trie(v);
		return true;
	}

	int search(string& w) {
		Trie* node = this;
		auto ps = split(w, '/');
		for (int i = 1; i < ps.size(); ++i) {
			auto p = ps[i];
			if (!node->children.count(p)) {
				return -1;
			}
			node = node->children[p];
		}
		return node->v;
	}

private:
	vector<string> split(string& s, char delim) {
		stringstream ss(s);
		string item;
		vector<string> res;
		while (getline(ss, item, delim)) {
			res.emplace_back(item);
		}
		return res;
	}
};

class FileSystem {
public:
	FileSystem() {
		trie = new Trie(-1);
	}

	bool createPath(string path, int value) {
		return trie->insert(path, value);
	}

	int get(string path) {
		return trie->search(path);
	}

private:
	Trie* trie;
};

