minimum-cost-tree-from-leaf-values.solutionCode:
class Solution {
public:
	int mctFromLeafValues(vector<int>& arr) {
		int n = arr.size();
		int f[n][n];
		int g[n][n];
		memset(f, 0, sizeof(f));
		for (int i = n - 1; ~i; --i) {
			g[i][i] = arr[i];
			for (int j = i + 1; j < n; ++j) {
				g[i][j] = max(g[i][j - 1], arr[j]);
			}
		}
		function<int(int, int)> dfs = [&](int i, int j) -> int {
			if (i == j) {
				return 0;
			}
			if (f[i][j] > 0) {
				return f[i][j];
			}
			int ans = 1 << 30;
			for (int k = i; k < j; ++k) {
				ans = min(ans, dfs(i, k) + dfs(k + 1, j) + g[i][k] * g[k + 1][j]);
			}
			return f[i][j] = ans;
		};
		return dfs(0, n - 1);
	}
};

as-far-from-land-as-possible.solutionCode:
class Solution {
public:
	int maxDistance(vector<vector<int>>& grid) {
		int n = grid.size();
		queue<pair<int, int>> q;
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j]) {
					q.emplace(i, j);
				}
			}
		}
		int ans = -1;
		if (q.empty() || q.size() == n * n) {
			return ans;
		}
		int dirs[5] = {-1, 0, 1, 0, -1};
		while (!q.empty()) {
			for (int m = q.size(); m; --m) {
				auto [i, j] = q.front();
				q.pop();
				for (int k = 0; k < 4; ++k) {
					int x = i + dirs[k], y = j + dirs[k + 1];
					if (x >= 0 && x < n && y >= 0 && y < n && !grid[x][y]) {
						grid[x][y] = 1;
						q.emplace(x, y);
					}
				}
			}
			++ans;
		}
		return ans;
	}
};

