 */

stone-game-ii.solutionCode:
class Solution {
public:
	int stoneGameII(vector<int>& piles) {
		int n = piles.size();
		int s[n + 1];
		s[0] = 0;
		for (int i = 0; i < n; ++i) {
			s[i + 1] = s[i] + piles[i];
		}
		int f[n][n + 1];
		memset(f, 0, sizeof f);
		function<int(int, int)> dfs = [&](int i, int m) -> int {
			if (m * 2 >= n - i) {
				return s[n] - s[i];
			}
			if (f[i][m]) {
				return f[i][m];
			}
			int res = 0;
			for (int x = 1; x <= m << 1; ++x) {
				res = max(res, s[n] - s[i] - dfs(i + x, max(x, m)));
			}
			return f[i][m] = res;
		};
		return dfs(0, 1);
	}
};

largest-1-bordered-square.solutionCode:
class Solution {
public:
	int largest1BorderedSquare(vector<vector<int>>& grid) {
		int m = grid.size(), n = grid[0].size();
		int down[m][n];
		int right[m][n];
		memset(down, 0, sizeof down);
		memset(right, 0, sizeof right);
		for (int i = m - 1; i >= 0; --i) {
			for (int j = n - 1; j >= 0; --j) {
				if (grid[i][j] == 1) {
					down[i][j] = i + 1 < m ? down[i + 1][j] + 1 : 1;
					right[i][j] = j + 1 < n ? right[i][j + 1] + 1 : 1;
				}
			}
		}
		for (int k = min(m, n); k > 0; --k) {
			for (int i = 0; i <= m - k; ++i) {
				for (int j = 0; j <= n - k; ++j) {
					if (down[i][j] >= k && right[i][j] >= k && right[i + k - 1][j] >= k
						&& down[i][j + k - 1] >= k) {
						return k * k;
					}
				}
			}
		}
		return 0;
	}
};

