class Solution {
public:
	int kConcatenationMaxSum(vector<int>& arr, int k) {
		long s = 0, mxPre = 0, miPre = 0, mxSub = 0;
		for (int x : arr) {
			s += x;
			mxPre = max(mxPre, s);
			miPre = min(miPre, s);
			mxSub = max(mxSub, s - miPre);
		}
		long ans = mxSub;
		const int mod = 1e9 + 7;
		if (k == 1) {
			return ans % mod;
		}
		long mxSuf = s - miPre;
		ans = max(ans, mxPre + mxSuf);
		if (s > 0) {
			ans = max(ans, mxPre + (k - 2) * s + mxSuf);
		}
		return ans % mod;
	}
};

parallel-courses.solutionCode:
class Solution {
public:
	int minimumSemesters(int n, vector<vector<int>>& relations) {
		vector<vector<int>> g(n);
		vector<int> indeg(n);
		for (auto& r : relations) {
			int prev = r[0] - 1, nxt = r[1] - 1;
			g[prev].push_back(nxt);
			++indeg[nxt];
		}
		queue<int> q;
		for (int i = 0; i < n; ++i) {
			if (indeg[i] == 0) {
				q.push(i);
			}
		}
		int ans = 0;
		while (!q.empty()) {
			++ans;
			for (int k = q.size(); k; --k) {
				int i = q.front();
				q.pop();
				--n;
				for (int& j : g[i]) {
					if (--indeg[j] == 0) {
						q.push(j);
					}
				}
			}
		}
		return n == 0 ? ans : -1;
	}
};

