class Solution {
public:
	vector<string> mostVisitedPattern(vector<string>& username, vector<int>& timestamp, vector<string>& website) {
		unordered_map<string, vector<pair<int, string>>> d;
		int n = username.size();
		for (int i = 0; i < n; ++i) {
			auto user = username[i];
			int ts = timestamp[i];
			auto site = website[i];
			d[user].emplace_back(ts, site);
		}
		unordered_map<string, int> cnt;
		for (auto& [_, sites] : d) {
			int m = sites.size();
			unordered_set<string> s;
			if (m > 2) {
				sort(sites.begin(), sites.end());
				for (int i = 0; i < m - 2; ++i) {
					for (int j = i + 1; j < m - 1; ++j) {
						for (int k = j + 1; k < m; ++k) {
							s.insert(sites[i].second + "," + sites[j].second + "," + sites[k].second);
						}
					}
				}
			}
			for (auto& t : s) {
				cnt[t]++;
			}
		}
		int mx = 0;
		string t;
		for (auto& [p, v] : cnt) {
			if (mx < v || (mx == v && t > p)) {
				mx = v;
				t = p;
			}
		}
		return split(t, ',');
	}

	vector<string> split(string& s, char c) {
		vector<string> res;
		stringstream ss(s);
		string t;
		while (getline(ss, t, c)) {
			res.push_back(t);
		}
		return res;
	}
};

maximum-average-subtree.solutionCode:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
	double maximumAverageSubtree(TreeNode* root) {
		double ans = 0;
		auto dfs = [&](this auto&& dfs, TreeNode* root) -> pair<int, int> {
			if (!root) {
				return {0, 0};
			}
			auto [ls, ln] = dfs(root->left);
			auto [rs, rn] = dfs(root->right);
			int s = root->val + ls + rs;
			int n = 1 + ln + rn;
			ans = max(ans, s * 1.0 / n);
			return {s, n};
		};
		dfs(root);
		return ans;
	}
};

