		int dirs[5] = {1, -1, -1, 1, 1};
		const int inf = 1 << 30;
		int ans = -inf;
		int n = arr1.size();
		for (int k = 0; k < 4; ++k) {
			int a = dirs[k], b = dirs[k + 1];
			int mx = -inf, mi = inf;
			for (int i = 0; i < n; ++i) {
				mx = max(mx, a * arr1[i] + b * arr2[i] + i);
