class Solution {
public:
	int countWinningSequences(string s) {
		int n = s.size();
		int d[26]{};
		d['W' - 'A'] = 1;
		d['E' - 'A'] = 2;
		int f[n][n + n + 1][4];
		memset(f, -1, sizeof(f));
		auto calc = [](int x, int y) -> int {
			if (x == y) {
				return 0;
			}
			if (x < y) {
				return x == 0 && y == 2 ? 1 : -1;
			}
			return x == 2 && y == 0 ? -1 : 1;
		};
		const int mod = 1e9 + 7;
		auto dfs = [&](this auto&& dfs, int i, int j, int k) -> int {
			if (n - i <= j - n) {
				return 0;
			}
			if (i >= n) {
				return j - n < 0 ? 1 : 0;
			}
			if (f[i][j][k] != -1) {
				return f[i][j][k];
			}
			int ans = 0;
			for (int l = 0; l < 3; ++l) {
				if (l == k) {
					continue;
				}
				ans = (ans + dfs(i + 1, j + calc(d[s[i] - 'A'], l), l)) % mod;
			}
			return f[i][j][k] = ans;
		};
		return dfs(0, n, 3);
	}
};

count-connected-components-in-lcm-graph.solutionCode:
typedef struct DSU {
	unordered_map<int, int> par, rank;
	DSU(int n) {
		for (int i = 0; i < n; ++i) {
			par[i] = i;
			rank[i] = 0;
		}
	}

	void makeSet(int v) {
		par[v] = v;
		rank[v] = 1;
	}

	int find(int x) {
		if (par[x] == x) {
			return x;
		}
		return par[x] = find(par[x]);
	}

	void unionSet(int u, int v) {
		u = find(u);
		v = find(v);
		if (u != v) {
			if (rank[u] < rank[v]) swap(u, v);
			par[v] = u;
			if (rank[u] == rank[v]) rank[u]++;
		}
	}
} DSU;

class Solution {
public:
	int countComponents(vector<int>& nums, int threshold) {
		DSU dsu(threshold);
		for (auto& num : nums) {
			for (int j = num; j <= threshold; j += num) {
				dsu.unionSet(num, j);
			}
		}
		unordered_set<int> par;
		for (auto& num : nums) {
			if (num > threshold) {
				par.insert(num);
			} else {
				par.insert(dsu.find(num));
			}
		}
		return par.size();
	}
};

