class Solution {
public:
	int minArraySum(vector<int>& nums, int d, int op1, int op2) {
		int n = nums.size();
		int f[n + 1][op1 + 1][op2 + 1];
		memset(f, 0x3f, sizeof f);
		f[0][0][0] = 0;
		for (int i = 1; i <= n; ++i) {
			int x = nums[i - 1];
			for (int j = 0; j <= op1; ++j) {
				for (int k = 0; k <= op2; ++k) {
					f[i][j][k] = f[i - 1][j][k] + x;
					if (j > 0) {
						f[i][j][k] = min(f[i][j][k], f[i - 1][j - 1][k] + (x + 1) / 2);
					}
					if (k > 0 && x >= d) {
						f[i][j][k] = min(f[i][j][k], f[i - 1][j][k - 1] + (x - d));
					}
					if (j > 0 && k > 0) {
						int y = (x + 1) / 2;
						if (y >= d) {
							f[i][j][k] = min(f[i][j][k], f[i - 1][j - 1][k - 1] + (y - d));
						}
						if (x >= d) {
							f[i][j][k] = min(f[i][j][k], f[i - 1][j - 1][k - 1] + (x - d + 1) / 2);
						}
					}
				}
			}
		}
		int ans = INT_MAX;
		for (int j = 0; j <= op1; ++j) {
			for (int k = 0; k <= op2; ++k) {
				ans = min(ans, f[n][j][k]);
			}
		}
		return ans;
	}
};

