		int n = nums.size();
		int d[n + 1];
		memset(d, 0, sizeof(d));
		for (const auto& q : queries) {
			int l = q[0], r = q[1];
			++d[l];
			--d[r + 1];
		}
		for (int i = 0, s = 0; i < n; ++i) {
			s += d[i];
			if (nums[i] > s) {
				return false;
			}
		}
		return true;
	}
};

