class Solution {
public:
	bool hasIncreasingSubarrays(vector<int>& nums, int k) {
		int mx = 0, pre = 0, cur = 0;
		int n = nums.size();
		for (int i = 0; i < n; ++i) {
			++cur;
			if (i == n - 1 || nums[i] >= nums[i + 1]) {
				mx = max({mx, cur / 2, min(pre, cur)});
				pre = cur;
				cur = 0;
			}
		}
		return mx >= k;
	}
};

find-minimum-time-to-reach-last-room-ii.solutionCode:
class Solution {
public:
	int minTimeToReach(vector<vector<int>>& moveTime) {
		int n = moveTime.size();
		int m = moveTime[0].size();
		vector<vector<int>> dist(n, vector<int>(m, INT_MAX));
		dist[0][0] = 0;
		priority_queue<array<int, 3>, vector<array<int, 3>>, greater<>> pq;
		pq.push({0, 0, 0});
		int dirs[5] = {-1, 0, 1, 0, -1};

		while (1) {
			auto [d, i, j] = pq.top();
			pq.pop();

			if (i == n - 1 && j == m - 1) {
				return d;
			}
			if (d > dist[i][j]) {
				continue;
			}

			for (int k = 0; k < 4; ++k) {
				int x = i + dirs[k];
				int y = j + dirs[k + 1];

				if (x >= 0 && x < n && y >= 0 && y < m) {
					int t = max(moveTime[x][y], dist[i][j]) + (i + j) % 2 + 1;
					if (dist[x][y] > t) {
						dist[x][y] = t;
						pq.push({t, x, y});
					}
				}
			}
		}
	}
};

