remove-methods-from-project.solutionCode:
class Solution {
public:
	vector<int> remainingMethods(int n, int k, vector<vector<int>>& invocations) {
		vector<bool> suspicious(n);
		vector<bool> vis(n);
		vector<int> f[n];
		vector<int> g[n];
		for (const auto& e : invocations) {
			int a = e[0], b = e[1];
			f[a].push_back(b);
			f[b].push_back(a);
			g[a].push_back(b);
		}
		auto dfs = [&](this auto&& dfs, int i) -> void {
			suspicious[i] = true;
			for (int j : g[i]) {
				if (!suspicious[j]) {
					dfs(j);
				}
			}
		};
		dfs(k);
		auto dfs2 = [&](this auto&& dfs2, int i) -> void {
			vis[i] = true;
			for (int j : f[i]) {
				if (!vis[j]) {
					suspicious[j] = false;
					dfs2(j);
				}
			}
		};
		for (int i = 0; i < n; ++i) {
			if (!suspicious[i] && !vis[i]) {
				dfs2(i);
			}
		}
		vector<int> ans;
		for (int i = 0; i < n; ++i) {
			if (!suspicious[i]) {
				ans.push_back(i);
			}
		}
		return ans;
	}
};

digit-operations-to-make-two-integers-eq.solutionCode:
class Solution {
private:
	vector<bool> sieve;
	void runSieve() {
		sieve.resize(100000, true);
		sieve[0] = false, sieve[1] = false;
		for (int i = 2; i < 1e5; ++i) {
			if (sieve[i]) {
				for (int j = 2 * i; j < 1e5; j += i) {
					sieve[j] = false;
				}
			}
		}
	}
	int solve(int n, int m) {
		priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
		unordered_set<int> vis;
		pq.push({n, n});
		while (!pq.empty()) {
			int sum = pq.top().first, cur = pq.top().second;
			pq.pop();
			if (vis.find(cur) != vis.end()) continue;
			vis.insert(cur);
			if (cur == m) return sum;
			string s = to_string(cur);
			for (int i = 0; i < s.size(); ++i) {
				char c = s[i];
				if (s[i] < '9') {
					s[i]++;
					int next = stoi(s);
					if (!sieve[next] && vis.find(next) == vis.end()) {
						pq.push({sum + next, next});
					}
					s[i] = c;
				}
				if (s[i] > '0' && !(i == 0 && s[i] == '1')) {
					s[i]--;
					int next = stoi(s);
					if (!sieve[next] && vis.find(next) == vis.end()) {
						pq.push({sum + next, next});
					}
					s[i] = c;
				}
			}
		}
		return -1;
	}

public:
	int minOperations(int n, int m) {
		runSieve();
		if (sieve[n] || sieve[m]) return -1;
		return solve(n, m);
	}
};

find-the-original-typed-string-ii.solutionCode:
class Solution {
public:
	int possibleStringCount(string word, int k) {
		const int mod = 1e9 + 7;
		vector<int> nums;
		long long ans = 1;
		int cur = 0;
		int n = word.size();

		for (int i = 0; i < n; ++i) {
			cur++;
			if (i == n - 1 || word[i] != word[i + 1]) {
				if (cur > 1) {
					if (k > 0) {
						nums.push_back(cur - 1);
					}
					ans = ans * cur % mod;
				}
				cur = 0;
				k--;
			}
		}

		if (k < 1) {
			return ans;
		}

		int m = nums.size();
		vector<vector<int>> f(m + 1, vector<int>(k, 0));
		f[0][0] = 1;

		for (int i = 1; i <= m; ++i) {
			int x = nums[i - 1];
			vector<long long> s(k + 1, 0);
			for (int j = 0; j < k; ++j) {
				s[j + 1] = (s[j] + f[i - 1][j]) % mod;
			}
			for (int j = 0; j < k; ++j) {
				int l = max(0, j - x);
				f[i][j] = (s[j + 1] - s[l] + mod) % mod;
			}
		}

		long long sum = 0;
		for (int j = 0; j < k; ++j) {
			sum = (sum + f[m][j]) % mod;
		}

		return (ans - sum + mod) % mod;
	}
};

find-x-sum-of-all-k-long-subarrays-i.solutionCode:
class Solution {
public:
	vector<int> findXSum(vector<int>& nums, int k, int x) {
		using pii = pair<int, int>;
		set<pii> l, r;
		int s = 0;
		unordered_map<int, int> cnt;
		auto add = [&](int v) {
			if (cnt[v] == 0) {
				return;
			}
			pii p = {cnt[v], v};
			if (!l.empty() && p > *l.begin()) {
				s += p.first * p.second;
				l.insert(p);
			} else {
				r.insert(p);
			}
		};
		auto remove = [&](int v) {
			if (cnt[v] == 0) {
				return;
			}
			pii p = {cnt[v], v};
			auto it = l.find(p);
			if (it != l.end()) {
				s -= p.first * p.second;
				l.erase(it);
			} else {
				r.erase(p);
			}
		};
		vector<int> ans;
		for (int i = 0; i < nums.size(); ++i) {
			remove(nums[i]);
			++cnt[nums[i]];
			add(nums[i]);

			int j = i - k + 1;
			if (j < 0) {
				continue;
			}

			while (!r.empty() && l.size() < x) {
				pii p = *r.rbegin();
				s += p.first * p.second;
				r.erase(p);
				l.insert(p);
			}
			while (l.size() > x) {
				pii p = *l.begin();
				s -= p.first * p.second;
				l.erase(p);
				r.insert(p);
			}
			ans.push_back(s);

			remove(nums[j]);
			--cnt[nums[j]];
			add(nums[j]);
		}
		return ans;
	}
};

find-the-maximum-factor-score-of-array.solutionCode:
class Solution {
public:
	long long maxScore(vector<int>& nums) {
		int n = nums.size();
		vector<long long> sufGcd(n + 1, 0);
		vector<long long> sufLcm(n + 1, 1);
		for (int i = n - 1; i >= 0; --i) {
			sufGcd[i] = gcd(sufGcd[i + 1], nums[i]);
			sufLcm[i] = lcm(sufLcm[i + 1], nums[i]);
		}

		long long ans = sufGcd[0] * sufLcm[0];
		long long preGcd = 0, preLcm = 1;
		for (int i = 0; i < n; ++i) {
			ans = max(ans, gcd(preGcd, sufGcd[i + 1]) * lcm(preLcm, sufLcm[i + 1]));
			preGcd = gcd(preGcd, nums[i]);
			preLcm = lcm(preLcm, nums[i]);
		}
		return ans;
	}
};

