class Solution {
public:
	long long countOfSubstrings(string word, int k) {
		auto f = [&](int k) -> long long {
			long long ans = 0;
			int l = 0, x = 0;
			unordered_map<char, int> cnt;
			auto vowel = [&](char c) -> bool {
				return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
			};
			for (char c : word) {
				if (vowel(c)) {
					cnt[c]++;
				} else {
					++x;
				}
				while (x >= k && cnt.size() == 5) {
					char d = word[l++];
					if (vowel(d)) {
						if (--cnt[d] == 0) {
							cnt.erase(d);
						}
					} else {
						--x;
					}
				}
				ans += l;
			}
			return ans;
		};

		return f(k) - f(k + 1);
	}
};

zero-array-transformation-ii.solutionCode:
class Solution {
public:
	int minZeroArray(vector<int>& nums, vector<vector<int>>& queries) {
		int n = nums.size();
		int d[n + 1];
		int m = queries.size();
		int l = 0, r = m + 1;
		auto check = [&](int k) -> bool {
			memset(d, 0, sizeof(d));
			for (int i = 0; i < k; ++i) {
				int l = queries[i][0], r = queries[i][1], val = queries[i][2];
				d[l] += val;
				d[r + 1] -= val;
			}
			for (int i = 0, s = 0; i < n; ++i) {
				s += d[i];
				if (nums[i] > s) {
					return false;
				}
			}
			return true;
		};
		while (l < r) {
			int mid = (l + r) >> 1;
			if (check(mid)) {
				r = mid;
			} else {
				l = mid + 1;
			}
		}
		return l > m ? -1 : l;
	}
};

