class Solution {
public:
	int maxCollectedFruits(vector<vector<int>>& fruits) {
		int n = fruits.size();
		const int inf = 1 << 29;
		vector<vector<int>> f(n, vector<int>(n, -inf));

		f[0][n - 1] = fruits[0][n - 1];
		for (int i = 1; i < n; i++) {
			for (int j = i + 1; j < n; j++) {
				f[i][j] = max(f[i - 1][j], f[i - 1][j - 1]) + fruits[i][j];
				if (j + 1 < n) {
					f[i][j] = max(f[i][j], f[i - 1][j + 1] + fruits[i][j]);
				}
			}
		}

		f[n - 1][0] = fruits[n - 1][0];
		for (int j = 1; j < n; j++) {
			for (int i = j + 1; i < n; i++) {
				f[i][j] = max(f[i][j - 1], f[i - 1][j - 1]) + fruits[i][j];
				if (i + 1 < n) {
					f[i][j] = max(f[i][j], f[i + 1][j - 1] + fruits[i][j]);
				}
			}
		}

		int ans = f[n - 2][n - 1] + f[n - 1][n - 2];
		for (int i = 0; i < n; i++) {
			ans += fruits[i][i];
		}

		return ans;
	}
};

maximize-the-number-of-target-nodes-afte.solutionCode:
class Solution {
public:
	vector<int> maxTargetNodes(vector<vector<int>>& edges1, vector<vector<int>>& edges2, int k) {
		auto g2 = build(edges2);
		int m = edges2.size() + 1;
		int t = 0;
		for (int i = 0; i < m; ++i) {
			t = max(t, dfs(g2, i, -1, k - 1));
		}

		auto g1 = build(edges1);
		int n = edges1.size() + 1;

		vector<int> ans(n, t);
		for (int i = 0; i < n; ++i) {
			ans[i] += dfs(g1, i, -1, k);
		}

		return ans;
	}

private:
	vector<vector<int>> build(const vector<vector<int>>& edges) {
		int n = edges.size() + 1;
		vector<vector<int>> g(n);
		for (const auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		return g;
	}

	int dfs(const vector<vector<int>>& g, int a, int fa, int d) {
		if (d < 0) {
			return 0;
		}
		int cnt = 1;
		for (int b : g[a]) {
			if (b != fa) {
				cnt += dfs(g, b, a, d - 1);
			}
		}
		return cnt;
	}
};

