class Solution {
public:
	int maxGoodNumber(vector<int>& nums) {
		int ans = 0;
		auto f = [&](vector<int>& nums) {
			int res = 0;
			vector<int> t;
			for (int x : nums) {
				for (; x; x >>= 1) {
					t.push_back(x & 1);
				}
			}
			while (t.size()) {
				res = res * 2 + t.back();
				t.pop_back();
			}
			return res;
		};
		for (int i = 0; i < 6; ++i) {
			ans = max(ans, f(nums));
			next_permutation(nums.begin(), nums.end());
		}
		return ans;
	}
};

find-maximum-removals-from-source-string.solutionCode:
class Solution {
public:
	int maxRemovals(string source, string pattern, vector<int>& targetIndices) {
		int m = source.length(), n = pattern.length();
		vector<vector<int>> f(m + 1, vector<int>(n + 1, INT_MIN / 2));
		f[0][0] = 0;

		vector<int> s(m);
		for (int i : targetIndices) {
			s[i] = 1;
		}

		for (int i = 1; i <= m; ++i) {
			for (int j = 0; j <= n; ++j) {
				f[i][j] = f[i - 1][j] + s[i - 1];
				if (j > 0 && source[i - 1] == pattern[j - 1]) {
					f[i][j] = max(f[i][j], f[i - 1][j - 1]);
				}
			}
		}

		return f[m][n];
	}
};

