class Solution {
public:
	bool findSafeWalk(vector<vector<int>>& grid, int health) {
		int m = grid.size();
		int n = grid[0].size();
		vector<vector<int>> dist(m, vector<int>(n, INT_MAX));
		dist[0][0] = grid[0][0];
		queue<pair<int, int>> q;
		q.emplace(0, 0);
		int dirs[5] = {-1, 0, 1, 0, -1};
		while (!q.empty()) {
			auto [x, y] = q.front();
			q.pop();
			for (int i = 0; i < 4; ++i) {
				int nx = x + dirs[i];
				int ny = y + dirs[i + 1];
				if (nx >= 0 && nx < m && ny >= 0 && ny < n && dist[nx][ny] > dist[x][y] + grid[nx][ny]) {
					dist[nx][ny] = dist[x][y] + grid[nx][ny];
					q.emplace(nx, ny);
				}
			}
		}
		return dist[m - 1][n - 1] < health;
	}
};

sum-of-consecutive-subsequences.solutionCode:
class Solution {
public:
	int getSum(vector<int>& nums) {
		using ll = long long;
		const int mod = 1e9 + 7;
		auto calc = [&](const vector<int>& nums) -> ll {
			int n = nums.size();
			vector<ll> left(n), right(n);
			unordered_map<int, ll> cnt;

			for (int i = 1; i < n; ++i) {
				cnt[nums[i - 1]] += 1 + cnt[nums[i - 1] - 1];
				left[i] = cnt[nums[i] - 1];
			}

			cnt.clear();

			for (int i = n - 2; i >= 0; --i) {
				cnt[nums[i + 1]] += 1 + cnt[nums[i + 1] + 1];
				right[i] = cnt[nums[i] + 1];
			}

			ll ans = 0;
			for (int i = 0; i < n; ++i) {
				ans = (ans + (left[i] + right[i] + left[i] * right[i] % mod) * nums[i] % mod) % mod;
			}
			return ans;
		};

		ll x = calc(nums);
		reverse(nums.begin(), nums.end());
		ll y = calc(nums);
		ll s = accumulate(nums.begin(), nums.end(), 0LL);
		return static_cast<int>((x + y + s) % mod);
	}
};

construct-string-with-minimum-cost-(easy.solutionCode:
const int inf = 1 << 29;

class Trie {
public:
	Trie* children[26]{};
	int cost = inf;

	void insert(string& word, int cost) {
		Trie* node = this;
		for (char c : word) {
			int idx = c - 'a';
			if (!node->children[idx]) {
				node->children[idx] = new Trie();
			}
			node = node->children[idx];
		}
		node->cost = min(node->cost, cost);
	}
};

class Solution {
public:
	int minimumCost(string target, vector<string>& words, vector<int>& costs) {
		Trie* trie = new Trie();
		for (int i = 0; i < words.size(); ++i) {
			trie->insert(words[i], costs[i]);
		}
		int n = target.length();
		int f[n];
		memset(f, 0, sizeof(f));
		auto dfs = [&](this auto&& dfs, int i) -> int {
			if (i >= n) {
				return 0;
			}
			if (f[i]) {
				return f[i];
			}
			f[i] = inf;
			Trie* node = trie;
			for (int j = i; j < n; ++j) {
				int idx = target[j] - 'a';
				if (!node->children[idx]) {
					return f[i];
				}
				node = node->children[idx];
				f[i] = min(f[i], node->cost + dfs(j + 1));
			}
			return f[i];
		};
		int ans = dfs(0);
		return ans < inf ? ans : -1;
	}
};

count-substrings-that-satisfy-k-constrai.solutionCode:
class Solution {
public:
	vector<long long> countKConstraintSubstrings(string s, int k, vector<vector<int>>& queries) {
		int cnt[2]{};
		int n = s.size();
		vector<int> d(n, n);
		long long pre[n + 1];
		pre[0] = 0;
		for (int i = 0, j = 0; j < n; ++j) {
			cnt[s[j] - '0']++;
			while (cnt[0] > k && cnt[1] > k) {
				d[i] = j;
				cnt[s[i++] - '0']--;
			}
			pre[j + 1] = pre[j] + j - i + 1;
		}
		vector<long long> ans;
		for (const auto& q : queries) {
			int l = q[0], r = q[1];
			int p = min(r + 1, d[l]);
			long long a = (1LL + p - l) * (p - l) / 2;
			long long b = pre[r + 1] - pre[p];
			ans.push_back(a + b);
		}
		return ans;
	}
};

