class NeighborSum {
public:
	NeighborSum(vector<vector<int>>& grid) {
		this->grid = grid;
		int m = grid.size(), n = grid[0].size();
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				d[grid[i][j]] = {i, j};
			}
		}
	}

	int adjacentSum(int value) {
		return cal(value, 0);
	}

	int diagonalSum(int value) {
		return cal(value, 1);
	}

private:
	vector<vector<int>> grid;
	unordered_map<int, pair<int, int>> d;
	int dirs[2][5] = {{-1, 0, 1, 0, -1}, {-1, 1, 1, -1, -1}};

