shortest-distance-after-road-addition-qu.solutionCode:
class Solution {
public:
	vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
		vector<int> g[n];
		for (int i = 0; i < n - 1; ++i) {
			g[i].push_back(i + 1);
		}
		auto bfs = [&](int i) -> int {
			queue<int> q{{i}};
			vector<bool> vis(n);
			vis[i] = true;
			for (int d = 0;; ++d) {
				for (int k = q.size(); k; --k) {
					int u = q.front();
					q.pop();
					if (u == n - 1) {
						return d;
					}
					for (int v : g[u]) {
						if (!vis[v]) {
							vis[v] = true;
							q.push(v);
						}
					}
				}
			}
		};
		vector<int> ans;
		for (const auto& q : queries) {
			g[q[0]].push_back(q[1]);
			ans.push_back(bfs(0));
		}
		return ans;
	}
};

