final-array-state-after-k-multiplication.solutionCode:
class Solution {
public:
	vector<int> getFinalState(vector<int>& nums, int k, int multiplier) {
		if (multiplier == 1) {
			return nums;
		}

		using ll = long long;
		using pli = pair<ll, int>;
		auto cmp = [](const pli& a, const pli& b) {
			if (a.first == b.first) {
				return a.second > b.second;
			}
			return a.first > b.first;
		};
		priority_queue<pli, vector<pli>, decltype(cmp)> pq(cmp);

		int n = nums.size();
		int m = *max_element(nums.begin(), nums.end());

		for (int i = 0; i < n; ++i) {
			pq.emplace(nums[i], i);
		}

		while (k > 0 && pq.top().first < m) {
			auto p = pq.top();
			pq.pop();
			p.first *= multiplier;
			pq.emplace(p);
			--k;
		}

		auto qpow = [&](ll a, ll n, ll mod) {
			ll ans = 1 % mod;
			a = a % mod;
			while (n > 0) {
				if (n & 1) {
					ans = ans * a % mod;
				}
				a = a * a % mod;
				n >>= 1;
			}
			return ans;
		};

		const int mod = 1e9 + 7;
		for (int i = 0; i < n; ++i) {
			auto p = pq.top();
			pq.pop();
			long long x = p.first;
			int j = p.second;
			nums[j] = static_cast<int>((x % mod) * qpow(multiplier, k / n + (i < k % n ? 1 : 0), mod) % mod);
		}

		return nums;
	}
};

find-the-maximum-sequence-value-of-array.solutionCode:
class Solution {
public:
	int maxValue(vector<int>& nums, int k) {
		int m = 1 << 7;
		int n = nums.size();

		vector<vector<vector<bool>>> f(n + 1, vector<vector<bool>>(k + 2, vector<bool>(m, false)));
		f[0][0][0] = true;

		for (int i = 0; i < n; i++) {
			for (int j = 0; j <= k; j++) {
				for (int x = 0; x < m; x++) {
					if (f[i][j][x]) {
						f[i + 1][j][x] = true;
						f[i + 1][j + 1][x | nums[i]] = true;
					}
				}
			}
		}

		vector<vector<vector<bool>>> g(n + 1, vector<vector<bool>>(k + 2, vector<bool>(m, false)));
		g[n][0][0] = true;

		for (int i = n; i > 0; i--) {
			for (int j = 0; j <= k; j++) {
				for (int y = 0; y < m; y++) {
					if (g[i][j][y]) {
						g[i - 1][j][y] = true;
						g[i - 1][j + 1][y | nums[i - 1]] = true;
					}
				}
			}
		}

		int ans = 0;

		for (int i = k; i <= n - k; i++) {
			for (int x = 0; x < m; x++) {
				if (f[i][k][x]) {
					for (int y = 0; y < m; y++) {
						if (g[i][k][y]) {
							ans = max(ans, x ^ y);
						}
					}
				}
			}
		}

		return ans;
	}
};

