		int ans = 0;
		for (int i = 0; i < m / 2; ++i) {
			for (int j = 0; j < n / 2; ++j) {
				int x = m - i - 1, y = n - j - 1;
				int cnt1 = grid[i][j] + grid[x][j] + grid[i][y] + grid[x][y];
				ans += min(cnt1, 4 - cnt1);
			}
		}
		if (m % 2 == 1 && n % 2 == 1) {
			ans += grid[m / 2][n / 2];
		}

		int diff = 0, cnt1 = 0;
		if (m % 2 == 1) {
			for (int j = 0; j < n / 2; ++j) {
				if (grid[m / 2][j] == grid[m / 2][n - j - 1]) {
					cnt1 += grid[m / 2][j] * 2;
				} else {
					diff += 1;
				}
			}
		}
		if (n % 2 == 1) {
			for (int i = 0; i < m / 2; ++i) {
				if (grid[i][n / 2] == grid[m - i - 1][n / 2]) {
					cnt1 += grid[i][n / 2] * 2;
				} else {
