class Solution {
public:
	int minLargest(vector<int>& nums1, vector<int>& nums2) {
		int m = nums1.size(), n = nums2.size();
		int f[m + 1][n + 1];
		memset(f, 0, sizeof(f));
		auto nxt = [](int x, int y) -> int {
			return (x & 1 ^ y) == 1 ? x + 1 : x + 2;
		};
		for (int i = 1; i <= m; ++i) {
			f[i][0] = nxt(f[i - 1][0], nums1[i - 1]);
		}
		for (int j = 1; j <= n; ++j) {
			f[0][j] = nxt(f[0][j - 1], nums2[j - 1]);
		}
		for (int i = 1; i <= m; ++i) {
			for (int j = 1; j <= n; ++j) {
				int x = nxt(f[i - 1][j], nums1[i - 1]);
				int y = nxt(f[i][j - 1], nums2[j - 1]);
				f[i][j] = min(x, y);
			}
		}
		return f[m][n];
	}
};

find-minimum-diameter-after-merging-two-.solutionCode:
class Solution {
public:
	int minimumDiameterAfterMerge(vector<vector<int>>& edges1, vector<vector<int>>& edges2) {
		int d1 = treeDiameter(edges1);
		int d2 = treeDiameter(edges2);
		return max({d1, d2, (d1 + 1) / 2 + (d2 + 1) / 2 + 1});
	}

	int treeDiameter(vector<vector<int>>& edges) {
		int n = edges.size() + 1;
		vector<int> g[n];
		for (auto& e : edges) {
			int a = e[0], b = e[1];
			g[a].push_back(b);
			g[b].push_back(a);
		}
		int ans = 0, a = 0;
		auto dfs = [&](this auto&& dfs, int i, int fa, int t) -> void {
			for (int j : g[i]) {
				if (j != fa) {
					dfs(j, i, t + 1);
				}
			}
			if (ans < t) {
				ans = t;
				a = i;
			}
		};
		dfs(0, -1, 0);
		dfs(a, -1, 0);
		return ans;
	}
};

