		vector<vector<int>> p(n, vector<int>(m));
		long long suf = 1;
		for (int i = n - 1; i >= 0; --i) {
			for (int j = m - 1; j >= 0; --j) {
				p[i][j] = suf;
				suf = suf * grid[i][j] % mod;
