count-the-number-of-powerful-integers.solutionCode:
class Solution {
public:
	long long numberOfPowerfulInt(long long start, long long finish, int limit, string s) {
		string t = to_string(start - 1);
		long long f[20];
		memset(f, -1, sizeof(f));

		auto dfs = [&](this auto&& dfs, int pos, int lim) -> long long {
			if (t.size() < s.size()) {
				return 0;
			}
			if (!lim && f[pos] != -1) {
				return f[pos];
			}
			if (t.size() - pos == s.size()) {
				return lim ? s <= t.substr(pos) : 1;
			}
			long long ans = 0;
			int up = min(lim ? t[pos] - '0' : 9, limit);
			for (int i = 0; i <= up; ++i) {
				ans += dfs(pos + 1, lim && i == (t[pos] - '0'));
			}
			if (!lim) {
				f[pos] = ans;
			}
			return ans;
		};

		long long a = dfs(0, true);
		t = to_string(finish);
		memset(f, -1, sizeof(f));
		long long b = dfs(0, true);
		return b - a;
	}
};

