class Solution {
public:
	int minimumCoins(vector<int>& prices) {
		int n = prices.size();
		deque<int> q;
		for (int i = n; i; --i) {
			while (q.size() && q.front() > i * 2 + 1) {
				q.pop_front();
			}
			if (i <= (n - 1) / 2) {
				prices[i - 1] += prices[q.front() - 1];
			}
			while (q.size() && prices[q.back() - 1] >= prices[i - 1]) {
				q.pop_back();
			}
			q.push_back(i);
		}
		return prices[0];
	}
};

maximum-xor-product.solutionCode:
class Solution {
public:
	int maximumXorProduct(long long a, long long b, int n) {
		const int mod = 1e9 + 7;
		long long ax = (a >> n) << n, bx = (b >> n) << n;
		for (int i = n - 1; ~i; --i) {
			int x = a >> i & 1, y = b >> i & 1;
			if (x == y) {
				ax |= 1LL << i;
				bx |= 1LL << i;
			} else if (ax < bx) {
				ax |= 1LL << i;
			} else {
				bx |= 1LL << i;
			}
		}
		ax %= mod;
		bx %= mod;
		return ax * bx % mod;
	}
};

