class Solution {
public:
	vector<string> getWordsInLongestSubsequence(vector<string>& words, vector<int>& groups) {
		auto check = [](string& s, string& t) {
			if (s.size() != t.size()) {
				return false;
			}
			int cnt = 0;
			for (int i = 0; i < s.size(); ++i) {
				cnt += s[i] != t[i];
			}
			return cnt == 1;
		};
		int n = groups.size();
		vector<int> f(n, 1);
		vector<int> g(n, -1);
		int mx = 1;
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < i; ++j) {
				if (groups[i] != groups[j] && f[i] < f[j] + 1 && check(words[i], words[j])) {
					f[i] = f[j] + 1;
					g[i] = j;
					mx = max(mx, f[i]);
				}
			}
		}
		vector<string> ans;
		for (int i = 0; i < n; ++i) {
			if (f[i] == mx) {
				for (int j = i; ~j; j = g[j]) {
					ans.emplace_back(words[j]);
				}
				break;
			}
		}
		reverse(ans.begin(), ans.end());
		return ans;
	}
};

