class Solution {
public:
	int distributeCandies(int n, int limit) {
		auto comb2 = [](int n) {
			return 1LL * n * (n - 1) / 2;
		};
		if (n > 3 * limit) {
			return 0;
		}
		long long ans = comb2(n + 2);
		if (n > limit) {
			ans -= 3 * comb2(n - limit + 1);
		}
		if (n - 2 >= 2 * limit) {
			ans += 3 * comb2(n - 2 * limit);
		}
		return ans;
	}
};

