/**
 * Definition for BigArray.
 * class BigArray {
 * public:
 *     BigArray(vector<int> elements);
 *     int at(long long index);
 *     long long size();
 * };
 */
class Solution {
public:
	int countBlocks(BigArray* nums) {
		int ans = 0;
		using ll = long long;
		ll n = nums->size();
		auto search = [&](ll l) {
			ll r = n;
			int x = nums->at(l);
			while (l < r) {
				ll mid = (l + r) >> 1;
				if (nums->at(mid) != x) {
					r = mid;
				} else {
					l = mid + 1;
				}
			}
			return l;
		};
		for (long long i = 0; i < n; ++ans) {
			i = search(i);
		}
		return ans;
	}
};

