	vector<int> sameEndSubstringCount(string s, vector<vector<int>>& queries) {
		int n = s.size();
		int cnt[26][n + 1];
		memset(cnt, 0, sizeof(cnt));
		for (int j = 1; j <= n; ++j) {
			for (int i = 0; i < 26; ++i) {
				cnt[i][j] = cnt[i][j - 1];
			}
			cnt[s[j - 1] - 'a'][j]++;
		}
		vector<int> ans;
		for (auto& q : queries) {
			int l = q[0], r = q[1];
			ans.push_back(r - l + 1);
			for (int i = 0; i < 26; ++i) {
				int x = cnt[i][r + 1] - cnt[i][l];
				ans.back() += x * (x - 1) / 2;
			}
		}
		return ans;
	}
};

