	vector<int> findIndices(vector<int>& nums, int indexDifference, int valueDifference) {
		int mi = 0, mx = 0;
		for (int i = indexDifference; i < nums.size(); ++i) {
			int j = i - indexDifference;
			if (nums[j] < nums[mi]) {
				mi = j;
			}
			if (nums[j] > nums[mx]) {
				mx = j;
			}
			if (nums[i] - nums[mi] >= valueDifference) {
				return {mi, i};
			}
			if (nums[mx] - nums[i] >= valueDifference) {
				return {mx, i};
			}
		}
		return {-1, -1};
	}
};

count-complete-substrings.solutionCode:
class Solution {
public:
	int countCompleteSubstrings(string word, int k) {
		int n = word.length();
		int ans = 0;
		auto f = [&](string s) {
			int m = s.length();
			int ans = 0;
			for (int i = 1; i <= 26 && i * k <= m; ++i) {
				int l = i * k;
				int cnt[26]{};
				for (int j = 0; j < l; ++j) {
					++cnt[s[j] - 'a'];
				}
				unordered_map<int, int> freq;
				for (int x : cnt) {
					if (x > 0) {
						freq[x]++;
					}
				}
				if (freq[k] == i) {
					++ans;
				}
				for (int j = l; j < m; ++j) {
					int a = s[j] - 'a';
					int b = s[j - l] - 'a';
					freq[cnt[a]]--;
					cnt[a]++;
					freq[cnt[a]]++;

					freq[cnt[b]]--;
					cnt[b]--;
					freq[cnt[b]]++;

					if (freq[k] == i) {
						++ans;
					}
				}
			}
			return ans;
		};
		for (int i = 0; i < n;) {
			int j = i + 1;
			while (j < n && abs(word[j] - word[j - 1]) <= 2) {
				++j;
			}
			ans += f(word.substr(i, j - i));
			i = j;
		}
		return ans;
	}
};

maximum-strong-pair-xor-ii.solutionCode:
class Trie {
public:
	Trie* children[2];
	int cnt;

	Trie()
		: cnt(0) {
		children[0] = nullptr;
		children[1] = nullptr;
	}

	void insert(int x) {
		Trie* node = this;
		for (int i = 20; ~i; --i) {
			int v = (x >> i) & 1;
			if (node->children[v] == nullptr) {
				node->children[v] = new Trie();
			}
			node = node->children[v];
			++node->cnt;
		}
	}

	int search(int x) {
		Trie* node = this;
		int ans = 0;
		for (int i = 20; ~i; --i) {
			int v = (x >> i) & 1;
			if (node->children[v ^ 1] != nullptr && node->children[v ^ 1]->cnt > 0) {
				ans |= 1 << i;
				node = node->children[v ^ 1];
			} else {
				node = node->children[v];
			}
		}
		return ans;
	}

	void remove(int x) {
		Trie* node = this;
		for (int i = 20; ~i; --i) {
			int v = (x >> i) & 1;
			node = node->children[v];
			--node->cnt;
		}
	}
};

class Solution {
public:
	int maximumStrongPairXor(vector<int>& nums) {
		sort(nums.begin(), nums.end());
		Trie* tree = new Trie();
		int ans = 0, i = 0;
		for (int y : nums) {
			tree->insert(y);
			while (y > nums[i] * 2) {
				tree->remove(nums[i++]);
			}
			ans = max(ans, tree->search(y));
		}
		return ans;
	}
};

number-of-self-divisible-permutations.solutionCode:
class Solution {
public:
	int selfDivisiblePermutationCount(int n) {
		int f[1 << (n + 1)];
		memset(f, -1, sizeof(f));
		function<int(int)> dfs = [&](int mask) {
			if (f[mask] != -1) {
				return f[mask];
			}
			int i = __builtin_popcount(mask) + 1;
			if (i > n) {
				return 1;
			}
			f[mask] = 0;
			for (int j = 1; j <= n; ++j) {
				if ((mask >> j & 1) == 0 && (i % j == 0 || j % i == 0)) {
					f[mask] += dfs(mask | 1 << j);
				}
			}
			return f[mask];
		};
		return dfs(0);
	}
};

