class Solution {
public:
	long long minimumCost(vector<int>& nums) {
		sort(nums.begin(), nums.end());
		int i = lower_bound(ps, ps + 2 * 100000, nums[nums.size() / 2]) - ps;
		auto f = [&](ll x) {
			ll ans = 0;
			for (int& v : nums) {
				ans += abs(v - x);
			}
			return ans;
		};
		ll ans = LLONG_MAX;
		for (int j = i - 1; j <= i + 1; j++) {
			if (0 <= j && j < 2 * 100000) {
				ans = min(ans, f(ps[j]));
			}
		}
		return ans;
	}
};

