class Solution {
public:
	int maxUniqueSplit(string s) {
		unordered_set<string> st;
		int n = s.size();
		int ans = 0;
		auto dfs = [&](this auto&& dfs, int i) -> void {
			if (st.size() + n - i <= ans) {
				return;
			}
			if (i >= n) {
				ans = max(ans, (int) st.size());
				return;
			}
			for (int j = i + 1; j <= n; ++j) {
				string t = s.substr(i, j - i);
				if (!st.contains(t)) {
					st.insert(t);
					dfs(j);
					st.erase(t);
				}
			}
		};
		dfs(0);
		return ans;
	}
};

