detect-cycles-in-2d-grid.solutionCode:
class Solution {
public:
	bool containsCycle(vector<vector<char>>& grid) {
		int m = grid.size(), n = grid[0].size();
		vector<vector<bool>> vis(m, vector<bool>(n));
		const vector<int> dirs = {-1, 0, 1, 0, -1};

		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if (!vis[i][j]) {
					queue<array<int, 4>> q;
					q.push({i, j, -1, -1});
					vis[i][j] = true;

					while (!q.empty()) {
						auto p = q.front();
						q.pop();
						int x = p[0], y = p[1], px = p[2], py = p[3];

						for (int k = 0; k < 4; ++k) {
							int nx = x + dirs[k], ny = y + dirs[k + 1];
							if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
								if (grid[nx][ny] != grid[x][y] || (nx == px && ny == py)) {
									continue;
								}
								if (vis[nx][ny]) {
									return true;
								}
								q.push({nx, ny, x, y});
								vis[nx][ny] = true;
							}
						}
					}
				}
			}
		}
		return false;
	}
};

count-all-possible-routes.solutionCode:
class Solution {
public:
	int countRoutes(vector<int>& locations, int start, int finish, int fuel) {
		int n = locations.size();
		int f[n][fuel + 1];
		memset(f, -1, sizeof(f));
		const int mod = 1e9 + 7;
		function<int(int, int)> dfs = [&](int i, int k) -> int {
			if (k < abs(locations[i] - locations[finish])) {
				return 0;
			}
			if (f[i][k] != -1) {
				return f[i][k];
			}
			int ans = i == finish;
			for (int j = 0; j < n; ++j) {
				if (j != i) {
					ans = (ans + dfs(j, k - abs(locations[i] - locations[j]))) % mod;
				}
			}
			return f[i][k] = ans;
		};
		return dfs(start, fuel);
	}
};

