		int x = 0;
		for (Node* node : tree) {
			x ^= node->val;
			for (Node* child : node->children) {
				x ^= child->val;
			}
		}
		for (int i = 0;; ++i) {
			if (tree[i]->val == x) {
				return tree[i];
			}
		}
	}
};

