class Solution {
public:
	int minOperationsMaxProfit(vector<int>& customers, int boardingCost, int runningCost) {
		int ans = -1;
		int mx = 0, t = 0;
		int wait = 0, i = 0;
		while (wait || i < customers.size()) {
			wait += i < customers.size() ? customers[i] : 0;
			int up = min(4, wait);
			wait -= up;
			++i;
			t += up * boardingCost - runningCost;
			if (t > mx) {
				mx = t;
				ans = i;
			}
		}
		return ans;
	}
};

