class Solution {
public:
	int connectTwoGroups(vector<vector<int>>& cost) {
		int m = cost.size(), n = cost[0].size();
		int f[m + 1][1 << n];
		memset(f, 0x3f, sizeof(f));
		f[0][0] = 0;
		for (int i = 1; i <= m; ++i) {
			for (int j = 0; j < 1 << n; ++j) {
				for (int k = 0; k < n; ++k) {
					if (j >> k & 1) {
						int c = cost[i - 1][k];
						int x = min({f[i][j ^ (1 << k)], f[i - 1][j], f[i - 1][j ^ (1 << k)]}) + c;
						f[i][j] = min(f[i][j], x);
					}
				}
			}
		}
		return f[m][(1 << n) - 1];
	}
};

