/**
 * // This is the ArrayReader's API interface.
 * // You should not implement it, or speculate about its implementation
 * class ArrayReader {
 *   public:
 *     // Compares the sum of arr[l..r] with the sum of arr[x..y]
 *     // return 1 if sum(arr[l..r]) > sum(arr[x..y])
 *     // return 0 if sum(arr[l..r]) == sum(arr[x..y])
 *     // return -1 if sum(arr[l..r]) < sum(arr[x..y])
 *     int compareSub(int l, int r, int x, int y);
 *
 *     // Returns the length of the array
 *     int length();
 * };
 */

class Solution {
public:
	int getIndex(ArrayReader& reader) {
		int left = 0, right = reader.length() - 1;
		while (left < right) {
			int t1 = left, t2 = left + (right - left) / 3, t3 = left + (right - left) / 3 * 2 + 1;
			int cmp = reader.compareSub(t1, t2, t2 + 1, t3);
			if (cmp == 0) {
				left = t3 + 1;
			} else if (cmp == 1) {
				right = t2;
			} else {
				left = t2 + 1;
				right = t3;
			}
		}
		return left;
	}
};

maximum-non-negative-product-in-a-matrix.solutionCode:
class Solution {
public:
	int maxProductPath(vector<vector<int>>& grid) {
		int m = grid.size(), n = grid[0].size();
		vector<vector<array<long long, 2>>> f(m, vector<array<long long, 2>>(n));

		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				long long x = grid[i][j];
				if (i == 0 && j == 0) {
					f[i][j] = {x, x};
					continue;
				}

				long long mn = LLONG_MAX, mx = LLONG_MIN;

				if (i > 0) {
					auto [a, b] = f[i - 1][j];
					mn = min(mn, min(a * x, b * x));
					mx = max(mx, max(a * x, b * x));
				}

				if (j > 0) {
					auto [a, b] = f[i][j - 1];
					mn = min(mn, min(a * x, b * x));
					mx = max(mx, max(a * x, b * x));
				}

				f[i][j] = {mn, mx};
			}
		}

		long long ans = f[m - 1][n - 1][1];
		const int mod = 1e9 + 7;
		return ans < 0 ? -1 : ans % mod;
	}
};

