		cuts.push_back(0);
		cuts.push_back(n);
		sort(cuts.begin(), cuts.end());
		int m = cuts.size();
		int f[110][110]{};
		for (int l = 2; l < m; ++l) {
			for (int i = 0; i + l < m; ++i) {
				int j = i + l;
				f[i][j] = 1 << 30;
				for (int k = i + 1; k < j; ++k) {
					f[i][j] = min(f[i][j], f[i][k] + f[k][j] + cuts[j] - cuts[i]);
