class Solution {
public:
	int numOfWays(vector<int>& nums) {
		int n = nums.size();
		const int mod = 1e9 + 7;
		int c[n][n];
		memset(c, 0, sizeof(c));
		c[0][0] = 1;
		for (int i = 1; i < n; ++i) {
			c[i][0] = 1;
			for (int j = 1; j <= i; ++j) {
				c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % mod;
			}
		}
		function<int(vector<int>)> dfs = [&](vector<int> nums) -> int {
			if (nums.size() < 2) {
				return 1;
			}
			vector<int> left, right;
			for (int& x : nums) {
				if (x < nums[0]) {
					left.push_back(x);
				} else if (x > nums[0]) {
					right.push_back(x);
				}
			}
			int m = left.size(), n = right.size();
			int a = dfs(left), b = dfs(right);
			return c[m + n][m] * 1ll * a % mod * b % mod;
		};
		return (dfs(nums) - 1 + mod) % mod;
	}
};

number-of-ways-to-split-a-string.solutionCode:
class Solution {
public:
	int numWays(string s) {
		int cnt = 0;
		for (char& c : s) {
			cnt += c == '1';
		}
		int m = cnt % 3;
		if (m) {
			return 0;
		}
		const int mod = 1e9 + 7;
		int n = s.size();
		if (cnt == 0) {
			return (n - 1LL) * (n - 2) / 2 % mod;
		}
		cnt /= 3;
		auto find = [&](int x) {
			int t = 0;
			for (int i = 0;; ++i) {
				t += s[i] == '1';
				if (t == x) {
					return i;
				}
			}
		};
		int i1 = find(cnt), i2 = find(cnt + 1);
		int j1 = find(cnt * 2), j2 = find(cnt * 2 + 1);
		return (1LL * (i2 - i1) * (j2 - j1)) % mod;
	}
};

