/**
 * // This is the ArrayReader's API interface.
 * // You should not implement it, or speculate about its implementation
 * class ArrayReader {
 *   public:
 *     // Compares 4 different elements in the array
 *     // return 4 if the values of the 4 elements are the same (0 or 1).
 *     // return 2 if three elements have a value equal to 0 and one element has value equal to 1 or vice versa.
 *     // return 0 : if two element have a value equal to 0 and two elements have a value equal to 1.
 *     int query(int a, int b, int c, int d);
 *
 *     // Returns the length of the array
 *     int length();
 * };
 */

class Solution {
public:
	int guessMajority(ArrayReader& reader) {
		int n = reader.length();
		int x = reader.query(0, 1, 2, 3);
		int a = 1, b = 0;
		int k = 0;
		for (int i = 4; i < n; ++i) {
			if (reader.query(0, 1, 2, i) == x) {
				++a;
			} else {
				++b;
				k = i;
			}
		}

		int y = reader.query(0, 1, 2, 4);
		if (reader.query(1, 2, 3, 4) == y) {
			++a;
		} else {
			++b;
			k = 0;
		}
		if (reader.query(0, 2, 3, 4) == y) {
			++a;
		} else {
			++b;
			k = 1;
		}
		if (reader.query(0, 1, 3, 4) == y) {
			++a;
		} else {
			++b;
			k = 2;
		}
		if (a == b) {
			return -1;
		}
		return a > b ? 3 : k;
	}
};

minimum-number-of-days-to-disconnect-isl.solutionCode:
class Solution {
public:
	const vector<int> dirs = {-1, 0, 1, 0, -1};
	int m, n;

	int minDays(vector<vector<int>>& grid) {
		m = grid.size(), n = grid[0].size();
		if (count(grid) != 1) {
			return 0;
		}
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j] == 1) {
					grid[i][j] = 0;
					if (count(grid) != 1) {
						return 1;
					}
					grid[i][j] = 1;
				}
			}
		}
		return 2;
	}

	int count(vector<vector<int>>& grid) {
		int cnt = 0;
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j] == 1) {
					dfs(i, j, grid);
					++cnt;
				}
			}
		}
		for (int i = 0; i < m; ++i) {
			for (int j = 0; j < n; ++j) {
				if (grid[i][j] == 2) {
					grid[i][j] = 1;
				}
			}
		}
		return cnt;
	}

	void dfs(int i, int j, vector<vector<int>>& grid) {
		grid[i][j] = 2;
		for (int k = 0; k < 4; ++k) {
			int x = i + dirs[k], y = j + dirs[k + 1];
			if (x >= 0 && x < m && y >= 0 && y < n && grid[x][y] == 1) {
				dfs(x, y, grid);
			}
		}
	}
};

