maximum-sum-obtained-of-any-permutation.solutionCode:
class Solution {
public:
	int maxSumRangeQuery(vector<int>& nums, vector<vector<int>>& requests) {
		int n = nums.size();
		int d[n];
		memset(d, 0, sizeof(d));
		for (auto& req : requests) {
			int l = req[0], r = req[1];
			d[l]++;
			if (r + 1 < n) {
				d[r + 1]--;
			}
		}
		for (int i = 1; i < n; ++i) {
			d[i] += d[i - 1];
		}
		sort(nums.begin(), nums.end());
		sort(d, d + n);
		long long ans = 0;
		const int mod = 1e9 + 7;
		for (int i = 0; i < n; ++i) {
			ans = (ans + 1LL * nums[i] * d[i]) % mod;
		}
		return ans;
	}
};

count-unhappy-friends.solutionCode:
class Solution {
public:
	int unhappyFriends(int n, vector<vector<int>>& preferences, vector<vector<int>>& pairs) {
		vector<vector<int>> d(n, vector<int>(n));
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n - 1; ++j) {
				d[i][preferences[i][j]] = j;
			}
		}
		vector<int> p(n, 0);
		for (auto& e : pairs) {
			int x = e[0], y = e[1];
			p[x] = y;
			p[y] = x;
		}
		int ans = 0;
		for (int x = 0; x < n; ++x) {
			int y = p[x];
			for (int i = 0; i < d[x][y]; ++i) {
				int u = preferences[x][i];
				int v = p[u];
				if (d[u][x] < d[u][v]) {
					++ans;
					break;
				}
			}
		}
		return ans;
	}
};

shortest-subarray-to-be-removed-to-make-.solutionCode:
class Solution {
public:
	int findLengthOfShortestSubarray(vector<int>& arr) {
		int n = arr.size();
		int i = 0, j = n - 1;
		while (i + 1 < n && arr[i] <= arr[i + 1]) {
			++i;
		}
		while (j - 1 >= 0 && arr[j - 1] <= arr[j]) {
			--j;
		}
		if (i >= j) {
			return 0;
		}
		int ans = min(n - 1 - i, j);
		for (int l = 0; l <= i; ++l) {
			int r = lower_bound(arr.begin() + j, arr.end(), arr[l]) - arr.begin();
			ans = min(ans, r - l - 1);
		}
		return ans;
	}
};

