magnetic-force-between-two-balls.solutionCode:
class Solution {
public:
	int maxDistance(vector<int>& position, int m) {
		ranges::sort(position);
		int l = 1, r = position.back();
		auto count = [&](int f) {
			int prev = position[0];
			int cnt = 1;
			for (int& curr : position) {
				if (curr - prev >= f) {
					prev = curr;
					cnt++;
				}
			}
			return cnt;
		};
		while (l < r) {
			int mid = (l + r + 1) >> 1;
			if (count(mid) >= m) {
				l = mid;
			} else {
				r = mid - 1;
			}
		}
		return l;
	}
};

stone-game-iv.solutionCode:
class Solution {
public:
	bool winnerSquareGame(int n) {
		int f[n + 1];
		memset(f, 0, sizeof(f));
		function<bool(int)> dfs = [&](int i) -> bool {
			if (i <= 0) {
				return false;
			}
			if (f[i] != 0) {
				return f[i] == 1;
			}
			for (int j = 1; j <= i / j; ++j) {
				if (!dfs(i - j * j)) {
					f[i] = 1;
					return true;
				}
			}
			f[i] = -1;
			return false;
		};
		return dfs(n);
	}
};

